var KM = {"1": {"c": "THƯỢNG THƯỢNG", "hexagram": "Bát Thuần Càn", "line_label": "Động Hào Nhất", "p": "Thiên môn nhất quải bảng,\nDự định đoạt tiêu nhân. Mã tô phường thảo địa,\nThu cao thính lọc minh.\nCửa trời treo bảng đề danh,\nCàng treo giá ngọc, càng dành phẩm tiên.\nÂm vang ngựa thét băng miền,\nCuối thu ồ ạt vẫn truyền tiếng nai.", "b": "Quẻ này chủ: Con Rồng hiện trên ruộng, rất lợi khi gặp người đại nhân quân tử. Được thì suốt ngày nơm\nnớp, chiều tới thì lo lắng giữ gìn. Bởi thế nên lấy đó mà tự cường ở trên thì không kêu, ở dưới thì không\nlo. Thật là Đại cát vậy.\nQuẻ này cầu bất cứ việc gì cũng đều được may mắn, vì câu thứ ba tả rằng \"Nay người xin cầu như con\nngựa hí ngoài đồng cỏ xanh tươi” và câu thứ tư còn thêm rằng “Cuối thu được nghe tiếng nay”. Cảnh\nthanh thản an nhàn biết bao, vậy còn gì hơn nữa.\nÝ quẻ muốn nói rằng: cầu xin việc gì đều toại nguyện. Buổi phú quý, vinh hoa ắt đến, và hoá rủi thành\nmay, đó là một quẻ đại cát, cầu danh cầu việc đắt thành vậy.\nHơn nữa, câu thứ nhất đã nói rất rõ rồi \"Cửa trời treo bảng đề danh”, cầu danh, cầu mưu, cầu lợi đều đạt.\nCòn lo gì nữa.", "g": "rất tốt , sự nghiệp 、tài vận 、sức khỏe 、hôn nhân đều thuận toại.", "s": "10, 11, 21, 31, 1. Nếu muốn đánh số hên, đều đạt thành mỹ mãn 1 quẻ tốt cho việc cầu lợi."}, "2": {"c": "THƯỢNG THƯỢNG", "hexagram": "Bát Thuần Càn", "line_label": "Động Hào Nhị", "p": "Địa hữu thần,\nThậm uy nghiêm.\nHưng bang, phụ quốc,\nTôn chủ tà dân.\nĐất này là đất có thần\nHữu cầu tất ứng, bội phần hiển linh,\nHưng bang Quốc phụ dân sanh,\nKhuôn phù đức cả, thanh bình công cao.", "b": "Quẻ này chủ mưu vọng bất cứ một chuyện gì đều được thuận toại. Quan lại bói xem thì có cái vui thăng\nquan tiến chức. Kẻ sĩ bói xem thì có cái mừng đạt được công danh. Kẻ muốn xem về tiến trình thì phúc\nlộc lâu dài. Người muốn xem về sự nghiệp thì cơ sở vững bền. Tất cả đều tốt đẹp, duy chỉ có cầu tài thì vô\nvọng.\nQuẻ này khá lắm, cầu mưu việc gì đều không trở ngại. Cầu tài có tiền, cầu công danh được lên chức, cầu\nduyên nợ được toại lòng, nhưng phải tận tụy và thành tâm với việc cầu, đừng làm những đều trái với\nlương tâm.\nBởi vì ta đã hiểu rằng: Đức là tất cả, đức tạo nên hạnh phúc cho người. Cho nên quẻ chú ý khuyên nhủ\nngười nên tạo đức thêm dày, để được trọn việc sở cầu.\nCăn cứ ý quẻ nói trên, sự cầu xin của người, hãy nén lòng góp sức người trong gia đình, đừng nản chí,\nráng sức tiến tới, thì sẽ giải quyết được vấn đề của người trông mong trong mai sau. Dẫu là quá tốt đẹp,\nmọi sự hanh thông, chỉ hiềm cần cố gắng mới được. Chớ không phải việc dễ, mà chẳng cố. Đánh số rất\ntốt.", "g": "Quẻ được thần phù hộ, lời nói và việc làm vào nề nếp, có quí nhân tương trợ sự nghiệp, hôn nhân\nđược người, sức khỏe tốt.", "s": "22, 20, 2, 32."}, "3": {"c": "TRUNG BÌNH", "hexagram": "Bát Thuần Càn", "line_label": "Động Hào Tam", "p": "Tràng An hoa bất khả cập,\nXuân phong trung mã đề tật.\nCấp tảo gia tiên,\nSau nhiên sinh sắc.\nTrường An hoa nở khó thay,\nGió xuân, vó ngựa, tràn đầy đường xa.\nThời lai, mệnh xấu sẽ qua,\nCành cây nở rộ sắc hoa trổ màu.", "b": "Có nếm được cái khó bậc nhất trong muôn khó mới là người thượng đại nhân. Người xin được quẻ này\nnên hết sức tiến lên. Nếu chỉ ỷ thân cậy thế không lo hoạt động thì chẳng những không tiến mà còn thoái\nnữa là khác.\nNhững việc cầu xin của người. Như là bông hoa ở nơi kinh kỳ Trường An, thơm đẹp vô cùng mà lại ở nơi\nxa xôi. Song chẳng sao cả, người chỉ nên tính toán kỹ lưỡng và nắm lấy cơ hội, rồi mau tiến tới thì sẽ thấy\nsáng lạn và thành đạt trong việc cầu xin.\nÝ quẻ nói: Việc cầu xin tuy còn xa xôi, nhưng ý đã định làm thì nên thực hành ngay đi, đừng chần chờ\nnữa ắt sẽ lỡ dịp may. Vận may sắp đến cần đưa tay ra bắt lấy thì sẽ ắt thành.", "g": "E rằng không thể bay cao chạy xa, trước mắt tình trạng chẳng được tốt lắm.\nQuẻ dạy: Làm ăn phải đi xa chổ khác. Mưu sự ở một chỗ chẳng thông, cần trì chí. Quẻ này nếu cầu tài chỉ\ncó thề đạt một nửa và phải gắng sức đi xa mới mong.", "s": "43, 13, 23, 33, 30, 3."}, "4": {"c": "TRUNG BÌNH", "hexagram": "Bát Thuần Càn", "line_label": "Động Hào Tứ", "p": "Xuân hoa kiều mỵ,\nBất cấm vũ đả phong nhiêu.\nThu cúc u phương,\nPhản nại sương lăng tuyết ngạo.\nHoa Xuân khoe sắc màu tươi,\nNhưng không chịu nổi dập vùi gió mưa.\nCúc cô đơn, nở trễ mùa,\nTuyết sương dầu dãi vẫn thừa sắc hương.", "b": "Quẻ này chủ đại khí vãn thành, người có chí lớn muốn đắc ý phải lúc về già. Ví thử lúc thanh xuân đà đắc\ný thì rồi đây cũng như Cam La đời Tần, Vương Bột đời Đường mà thôi. Vũ đã phong nhiêu: gió đạp mưa\nvùi ý nói gian nan lận đận cuộc đời phong trần như Cam và Vương.\nNgười cầu được quẻ này, muốn cầu xin việc gì, hãy nên hoãn lại, hãy dò dẫm tiến tới mới hay. Bởi như\nhoa xuân rất tươi đẹp nhưng đâu chịu nổi mưa đùa gió tạt. Ngược lại hoa cúc tuy sanh trưởng trong mùa\nthu khí hậu hàn lạnh mà vẫn thơm tươi, chẳng sợ tuyết sương gì cả. Vậy ý quẻ khuyên ta nên chờ thời,\nđừng nên quá nóng, dù giàu sang hay công danh có muộn mấy đi nữa cũng đừng buồn, vì như hoa Cúc\nmùa Thu nở muộn mà vẫn thơm tho, hương sắc tốt tươi, chờ đợi là tốt, nhứt là thay đổi chổ ở, nơi làm\ncàng không nên nóng ruột.\nQuẻ dạy: Nhẫn nhẫn! Bôn ba chẳng qua thời vận. Công danh tiền bạc như mây nổi giửa trời, hơi nào phải\nlụy. Khương Tử Nha 80 tuổi mới nên danh, Cam La 12 tuổi đã nên phận, thì đã sao? Cầu tài nên chờ đợi.", "g": "Mọi việc đang không thuận lợi, cố gắng hết sức may ra còn có chút hy vọng.", "s": "44, 4, 14, 34,\n24, 40."}, "5": {"c": "THƯỢNG THƯỢNG", "hexagram": "Bát Thuần Càn", "line_label": "Động Hào Ngũ", "p": "Xuân sơn Chấn, Hạ phong Tốn,\nNgọa long khỏi, mãnh hổ kinh.\nPhong vân hội họp,\nCứu tế thương sinh.\nXuân Lôi chấn, Hạ giao hòa,\nRồng nằm thức dậy, giỡn già trên mây,\nCọp kia thấy sợ chạy ngay,\nGió mây hội họp dịp may cứu người.", "b": "Quẻ này chủ đợi thời hãy hành động, Người xin được quẻ này nên chờ nuôi tinh thần để chờ dịp thần phân\nphát, nhất thiết chớ khinh cử vọng động để đến nổi chịu hại. Thuận theo thì khá, ngược lại ắt mệt đó.\nQuẻ này tốt lắm. Vận thời sắp đến lúc hanh thông, vì đã đến lúc thuận theo thiên thời. Bởi quẻ nói: Mùa\nXuân có sấm động, mùa hạ có gió đông, đó là hiện tượng của trời đất giao thái, thì con Rồng ắt đến lúc\ntung hoành trong mây, mà Cọp dữ kia cũng phải kinh sợ, và khi gió mây tụ họp càng là lúc đắc chí của\nRồng. Hơn nữa, Rồng là tượng trưng cho thần oai cao thượng, thanh bình an vui. Cho nên người cầu xin\nđược quẻ này, sở cầu mưu ắt được toại nguyện.\nTuy nhiên, thời vận hanh thông cần phải chờ có cơ duyên, như câu chót trong quẻ nói “gió mây hội họp,\nmới là dịp may thành đạt” vậy.", "g": "Hết bĩ thì đến thái, nắng lâu gặp mưa rào, hôn nhân sợ có sóng gió, không nên ra ngoài du lịch xa.\nQuẻ dạy: Cầu tài, cầu danh thì tốt nhất, nếu cần chờ ngày Dần, ngày Thìn thì đẹp hơn. Vì quẻ có biểu\ntượng Rồng và Cọp. Đánh số nên lấy con nầy làm căn bản. Tốt lắm.", "s": "5, 15, 25, 35, 50, 55."}, "6": {"c": "TRUNG HẠ", "hexagram": "Bát Thuần Càn", "line_label": "Động Hào Lục", "p": "Phi huyền phi ảo,\nPhi thiên phi thâm.\nNhất cá diệu đạo,\nTrước ý sưu tầm.\nKhông huyền chẳng ảo cũng không sâu,\nViệc tính cầu xin từ khởi đầu.\nCó dốc lòng đi, nên khéo léo,\nDò tìm hay dở tránh âu sầu.", "b": "Tưởng rằng điều khó hiểu ai ngờ đã tìm ra. Lâu nay không biết chỉ tại ít để ý tới việc đời, không nghiên\ncứu kỹ sự vật đó thôi. Quẻ này ngụ ý khuyên ta nên đi tìm tìm lấy cái đạo huyền diệu cho cuộc sống của\nmình. Thực ra thì cái diệu đạo chẳng ở đâu xa, chỉ là sự giác ngộ của mình đó thôi.\nNgười cầu xin được quẻ này nên lưu tâm về việc đã định cầm mưu và phải tính toán kỹ lưỡng từ đầu, bởi\ntrong quẻ câu thứ nhất nói rất là tế nhị. Hơn nữa, ta muốn thành đạt theo ý nguyện thì càng nên khéo léo\nvà dò dẫm từng bước tiến, chớ quá nóng nảy gây những điều không hay.\nÝ quẻ muốn khuyên nhủ ta thận trọng, cân nhắc trong mọi công việc nhất là việc đang tính làm ăn tiểu\ntâm nghiên cứu chu đáo, rồi hãy tiến tới thì mới mong thành đạt. Sách có câu Dục tốc bất đạt vậy.\nQuẻ vừa phải. Cầu tài không mấy lợi. Cầu danh phải cố gắng, may ra mới mong thành đạt. Nhẫn Nhẫn.\nViệc đánh số, cầu hên xuôi, ít thuận lợi. Thận trọng.", "g": "Lòng đừng chán nản, ra sức kiếm tìm, ắt được như sự mong cầu.", "s": "16, 26, 36, 6, 60, 66."}, "7": {"c": "TRUNG BÌNH", "hexagram": "Thiên Trạch Lý", "line_label": "Động Hào Nhất", "p": "Quân tu ngộ, vật ngộ nghi,\nHữu bình lộ, nhiệm khu trì.\nTùy thời biến,\nKiện kiện hàm nghi.\nTỉnh đi, chớ quá hoài nghi,\nCon đường bằng thẳng, có gì bận tâm.\nTùy cơ ứng biến công thành,\nRồi đây muôn sự đem lành với ta.", "b": "Nhân tình đen bạc, thế thái nhạt nồng.\nNhưng nếu ta nắm vững được phương châm hành động, rồi tùy cơ ứng biến, thì cũng có thể gọi là người\ntuấn kiệt thực thời vụ vậy. Có thế thì mới tránh được lỗi lầm.\nQuẻ này cho hay sự cầu xin của người, như đi con đường bằng thẳng. Chớ nên nghi ngờ, và hãy nên tiến\ntới chẳng có gì trở ngại đâu. Nhưng có điều phải giữ lấy phước đức và ối với người phải tùy cơ khéo léo,\nđừng làm những gì trái với lương tâm, thì sự cầu xin của người ắt được công thành.\nNên uyển chuyển, tùy thời, tùy thế, mà hành động mới mong thành đạt. Làm như tánh người quân tử.\nQuân tử tánh như thủy năng phương, năng viên, ủy khúc tùy hành, nghĩa là uyển chuyển tánh tình và công\nviệc như nước, thì chui chỗ nào cũng lọt. Cầu tài cứ tiến tới. Cầu danh cứ hành động.", "g": "Tùy thực tế mà giải quyết khéo léo, mới dần dần đạt mục tiêu.", "s": "70, 7, 17,\n27, 77, 37."}, "8": {"c": "TRUNG BÌNH", "hexagram": "Thiên Trạch Lý", "line_label": "Động Hào Nhị", "p": "Hổ luyến cao sơn biệt hữu cơ,\nChứng nhân mục hạ thượng vô nghi.\nNhạn lai liều lượng hoàng hoa phát,\nThử tế thanh danh đế kỳ.\nCọp kia luyến núi ắt mưu cơ,\nMục hạ người ta vẫn ý ngờ,\nNhạn đến, hoa hoàng đầy phát nở,\nThanh danh vang dội khắp kinh đô.", "b": "Đã từ lâu đành chịu nhục trong cảnh bi, nhưng ý vẫn lặng xét thời cơ để hành động. Rồi đây một sớm vạn\nđến, tự nhiên hanh thông. Người xin được quẻ này, nên nhớ kỹ điều này: nhất thiết mọi mưu vọng đều\nphải đợi đến lúc cúc vàng đua nở (tức mùa thu).\nTheo bài thơ của quẻ cho rằng: Sự cầu mưu của người hiện giờ, còn có sự trở ngại và chưa được thuận lợi\nlắm như trong quẻ câu thứ hai nói, người ta chưa tin tưởng nơi mình và ang nghi ngờ việc làm của ta. Nên\nphải chờ một thời gian nữa đến lúc nhạn về bóng nở thì khi ấy mới thành đạt ý muốn.\nÝ quẻ nói rằng: nên nhẫn nại mà chờ đợi nhạn đến hoa nỡ, lúc đó hành động thì mới có kết quả và thu\nhoạch mỹ mãn vậy.\nQuẻ dạy: Dục tốc thì bất thông chờ mùa thu, vì mùa thu là mùa chim nhạn bay về nam. Cầu tài chỉ thông\nmột nửa . Nên lấy biểu tượng cọp và nhạn làm tượng trưng mà cầu may rủi.", "g": "Hiện tại thì chưa ai biết, về sau được mọi người ca tụng, đây là quẻ chỉ cho người có tài mà chưa\ngặp thời, chắc chắn về sau sẽ phát đạt.", "s": "38, 28, 8, 18, 80, 88."}, "9": {"c": "TRUNG THƯỢNG", "hexagram": "Thiên Trạch Lý", "line_label": "Động Hào Tam", "p": "Quý khách tương phùng cánh khả kỳ,\nĐình tiên kho mộc phượng lai nghi.\nHảo tương đoàn sự tòng trường sự,\nHữu thính bàn nhân thuyết thị phi.\nTương phùng khách quý nẻo đường mai,\nTrước ngõ cây khô phụng trổ tài.\nTà vọng đứng nghe làm việc thiện,\nTheo người phải trái sẽ ương tai.", "b": "Có người đề bạt, mọi việc đều toại lòng, ngoài hẳn ý liệu của mình. Tuy nhiên, nếu không có tu nhân tích\nđức thì quyết không thể có cái hy vọng đó được. Bởi thế, người quân tử bói được quẻ này thì nên, nhưng\nđứa tiểu nhân bói được quẻ này thì hung.\nTheo ý quẻ nói, người cầu xin được quẻ này, thì hoàn cảnh sắp gặp may, mà chỉ còn một thời gian rất\nngắn thôi.\nNhưng ý quẻ cũng khuyên nhủ rằng đừng nghe theo những lời tà vọng, mà phải tu tâm, tích đức thì mới\ntốt lành.\nQuẻ dạy: Gần gặp lúc Thới lai phong tống rồi đó không cần phải lo âu, buồn khổ làm gì. Thời đến như cây\nsắt trổ bông! Chỉ hiềm phải giữ lòng ngay thật mới mong có kết quả tốt đẹp. Cầu tài sắp vượng. Cầu danh\nsắp được thông. Có thể tính chuyện hên xuôi.", "g": "Chắc chắn mọi việc có quí nhân giúp đỡ, trai chưa vợ sẽ gặp người đẹp, buôn bán sẽ được trúng\nmối mang, bắt đầu thu hoạch lợi lộc.", "s": "99, 9, 19, 29, 90."}, "10": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Trạch Lý", "line_label": "Động Hào Tứ", "p": "Liêu lệ chinh hồng đôc xuất quan,\nCao phi vũ dục cánh nhan nhan.\nNam chinh bắc tiến, hỏa gia tranh đấu,\nTriều vân mộ vũ, ân giao hữu nhạt.\nCô hồng xuất chúng vút bay cao,\nPhấn khởi nương mây chí khí hào.\nHướng Bắc đường xa tin sẽ lại,\nNhờ nơi giúp rập toại đường bao.", "b": "Công danh phú quý, có cần khổ mới có được. Hoàn thành công việc mình thì hoàng thiên ắt chẳng phụ ta.\nTrái lại, nếu dục vọng nhiều mà biếng nhác quen thân, hoặc trước siêng sau nhác thì chắng khác nào mui\nxe ở bắc mà trục bánh xe ở nam vậy.\nQuẻ này tốt lắm, thời vận đến lúc hanh thông rồi vậy. Quẻ cho biết rằng: Người tuy là cô đơn, nhưng là kẻ\ncó tài, nên nay lại được xuất chúng. Có thể bay cao chơi xa, tất cả sự cầu mưu đều được may mắn toại\nlòng. Phủ khứ thái lai đấy.\nNhưng có điều hãy nên lưu ý, theo ý quẻ hướng làm ăn thuận lợi về hướng bắc hơn,như trong câu thơ thứ\n3 nói: Hướng bắc đường xa tin sẽ lại, đó là ám chỉ đại lợi về hướng Bắc vậy.\nQuẻ dạy: Cầu mưu, cầu tài nên tìm về hướng Bắc cầu tài đạt mười phân vẹn mười. Biểu tượng chim: chim\nHồng.", "g": "- Có tài xuất chúng mà chưa gặp thời. Nên đi về hướng Bắc sẽ gặp điều may mắn đang chờ.", "s": "1, 10, 100, 11, 21, 31."}, "11": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Trạch Lý", "line_label": "Động Hào Ngũ", "p": "Vô tung diệc vô tích,\nViễn cận quan nạn mịch.\nBình địa khởi phong ba,\nTự tiêu hoàn thành khap.\nLưng treo đao kiếm thanh cao.\nBước vào cung điện lạy chào đế vương,\nĐảm đương công việc phi thường,\nTrăm ngàn rèn luyện, đường đời mới nên.", "b": "Quẻ này chủ có cái lo chết chóc tan thương, cái buồn khóc lóc bi ai. Mọi việc đều bất lợi, có danh mà\nkhông có thực. Đã thế mà còn những tai biến phi thường. Người xin được quẻ này cần biết giới căn lúc\nnào cũng lo tu tâm để mong giải bớt tai họa.\nÝ quẻ cho hay rằng hiện hoàn cảnh của con người, lưng treo đao kiếm nghĩa là có quyền cao đó, và ra vào\ncửa cổng. Nhưng muốn thành đạt sự nghiệp cần trải qua trăm ngàn rèn luyện thử thách nữa mới nên.\nNhư vậy sự cầu xin của người. Trong giai đoạn này chỉ có tiếng mà chưa có miếng. Nếu muốn thành đạt\nđược sở cầu phải cố gắng trên đường đời thì mới mong.\nTuy tốt nhưng chưa hẳn là tốt, tuy ở giai đoạn vinh sang, nhưng chưa có quyền thực lực. Cần cố gắng ra\nsức và rèn luyện tri thức, may ra mới có tương lai hơn bây giờ. Tính chuyện may rủi khá hạp. Cầu danh,\ncầu lợi và tình duyên đều tốt.", "g": "Mọi việc bất lợi .", "s": "1, 10, 11, 21."}, "12": {"c": "HẠ HẠ", "hexagram": "Thiên Trạch Lý", "line_label": "Động Hào Lục", "p": "Thần ảm ảm,\nỶ du du.\nThu khước tuyên,\nMạc hạ câu.\nPhần buồn ý lại sầu.\nCòn biết làm gì đâu.\nTa hãy rút dây mất.\nCá nào mà thả câu.", "b": "Quẻ này khuyên ta chớ vọng tưởng, chỉ nên giữ gìn cẩn thận để tránh tai họa, và tránh chuyện thị phi. Nếu\nkhông nghe lời răn ắt xảy ra chuyện lầm lạc tội lỗi, hối thì đã muộn.\nTheo ý quẻ nói, hiện nay vận tình của bạn còn xấu xa lắm, chưa thấy may mắn chút nào như công việc\nmưu cầu, nên ngừng lại chờ thờ tốt hơn, nếu có làm tới e rằng sẽ bị tổn hao không thì cũng phí sức hao\ncông chứ chẳng lợi gì.\nQuẻ dạy: Xấu! Nhẫn nhẫn chờ thời Hai câu sao rất dở đi câu bị mất dây thì cá làm sao ăn? Cầu mưu cầu\nlợi chẳng thông chút nào đánh số chẳng hạp. Biểu tượng lả cá. Chỉ cầu may chút thôi.", "g": "mọi việc tạm dừng lại để tránh những việc đáng tiếc có thể xảy ra, có hối cũng không kịp.", "s": "10, 11, 22,\n2, 12, 20."}, "13": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Hỏa Đồng Nhân", "line_label": "Động Hào Nhất", "p": "Đắc ý nghi phung phụ,\nTiền trình khứ hữu duyên.\nLợi danh chung hữu vọng,\nTam ngũ nguyệt đoàn viên.\nCông thành nghĩ lại chuyện xưa\n\"Ở thì ăn xổi\" lọc lừa nên khi\nDuyên may ắt gặp còn chi\nTrăng tròn danh lợi định kỳ vàng son.", "b": "Quẻ này chủ: mưu việc ắt thành, mọi việc đều có duyên may. Kén vợ thì được vợ đẹp, tìm việc thì được y\nviệc hay. Trong cuộc trò chuyện, lập tức thành công, đấy mới gọi là người lành được trời giúp. Năm ba\ntháng ý nói cái ngày tốt đẹp gần kề.\nQuẻ này khá lắm. Cầu mưu việc gì chẳng hề lo ngại, nhất là cầu xin về duyên nợ và tài lộc, chắc chắn\nthành đạt toại lòng. Nhưng một khi công thành rồi, nên nhớ lại cảnh cũ ngày xưa, mà ừng nên ăn xổi ở thì\nquên những ngày cay đắng cũ, mà ăn ở sao cho phải đạo làm người mới được. Được như vậy, cảnh giàu\nsang, phú quý sẽ được vững bền lâu.\nÝ quẻ khuyên nên ăn ở đạo đức thì sẽ gặp duyên may. Tuy cũng cần chờ đợi khi trăng sáng tròn mới\nmong thành\nQuẻ dạy: tốt, cầu danh đắc danh, cầu lợi đắc lợi. Thời vận đã đến lúc hanh thông. Chẳng còn lo gì lận đận\nvề sau nữa . Tuy nhiên cần giữ gìn lòng đạo đức, chớ theo phường “Có trăng rồi lại phụ đèn”. Cầu tài, cầu\nlợi thông. Tính chuyện rủi may rất hạp.", "g": "Tốt, lưu ý những ngày tháng mang số 3, số 5. Có thể gặp gỡ hoặc có tin vui.", "s": "3, 11, 33, 13, 10, 30."}, "14": {"c": "HẠ HẠ", "hexagram": "Thiên Hỏa Đồng Nhân", "line_label": "Động Hào Nhị", "p": "Đỉnh phi khởi phong ba,\nCô chu yếu độ hà.\nXảo trung khước tàng chuyết,\nNhân sự chuyên tha là.\nNước đèo đổ động phong ba\nThuyền nan một mảnh giang hà muốn sang.\nKhó khăn lắm chuyện nguy nan.\nKhông điểu xảo, cũng gian nan một chèo.", "b": "Tránh dữ tìm lành, đó là thường tình của nhân thế. Nếu một ngày nào đó gặp phải biến cố, tất nhiên ta\nphải khôn khéo tránh dữ tìm lành. Sống trong biến cố, chẳng phải mình ta tự cảm thấy bất an mà đến cả\nmọi người cũng đều lo lắng giùm ta. Việc người lần lửa chứa cái ý khuyên răn sau đó.\nNgười xin được quẻ này không nên tránh gian hiểm, cần phải cố gắng chống chọi quyết liệt với nguy cảnh\nlà khác.\nNgười cầu xin được quẻ này, không được may mắn lắm. Phàm việc cầu mưu khó tránh điều trắc trở, nguy\nnan, nhất là về việc xin sở làm càng khó lòng vừa ý.\nÝ quẻ dạy rằng: Công việc cầu xin kkhó mà thành công, nếu cố mà làm sẽ gặp nguy nan và những điều\ngian hiểm, nên bình tĩnh mà chờ thời thì tốt hơn.\nQuẻ dạy: Xấu! Chớ tính toán. Gặp nhiều gian, mà chẳng nên công gì. Hoàn cảnh đang rắc rối. Cần ẩn\nnhẫn chờ thời, thì tốt hơn hết. Cầu tài, Cầu danh chẳng thông. Tính chuyện may rủi lại càng đỡ hơn. Nếu\nchờ đợi xin quẻ khác.", "g": "Không tốt. Đề phòng cây bị gió to thổi bật rễ. Nếu hỏi về hôn nhân, hoặc tìm cầu người thân, mịt\nmờ ai biết được, chờ đợi biết bao lần.", "s": "10, 4, 44, 11, 40. Vì quẻ xấu, chớ nên tin tưởng lắm."}, "15": {"c": "HẠ TRUNG", "hexagram": "Thiên Hỏa Đồng Nhân", "line_label": "Động Hào Tam", "p": "Ý tại nhân trung tín vị lai,\nCố nhân thiên lý tự bồi hồi.\nThiên biên nhạn túc truyền tiêu tức,\nNhất điểm mai hoa xuân sắc hồi.\nNóng nảy chờ tin, tin chẳng lại,\nCố nhân dịu viễn cách trùng quan.\nNhạn về tin báo mai vàng nở,\nXuân đến hồng lên ngập ngút ngàn.", "b": "Quẻ này chủ cái tượng: trầm trệ đã lâu, khốn quẫn nhiều ngày nhưng sắp được hạnh thông. Tuy vật song\nsong cũng phải đợi đến mùa mai nở thì lúc đó mới có tin vui. Người xin được quẻ này nên chờ đợi ít lâu,\nđừng nóng lòng vội tiến.\nNhững sự cầu xin của bạn vẫn chưa chút tia sáng nào tất cả sự trông chờ vẫn còn nơi xa, nhưng bạn hãy\nchờ một thời gian nữa sẽ được toại nguyện mai sau, như câu thứ tư, ba trong quẻ nói: \"Nhạn báo Mai nở\nxuân sắp về\".\nÝ quẻ dạy: Chờ đợi và nhẫn nại thì tốt hơn, vì chờ tin, thì tin chưa lại, cố nhân vẫn còn lẩn quẩn nơi xa.\nQuẻ dạy: Ẫn nhẫn chờ thời. Công việc tính chưa tiện vì quý nhân, hay người bảo bọc còn ở xa thì làm sao\ngiúp bạn được. Tuy nhiên, cũng gần đến lúc thời vận tốt chỉ chờ vào mùa Thu, mùa Xuân, ắt đắt quả đạt\nthành. Biểu tượng nhạn hay chim. Cầu tài chưa toại mấy.", "g": "mọi việc mong chờ đều có thể được, rán nhẫn nại chờ thêm ít lâu nửa xem.", "s": "11, 50, 55, 5, 10."}, "16": {"c": "TRUNG THƯỢNG", "hexagram": "Thiên Hỏa Đồng Nhân", "line_label": "Động Hào Tứ", "p": "Tâm hòa đồng,\nSự hòa đồng.\nMôn ngoại hảo thi công,\nGiao gia sự hữu chung.\nViệc nào việc nấy hiệp hòa\nĐùa vui cười nói thật là thảnh thơi,\nTin này tùy ở nữa trời,\nThong dong bước tới cuộc đời vinh quang.", "b": "Cùng hội cùng thuyền, cùng lòng cùng giúp, hễ ra khỏi cửa là có công, đó là cái tượng của quẻ này. Người\nxin được quẻ này chớ nên ít kỹ hại nhân, cũng chẳng nên duy ngã độc tôn, nếu không, thì đầu cọp đuôi rắn\nquyết không thể có lợi lộc được.\nÝ quẻ cho biết rằng: Việc cầu xin của bạn ắt được vừa ýtrong mai sau. Bởi quẻ đã cho người rất rõ, hiện\nnay mọi việc đều được hòa hiệp, đàm tiếu chơi vui, nghĩa là hiện tình cảnh đã dễ chịu lắm rồi. Nếu cứ\nthong dong tiến tới nữa, thì sẽ hạnh phúc cuộc đời.\nDo những lời phán xét của quẻ, thì sự cầu xin của bạn tuy còn hơi xa vời, nhưng rút cuộc đạt đến mục tiêu\ntốt đẹp. Nếu theo đúng lời khuyên của quẻ thong dong bước tới.\nQuẻ dạy: Thời sắp đến, Nên gắng sức ắt thành công. Cầu tài tuy nhiên đạt nữa phần. Cầu danh còn đợi dịp\nmột chúc. Cần chờ đợi chớ nóng nảy.", "g": "Được quẻ nầy, những gì chưa hợp sẽ được hợp.", "s": "60, 11, 16, 66, 10."}, "17": {"c": "HẠ TRUNG", "hexagram": "Thiên Hỏa Đồng Nhân", "line_label": "Động Hào Ngũ", "p": "Dục hành hoàn chỉ,\nBồi hồi bạt dĩ.\nTàng ngọc hoài châu,\nThốn tâm thiên lý.\nMuốn đi sao lại ngập ngừng,\nChi mà quanh quuẩn lừng chừng nghĩ sao,\nĐã từng nuôi dưỡng chí cao,\nHùng tâm ngàn dặm ai nào rút lui.", "b": "Quẻ này khuyên ta nên cẩn thận làm đầu. Phàm công việc thường kéo tới bề bộn ngổn ngang, ta cần phải\nxét tín cẩn thận mà tiến lui. Nếu ta không cẩn thận, liều lĩnh hành động thì có khác chi ném ngọc quăng\nchâu xuống vũng lầy, và như thế thì tránh sao khỏi tự bạo, tự khí. Coi chừng đấy.\nÝ quẻ nói rằng: phàm mưu tính việc gì, phải quyết chí một lòng tiến tới, nhất là đã nuôi mộng cao đẹp, thì\ncàng phải kiên quyết hơn, nếu không, công lao nữa chừng, và sẽ tốn của hao sức chẳng nên gì cả.\nVậy những việc mưu tính của mình, phải theo ý nguyện để tiến tới, ắt sẽ toại lòng, xưa có câu \"Hữu chí\ncảnh thành\".\nQuẻ dạy: Chớ chần chừ, cứ tiến tới ắt thành công. Đừng sợ thất bại. Thất bại là mẹ của thành công, lo gì.\nHơn nữa, quẻ tốt chớ không xấu. Cầu tài, cầu danh, cần cố gắng.", "g": "Đang ngon trớn bổng khởi lòng nghi, trù trừ do dự. Mau hạ quyết tâm, hoàn thành nghiệp lớn.", "s": "77, 7, 17, 11, 10."}, "18": {"c": "HẠ HẠ", "hexagram": "Thiên Hỏa Đồng Nhân", "line_label": "Động Hào Lục", "p": "Tâm thích thích,\nKhẩu thu thu.\nNhất phiên tư lự nhất phiên ưu,\nThuyết liễu hưu thời hậu bất hưu.\nLòng xa xót, ý bơ thờ!\nThan thầm trong dạ, hững hờ lòng ai.\nSuy tư đã lắm ưu hoài,\nChẳng ra manh mối lạc loài hư không.", "b": "Quẻ này chủ vừa lo được vừa lo mất, chẳng khác gì con ngựa con quyến luyến giàn đậu non, chẳng có\nhành động quả quyết, cho nên uổng phí cả tâm trường, chỉ mua lấy phiền não mà thôi.\nTheo quẻ thơ cho biết, người cầu xin được quẻ này, hiện tâm tình rất lo âu cho việc đang mưu tính vô\ncùng. Bởi công việc quá rắc rối, nên rất buồn lòng phẫn trí. Vì vậy, người xin được quẻ này mà sự cầu\nmong hiện đang lưng chừng và hơi khó thành. Nhưng riêng tôi lại khuyên người rằng \"Thế gian vô nan sự,\nchỉ sợ chí không kiên\".\nQuẻ dạy: Xấu. Mọi sự tính toán đều hư hỏng, chỉ nên chờ đợi. Tuy nhiên, dù sao ta cũng phải cố gắng tính\ntoan chứ không phải làm như Đại Lản chờ sung \"Có chí thì nên\". Cầu danh, cầu lợi còn xa. Tính chuyện\nrủi may không hạp mấy.", "g": "Bất lợi. Kết quả khó chờ mong.", "s": "88, 8, 18, 11."}, "19": {"c": "TRUNG TRUNG", "hexagram": "Thiên Lôi Vô Vọng", "line_label": "Động Hào Nhất", "p": "Bất viễn bất cận,\nTự dị tự nan.\nĐẳng nhàn nhất sự,\nVân trung tiếu khan.\nÝ xa mà lại như gần,\nÝ gần mà lại như gần như xa.\nDễ như mà lại khó hòa,\nTrông mây cười nu ïkhi mà tin sang.", "b": "Quẻ này chủ bất cứ nghi nan nào dù xa gần, dù khó dễ, thảy đều phải do chính ta chủ trương lấy. Song,\nnếu ta chịu khó tìm hiểu cơ huyền của tạo hóa thì càng dễ dàng trong việc giải quyết công việc. Cười nói\nngâm trong mây ngụ ý nói lúc đắc thời đắc ý.\nNhững việc cầu xin ở đây, thấy dễ nhưng chẳng dễ, tưởng khó nhưng mà chẳng khó. Cần phải chờ dịp\nthuận tiện thì mới thành tựu.\nVậy xin được quẻ này, phải tính toán cho kỹ về việc sở cầu và chờ đợi một thời gian nào đó, đừng quá vội\nvả mà hư hại công việc đang cầu xin. Ý quẻ dạy rằng: Chờ đợi đến lúc thuận dịp sẽ thành, việc tuy dễ mà\nlại khó, tuy khó mà lại dễ. Dễ khó, hay khó dể đều do tài mình và nơi hoàn cảnh thuận tiện đưa đẩy mà tạo\nnên.\nQuẻ dạy: Do ở tài mình, và trí lực của mình. Cương cầu cũng vô ích, nếu ta không đủ tài. Quẻ không hoàn\ntoàn tốt, mà cũng chẳng hoàn toàn xấu. Xấu tốt, tùy ở hành động của ta. Cầu tài, cầu mưu tuy chậm,\nnhưng cố thì thành.", "g": "Trung bình , kết quả hay không là do sự phấn đấu nỗ lực của mình.", "s": "99, 9, 19, 10, 90."}, "20": {"c": "HẠ HẠ", "hexagram": "Thiên Lôi Vô Vọng", "line_label": "Động Hào Nhị", "p": "Đào Lý tạ xuân phong,\nTây phi hựu hậu đông.\nGia trùng vô ý tự,\nThuyền tại lãng đào trung.\nĐào Lý tạ, gió xuân đưa,\nĐông Tây tản mác hương thừa hết vương.\nTrong nhà không có chủ trương,\nNhư thuyền một mảnh tang thương ba đào.", "b": "Quẻ này bói sự nghiệp bất lợi, bói bệnh tật bất định, bói hôn nhân vô hy vọng, bói ra đi bị ngăn trở, bói\nkiện tụng lành ít dữ nhiều, đó là cái tượng thăng trầm thôi nổi, không tốt đẹp thanh thản gì. Người xin quẻ\nnày phải hết sức tu chính mới được.\nNgười cầu xin được quẻ này, nên phải cẩn thận công ăn việc làm. Và khó thành đạt toại nguyện trong\nnhững việc cầu mưu. Bởi hoàn cảnh thời vận của bạn hiện đang như cây lý chào biệt gió xuân, như chiếc\nthuyền đang gặp sóng gió. Vậy đã cho ta thấy rằng còn gì gọi là may mắn!\nHơn nữa thơ quẻ còn tả cảnh người thêm rằng: Trong nhà không chủ trương, bay chạy đông tây. Đó là ý\nnói người sầu buồn và vất vả vô cùng vậy.\nQuẻ dạy: Chớ tính toán vô ích thời chưa đến thì dù cho tài mấy, cũng như cá mắc cạn. \"Bôn Ba Chẳng\nQua Thời Vận\". Suy cho kỹ, nghĩ cho cùng, chờ dịp thuận lợi hãy hay. Cầu tài, cầu mưu đều bất thông.\nKhông mấy hạp cho việc tính chuyện may rủi. Vì quẻ quá xấu.", "g": "Trồng trọt chẳng đúng tiết, phiêu lưu không chắc ăn, đi xa đâu có lợi, trong nhà nổi phong ba.", "s": "22, 2, 12, 32, 20."}, "21": {"c": "TRUNG TRUNG", "hexagram": "Thiên Lôi Vô Vọng", "line_label": "Động Hào Tam", "p": "Nhật thủy viễn nhất thủy,\nNhất sơn tuyền nhất sơn.\nThủy cùng sơn tận xứ,\nDanh lợi bất vi nan.\nNước non non nước dặm ngàn,\nNon càng quanh quất, nước càng mênh mông.\nĐến nơi non nước tận cùng,\nCông danh tài lợi hanh thông khó gì.", "b": "Quẻ này chủ trải khắp mọi gian hiểm mới có thể cáo thành. Tuyệt địa phùng sinh cuối cùng mới tới được\nthôn đầy liễu, am hoa minh. Do đó, ta mới thấy rằng cùng khốn mới làm đẹp được ta, nhẩn nhục mới\nluyện được chí cho ta.\nNhững việc cầu xin của bạn lúc bắt đầu ắt phải gian nan khổ cực. Song nếu là người dốc lòng bước tới,\nchung quy sẽ được toại nguyện, chớ không đến nỗi làm cho người thất vọng đâu.\nBởi ý quẻ có mách người rằng: Đến nỗi non nước tận cùng, danh lợi ắt chẳng khó gì. Vậy lo chi bạn\nkhông thắng lợi cuối cùng. Nhưng tôi khuyên bạn hãy kiên nhẫn và cố gắng bước tới, đừng nửa đường\nnản chí, thành công sẽ về với bạn.\nQuẻ dạy: Cố gắng ắt đạt thành công. Cầu danh, tuy chưa thông buổi này, nhưng về sau ắt đạt, chỉ cần có\nchí kiên nhẫn. Cầu tài hơi chậm. Tính chuyện rủi may có hạp 1 phần.", "g": "Hãy cố gắng làm hết sức mình, kết quả tốt đang chờ.", "s": "20, 21, 11, 22, 10."}, "22": {"c": "TRUNG TRUNG", "hexagram": "Thiên Lôi Vô Vọng", "line_label": "Động Hào Tứ", "p": "Sự tương phù,\nTại bán đo.\nPhiên phúc chung khả miên,\nPhong ba nhất diêm vo.\nNửa đường được sự giúp nhau,\nĐừng nên áy náy lo rầu làm chi.\nGió mưa tắc nẻo chẳng gì,\nBa đào êm lặng, vậy thì yên vui.", "b": "Quẻ này chủ bỉ thử tương trợ nhau, không có việc gì là không xong. Người chính nhân quân tử một lòng\nthành kính cùng nhau tương thân tương trợ, không bao giờ có cái lo lật lọng trắng đen, điều gì cũng thuận\nbuồm xuôi gió, chén chú chén anh.\nÝ quẻ cho hay rằng: Việc cầu xin của bạn, tuy chưa được toại nguyện tức khắc, nhưng dần dần sẽ thành\ncông tốt đẹp.\nNhư lời thơ quẻ nói: Nửa đường được quý nhân giúp đỡ, dù vấp phải những khó khăn gì, cũng sẽ vượt qua\nđược, dù cho gặp gió mưa cũng chẳng sao, và rốt cuộc cũng không có sóng gió nổi dậy làm cản trở bước\ntiến của ta. Vậy hãy cố gắng đến bến vinh quang.\nQuẻ dạy: Có quý nhân hỗ trợ, lo gì chẳng nên công. Gặp gian nan buổi đầu sau sẽ hanh thông. Chỉ cần cố\ngắng ắt đạt thành. Cầu danh, cầu tài có kẻ giúp. Chớ lo.", "g": "Trước mắt khó khăn, không quá nguy hiểm, an tâm đi tới.", "s": "20, 22, 2, 12."}, "23": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Lôi Vô Vọng", "line_label": "Động Hào Ngũ", "p": "Hỉ, hỉ, hỉ,\nXuân phong nhập đào lý.\nBất dụng cưởng ưu tiên,\nNguyệt minh nhan thiên lý.\nVui thay ôi, lắm vui thay!\nXuân xanh Đào, Lý, đêm ngày hồng tươi.\nLo âu gì, cái nỗi đời,\nDặm ngàn trăng sáng một trời hoàng huy.", "b": "Quẻ này chủ bỉ cực thái lai, từ chổ khốn quẩn trở về. Cố nhân từ ngoài xa muôn dặm đem hết tâm lực để\ngiúp ta, khiến mọi việc của ta đều được thuận lợi toại lòng. Như vậy thì là tất cả ta phải lo lắng buồn rầu,\nchỉ tổ khổ thân ta mà thôi.\nNgười xin được quẻ này rất là tốt phước. Cầu gì được nấy, muôn việc như ý, nhứt là xin cầu về tình duyên\ncưới gả, nhưng phải nhớ tu tâm tích đức thì mới nên sự nghiệp.\nQuẻ dạy: Tốt đẹp vô cùng. Cầu được ước thấy. Sự hanh thông. Cầu danh đắc danh, cầu lợi đắc lợi. Hoàn\ncảnh đang gặp đại vận hanh thông như cảnh phong vân gặp hội. Tính chuyện rủi may càng hạp hơn. Số\nhên: 33, 22, 23, 3, 2.", "g": "Tin mừng đã đến, người xưa bình an không sao Bệnh hoạn sẽ lành, hôn nhân sẽ hợp.", "s": ""}, "24": {"c": "HẠ HẠ", "hexagram": "Thiên Lôi Vô Vọng", "line_label": "Động Hào Lục", "p": "Ý kiết kiết,\nTâm thích thích.\nYếu bình an,\nPhòng xuất nhập.\nÝ buồn biết tính gì đây,\nCho thêm xót dạ, cho khuây ý tình.\nMuốn yên chớ có đăng trình,\nMà thêm gian khổ phận mình đắng cay.", "b": "Người xin được quẻ này hãy an tâm, an phận thủ kỷ, đề phòng cẩn thận lúc ra vào. Buôn bán thì chớ có\nđấu lưng cân nhẹ. Học trò thì chớ có khinh thánh miệt hiền. Làm quan tại triều thì chớ có tham lam hối lộ.\nỞ nơi nhà quê thì chớ có gây gổ đấu tranh. Tóm lại cần có một thái độ vô cùng thận trọng việc xử thế tiếp\nviệt.\nTheo ý quẻ cho biết, hiện nay hoàn cảnh của người rất là buồn phiền, đang lâm cảnh lúng túng. Do đó, tất\ncả công ăn việc làm của bạn cần nên cẩn thận, nhứt là đi xa không tốt, và thận trọng đừng làm những\nchuyện xa với sức mình, mà nên an phận chờ thời là tốt hơn.\nQuẻ dạy: Mọi sự bất thông. Làm đâu hỏng đó. Đi xa còn gặp nguy. Chẳng lợi mà còn hao tổn tâm cơ, tiền\nbạc là khác. Chỉ nên ẩn nhẫn chờ thời là tốt nhất. Cầu tài bất thông. Chưa thuận dịp. Xấu lắm.", "g": "Giữ gìn lời nói, cẩn thận việc làm, ắt được an ổn.", "s": "20,\n44, 22, 4, 24."}, "25": {"c": "HẠ HẠ", "hexagram": "Thiên Phong Cấu", "line_label": "Động Hào Nhất", "p": "Kiến bất kiến,\nDã phòng nhân hội diện.\nNgộ bất ngộ,\nĐao đê vô bằng cứ.\nHư không, vô ích, vô tăm,\nGiả chân, chân giả chớ lầm mà nguy.\nPhòng người trở mặt thị phi,\nKhông bằng, không chứng làm gì mà mong.", "b": "Quẻ này chủ mệnh kệt thời xui, bị bọn tiểu nhân giởn mặt. Mất vật thì khó tìm. Lục giáp thì thiếu an lành.\nTa nên ăn ở mực thước, hành động hợp lý để may ra khỏi vạ.\nQuẻ này không được may gì, mọi sự cầu mưu khó được vừa ý và càng nên đề phòng tiểu nhân. Tốt hơn là\nphải giữ mình, ít giao du để tránh những việc không may đưa đến.\nBởi quẻ ý có cho hay như trên, nên sự cầu xin của người phải cẩn thận và tính toán cho kỹ. Chớ nên nóng\nnảy gấp gáp tiến hành thì hỏng.\nQuẻ dạy: Phòng ngừa tiểu nhân xấu thời vận bất tề. Nên ẫn nhẫn chờ thời là tốt. Dù cố gắng đến mấy,\ncũng khó mong, vì có kẻ phản bội, thọc gậy. Phòng thị phi quan sự. Cầu tài cầu danh còn xa vời, tính toán\nđỏ đen càng không hạp.", "g": "Đề phòng mũi tên bắn lén từ hướng Tây tới. Điều đang thắc mắc đó, chẳng phải lo âu nữa.", "s": "5, 2, 55, 22, 25."}, "26": {"c": "TRUNG HẠ", "hexagram": "Thiên Phong Cấu", "line_label": "Động Hào Nhị", "p": "Nhất phiên đài lý nhất phiên xuân,\nThùy thức đương sơ khí tượng tan.\nLâm hạ thủy biên tầm hoạt kê,\nKiến sơ lỉu lỉu xứng tâm tình.\nCây tươi là một lần xuân,\nNhưng ai biết được nghĩa xuân là gì?\nSanh nhai rừng núi đặng chi,\nBao giờ thấy rõ việc thì mới hay.", "b": "Quẻ này chủ tiến chẳng bằng lui, hành chẳng bằng tàng, giàu chẳng bằng nghèo, đạt chẳng bằng cùng bất\ncứ lúc nào, bất cứ nơi nào, nếu ta giữ được thái độ điềm đạm thì tức là giữ được tư cách của ta và hạnh\nphúc của ta. Ngư tiều nong pho, đây là những lối sống có thể giúp ta an cư. Phú quý tôn nghiêm, ngày nay\nđâu có còn so sánh được với ngày xưa.\nÝ quẻ nói rằng: Tình đời thường hay thay đổi. Chẳng ai đoán biết trước sự may rủi của nó. Nhưng một khi\ntrông thấy sự thực rõ ràng rồi thì lúc đó mới tỉnh ngộ. Vậy thì cầu xin của người, đừng tin nơi người mà\nhãy tin nơi ta. Tất cả sự việc mưu cầu, nên thận trọng.\nQuẻ dạy: Vừa phải, tin nơi lòng ta và tài ta là hơn. Mọi sự sở cầu đều chậm chạp, chưa ra gì cả. E rằng còn\nnên công, cần chờ thời vận là tốt. Bôn ba chẳng lợi gì. Cầu danh cầu tài không lợi. Còn hơi xa vời. Tính\nviệc may rủi khó có may mắn.", "g": "Có thể nhậm chức mới. Nên kinh doanh nghề rừng hoặc thủy sản. Trị bệnh nên đổi thầy thuốc\nkhác hoặc đến chỗ có núi sông mà tịnh dưỡng.", "s": "66, 26, 22, 6, 2."}, "27": {"c": "TRUNG HẠ", "hexagram": "Thiên Phong Cấu", "line_label": "Động Hào Tam", "p": "Mạc quái ngã kiên thác,\nTâm tính tự thành kha.\nThiên tịch bất thông tâm,\nChân nhân khước bát ma.\nẦy ơi đừng tưởng ta lầm,\nHiểm sâu gian ác, tại tâm ngược trời.\nỞ ăn hiền đức một đời,\nNgười tiên nào sợ chuyện thời tà ma.", "b": "Kẻ trí ôm ngọc châu ở trong lòng, người thành đạt giữ trúc tại bên sườn. Không bị chịu cái ngu của kẻ\nkhác, không bị mê lầm cái mê muội của kẻ khác, thấy lầm lẩn của đời nên không thể nhầm lẩn, chỉ có\nngười chân nhân mới có những điều chân thực, Người xin được quẻ này chính nhờ đó mà tự quyết được\nđời sống của mình khiến được an lành. Nếu theo ý kẻ khác thì dữ, không lành đâu.\nNgười xin được quẻ này, hãy nên suy tính đường chính, đừng nên mộng tưởng những điều giàu sang bất\nnghĩa thì mới được an lành và khỏi bị ma quỷ cám dỗ trong đời.\nÝ quẻ dạy: Nên ăn ở hiền lành đạo đức ắt sẽ thọ, sẽ sung sướng mà không sợ đến sự trả vay nhân quả\nthảm khốc ở ngày mai vậy.\nLời quẻ dạy: Nên giữ đạo làm người là tốt. Gieo nhân tốt, gặp quả tốt. Gieo gió thì gặt bão. Đó là định luật\nbất biến của tạo hóa. Cho nên mới có câu họa phúc vô môn tự do nhân tự triện. Quẻ không xấu, không tốt\nlắm. Cầu danh cầu tài chưa đạt, đánh số khó nên công.", "g": "Đừng quá cố chấp theo ý mình, mau sửa đổi tánh nết cho đằm (vững vàng) trở lại.", "s": "7, 2, 77, 22, 70, 20."}, "28": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Phong Cấu", "line_label": "Động Hào Tứ", "p": "Lộc mã giao trì,\nNam nhi đắc chí thì.\nHành trình tảo biện,\nVinh quy lạc kỳ di.\nNgựa kia đang trẩy thôi đường,\nNam nhi đang thuở, bốn phương tung hoành.\nLên đường mau, mộng bình sanh\nHồi hương áo gấm công thành nên danh.", "b": "Quẻ này cho biết thời đã tới vận đã sang. Ta hãy nghe tiếng gà gáy dòn là phải dậy ngay chớ có ngồi rốn\nmàhết thời cơ. Rồi một ngày mai áo gấm về làng hưởng phúc mãi tới già lúc đó mới biết cái thời giờ quyết\nđịnh đó là quan trọng.\nNgười cầu được quẻ này thì tốt lắm. Nhứt là cầu xin về việc công danh, thi cử. Nếu cầu về kinh doanh, gia\nđạo, hôn nhân v.v cũng đều được xứng ý, không gì đáng ngại.\nQuẻ dạy rằng: Đang tính việc gì thì nên cấp tốc thực hành đừng để trễ nữa. Cuộc đời đang bắt đầu lên\nhương với cảnh vàng son, hoa mộng đẹp đẽ lắm rồi.\nQuẻ dạy: Tốt đẹp lắm. Quẻ khuyên chớ chần chờ. Tiến tới ắt kết quả đạt thành. Cầu được ước thấy. Vạn\nsự đều thông, cầu danh, cầu lợi đều thông suốt. Đánh số càng hạp.", "g": "- Tốt lành. Nếu đang cầu hoạn lộ công danh ở xa, chắc chắn gặp may.", "s": "8, 2, 88, 22, 80, 20."}, "29": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Phong Cấu", "line_label": "Động Hào Ngũ", "p": "Liễu khước tâm đầu sự,\nTam sinh túc hữu duyên.\nHương văn thập lý quế,\nDi bộ nhập thiên biên.\nĐáy lòng sự việc đã làm xong,\nDuyên nợ tiền sanh kỹ ngộ phùng.\nMười dặm quế thơm tràn nở rộ,\nBước vào trời nọ chẳng hao công.", "b": "Quẻ này chủ vì mình mà chính là vì người, cho nên khi đặc thân lên cõi trên, cõi trời mây cao rộng khiến\nhương thơm bay đi xa hàng mười dặm, phải chăng là đã có túc duyên hương lửa và tự được hưởng cái\ncông quả của chính mình. Người xin được quẻ này càng cần phải làm sao cho lợi ít nhiều hơn nữa, mong\nđáp lại lòng trời.\nÝ quẻ cho biết, tất cả sự cầu xin của bạn sẽ được toại nguyện trong tương lai gần đây. Nhứt là cầu xin về\nhôn nhân thì càng tốt đẹp hạnh phúc vô cùng.\nCầu xin về những việc như công danh, gia đạo, kinh doanh, tiền tài, bịnh tật đều gặp được may mắn và\nyên lành. Chẳng có gì lo ngại.\nQuẻ dạy: Gặp thời cây sắt trổ bông, tốt đẹp vô cùng. Vạn sự như ý sở cầu. Mọi sự hanh thông. Thuận chèo\nmát mái. Cầu danh, cầu lợi đều thành đạt. Đánh số thuận lợi.", "g": "Đại cát đại lợi, nhất là tình duyên nam nữ. Nói đến quế thơm , ý nói đến mùa Thu sẽ tốt đẹp.", "s": "22, 99, 2, 9, 29, 90, 20. Biểu tượng:\nBản quế."}, "30": {"c": "HẠ TRUNG", "hexagram": "Thiên Phong Cấu", "line_label": "Động Hào Lục", "p": "Lục hoàng các bạch liểu đầu,\nTất cánh thành hà tế.\nBất như xu thử tinh thần,\nDo hảo mãi ta chân khí.\nHoạn lộ công danh có nghĩa gì?\nBạc đầu gối mỏi còn nên chi!\nHư không rút cuộc hư không cả,\nDưỡng khí thừa nay chẳng mấy khi!", "b": "Quẻ này cố khuyên ta chớ nên vội vả hành động cố giữ sự yên tỉnh, chớ tham lam tìm đường phải trái, chớ\nliều lỉnh vọng tưởng. Ta phải làm sao giữ được cái tinh thần có hại của ta, bồi bổ được cái nguyên khí vô\ncùng của ta. Người quân tử bói được quẻ này, có thể cầu phúc, kẻ tiểu nhân bói được quẻ này có thể lấy\nđó khỏi vạ.\nNgười cầu xin quẻ này hiện như một ông lão, đầu đã bạc và khí sắc tàn phai, ngày dương oai, điệu võ\nkhông còn nữa. Mà tốt hơn hết là thừa dịp nuôi dưỡng tinh thần để khỏe mạnh tuổi già.\nVậy ý quẻ có ý nói rằng: Nên yên phận, chớ nên cưỡng cầu và cần phải tu tâm dưỡng tính, làm điều phước\nlành, thì mới yên thân hơn.\nQuẻ dạy: An phận thủ thường. Tài ba không có, thời vận cũng không, hay hơn hết nên thủ thường, để tìm\nhai chữ bình an là tốt hơn hết. Dù cho cố gắng mấy cũng chẳng nên công gì. Cầu tài, cầu danh trầm trệ,\nđánh đỏ đen khó trúng.", "g": "Tìm công danh, trắng cả đầu,\nMà danh lợi, chẳng thấy đâu bến bờ.\nMau quay về với nơi xưa,\nCuộc đời làm lại, được nhờ tấm thân.", "s": "3, 30, 33, 23."}, "31": {"c": "TRUNG TRUNG", "hexagram": "Thiên Thủy Tụng", "line_label": "Động Hào Nhất", "p": "Ly biệt gian, tuy bất dị.\nBạn đồng hành, di bất trệ.\nTảo tảo khởi trình,\nMiển tha thất ý.\nKhi xa nhau, chẳng dễ gì,\nLúc cùng đi, chẳng ngại khi đăng trình.\nCứ đi cho vạn ý tình,\nSớm hôm cho trọn nghĩa mình thì thôi.", "b": "Quẻ này cho biết cuộc mưu vi tuy lúc đầu chẳng khỏi trở trệ, nhưng lâu sau vẫn được thuận lợi. Rất nên\ntùy cơ phán đoán mà hành động, chớ có dùng dằng do dự mà lở việc, khiến luôn tuổi già nua, ngồi than\nthân thở phận.\nÝ quẻ dạy rằng: Việc cầu xin của người, bỏ chẳng mà làm thì khó. Vậy cứ cố gắng ráng sức tiến tới đi, để\nkhỏi băn khoăn còn thành công hay thất bại, do Trời an bày cho mà thôi, lo lắng làm chi cho mệt trí.\nTuy nhiên, ta muốn thành đạt việc gì cũng phải cố gắng, bền chí, có kế hoạch và phối hợp hoàn cảnh thì\nmới nên vậy.\nQuẻ khuyên: Cố gắng chớ nản chí, cócông mài sắc, có ngày nên kim, cứ cố sức mình, rồi cũng có ngày\ncũng được hưởng công xứng đáng, lo gì. Cuộc đời là một trường thử thách của con người. Hay dở đều ở\nđó, chỉ sợ không có tài trí, lo gì chẳng nên công. Cầu tài, cầu danh còn chậm. Đánh số hên xui không có\nlợi.", "g": "- Trung bình, muốn lập nghiệp phải có bạn .", "s": "11, 33, 1, 3, 30, 10."}, "32": {"c": "HẠ HẠ", "hexagram": "Thiên Thủy Tụng", "line_label": "Động Hào Nhị", "p": "Lạc chi cực hỉ, ưu tương chí,\nThiên thủy phân minh cát dữ hung.\nTài năng quang đại u chung ám,\nNhật lạc tây sơn phản chiếu trùng.\nSướng quá mức rồi nay sắp rầu,\nĐông tây rõ rệt vui cùng sầu.\nNếu không sáng sủa thì u ám,\nTrời lặn hướng tây còn sáng đâu!", "b": "Điều kiện thuận lợi tới với ta thường không lâu, trái lại điều hoảnh nghịch ít khi ta thoát khỏi. Trời ở trên\nlà tốt nước ở dưới là hung. Người xin được quẻ này bị cái cảnh nghịch lai mà thuận thụ, bị co mà mong\nđược duổi.\nHiện tại cuộc đời thực có vẻ đen tối nhưng lần về sau cũng sẻ được sáng sủa. Y như cái cảnh mặt trời\nchiếu ánh vàng trên nền trời thành một lớp ráng vàng tuyệt đẹp.\nNgười cầu xin được quẻ này, nên phải cẩn thận công ăn việc làm của mình, tiền tài không nên tin người,\nkinh doanh nên giữ mức cũ mà đừng khuếch trương, nhứt là bệnh tật cần nên lưu ý mới tránh được đau\nthương đưa đến. Bởi vì toàn thơ của quẻ không có một lời may mắn hay khuyên dạy điều tránh gì cả.\nQuẻ dạy: Cẩn thận đề phòng mọi việc Cực lạc sinh bi Đó là chuyện thường tình của đời người. Chỉ nên ẩn\nnhẫn và an phận cho qua lúc bỉ là hay. Cầu tài, cầu danh chẳng ra gì. Đánh số chẳng thông.", "g": "Không tốt.", "s": "3, 2,\n22, 33, 30, 20."}, "33": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Thủy Tụng", "line_label": "Động Hào Tam", "p": "Dược quá ba đào tam ngũ lý,\nThùy tri lãng tỉnh hựu vô phong.\nHạnh mong trực tông thanh vạn lọ,\nDụng xả, hành tàng, chẳng phí công.\nMây độ ba đào đã vượt qua,\nGió êm sóng lặn khí ôn hòa.\nĐường mây nhẹ bước ngay thang thái,\nẰt đạt thành, nào phí sức ta.", "b": "Khổ chưa hết thì cam đã về, gió lặng sóng êm, tiến thẳng bước trên đường mây rộng thênh thang. Người\nxin được quẻ này mọi việc đều cát lợi, khỏi lo buồn rầu.\nThơ quẻ cho hay, những việc không hay đã qua rồi, từ nay về sau được bình an vô sự, vận thời hanh\nthông.\nVậy, những việc cầu xin của bạn, dù có trở ngại gì đi nữa, cuối cùng sẽ thành đạt sở nguyện. Cầu tài lợi\ngia đạo, hôn nhân, kinh doanh, viễn du, nhứt là thi cử sẽ thành công vinh quang.\nQuẻ dạy: Tốt đẹp như gấm thêu hoa. Bây giờ là lúc hết cơn bỉ cực đến hồi thái lai. May mắn đến thì chẳng\ncòn lo, mà cũng chẳng phí sức. Thời không đến, thì như cảnh lôi oanh tấn phúc bi?\". Cuộc đời hanh thông\nđến rồi lo gì nữa. Cầu tài, cầu danh đều hanh thông. Đánh số hên xui đắc lợi.", "g": "Trung bình .", "s": "3, 33, 30, 13, 23."}, "34": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Thủy Tụng", "line_label": "Động Hào Tứ", "p": "Nguyệt khuyết hựu trùng viên,\nKhô ghi sắc cánh tiên.\nNhất diều di thản lộ,\nKiều thủ vọng thanh thiên.\nTrăng kia hết khuyết lại tròn,\nCây khô nầy lại xanh tròn xinh thay.\nĐường đi quang quẻ ven mây,\nNgẩng đầu lên ngó, trời nầy xanh xanh.", "b": "Vận hạn tạm thời vẫn còn kẹt, nhưng rốt cuộc vẫn được đạt phát, cuộc đời xinh đẹp như cây khô gặp được\ntiết xuân, rừng rậm được khai hoang. Thật là một cảnh buồn gây ngạc nhiên không nhỏ cho mọi người.\nSong người ta sống ở đời trọng điều nghĩa thì sẻ không lo người không biết đến mình.\nÝ quẻ cho biết: Người cầu xin đang đến lúc thịnh, điều xui xẻo đều đã qua, việc sung sướng và hạnh phúc\nsắp về người, bởi cảnh tình của người, như trăng khuyết lại tròn, cây khô nay lại mọc xanh tươi.\nVậy tất cả sự cầu xin của người ắt được toại nguyện như ý. Nhứt là cầu xin về thi cử và công danh ắt càng\ngặp nhiều may mắn.\nQuẻ dạy: Thời vận hanh thông. Vạn sự như ý sở cầu. Trăng có khi tròn khi khuyết, bèo cũng lúc hợp lúc\ntan thì người cũng có lúc hẩm, lúc thái, đó là chuyện dĩ nhiên của cuộc đời. Bây giờ là lúc gặp vận thái, lo\ngì chẳng giàu sang, vinh hiển. Cầu được ước thấy. Đánh số tốt.", "g": "Tốt lành.", "s": "3, 44, 4, 33, 40, 34."}, "35": {"c": "HẠ TRUNG", "hexagram": "Thiên Thủy Tụng", "line_label": "Động Hào Ngũ", "p": "Hành lộ nan, hành lộ nan,\nKim nhật phương tri hành lộ nan.\nTiền trình quảng đại hà túc lự,\nMiên lực kim triều độ thử than.\nĐường đi khó, khó đường đi,\nĐi đường mới biết những gì khó khăn.\nTương lai tốt, chớ băn khoăn,\nBờ này ráng sức, hãy cần vượt qua.", "b": "Quẻ này chủ mọi việc đình trệ, nhưng nhờ có định thức định lực, bạt thiệp san hà nên mới có ngày đáo bỉ\nngạn (qua bờ bên kia). Phàm những việc mưu tính đạt được thành đạt đều do ở người có chí. Không thể\nngồi phởn ron ăn chơi mà rồi công việc xong được. Đấy là cái nghĩa sâu xa, tế nhị, và quan thiết.\nQuẻ dạy: Đường đi tuy khó, nhưng ta cố gắng vượt qua thì muôn sự khó cũng không thể nào cản bước\nchân ta. Không đáng lo ở sự đường đi khó, mà chỉ đáng lo vì ta bị nhụt chí mà thôi.\nVậy sự cầu xin của người, ắt tránh được điều khó khăn, trắc trở, nhưng cần cố gắng vượt qua, thì sở cầu\nvẫn được thành công toại nguyện.\nQuẻ dạy: Ẫn nhẫn chờ đợi và gắng sức vận thời chưa tới, băn khoăn làm gì? Chỉ nên tích đức, luyện tài\nchờ thời đến thì mặc sức vẫy vùng. Cầu danh, cầu tài còn chậm. Đánh số chưa thông.", "g": "Đang lúc thuận lợi, bổng gặp khó khăn, rồi cũng qua mà thôi.", "s": "5, 3, 33, 55,\n30, 50, 35."}, "36": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Thủy Tụng", "line_label": "Động Hào Lục", "p": "Xuân cảnh minh xuân sắc,\nXuân ý bàng thủy sinh.\nXuân thiên vô hạn hảo,\nHáp khứ yên quỳnh lâm.\nCảnh xuân sáng, sắc xuân tươi,\nÝ xuân đem lại cuộc đời lên hương.\nNgày xuân đẹp đẽ lạ thường,\nTa nên thết tiệc một trường hoan ca.", "b": "Mùa xuân là vạn vật bắt đầu đổi mới. Con người được hưởng ngoạn gió xuân tươi mát, nói rằng: đẹp vô\nhạn, tức là cố lẹ chí khí, biết thừa thời mà hành động.\nNói rằng phó yên Quỳnh Lâm, tức là nói kết quả tốt đẹp, phải tốt. Đó chính là tượng trưng cho cái cảnh\nthịnh vượng chấn phát. Người xin được quẻ này thực hết sức phấn phát rồi vậy.\nQuẻ cho biết rằng: Người cầu được quẻ này rất may mắn vô cùng. Cầu danh sẽ được lên chức, thi cử chắc\nđậu, gia đạo bình an vui vẻ, tiền tài được vừa ý, hôn nhân tình duyên được hạnh phúc và vợ hiền chồng\nsang, kinh doanh thì thuận lợi. Tóm lại thời vận được hanh thông, vạn sự như ý sở cầu.\nQuẻ dạy: Vận thời lên hương. Cầu danh, cầu lợi dễ dàng, xuôi chèo mát mái. Tốt đẹp vô cùng. Đánh số\nhạp.", "g": "sự nghiệp phát đạt , sức khỏe tốt , tâm tình cởi mở , giao du rộng rãi .", "s": "6, 3, 36, 66, 30, 33, 60."}, "37": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thiên Sơn Độn", "line_label": "Động Hào Nhất", "p": "Vạn mã quy nguyên,\nThiên viên triều động.\nHổ phục long giáng,\nĐạo cao đức trọng.\nNgựa dần chung một đường về,\nVượn hầu cùng một sơn khê huy hoàng.\nRồng hầu hổ phục tề toàn,\nTài cao đức trọng huy hoàng công danh.", "b": "Quẻ này chỉ người quân tử, hiền nhân thì danh vọng tất nhiên phải có. Ví thử có kẻ lòng tham, lòng lang\ndạ thú, dèm pha phỉ báng, thì cũng chẳng làm mai một được cái chân tài thực học của họ. Về chuồng, chầu\nđộng, chỉ là những tỉ so sánh với núi Thái, với sao Bắc Đẩu đủ để cho mọi người phải ngưỡng mộ.\nNgười cầu xin được quẻ này thì may mắn vô cùng, trăm việc hanh thông, cầu tài có tài, hôn nhân được vợ\nchồng, làm quan nổi tiếng. Gia đạo vui vẻ, kinh doanh thành đạt, bịnh tật mau khỏi. Tóm lại ý quẻ nói:\nRồng mây gặp hội, công danh vinh quang vậy.\nQuẻ dạy: Tốt đẹp, thời vận hanh thông. Công danh tài lợi vững. Mọi việc đều thông đồng bén đọt, được\ntiến chức, thăng quan. Tài lộc vào như nước. Đánh số hạp mười phân.", "g": "Nên lấy đức để cảm hoá người .", "s": "7, 3, 33, 77, 37, 30, 70."}, "38": {"c": "TRUNG THƯỢNG", "hexagram": "Thiên Sơn Độn", "line_label": "Động Hào Nhị", "p": "Hoàng bằng báo thượng lâm,\nXuân sắc tiên minh.\nĐề tiên khoái trước,\nMã thượng tốc hành trình.\nHoàng oanh đã báo tin mừng,\nXuân tươi sắc đượm tưng bừng non sông.\nBập bùng lên ngựa ruỗi dong,\nĐường mây rực rỡ sự mong công thành.", "b": "Ham vui biếng nhác, ngạo mạn đó là nguồn gốc của sự thất nghiệp. Chè chén say sưa, đó là gốc của sự\nthất thời. Phàm làm việc cần phải sớm, chớ nên dùng dằng do dự. Hãy đứng ngay lên mà đi, mà mưu tính\nxoay sở thì mới có lợi ít được. Người xin được quẻ này chính là đã có một cơ hội phi thăng đằng đạt, rất\nđáng mừng đây.\nNhững sự cầu xin của người, nên sớm kế hoạch tiến hành. Nay đang là hợp thời và vận đến, đừng nên\nchần chờ nữa rồi mất cơ duyên dù xin về bệnh tật cũng mau đi cầu, chớ để chậm trễ thì lại nguy.\nÝ quẻ dạy rằng, bất cứ cầu xin việc gì, hãy mau mà không nên chậm trễ mới nên việc.\nQuẻ dạy: Thời hanh thông đến rồi. Tuy nhiên, chớ chần chờ, nên thực hành gấp đi, để trễ là hỏng. Cầu tài,\ncầu danh đều đắc lợi. Cầu đánh số cũng hạp.", "g": "Mưu tính việc chi, đây là lúc thuận lợi nhất.", "s": "8, 3, 33, 88, 80, 30, 38."}, "39": {"c": "TRUNG TRUNG", "hexagram": "Thiên Sơn Độn", "line_label": "Động Hào Tam", "p": "Đại tứ phóng linh đơn,\nCứu nhân hành vạn lý.\nĐáo đầu đăng bỉ ngạn,\nĐộ quá nhận tiên ban.\nMở rộng con tâm bố đức lành,\nLinh đơn diệu được cứu dân sanh.\nSông mê bến giác khi qua nổi,\nLiệt vị thần tiên sự nghiệp thành.", "b": "Quẻ này chủ đại giác ngộ, có cái nghĩa phổ độ chúng sinh, đưa người tới bờ bên kia, còn mình thì nhập\nvào làng tiên. Mình đã có lòng vị tha mưu việc cho người há rằng mình lại bị trầm luân ở dưới? Người\nlàm việc thiện tự tiện cho rằng có thiện báo, không mất đi đâu mà sợ.\nÝ quẻ dạy: Đạo đức là tất cả, bố đức làm lành cho nhiều ắt được hạnh phúc, thọ trường vì tất cả đều hư\nkhông ngoài cái tâm và cái đức thì tại sao người lại không gieo cái nhân tốt trong hiện tại, để hái cái quả\nlành về sau?\nVậy sự cầu của người nên tính mưu điều phải, và phải cố làm những điều phước đức, thì việc mưu cầu\nmới gặp được quý nhân giúp đỡ mà nên sự.\nQuẻ dạy: Bố đức, làm lành thì tốt mọi việc sở cầu trong tương lai, ắt có kết quả viên mãn. Cầu danh, cầu\nlợi chậm, cần chờ đợi, đánh số hạp vừa phải.", "g": "Hành thiện để cứu người, ắt được quả tốt lành.Thầy thuốc mà gặp quẻ nầy, trở thành danh y.\nThầy giáo được quẻ nầy, sẽ thành thầy giỏi.", "s": "9, 3, 99, 33, 39, 30, 90."}, "40": {"c": "TRUNG HẠ", "hexagram": "Thiên Sơn Độn", "line_label": "Động Hào Tứ", "p": "Nhất đới thủy, bích trừng trừng,\nChu trú giang biên, nguyệt đáo thiên tâm.\nỒn bộ kỳ trung, huyền diệu bất minh,\nPhi nhân ngọ kỷ, cơ tán sinh thần.\nThuyền nan một mảnh giữa dòng,\nTrăng soi lồng lộng bềnh bồng đẹp thay.\nVậy mà ai lại sầu tây,\nCho ray rức dạ, cho cay thân mình.", "b": "Quẻ này chủ nhẹ tin lời người, nhu nhược quả đoán, có cái kiến thức của kẻ ngồi đáy giếng nhìn trời, làm\nnhững việc chụp hình bắt bóng, cho nên xuýt nữa bỏ mạng. Những người xin được quẻ này há lại không\nlấy đấy làm răn?\nNhững việc cầu xin của bạn cần phải tính toán kỹ, đừng quá vội vã mà có hại, hãy nên giữ yên những điều\nlàm ăn xưa nay tốt hơn.\nBởi ý quẻ cho hay rằng: Nước trong trăng sáng, thuyền ở giữa sông là một cảnh rất thơ mộng nhưng người\nkhông chịu hiểu cái hay đẹp của nó mà lại suy tư việc khác thành ra tự mình gieo cái buồn mà thôi.\nQuẻ dạy: Đang có tâm sự buồn. Vận thời chưa thông. Làm ăn chỉ vào mức thường. Quẻ khuyên tùy thời,\ntùy lúc, hãy yên với cảnh hiện tại của mình. Cầu tài cầu danh chưa thông. Đánh số ít hạp.", "g": "Gặp cảnh Tái Ông thất mã , biết là đã kém phước rồi. Mọi việc đang hồi chẳng thuận , tuy chưa\nsụp đổ hẳn, nhưng biết thối lui là hay nhất.", "s": "4, 40,\n44, 14, 24, 34."}, "41": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Càn", "line_label": "Động Hào Ngũ", "p": "Đào lý thư nghiên, xuân quan tiên lệ,\nLương thân mỹ cảnh quan tu ký.\nTùy tâm sở vãng, sự sự tương nghi,\nVô dụng đa nghi, can độc than kỳ.\nĐào lý hoa khai xuân bắt màu,\nNgười nên nhớ cảnh đẹp trời cao.\nTùng tâm sở nguyện muôn điều lợi,\nChớ lại nghi ngờ thần thánh nào.", "b": "Quẻ này cho biết mọi việc đều được xứng tâm toại ý nên kịp thời hành lạc. Tuy nhiên hành lạc nhưng phải\ntri túc mới được. Hôm nay nhàn rảnh an vui đây nhưng ngày mai lại phải cố tâm hoạt động, độc tâm cầu\nđạo, mong chờ các đấng thần linh ủng hộ, trời phật chở che. Sửa mình làm điều thiện đó là điều cần thiết\ntrước hết.\nTheo ý quẻ thơ tả hoàn cảnh hiện nay của người cầu xin rằng thời vận của người hiện như hoa lý đang nở\nrộ, báo hiệu ngày xuân đã về với người. Nghĩa là thời vận đã đến. Cầu mưu hay cầu việc đều nên cả. Cứ\ncố gắng tiến hành ắt được định. Nhưng đừng nên hoài nghi công việc làm của mình, phải kiên chí mới\nnên.\nQuẻ dạy: Thời gần đến kề. Chớ có nghi ngờ tùng tâm thì sở nguyện ắt thành, chớ lo. Cầu danh cầu lợi sắp\nđạt, đánh số hạp.", "g": "Tốt lành. Những dự định trong lòng đều được thuận lợi. Không nên đa nghi mà thiếu tự tin, cô phụ\nân đức của Trời cao ban cho.", "s": "1, 4, 40, 10, 41, 44, 21."}, "42": {"c": "TRUNG TRUNG", "hexagram": "Thiên Sơn Độn", "line_label": "Động Hào Lục", "p": "Ần trung hiền, hiện trung vi.\nCá trung hữu huyền cơ.\nTham đắc thân liễu,\nTrực thượng tiên the.\nMờ lại sáng, nhưng sáng lại mờ,\nTrong kia đ]àng ẩn có huyền cơ.\nAi mà biết được ý tình rõ,\nLên thẳng thang tiên đã sẵn chờ.", "b": "Huyền cơ mà không huyền, đó là cái đạo gốc ở Trung Dung. Thánh hiền Tiên Phật, ai cũng lấy đạo ở\nTrung Dung làm gốc để làm những việc mà trăm ngàn đời về sau còn ngưỡng mộ. Ngoài thường nếu\nmuốn lên cõi tiên, mà lấy đó làm tiêu chuẩn thực cũng chẳng khó gì. Duy có điều chớ nên cho huyền cơ là\nu ẩn khó hiểu, khó đạt, mà đành cam chịu lạc hậu chạy sau người.\nNgười xin được quẻ này, mọi việc mưu cầu đều phải tính toán suy nghĩ cho kỹ, và kế hoạch chu đáo thì\nmới thành đạt về sau.\nBởi theo thơ quẻ nói hiện sự việc đang như một cảnh ánh sáng vào đó không rõ trong đó có rất nhiều bí\nẩn. Người phải tìm hiểu rõ ràng nguyên do của nó mới nên sự việc.\nQuẻ dạy: Cần suy nghĩ cùng cạn làm ăn chưa thông. Cầu lợi chưa đạt. Cầu danh còn chậm, có tính cách\nchờ đợi. Đánh số không hạp.", "g": "Việc đang mưu tính có thể thành tựu, nhưng phải xét kỹ chân tơ kẻ tóc vấn đề, sẽ thấy được “lối\nra” thích nghi, không bắt tay vào việc làm sao thấy được chỗ hay dỡ mà chuyển đổi cho phù hợp ?", "s": "2, 4, 22, 44, 42, 40, 20"}, "43": {"c": "TRUNG TRUNG", "hexagram": "Thiên Địa Bỉ", "line_label": "Động Hào Nhất", "p": "Vô thượng khứ tại tiền đầu,\nHồi đầu nhất ngộ, thắng cương hải thu.\nThiên điều vạn tuyến, lộ thường tại,\nTự hảo sưu cầu.\nĐừng đi tới tại nơi này,\nTrở đầu tỉnh ngộ, kéo dây ngựa cương.\nBiết bao trước mặt nẻo đường,\nTự mình lựa chọn, đo lường mà đi.", "b": "Phải tùy cơ mà hành động, chớ có đợi thời. Xưa nay những nhà hiền triết giữ mình quyết không bao giờ\nchịu để mình chạy vào đất chết. Họ giữ gìn cẩn thận, họ tìm đủ kế sách thoát khỏi cảnh gieo neo nguy\nhiểm, để sửa soạn cho một đường lối mới tốt đẹp hơn. Đây là một điều mà họ cần tới đôi mắt tinh tường\nmới đạt tới được kết quả mỹ mãn.\nÝ quẻ nói: Tìm chi cho xa, tất cả đều ở nơi trước mặt. Và biết bao nẻo đường ngay trong mắt. Muốn đi\nđường nào cứ chọn mà đi. Nghĩa là người muốn cầu xin điều gì hãy tìm hiểu các hoàn cảnh chung quanh\nmà mình từng thấu rõ, phù hợp với phả năng điều kiện của mình chớ nên đặt vọng cao quá.\nTốt hơn hết người dựa vào cái hiện hữu mà cần tiến tới đừng thay cũ đổi mới về việc làm ăn. Còn việc đi\nxa cũng không nên.\nQuẻ dạy: Việc trước mắt không tìm, lại tìm ở đâu. Thời đến không lo nắm ắt sẽ bị vuột. Cầu tài, cầu danh,\ncẩn thận mới hay, đánh số hạp vừa phải.", "g": "Việc đang mưu tính đang có sự lầm lẫn , cần phải sửa đổi hướng khác, sớm tìm ra đường đi tốt.", "s": "3, 4, 33, 44, 30, 40, 43."}, "44": {"c": "HẠ TRUNG", "hexagram": "Thiên Địa Bỉ", "line_label": "Động Hào Nhị", "p": "Tứ cố vô môn lộ,\nĐào Nguyên lộ khả thông.\nTu luyện thành chính quả,\nVạn tuế thọ như tùng.\nDòm ngó bốn phương tắt nẻo cùng,\nChỉ còn đường ngõ đào nguyên thông.\nMuốn thành chánh quả nên tu luyện,\nVạn thọ trường sanh mới phải công.", "b": "Quẻ này chủ họa phúc không cửa, duy chỉ do người rước lấy đó mà thôi. Hãy bỏ con dao phai xuống ngồi\nngay xuống mà niệm Phật, khổ tâm tu luyện, hà tất lại để mình rơi vào vòng tục lụy. Người xin được quẻ\nnày nên biết cái cơ vinh nhục mà tự vận dụng lấy, bất tất phải trách người oán trời.\nTheo ý quẻ cho biết, hiện nay tình cảnh của người, đường đời bước tới cũng như tất cả những điều cầu\nmưu, các ngã đường đi đều bị bế tắc, không ngõ nào đi nữa. Mà chỉ còn con đường đi Đào Nguyên có thể\nthông hành thôi (Đào Nguyên là nơi cảnh tiên) và tu luyện mới có thể thành chánh quả, mới có thể sống\ndai.\nÝ quẻ muốn nói rằng: Người nên cố làm việc phước đức và mưu tính những điều đúng đắn, chớ đặt cao\nvọng quá là hơn.\nQuẻ khuyên: Chỉ nên đi tu, thời vận chẳng mấy thông. Làm ăn phải ẩn nhẫn đợi chờ. Nên an phận thủ\nthừa là hay. Cầu tài, cầu danh vừa phải, chậm. Đánh số hạp chút ít thôi.", "g": "Đang ở giai đoạn trung bình, chớ than thở sao đời chẳng gặp may, chỉ vì tự mình thiếu khổ luyện\nsiêng rèn, lo gì chẳng thành công.", "s": "4, 40, 44, 14, 24, 34."}, "45": {"c": "TRUNG TRUNG", "hexagram": "Thiên Địa Bỉ", "line_label": "Động Hào Tam", "p": "Bất dụng mạng, bất dụng hoang,\nTự hữu túc túc hương.\nMinh cô ưởng chung địa,\nTam bảo hiện môn tường.\nĐừng mê vội chớ hoang mang,\nTự nhiên lại có xóm làng nghỉ ngơi.\nTiếng chuông vang dội chỗ nơi,\nThấy đường tam bửu, tuyệt vời binh thanh.", "b": "Hành động bất cứ một việc gì cần phải hết sức thực tế, chớ nên kiêu hãnh làm liều, có thế thì mới có thể\nan tâm lập nghiệp.\nÝ quẻ thơ nói rằng: \"Hữu xạ tự nhiên hương, hà tất lai cưỡng cầu\". Nghĩa là vội vàng làm chi, tất cả của\ncải ngoài thân mình của ta, số phận ắt phải có, nếu không dù tính toán mưu kế đến đâu cũng là số không.\nCho nên hay hơn là cầu khẩn Thần Phật, tu tâm dưỡng tánh, như hai câu sau của quẻ thơ đã chỉ ra.\nNhư vậy, những việc cầu xin của người cứ tiến hành, nhưng phải cho công việc từ từ. Chớ nên quá vội và\ncưỡng cầu mà hỏng, nhứt là việc cầu mưu hãy theo đường đứng đắn, đừng tính chuyện tà đạo.\nQuẻ dạy: Thời sắp đến nơi, chớ vội mà chi. Thời chưa đến thì bôn ba mấy cũng chẳng ra gì, Đời sắp lên\nhương lo gì. Chỗ bôn chôn sắp đến huy hoàng, sán lạng. Cầu tài, cầu danh sắp đạt thành, đánh số gặp may.", "g": "Mọi việc đang bị đình trệ, nhưng tự mình có cách giải quyết. Rán sức cố gắng, nhất định vượt qua\nmọi trở ngại, tiến đến thành công.", "s": "54, 4, 5, 55, 44, 50, 40, 45."}, "46": {"c": "HẠ HẠ", "hexagram": "Thiên Địa Bỉ", "line_label": "Động Hào Tứ", "p": "Bôn ba nhất thế,\nTống thị hư phù.\nVô thường nhất đáo vạn sự hưu,\nGấp tảo hồi đầu.\nCả đời vất vả thân người,\nĐiều là lận đận cuộc đời hư không.\nMột khi mọi việc đến cùng,\nMau hồi đầu chớ nên mong những gì.", "b": "Nhất âm nhất trác phải chăng do tiền định? Vì con cháu mà phải làm thân trâu ngựa, thì chi bằng trồng cây\nphúc được quả phúc, mong làm đẹp cho hậu thế mai sau. Người xin được quẻ này phải nên mau mau tỉnh\nngộ.\nNgười cầu xin được quẻ này, hãy đề phòng cẩn thận, chớ nên sơ ý mới có thể tránh được những điều\nkhông hay đưa đến.\nBởi vì trong những lời của quẻ, nói rất rõ ràng, không câu nào may mắn tốt đẹp cả, mọi sự cầu xin nên\nphải dè dặt thận trọng và dò dẫm từng bước, đừng nên vội vã có hại.\nQuẻ dạy: Ẫn nhẫn và yên phận thủ thường. Đề phòng mọi người xung quanh và chớ tính chuyện trái đạo,\ntrái lòng, ắt bị nhân quả xấu. Cuộc đời chưa ra gì nên chờ thời cơ. Cầu tài, cầu danh đều chậm. Tính\nchuyện đen đỏ dở.", "g": "một đời đoạt lợi tranh danh, cuối cùng cũng chỉ số không, hãy sớm tỉnh ngộ , quay đầu là bờ.", "s": "6, 4, 44, 66, 46, 40."}, "47": {"c": "TRUNG TRUNG", "hexagram": "Thiên Địa Bỉ", "line_label": "Động Hào Ngũ", "p": "Chân, chân, chân, nhân bất thức,\nChân, chân, chân, thần hữu linh.\nQuy tông phản bản,\nPhương thị nguyên tinh.\nThiệt thiệt thiệt, người chẳng biết mình,\nChân chân chân, quả có Thần Linh.\nHuy hoàng nguồn gốc trở về cội,\nVậy mới xứng là nguyên khí tinh?", "b": "Ngay thực là một đức tốt. Người dù chẳng biết trời đã biết cho, cho nên ở đời, phải chuộng lòng chân\nthành. Chỉ cần có một ý niệm lòng chân thành mà quỷ thần ở chốn u minh cũng đã chứng giám cho mình,\nchẳng có gì đáng ngại.\nNgười xin được quẻ này cần phải chỉ trích phê bình mong thanh toán hết những điều gian dối, lừa lọc để\ntìm sự thật, lấy chân lý. Nhất thiết chớ có dối lừa, bịp người, bởi vì dối người tức là dối mình, bịp đời tức\nlà bịp mình vậy.\nQuẻ nói: Thiệt mà người không hiểu, nên Thần Linh đó phải quy tông hoàn bồn, thì mới là nguyên tinh,\nnghĩa là những việc cầu mưu của người, đã nằm trúng trọng tâm của sự việc, nhưng người chưa tìm được.\nMột phương pháp để đi đến kết quả. Vì sự việc hơi quá phức tạp. Như vậy, những việc cầu xin của người\nnên tùy cơ ứng biến, theo yêu cầu của hoàn cảnh thì sẽ thành đạt ý muốn, và ngược lại sẽ làm cho người\nhao công phí sức. Như câu thứ nhứt của quẻ nói thiệt mà người không hiểu tức là hư không.\nQuẻ dạy: Cần suy nghĩ cân nhắc trước khi hành động. Cố gắng mới nên công.Và làm việc có phương\npháp. Cầu tài cầu mưu chầm chậm một chút. Đánh số cần chín chắn.", "g": "Mọi việc rơi vào chỗ mơ hồ mờ mịt, rẻ vào đường nhánh, nhận ra chân tướng, trở lại đường\nchính.", "s": "74, 47, 77, 44, 7, 4, 40"}, "48": {"c": "HẠ HẠ", "hexagram": "Thiên Địa Bỉ", "line_label": "Động Hào Lục", "p": "Tấu tận thiên thai,\nPhong sương lịch biến.\nBất như vấn nhân tam thiên,\nTiệm tiệm thủ hồi thủ kiến.\nChạy khắp thiên thai chẳng biết đâu,\nThấm cùng sương gió hết nơi cầu.\nThì người thăm hỏi ba ngày đã,\nTự thấy lần lần đuôi với đầu.", "b": "Quẻ này cho ta biết nếu bỏ gần lấy xa thì không có chuyện gì thành cả, chỉ mua lấy khó nhọc vào thân mà\nthôi. Bởi vì rằng thời vận không tới, cầu cạnh lo lắng một cách cưỡng ép thảy đều vô ích. Người xin được\nquẻ này nên minh tâm kiếm tánh, an bần lạc đạo, chớ có ngược lại lòng trời ý người.\nTheo ý quẻ cho hay rằng đi cũng khắp nơi đầy sương gió đến giờ chưa tìm thấy một kết quả nào theo ý\nmuốn và bây giờ chỉ có cách tìm người làm cố vấn cho mới mong thành.\nVậy thì tất cả việc cầu xin cùa người hãy bình tỉnh suy xét im đời và để được có công việc đầu đuôi rồi\ntiến hành mới tránh được những chuyện lầm lẫn và không may.\nQuẻ dạy: Việc đang bế tắc cần có kẻ giúp và làm cố vấn cho mới thành. Tuy nhiên chớ chán nản, chậm\nmột chút mới thành sự, khi đã có kẻ giúp đỡ, tính toán giùm. Cầu tài, cầu mưu chưa đến. Đánh số không\nmấy hạp.", "g": "Mù quáng đi tới , chỉ uổng phí công, hỏi ý người hiền, chỉ lối mới nên.", "s": "8, 4, 48, 84, 44, 88, 40, 80."}, "49": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Đoài", "line_label": "Động Hào Nhất", "p": "Trầm trầm kha nhiên,\nBất kiến thiên tâm.\nLôi môn nhất chân,\nThẻ kiện thân khinh.\nBệnh tình quả thực trầm kha,\nĐất trời u ám hơi hà khổ đau.\nChờ khi sấm sét rồi sau,\nRồi sau mới khỏi mới mau dễ lành.", "b": "Cơ duyên chưa đến nên hoàn cảnh bi đát, nào có khác chi hoàn cảnh của con cá bị kẹt tre bị kẹt trên ruộng\ncạn. Nhưng một sớm thời cơ tốt đến, cuộc đời trở nên tốt đẹp hơn.\nBói được quẻ này, ta cần nên nhẩn nại đợi thời chớ có vội vàng hấp tấp. Khi thời đã tới thì như mây gặp\ngió, như rồng gặp mây bay lên trời thoát hẳn cái cảnh tù túng, khó khăn, trở ngại như trước.\nÝ quẻ nói rằng: Hiện thời vận của người đang như trầm kha trời đất ám mờ chẳng gọi là may mắn. Cần\nphải chờ khi sấm sét vang lên, mây gió tan mất rồi trời đất quang đãng, lúc đó mới nhẹ bước trên đường\nđi.\nNghĩa là những việc cầu mưu của bạn, hiện nay chưa gặp may mắn, thành đạt tức khắc. Cần chờ khi thời\nvận đến thì mới nên công, toại lòng. Vậy hãy ráng sức chịu đựng chờ đợi một thời gian nữa để hoàn cảnh\ntương đối dễ thở mới tính việc tương lai cao đẹp.\nQuẻ dạy: Vận bạn bất thông. Ẫn nhẫn chờ thời. Dù chạy cũng chẳng đến đâu. Chờ qua cơn giông tố, ắt\nmọi việc sẽ định. Đau bệnh kéo dài. Cầu tài, cầu mưu bế tắc, chơi việc đỏ đen càng bất lợi.", "g": "Mắc bệnh lâu ngày may gặp lương y, tức thì lành mạnh. Sự nghiệp, kinh doanh không thuận, nếu\ncó duyên gặp người tài, mới khôi phục lại sự nghiệp.", "s": "9, 4,\n49, 40, 90, 99, 44, 94."}, "50": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Đoài", "line_label": "Động Hào Nhị", "p": "Tài mã lưỡng mang mang,\nQuan lộc hữu định phương.\nTrư dương, ngưu khuyến,\nTự khứ chủ trương.\nTiền tài phú quý lo chi,\nVề điều quan lộc có gì đáng lo.\nHeo, Dê, Trâu, Chó đều cho,\nCho đi lo lấy, ấm no cuộc đời.", "b": "Quẻ này tốt, vì nó chủ việc làm quan gặp vận hạnh thông, tài lộc vài như nước, hết sức giàu sang phú quý.\nTạo hóa an bài đã từ trước không thể khác được.\nÝ quẻ nói: Việc tiền tài quan lộc vội cầu làm chi, tất cả đều có định sẵn rồi. Nghĩa là thời vận đã an bày\nsẵn cuộc sống của người. Đến lúc Phúc tự lại. Chẳng cần vất vả vội cầu mà phiền lòng, tuy nhiên, câu xưa\nTọa hưởng kỳ thành đối với khoa học tiến bộ ngày nay hơi có vô lý, song vẫn có lý do tồn tại của nó.\nChẳng hạn như trúng số không phải sao.\nVậy việc cầu xin của người, hãy chỉ cố công cày cấy, còn phần gặt hái thu hoạch cứ để tự nhiên thì trời ắt\nkhông phụ lòng người.\nQuẻ dạy: Chớ lo, cơ trời đã tạo con đường tương lai rồi. Chờ các năm Hợi, Mùi, Sửu, Tuất là những năm\nvận tốt của bạn. Cầu tài, cầu mưu đắc lợi. Tính chuyện đỏ đen hạp. Biểu tượng: heo, chó, dê, trâu.", "g": "- mọi việc cứ theo lẽ tự nhiên mà tiến tới, đừng thêm bớt mà hư việc.", "s": "50, 5, 55, 15, 25, 35."}, "51": {"c": "THƯỜNG THƯỜNG", "hexagram": "Bát Thuần Đoài", "line_label": "Động Hào Tam", "p": "Không, không, không,\nKhông lý đắc thành công.\nBàn Đào thiên tải thực,\nBất phạ ngũ canh phong.\nChớ tưởng không là đã không,\nChính vì cái đó mới thành công.\nBàn Đào quả trái nay mùi chín,\nNào sợ nửa đêm gió thổi bùng.", "b": "Chứa lâu ắt phải chướng, uất lâu ắt phải bật. Căn cơ đã kiên cố thì khỏi cần phải lung lay rung chuyển.\nKhông mà lại chẳng không, cho nên tự nhiên phát đạt. Đó là cái tượng của quẻ này. Người xin được quẻ\nnày nên biết rằng: nhà nào tích thiện ắt có thừa phúc, do đó có thể ngồi đợi được.\nĐầu hai câu của quẻ thơ nói, mới xem qua thì làm người khó hiểu. Thực vậy không làm sao mà thành\ncông được. Nhưng ta nếu xem qua cuốn lịch Tàu trong bài Quang Hiền văn có câu Cao thảo chi hạ hửu la,\nhương mao lư chi ốc xuất lương tướng. Nghĩa là trong cỏ rác còn có bông lan. Nhà nghèo tạo nên tướng\nsoái. Đó là cho chúng ta dẫn chứng triết lý hai câu đấy.\nNhư thể những việc cầu xin của người, nên cố gắng không ngừng, ngày vinh quang ắt có trong đời của\nngười vinh hoa phú quý vậy.\nQuẻ dạy: Tốt đẹp thời vận thái. Sự sự như ý toại lòng, làm chơi ăn thiệt. Cầu tài cầu mưu thành tựu. Đánh\nsố hạp.", "g": "Việc lớn muộn thành, nếu hỏi về tài vận, được quẻ nầy chẳng tốt. Nếu hỏi về tố tụng, kéo dài lâu\nngày có thể được thắng kiện.", "s": "15, 51, 11, 55, 50, 10, 5, 1"}, "52": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Đoài", "line_label": "Động Hào Tứ", "p": "Sầu kiếm phóng,\nTiếu nhan khai.\nThu nguyệt quải cao đài,\nNhân tòng thiên lý lai.\nBuồn bã nay đi hết mặt dài,\nNụ cười vui vẻ đón ngày mai.\nTrăng thu sáng chói treo trời giữa,\nMừng rỡ người từ thiên lý lai.", "b": "Quẻ này chủ người ra đi sắp trở về, mưu vọng có thể thành, lại được người phò trợ, chẳng khác gì hạn lâu\ngặp mưa. Thật là một triệu chứng tốt đẹp vô cùng. Quẻ này tất nhiên là quẻ đại cát.\nTheo ý quẻ nói rằng: Hiện nay sầu mặt đã tan mất. Mà đã vui vẻ rồi. Và hơn nữa trăng thu giữa trời sáng\nsủa mừng rỡ đón khách xa đến, nghĩa là thời vận của người sắp đến. Vận trình hanh thông để đón lấy\nnhững may mắn đó.\nVậy việc cầu xin của bạn ắt sẽ được toại nguyện trong nay mai, hãy sửa soạn tiến hành đi để đón lấy\nnhững kết quả tốt đẹp đấy.\nQuẻ dạy: Hết vận dở đến vận thái rồi. Có quý nhân từ xa đến, giúp công cho bạn đắc lực. Thành công chắc\nchắn. Sự sự đẹp lòng cầu tài. Cầu danh hạnh tiến. Đánh số hạp.", "g": "Tốt lành. Cảnh tâm dần dần mở sáng, tình hình sẽ chuyển tốt. Tìm người sẽ gặp, mọi việc đang\nchuyển tốt.", "s": "2, 5, 52, 22, 55, 50, 20."}, "53": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Đoài", "line_label": "Động Hào Ngũ", "p": "Tu trước lục,\nMạc viên vu.\nTràng cau câu hướng thiên thừ quạt,\nTrục dục no trung đắc cự ngạo.\nPhải ra sức chớ đi xa,\nHãy nên gìn giữ bước qua khỏi cầu.\nHang con cóc lại thả câu,\nTrên cây hết cá, xây lầu trên mây.", "b": "Quẻ này chủ muốn tính toán làm ăn tất nhiên là phải nhọc sức.\nTrong khi bôn ba vất vả, nếu không dụng vào những công việc: sắt, súng, kim châm, đá mài, thì không thể\nnào bước dần vào gia cảnh được.\nNgười xin được quẻ này có hy vọng tiến tới được, song trước hết, phải trải qua bao nhiêu tàn khổ mới có\nngày tươi sáng được.\nTheo quẻ thơ nói: Người hãy nên cố sức mà làm và đừng đặt cao vọng quá, thì mới được thư thả phần nào.\nNếu không, kết quả của sự cầu mưu của người ắt như thả câu vào hang cóc, bắt cá trên cây và xây lầu trên\nmây rút cuộc chỉ là hư không, mà lại tốn công hao sức thôi chẳng lợi ích gì cả.\nQuẻ dạy: Mọi việc nên đình đốn. An phận là hơn. Quá cao vọng càng thất bại. Nên chờ đợi. Mọi việc đều\nbất thông. Cầu danh, cầu lợi khó mong đạt. Đánh số e bị thua. Biểu tượng: cá, cóc.", "g": "Được quẻ nầy, hãy gắng hết sức mình, chẳng nên mãi lo du hí bỏ bê công việc, sự mong mỏi tự\nnhiên được thành.", "s": "35, 53, 5, 3,\n33, 55, 50, 30."}, "54": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Đoài", "line_label": "Động Hào Lục", "p": "Vô tung vô tích,\nViễn cận nan mịch.\nHãn hải hành chu,\nKhông lao phí lực.\nKhông hình không bóng hỏi ai,\nXa gần chẳng thấy, kiếm hoài thấy đâu.\nBiển nay cạn, thả thuyền châu.\nHao công tốn sức, cố cầu vẫn không.", "b": "Quẻ này chủ mọi việc đều không tốt: bói xem bệnh thì chẳng lợi, hỏi danh và tài thì cả hai đều không xem\nthai nghén thì sản phụ hoảng kinh, tìm người đi thì người đi không tới, hỏi mưu sự thì mọi việc không\nthành.\nTrong trường hợp thiên niên vạn nan này, nếu biết tỉnh ngộ mau lẹ thì cũng có thể vản hồi được cảnh ngộ\nvà thuận thao được lòng người.\nÝ quẻ nói rằng: Hiện nay, thời vận của con người vẫn còn bế tắc, chưa thể làm ăn gì được, mà phải theo\nlối sống lâu nay là hơn. Còn nếu cần hỏi về việc của cải mất lạc thì khó tìm lại.\nSở dĩ tôi dám bàn giải như vậy là căn cứ bốn câu thơ trên nói rằng không hình bóng, kiếm khắp xa gần\nchẳng thấy, vậy nếu xin hỏi mất đồ còn hy vọng gì. Và hai câu sau nói: Biển cạn không nước thuyền làm\nsao đi được, đó có phải hao công tốn sức chăng.\nQuẻ dạy: An phận thủ thường, giữ mức cũ. Công việc bế tắc, xoay sở mấy cũng thất bại. Đau bệnh gặp\nthầy, mất đồ khó kiếm. Cầu mưu, cầu tài còn lâu, lúng túng là khác. Đánh số khó trúng.", "g": "mọi việc khó thành .", "s": "40, 50,\n44, 55, 4, 5, 54, 45."}, "55": {"c": "HẠ HẠ", "hexagram": "Trạch Hỏa Cách", "line_label": "Động Hào Nhất", "p": "Tế vũ mông mông thần,\nGiang biên lộ bất thân.\nĐạo đồ âm tín viễn,\nBằng trượng tá đông phong.\nTrời lại mưa phùn ướt khắp cùng,\nMé sông đường sá chẳng nào thông.\nXa xôi âm tín biệt tăm tích,\nChỉ có vậy nhờ sức gió đông.", "b": "Quẻ này chủ Được người khích lệ, gởi gắm. Tuy vậy cũng phải nhẩn nại chờ đợi. Con chim trích bị chỉ\nmột cành nhưng lại có hy vọng. Nếu hăm hở vội vả, mong chóng thành tựu thì chẳng những không thể đạt\nnguyện mà còn thêm kẹt là khác.\nQuẻ thơ nói trời mưa phùn, đường không thông và tin tức là không, đều là những cảnh không may chưa\nđược hanh thông. Vì vậy, những việc cầu xin của bạn chưa thể thành đạt ý muốn.\nNhưng câu chót của thơ lại dạy: Nhờ cậy sức gió đông. Phải chăng có ý dạy người hãy nên nhờ sức người\nta giúp ta để công việc cầu xin được đỡ phần nào chăng.\nQuẻ dạy: Chờ tin, tin chẳng lại. Chờ công việc, việc chẳng thành. Đang bế tắc, các đường tính toán đều\nkhông thông. Ẫn nhẫn chờ thời, chờ kẻ giúp. Sẽ có người từ phương đông đến, giúp nên công. Cầu mưu,\ncầu tài còn chậm, đánh số chưa thông.", "g": "Thời vận chưa tốt, mọi việc khó mong được thành, chỉ có cách nhờ cậy người gần trợ giúp mới có\nhy vọng phần nào.", "s": "55, 5, 50, 25, 15, 35."}, "56": {"c": "HẠ HẠ", "hexagram": "Trạch Hỏa Cách", "line_label": "Động Hào Nhị", "p": "Bình địa khởi vân yên,\nThời hạ vị năng an.\nCao xứ mích nhân viên.\nGió lửa bỗng nhiên nỗi đất bằng,\nBây giờ thời vận chửa nên thân.\nHãy mà tìm kiếm nơi khô ráo,\nMối nợ tình duyên sẽ đến anh.", "b": "Quẻ này chủ công việc trầm trệ, thời vận chưa thông. Ví thử có niên tai nguyệt hối thì chỉ nên lặng lẽ đợi\nchời, hơn nữa cần phải cẩn thận lắm mới được. Còn một việc nhân duyên, nếu muốn cầu tìm thì nên tìm ở\nnhững nơi cao mới hy vọng thành tựu. Người xin được quẻ này phải nên mau tìm phục thủ kỹ để tránh tai\nhọa.\nThơ quẻ cho rằng, tình cảnh cũng như thời vận của người cầu xin hiện nay, như đất bằng bỗng lại nổi lên\nsóng gió. Và còn nói rõ hiện giờ chưa được ổn song lại khuyên người hãy tìm nơi cao để nối mối duyên\nnợ.\nVậy những việc cầu xin của người, nên phải nhờ sức lực và thế lực của người ta phụ giúp thì mới mong\nđược nên việc.\nQuẻ dạy: Xấu, bế tắc. Lợi cho việc tình duyên. Nhưng phải nhờ vào quý nhân giúp, trong việc làm ăn sụp\nđổ thình lình. Chớ cầu tài, cầu mưu chẳng ích gì. Chỉ may có 2 phần 10, nếu có quý nhân hỗ trợ. Tính\nchuyện đỏ đen chẳng nên công.", "g": "Điều muốn hỏi hiện giờ chưa có kết quả. Nếu hỏi về nhân duyên, nên đến những gia đình danh giá\nmà cầu hôn. Nếu hỏi về sự nghiệp, trở ngại vô cùng.", "s": "65, 56, 5, 6, 55, 66, 50, 60."}, "57": {"c": "TRUNG TRUNG", "hexagram": "Trạch Hỏa Cách", "line_label": "Động Hào Tam", "p": "Chính trực nghi thủ,\nVọng động sinh tai.\nLợi thông danh đạt,\nDiệp lạc hoa khai.\nẮn ngay nói thẳng sẽ yên lành,\nLàm bậy nghĩ tà tai hại thân.\nHiển đạt hai điều danh với lợi,\nLá tàn hoa nở sắc mau than.", "b": "Quẻ này chủ người ta nên giữ lòng ngay thẳng, chớ có theo dòng đuôi sóng, cùng với đời trôi nổi. Nếu\ntheo được như vậy thì danh tánh lợi tới, có thể nở mày nở mặt với thiên hạ. Lá rụng thì hoa nở, đó là lý chí\ntự nhiên.\nNgười xin được quẻ này vụ lấy điều ngay thẳng mà làm gốc. Quẻ dạy: Muốn thành đạt những việc sở cầu\nnên phải ăn ngay ở lành, chớ làm điều bậy thất đức, nếu không chỉ không nên việc mà còn tai họa lụy thân\nnữa là khác.\nNhững sự cầu xin của người hay tính mưu điều chính đáng, đừng tính việc tà. Phải làm ơn, làm phước, để\ncông việc sở cầu được quý nhân giúp đỡ thành công theo ý muốn vậy.\nQuẻ dạy: Trồng đức mà ăn quả, quả càng lành và trường tồn. Chớ tính chuyện ác đức, tà vậy mà có hại,\nviệc thành đạt trong đời đều do cái tâm đạo đức của bạn. Cầu mưu, cầu tài đạt thành, nhưng cần có đạo\ntâm. Đánh số hạp.", "g": "Rán giữ chặt cái gốc , thẳng ngay chẳng ai dám khi dễ.", "s": "7, 5, 57, 75, 70, 50, 77, 5"}, "58": {"c": "HẠ TRUNG", "hexagram": "Trạch Hỏa Cách", "line_label": "Động Hào Tứ", "p": "Quân tử thăng, tiểu nhân trở,\nChinh chiến sinh ly khổ.\nTiền hữu cát nhân phùng,\nTín tại mã ngưu nhân tại sở,\nSự yêu danh cầu thỏa.\nQuân tử khuôn phò kẻ xấu khi,\nCuộc chinh chiến khổ sầu sanh ly.\nQuý nhân hội ngộ nơi trâu ngựa,\nCông việc ráng lo chớ hoãn trì.", "b": "Quẻ này cho biết: Một Dương tới che chở nhưng lại đến một lũ Ấm tới phá ngăn. Tuy trên đường đời may\ngặp được người tốt nhưng vẫn phải nên tự mình xếp đặt lấy, giải quyết lấy công việc của mình, có thế mới\nthỏa đáng tốt đẹp, chứ chớ nên hoàn toàn ỷ cậy vào kẻ khác. Câu thứ tư nhụ ý khuyên răng, cần phải lưu\ný.\nTheo ý quẻ cho biết hiện hoàn cảnh của bạn đang ở một hoàn cảnh tế nhị như hai câu đầu đã nói quân tử\nphò, mà tiểu nhân khinh khi như cuộc chinh chiến, biết bao khổ sầu sanh ly. Nhưng mà hai câu sau lại nói\nsẽ gặp quý nhân giúp đỡ và khuyên nhủ phải cố sức chăm lo việc cầu xin.\nDo đó, việc cầu xin của bạn may hay rủi, thành hay bại đều phải do bản thân mình định đoạt phần lớn.\nVậy hãy cố gắng lên, chịu đựng những gian nan để thành đạt sở cầu.\nQuẻ dạy: Cố gắng thực hành ngay, chớ chần chừ, cần nhớ quý nhân, Biểu tượng quẻ: trâu, ngựa. Cầu tài\ncầu mưu sắp đạt nhưng phải nhớ quý nhân. Đánh số hạp một nữa .", "g": "Việc muốn hỏi đang gặp khó khăn triền miên, có người thì ngọc mới thành, không gặp may mắn\nvề địa lợi, nên khéo léo sắp đặt mới thành công.", "s": "85, 58, 5, 80, 50, 88, 55."}, "59": {"c": "HẠ HẠ", "hexagram": "Trạch Hỏa Cách", "line_label": "Động Hào Ngũ", "p": "Phân phân phục phân phân,\nHy hư độc yên môn.\nLiễm my vọng đăng hỏa,\nBạn ngã tọa hoàng hôn.\nBời bời càng lại ngổn ngang,\nMột mình khép cửa thở than buồn rầu.\nGió đèn nhăn mặt nghĩ đâu,\nNgười cùng cảnh tối, biết cầu với ai.", "b": "Quẻ này chủ thế đạo biển lớn, thời không phải của ta, khiến ta đành phải sống đơn độc, chỉ còn biết than\nthân với bóng. Người xin được quẻ này có cái lo đơn độc ngồi giữ bước đường cùng. Bới thế trăm việc\nmưu vi đều nên tạm thời đình chỉ.\nÝ quẻ cho rằng: tình cảnh của bạn hiện nay ngổn ngang bời bời trong cảnh chiều tối, buồn rầu vô cùng,\nnghĩa là chỉ thời vận của bạn còn trong bế tắc, chưa được hanh thông.\nTất cả sự cầu xin của bạn chưa toại nguyện trong lúc này, mà phải chịu đựng một thời gian nữa thì mới\ntốt. Vì bài thơ không được câu nào khuyến khích cả, nên người phải tự xét lấy.\nQuẻ dạy: An phận. Và chờ thời, mọi việc bế tắc, dù có đông xông, tây đột cũng vô công. Cầu lợi, cầu mưu\ndở. Đánh đỏ đen cũng hạp.", "g": "Nên hết sức nhẫn nại lúc nầy, chờ cơ hội tốt sẽ làm, đừng nên nóng vội mà hư việc. Người nữ mà\ncầu được quẻ nầy, e có chuyện tình cảm bất hòa giữa vợ chồng.", "s": "9, 5, 59, 95, 99, 55, 90, 50."}, "60": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Hỏa Cách", "line_label": "Động Hào Lục", "p": "Nhan sắc mỹ,\nHưu quải hoài.\nNhân tại xạ trung,\nChu hành thủy lý.\nHồng nhan mỹ, quả như tiên,\nẤu lo chi nữa, điểm ra phước lành.\nNgười trong xe, sắp khởi hành,\nThuyền nan một mảnh, thăng bay chạy nhanh.", "b": "Quẻ này khuyên ta chớ nên vọng tưởng xa xôi mà chỉ nên thủ thân an mệnh, ví thử có chạy vạy, mưu tính\ncao xa thì bất quá chỉ làm rối loạn tâm ý đó thôi, rốt cuộc cũng chẳng thành tựu điều gì.\nNgười được quẻ này chớ nên khinh cử vọng động, ta có thể lấy tỷ dụ như : kẻ kia là một thiếu nữ tuyệt\nđẹp đi trong xe, còn ta thì lại là một khách lữ hành ngồi trong thuyền, hai bên không có hy vọng chi gặp\ngỡ.\nTheo ý quẻ cho rằng: Những việc cầu xin của người, chẳng gặp gì trở ngại cả, mà nhứt định công việc trôi\nchảy, thành đạt sở cầu. Bởi người cầu xin được quẻ này là một quẻ Thượng Thượng tốt lắm.\nBài thơ quẻ đã nói rất rõ, như hồng nhan mỹ, người trong xe, thuyền đi trong nước. Vậy còn gì đáng chê\nnữa. Hãy tiến hành sớm những việc mưu cầu đã dự tính, chớ chần rồi mất dịp may, nay vận thời của người\nlà đang lúc đấy.\nQuẻ dạy: Gấp rút tính, ắt nên công. Tuy cũng khó khăn, nhưng bạn có tài nên vượt qua hết, nó như thuyền\nnan vượt sông vậy. Cầu tài, cầu mưu gấp rút, thì nên. Đánh số đắc lợi.", "g": "Đừng ham mê sắc đẹp, mọi việc đừng tham cầu quá khả năng mình.", "s": "60, 6, 16, 26, 36, 46, 56."}, "61": {"c": "HẠ HẠ", "hexagram": "Trạch Lôi Tùy", "line_label": "Động Hào Nhất", "p": "Kiều dĩ đoạn,\nLộ bất thông.\nĐặng chu lý tiếp,\nHựu ngộ cuồng phong.\nCầu nay đã gãy khó qua sông,\nBế tắt đường đi lộ bích cùng.\nBước xuống ghe thuyền chèo lái chạy,\nNào ngờ gặp lại thổi cuồng phong.", "b": "Cầu gãy đường kẹt, gió cản thuyền tàu, chừng ấy đã đủ cho ta thấy cái vận mạng chó mực của ta rồi.\nNgười xin phải quẻ này chỉ có thể tu nhân tích đức, vun trồng cây phúc, mới mong chuyển nguy ra an, hóa\nhung ra cát mà thôi. Nếu mưu tính quá nhiều lòng tham không đáy, e rằng chẳng thoát khỏi tai họa.\nThơ quẻ tả cảnh và thời vận của con người hiện nay. Như người đang tính lên đường để đi tìm tương lai,\nlại gặp cầu gẫy, đường sá bế tắc không, muốn đi thuyền lại bị gió to, như vậy làm sao đăng trình, không\nđăng trình mà ngồi trong nhà, thì làm sao có tương lai sáng lạng!\nĐó là mách cho người hay, thời vận của người chưa được hanh thông và việc cầu mưu của người khó\nthành công.\nQuẻ dạy: Thời vận rất tề, chỉ nên ẩn nhẫn chờ thời. Con người có lúc thái, lúc dở, thì lo gì. Thủ phận mà\nchờ đợi. Cầu tài, cầu mưu, còn lâu. Đánh số chưa gặp may.", "g": "đại bất cát , mọi việc phải hết sức cẩn thận .", "s": "16, 6, 1, 61, 66, 11, 60, 10."}, "62": {"c": "HẠ HẠ", "hexagram": "Trạch Lôi Tùy", "line_label": "Động Hào Nhị", "p": "Thâm đàm nguyệt,\nChiếu kính ảnh.\nNhất trường không,\nAn bác tín.\nVực thẳm nơi sâu trời sáng trắng,\nSoi gương chiếu bóng ảnh tinh thần.\nNhưng mà những đó hư không cả,\nChẳng có tin gì đáng hạnh hân.", "b": "Quẻ này chủ gia đình thì nhiều bệnh, bệnh nhân thì bất thành, công danh thì lận đận, người đi thì bặt tin,\nkiện cáo thì thất lợi, tất cả thảy đều không tránh khỏi tai họa thiệt thòi. Người xin phải quẻ này nếu biết tu\nchỉnh con người, thì chưa hẳn cảnh ngộ đã phải là vô ích.\nÝ quẻ nói: Dưới nước trăng hoa, hình bóng trong gương dù đẹp cách mấy đều cũng là hư không, chẳng có\nchút nào thực tế, có cũng như không. Vậy có gì đáng mừng đáng vui đâu.\nNhư vậy những việc mưu cầu bạn chỉ có tiếng mà không có miếng, rút cuộc trở lại không không, chẳng đi\nđến một kết quả nào nên cẩn thận lo lấy thôi.\nQuẻ dạy: Thực tế, chớ quá mơ mộng. Tình trạng đang bế tắc, cần ẩn nhẫn chờ thời. Tài lợi, tính toán\nchẳng đi đến đâu. Đánh số cũng bất lợi.", "g": "Đừng thả mồi bắt bóng, mau mau tỉnh ngộ kéo hối không kịp.", "s": "26, 6, 2, 62, 22, 66, 60, 20."}, "63": {"c": "TRUNG THƯỢNG", "hexagram": "Trạch Lôi Tùy", "line_label": "Động Hào Tam", "p": "Hồ hải ý du du,\nYên ba hạ diếu câu.\nNhược phùng long dữ thỏ,\nDanh lợi nhất tề chu.\nÝ tình sông biển nhởn nhơ,\nThả câu nơi sống, sững sờ lạ thay.\nNếu phùng long thỏ quả may,\nCuộc đời danh lợi chứa đầy hân hoan.", "b": "Quẻ này chủ vào lúc Mão Thìn niên giao thì danh lợi sẽ được song toàn, ngoài ra ta cũng gặp được những\nngười sinh năm Mão, Thìn giúp đỡ đề huề (Hoặc những người sinh năm này sẽ được giúp đỡ). Người xin\nđược quẻ này hãy nên suy nghĩ cẩn thận, và cố gắng tuân theo.\nTheo quẻ nói: Ý tình sông biển đang sóng gió nhưng lại nhỡn nhơ, mà thả câu nói đó, thực là một việc kỳ\nlạ, nếu bắt gặp con rồng con thỏ thì tiếng vang lừng trời và tiền của đầy nhà.\nNghĩa là ý muốn dạy rằng: Những việc cầu xin của người thiệt là gian nan vô cùng, nếu vượt được cũng\nnhư chịu đựng được những gian nan đó, ắt thành đạt ý nguyện lâu nay, cuộc đời sẽ nhanh lên hương.\nQuẻ dạy: Sự khó mà nên một cách bất ngờ, kỳ dị khó mà tưởng nổi. Cần rèn tài, luyện đức, thì việc càng\ncó kết quả tốt nữa. Biểu tượng: rồng và thỏ. Cầu mưu cầu tài đắc lợi, đánh số tốt.", "g": "hoài bảo to lớn ôm ấp trong lòng nếu quan tâm thêm thì sẽ đạt kết quả cả danh lẫn lợi. (Chú ý:-\nTốt cho những người tuổi Thìn và Mão, hoặc năm Thìn , năm Mão)", "s": "36, 6, 3, 63, 33,\n66, 60, 30."}, "64": {"c": "HẠ HẠ", "hexagram": "Trạch Lôi Tùy", "line_label": "Động Hào Tứ", "p": "Vật bất lao,\nNhân đoạn kiều.\nTrùng chỉnh lý,\nMạn tâm cao.\nVật không vững chắc gì đâu,\nBây giờ đã gãy cây cầu người đi.\nHãy mau sửa lại chờ gì,\nĐừng nuôi hy vọng, tâm thì mới yên.", "b": "Quẻ này có cái tượng tạo lập bên lò mới, trùng chỉnh lại kiền khôn, nghĩa là xây dựng lại cơ đồ một phen\nnữa. Người xin được quẻ này nên vững tâm tiến bước, tìm cách tự lo nhưng không nên xem thường mọi\nviệc, có thế mới có thể khôi phục lại cơ nghiệp xưa kia.\nTheo ý quẻ cho biết rằng: Thời vận của người hiện nay chưa được hanh thông, không vững chắc như cầu\nđã gãy. Chớ nên nuôi dưỡng mộng cao, để tránh phiền chí, hao công vô ích.\nXưa có câu (thời đến sắc thành vàng, không thời vàng như sắc) vậy trong thời gian này tạm ngừng lại\nnhững mưu cầu phát triển mà chỉ nên an phận để qua hạn vận không may này, rồi mới tính lại thì tốt hơn.\nQuẻ dạy: Dở, an phận thì tốt. Cầu gãy, cần sữa sang lại mới đi được. Nghĩa là nên rèn chí luyện tài đã rồi\nắt hay. Cầu mưu cầu tài đều dở. Đánh số bất thông.", "g": "Việc muốn hỏi cần phải điều chỉnh lại, nếu quyết tâm đeo đuổi và đầu tư đúng mức. sẽ đạt kết\nquả.", "s": "46, 4, 6, 64, 44, 66, 40, 60."}, "65": {"c": "HẠ HẠ", "hexagram": "Trạch Lôi Tùy", "line_label": "Động Hào Ngũ", "p": "Nhạn nhi dị,\nXuất nhi nan.\nYêm yêm đáo tái tán,\nGiao gia ý bất kham.\nMuốn vào chả có khó gì,\nMuốn ra mới khó, cực kỳ tốn công.\nTình lơ lửng ý đến cùng,\nCàng thêm lộn xộn, càng bung ý tình.", "b": "Quẻ này chủ dễ tiến mà khó lùi. Đấy là cái cảnh của con chim muốn sổ lồng mà không đặng, con cá muốn\nthoát lưới mà không được, con người bị khốn quẩn trì trệ đã quá lâu chỉ mong sao nhảy thoát được hố lửa.\nNgười xin phải quẻ này thường bối rối chẳng yên, ý nghĩ như mối tơ vò vậy.\nThơ quẻ nói: Vào dễ ra khó và đến lúc băn khoăn thì càng lại lôi thôi. Nghĩa là phàm việc bạn tính thì rất\ndễ, nhưng khi làm thì khó vô cùng. Nếu trước sự việc mình không tính kỹ, đến lúc xảy ra những điều\nkhông hay rồi thì khó cứu chữa đấy.\nVậy, những việc cầu xin của bạn trước khi tính làm phải đắn đo suy nghĩ cho kỹ lưỡng, phàm việc phải\nnắm chắc trong tay rồi mới làm. Mới tránh được những buồn sầu về sau.\nQuẻ khuyên: Nên tính toán nghiên cứu kỹ càng trước khi tính việc gì. Chờ thời là hơn. Cầu mưu cầu lợi\ncòn lâu. Đánh số ít có may.", "g": "rước thần thì dễ đưa thần khó (việc đã dĩ lỡ, khó giải quyết)", "s": "5, 6, 65, 56, 66, 55, 50, 60."}, "66": {"c": "HẠ HẠ", "hexagram": "Trạch Lôi Tùy", "line_label": "Động Hào Lục", "p": "Sự trì chí tốc,\nNhi thả phản phúc.\nNghi đãi tuế hàn,\nHoa tàn quả thục.\nViệc chậm muốn mau nào dễ thành,\nCòn nhiều phản phúc và quanh co.\nNên chờ mùa lạnh đến xem đã,\nQuả chín hoa tàn mới tốt lành.", "b": "Quẻ này chủ mưu sự nên hoãn không nên gấp, gấp thì chẳng những đã vô ích mà lại còn phản phúc bất\nthành. Qua tới mùa đông, ta sẽ thu hoạch được mỹ mãn, điều đặc biệt nhất là không phải mệt sức mà vẫn\nđược. Người xin được quẻ này nên nhẫn nại chờ đợi, không nên than thở là bất như ý.\nQuẻ thơ cho hay rằng: Công việc cầu mưu của bạn cần phải chờ đợi một thời gian nữa mới hanh thông\nđược. Bởi hiện nay sự việc chưa thong dong còn nhiều quanh co lắm, thì muốn mưu thành đạt khó vậy.\nNhư trong quẻ nói rất rõ ràng, hãy chờ đợi đến lúc hoa rụng quả chín mới là tốt lành. Đó có phải chẳng có\ný chỉ đến xuân tới, thời vận con người mới được hanh thông.\nQuẻ dạy: Chờ đợi mùa xuân sang, ắt việc mới có kết quả. Bây giờ thì chưa. Ẫn nhẫn chờ đợi thì hay.\nMuốn gấp cũng chẳng được vào. Cầu tài, cầu mưu còn chờ đợi. Đánh số chưa mấy hạp.", "g": "Thời cơ chưa chín muồi, dù có hết sức , cũng khó thành tựu. Người nữ được quẻ nầy, nói lên chỗ\nchưa thỏa mãn với kết quả hiện tại, đừng quá tham vọng.", "s": "68, 86, 6,\n8, 80, 60, 88, 66."}, "67": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Địa Tụy", "line_label": "Động Hào Nhất", "p": "Thừa mã tiền tiên,\nSở cầu cát trinh.\nTúy thời hài mỹ,\nKhuyết nguyệt trùng minh.\nCỡi ngựa lên đường bước vận trình,\nCầu xin sự việc mọi điều linh.\nLuôn luôn vui vẻ được sung sướng,\nTrăng khuyết lại tròn chót sáng tinh.", "b": "Quẻ này chủ nên động không nên tĩnh, nên xa không nên gần, càng đi càng có lợi, đến đâu là y như là có\nchuyện gặp gỡ, ý hợp tâm đầu. Đây chính là cái tượng trăng khuyết lại tròn, quả thực là Đại cát.\nTheo ý quẻ cho biết, tất cả sự cầu xin của người đều được hanh thông mà chẳng có gì đáng lo ngại, dầu có\nnhưng gì không may, đều trở thành quá khứ rồi, từ đây về sau sẽ gặp may mắn và sung sướng đấy.\nBởi vì vận thời cũng như hoàn cảnh của bạn hiện nay, đang như cỡi ngựa lên đường oai phong lắm lắm.\nQuẻ dạy: Thới lai phong tong đàng vương cái, như cảnh Chu Bốt đến lúc nên danh. Cầu tài, cầu mưu đạt\nthành. Đánh số hạp tốt.", "g": "một hồi trống giục,cứ thẳng tiến lên. Nhanh chóng khắc phục nhược điểm , mọi việc sẽ tốt thôi.", "s": "76, 6, 7, 67, 77, 66, 60, 70."}, "68": {"c": "TRUNG TRUNG", "hexagram": "Trạch Địa Tụy", "line_label": "Động Hào Nhị", "p": "Chu ly cổ độ, nguyệt ly vân,\nXuất nhập đông quan hiếu vân tân.\nThả hướng tiền hành khứ cần trú,\nHà tu nghi lự lưỡng tân tâm.\nThuyền rời khỏi bến, trăng xa mây,\nNgười khỏi đông quan dễ hỏi thay.\nCứ tiến mà đi cầu chỗ ở,\nLo nghi mãi mãi chẳng nào hay.", "b": "Quẻ này chủ ra khỏi cửa là có công, Người xin được quẻ này rất nên đập bàn dứt áo đứng lên. Tiến lên thì\nmới có cơ duyên gặp gỡ, chớ nên băn khoăn đầu cuối hai bên, do dự trong quyết định tiến thoái, khiến lầm\nlỡ tiến trình. Ý nói hiện nay thuyền xa bến, trăng xa mây rồi trời quang đãng đó, người ra khỏi đông quan\nrất dễ tìm một tương lai tốt đẹp và cứ đi tới đừng nghi ngờ lo âu và nản lòng.\nNghĩa là thời vận của người hiện nay tiền đồ sáng lạng như trăng, như thuyền rời bến vận tình ngàn dặm,\nvậy người hãy tiến tới đi thời vận đã hanh thông rồi.\nVậy những sự cầu xin của bạn sẽ được toại trong mai sau, nhưng phải kiên trì mà đừng nghi hoặc gian nan\nthì ắt đạt sở cầu.\nQuẻ dạy: Cứ tiến tới, sự ắt thành. Thời đến rồi, chớ lo, sự sự sẽ hanh thông, lo gì. Cầu tài, cầu mưu sắt đạt.\nĐánh số gặp may.", "g": "Quẻ chủ về việc bên ngoài, đi xa có lợi. Người được quẻ nầy, khó khăn đã qua, tại nạn đã hết, an\ntâm đi tiếp.", "s": "66, 88, 86, 6, 8, 68, 60, 80."}, "69": {"c": "HẠ HẠ", "hexagram": "Trạch Địa Tụy", "line_label": "Động Hào Tam", "p": "Bất túc bất túc,\nNan thân tâm khúc.\nDã đường vũ quá nguyệt như cau,\nMộng đoạn cam đan my đại sầu.\nChẳng no, chẳng đủ, chẳng đầy,\nKhómà thỏa mãn lòng này được đâu.\nNữa chừng dứt mộng sanh sầu,\nMưa qua trăng bóng sừng trâu mơ màng.", "b": "Quẻ này báo cho ta biết có chuyện trộm cướp cần phải đề phòng, có cái lo chết chóc tang thương, có cái\nbuồn vợ chồng chia ly, có cáo uất thân thích hiềm khích phản bội, có cái nguy gia cơ suy bại, có cái họa\ngia đình hiu quạnh.Hãy mau mau tu đức để bổ khuyết lỗi lầm và mong được thần linh ủng hộ.\nQuẻ thơ tả cảnh của người cầu xin rằng: Tất cả thiếu thốn mà không đầy đủ, nên cái chí nguyện của người\nkhó mà toại lòng, và như cảnh người nằm mộng nữa chừng tỉnh dậy, và sau trận mưa trăng bị mờ.\nVậy, ý quẻ cho rằng: Sự cầu xin của người rất gian nan. Muốn thành đạt theo ý muốn, phải cố công siêu\nquần xuất chúng thì mới được.\nQuẻ dạy: Thủ phận, đặt cao vọng, tính toán chỉ toàn gặp cảnh gian nan \"Tri túc thường túc, chung thân bất\nnhục\" cứ an phận, tự cho là đủ, thì ắt đủ, thì cuộc đời khỏi cảnh long đong, khổ nhục. Cầu tài cầu mưu còn\nlâu. Đánh số dở.", "g": "Biết đủ mới an lạc, tùy duyên mà nhận, tham cầu cao vọng sao cho thành. Phụ nữ được quẻ nầy,\ncần phải gấp bỏ đi những thứ phù phiếm hại thân.", "s": "9, 6, 69, 96, 99, 66, 90, 60."}, "70": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Địa Tụy", "line_label": "Động Hào Tứ", "p": "Mỹ hữu kham,\nKham hữu mỹ.\nThủy hữu chung,\nChung hữu thủy.\nĐẹp hay, hay đẹp lắm thay,\nThủy chung, chung thủy, lúc này sẽ xong.\nCầu xin nhứt định thành công,\nTa nên kiên chí, ắt thông vận thời.", "b": "Quẻ này chủ rằng: nếu không con thì được con, không việc thì được việc, không tiền thì được tiền, muốn\nhôn nhân thì được có vợ chồng, cần giao du bè bạn thì keo sơn một lòng.\nPhàm việc đều có cơ duyên, bởi thế cho nên không có việc gì mà không hòa hợp được. Từ lâu vận xui hạn\nkẹt, nhưng từ nay về sau, đường đời quyết bằng phẳng hạnh thông. Quẻ này bói rất linh nghiệm nhất khi ta\nđang thất ý.\nNgười xin được quẻ này, rất là may mắn vô cùng, như quẻ thơ đã nói rất rõ, chẳng có gì là không may cả.\nVậy nhữmg việc cầu xin của người ắt được giải quyết toại nguyện nay mai, nhưng phải kiên chí thì mới\nnên cầu việc.\nQuẻ dạy: Vận thời hạnh thái. Cần kiên chí là nên công. Hữu chí cảnh thanh gặp thêm vận may nữa, còn\nhay gì bằng. Cầu tài, cầu danh đắc lợi. Đánh số hạp.", "g": "người muốn cầu thiện mỹ phải đi theo con đường chính trực, phải có tinh thần trước sau như một\nmới thành công.", "s": "70, 7, 77, 17, 27, 37."}, "71": {"c": "HẠ HẠ", "hexagram": "Trạch Địa Tụy", "line_label": "Động Hào Ngũ", "p": "Hồ hải du du,\nCôchu lãng đầu.\nLai nhân vị độ,\nTàn chiều sơn lâu.\nÝ tình sông biển buồn bao,\nThuyền nan một mảnh, ba đào nhấp nhô.\nNgười sang sông chẳng gì đưa,\nTrời tàn phản chiếu, cảnh mờ núi non.", "b": "Quẻ này chủ sự trôi nổi vô định, chẳng khác chi là sóng dập bèo trôi, gió lùa tơ mảnh. Hiện tại ta còn chưa\ncó ai viện trợ giúp đỡ, chỉ nên ôm cột đợi thỏ, chớ có liều lĩnh nhảy đại xuống vực sâu để bắt cá. Người\nxin được quẻ này rất nên an phận dè dặt là hơn.\nÝ quẻ nói: Thuyền đang ngụp lặn trong ba đào, người muốn sang sông mà không đò đưa. Còn mặt trời lặn\nnúi tây, tuy cảnh đẹp đẽ, nhưng đã tới chiều tối rồi. Nghĩa là vận thời của người, lần lần bị mất những may\nmắn, dù còn tốt nhưng như cảnh chiều phản chiếu của mặt trời.\nVậy những cầu xin của người, hãy nên xét lại, thận trọng tất cả việc đang làm và tính làm, để tránh điều\nkhông may xảy cho bạn, vì vận trình không được may mắn lắm.\nQuẻ dạy: Nếu đang gặp nhiều ngăn trở, thuyền nan đang giữa dòng mà còn gặp cảnh ba đào nữa, thì nguy\nhiểm nào bằng. Thủ phận, chờ thời là hay. Cầu tài, cầu mưu bất lợi. Chơi đen đỏ còn dở nữa.", "g": "Việc muốn hỏi là điều rất phiêu lưu mạo hiểm, trong lúc chưa thấy kết quả, tâm lo lắng sợ hãi,\ntình cảnh đáng thương", "s": "70,\n11, 17, 71, 77, 7."}, "72": {"c": "HẠ HẠ", "hexagram": "Trạch Địa Tụy", "line_label": "Động Hào Lục", "p": "Thâm hộ yếu lao huynh,\nĐề phòng ám lý nhân.\nHạc ngôn vô ngoại sự,\nTúng hảo định tao chuân.\nNhà cửa lâu phải vững vàng,\nĐề phòng nơi ám kẻ ẩn tàng.\nĐừng tin vô sự mà không giữ,\nSơ ý việc làm bị dỡ dang.", "b": "Quẻ này chủ điều dữ tai họa sắp đến, nào việc quan tụng kéo tới, nào chuyện thị phi đem về. Mưu sự cũng\nchẳng thành, cầu tài, giao dịch cũng chẳng xong nữa. Tất cả mọi hành động, mọi việc làm không có gì gọi\nlà thuận lợi cả. Ngoài ra phải đề phòng cẩn thận nhất về chuyện có kẻ ám toán mưu hại.\nXin được quẻ này, chỉ nên lui về cố thủ, chứ chớ có tiến để phải gánh chịu, nhiều điều tai họa về sau.\nÝ quẻ nói: Tất cả việc mưu cầu của bạn phải tính toán rành rẽ từng tí, chớ nên sơ ý thì hỏng việc, như lời\nthơ đã nhắc nhở rằng: nhà cửa phải vững vàng. Còn phải xem xét lại những nơi tối ám, đề phòng kẻ gian\nẩn giấu bên trong và luôn luôn cẩn thận giữ lấy thì mới yên.\nVậy do lời quẻ dạy trên, những sự cầu xin của bạn tiểu tâm tùng sự, dò dẫm bước tiến từng bước một. Chớ\nnên vội vã sơ sót thì nguy, hỏng cả công việc.\nQuẻ dạy: Phòng kẻ gian, tiểu nhân thọc gậy, phá hoại trong nhà, cũng như trong công việc. Mọi sự nên\nđình đốn, tài bắt thắng thời, đời có lúc cũng lên hương, chớ không lẽ mạt hoài sao mà sợ. Cầu tài, cầu mưu\ncòn xa xôi. Đánh số e bị thua.", "g": "không việc cần thấy có việc, có việc gia tăng đề phòng. Người được quẻ nầy, cần chú ý giữ gìn\nnhà cửa, lời nói và việc làm phỉa thận trọng e có điều không hay xảy đến.", "s": "22, 77, 70, 20, 2, 7, 27, 72."}, "73": {"c": "TRUNG TRUNG", "hexagram": "Trạch Thiên Quải", "line_label": "Động Hào Nhất", "p": "Giang hải du du,\nYên ba hạ câu.\nLục ngao liên hoạch,\nCa tiếu trung lưu.\nBiển sông bình lặng êm mơ,\nThả câu nơi sóng sững sờ lạ thay.\nVậy mà bắt cả sáu bầy,\nHả cười ca hát vui vầy giữa sông.", "b": "Đây là quẻ chủ công danh phú quý. Giàu sang vinh dự hình như đã có phận. Có kẻ phải kẻ đạp trên sắt\nthép nhảy qua lửa đỏ, thế mà không tìm thấy, trái lại, ta chẳng nhọc sức mà vẫn thu hoạch tìm thấy được\nhoàn toàn.\nNgười xin được quẻ này đáng mừng hết chổ nói, vì đây là quẻ đem niềm vui tới không biết đâu mà chừng.\nTheo ý quẻ: những việc cầu xin của người ban đầu thấy rất khó khăn như thả câu ở trong sông biển gian\nnan, nhưng rút cuộc công việc đều được toại nguyện, chẳng có gì đáng ngại.\nBởi hai câu thơ sau nói rằng bắt được cá sáu bầy to, cả vui giữa giang hà, đó là ý chí công việc thành tựu\nđấy. Như vậy, người xin được quẻ này, cứ buông tay tiến tới, đừng ngại gian nan thì sự cầu mưu ắt được\nvừa ý.\nQuẻ dạy: Thời sắp đến rồi, đừng lo, mua số ắt trúng. Đánh số thuận lợi. Biểu tượng là cá. Cầu tài, cầu mưu\nđắc nguyện.", "g": "Quẻ nầy rất tốt, dự định hay tạo sự nghiệp đều có hy vọng. Thành công liên tiếp, chú ý đến con số\n“sáu”, sẽ có nhiều may mắn với nó.", "s": "77, 33, 70, 30, 37, 73, 3, 7."}, "74": {"c": "HẠ HẠ", "hexagram": "Trạch Thiên Quải", "line_label": "Động Hào Nhị", "p": "Dục tế vị tế,\nDục cầu dưỡng cầu.\nTâm vô nhất định,\nNhất xa lưỡng đầu.\nMuốn làm chẳng thấy làm đâu,\nMuốn cầu sau cố cưỡng cầu làm chi.\nTrong lòng lúng túng li bì,\nXe hai đầu biết đi hướng nào.", "b": "Muốn xong mà chẳng xong, ý nói có thể tiến được mà lại không tiến. Muốn cầu phải gượng cầu, ý nói\nđược mà lại chẳng được. Trong lòng cứ do dự mãi, băn khoăn hoài, không có gì nhất định cả, trong khi\ncần phải tìm thấy một con đường trong chổ rẽ, chẳng khác gì xe có hai đầu, chẳng biết đi về đường nào.\nNgười xin được quẻ này có thể là người đang ở tình trạng miệng hùm nọc rắn, vô cùng nguy hiểm khó\nkhăn.\nQuẻ dạy rằng phàm cầu mưu việc gì phải tận tâm chăm chú việc cầu nếu lưng chừng ắt chẳng việc gì\nthành công, nhứt là việc cầu xin của bạn càng nên cố gắng chăm chỉ, thì mới nên công. Đường đời phải\nchịu nhiều gian nan, khổ cực thì mong thành đạt.\nQuẻ dạy: Đừng cưỡng cầu tính toán. Vận đang hãm thì tài mấy cũng chẳng làm được gì. Hai đầu xe bị bít\nhết, làm sao mà lái? Nan giải, chờ đợi. Cầu tài, cầu danh chẳng ra gì. Đánh số lại càng hỏng.", "g": "ba tâm hai ý, trở ngại lẽ thường, tiến thoái lưỡng nan. Được quẻ nầy, việc muốn hỏi đang gặp\nđình trệ.", "s": "7, 4,\n47, 74, 70, 40, 77, 44"}, "75": {"c": "TRUNG TRUNG", "hexagram": "Trạch Thiên Quải", "line_label": "Động Hào Tam", "p": "Nhất đắc nhất lư,\nThoái hậu dục tiến.\nLộ thông đại đạo,\nTâm tư an nhiên.\nKhi nên vẫn có khi lo,\nNày lui để tiến, để cho hơn người.\nNgõ đường thông suốt thảnh thơi,\nYên lòng yên dạ, vận thời hanh thông.", "b": "Quẻ này tốt, phàm việc chớ có thoái chí nản lòng. Mình cứ nhất tâm hướng về điều lành, điều phải thì thế\nnào rồi cũng có chổ hay chổ đẹp. Tóm lại, ta cứ nên đường thẳng mà đi, không xấu hổ không lo ngại, ngay\ngiữa lúc ta bất đắc chí.\nTuy vậy, song ta cứ nhất tâm tiến thủ thì rồi ông trời cũng dành cho ta lúc hạnh thông, lúc hạnh phúc,\nthắng hơn kẻ chỉ muốn đi quanh khiến đường thêm dài hơn, mệt mỏi hơn.\nTheo quẻ thơ cho biết: Bước tiến trong đường đời, đâu phải bằng phẳng thông suốt đến cùng, cũng phải có\nhạnh có suy, có Đắc có Thất, có lên có xuống vậy. Nay cảnh tình của người tuy xuống nước nhưng cái\nxuống nước đó là bước để tiến, vận thời sắp hanh thông lên hương.\nVậy công việc cầu xin của người ắt thành đạt toại nguyện trong nay mai. Hãy yên chí tiến tới để thụ\nhưởng những may mắn sẵn sắp đến.\nQuẻ dạy: Tiến thoái tùy ư sự là hay. Thời vận sắp đến rồi. Cầu tài, cầu danh thông suốt, nhưng đừng nóng,\nđến lúc may nó đến là nó đến. Đánh số tốt.", "g": "", "s": "70, 50, 55, 77, 5, 7, 57, 75.\n*giải：Lúc được đừng quên hình bóng cũ—khi suy chớ nản chí làm gì—Chớ theo đường lệch thì đâu sợ--\nCứ thẳng đường đi sẽ tới nơi."}, "76": {"c": "TRUNG TRUNG", "hexagram": "Trạch Thiên Quải", "line_label": "Động Hào Tứ", "p": "Nan, nan, nan,\nHốt nhiên bình địa khởi ba lan.\nDị dị dị,\nĐàm tiếu tầm thường chung hữu vọng.\nNan nan, quả thực là nan,\nBỗng nhiên bình địa ba lan nổi bùng.\nĐến khi dễ, dễ vô cùng,\nDù đùa nói giỡn, vẫn thông việc mình.", "b": "Quẻ này cho biết hoàn cảnh hiện tại họa hoạn liên miên, khiến người ta buồn nản, chán ngán đến chết\nđược. Nhưng ai có ngờ được chuyện cũng thông nay tốt may xấu, hoặc nay xui may hên. Thực tế, tối quá\nthì sẽ sáng, chuyện Tái ông mất ngựa, càng giúp ta hôm nay tai họa đấy nhưng chính lại từ cái họa ấy mà\nđược phúc. Ví khi thời vận đã tới thì thế nào cũng thành mà lợi cũng tới.\nĐấy thật là quẻ đại cát đại lợi, là tượng trước khó sau dễ, trước khổ cực sau hạnh thông, đáng mừng chứ\nkhông phải đáng lo.\nÝ quẻ nói rằng: Tất cả việc cầu xin của người khi vận thời chưa đến dù cố gắng và tìm đủ mọi cách vẫn\nkhông đáp ứng được ý nguyện. Ngược lại khi thời đến vận thông, dù nói chơi cũng xong công việc.\nVậy, những việc cầu xin của người nên để tự nhiên mà đừng quá cưỡng cầu, tất cả thời vận của người đời\nlà Trời đã định sẵn, chớ không phải sức người cô đơn mà có thể cưỡng cầu được. Và người chỉ có cách là\ntận nhân lực mà tùy thiên định.\nQuẻ dạy: Chờ thời là hay. Cưỡng cầu chẳng ích gì. Sắp đến cái may rồi. Chờ, cầu tài, cầu danh tuy còn\nlâu, nhưng vẫn có đường. Đánh số hạp chút ít.", "g": "Vận xấu ngồi nhà, xui cũng đến—Cơ may chẳng tính cũng thành công.", "s": "70, 60, 77, 6, 7, 76, 67."}, "77": {"c": "TRUNG TRUNG", "hexagram": "Trạch Thiên Quải", "line_label": "Động Hào Ngũ", "p": "Tâm hữu dư,\nLực bất túc.\nÝ trượng xuân phong,\nNhất ca nhất khúc.\nLòng thừa sức kém chẳng nên công,\nMay mắn nào đâu dễ ngộ phùng.\nHãy cậy gió xuân vừa giúp hộ,\nCa vui một khúc khỏi buồn lòng.", "b": "Lòng mong muốn tuy cao xa, nhưng chưa thể mãn nguyện được. Tuy nhiên, cái thế của ta là cái thế của kẻ\nlên trời có thang, đâu có ngại gì trời cao, là cái thế của người đi vào nước có linh tê, thử hỏi sợ gì nước\nsâu.\nNgười được quẻ này, sẽ có người phò trợ, khiến có thể thành công mỹ mãn. Đã thế họ còn khá khéo ở chổ\ngiao dịch với đời, rồi cũng nhờ đó mà mọi việc của mình thành tựu.\nTheo ý quẻ cho biết: Phàm muốn làm nên công việc gì, ngoài có chí mà còn phải có tài sức mới được, bởi\ncái may mắn không phải dễ dàng mà gặp, nên nhờ cậy đến sức gió đông giúp hộ thì mới thành đạt ý cầu\n(gió đông ý chỉ quý nhân).\nNhư vậy, việc cầu xin của bạn ngoài việc nuôi chí mà còn phải cố gắng không ngừng, vượt qua mọi khó\nkhăn thì sẽ nên công.\nQuẻ dạy: Cố gắng. Nhờ quý nhân hỗ trợ mới nên công. Lòng thành có thừa nhưng tài kém, thì làm sao\nthành đạt. Phải có nhiều tay và quý nhân giúp cho mới thành. Cầu tài cầu mưu hơi chậm. Đánh số hạp. Số\nhên: 70, 77, 17, 27, 37.", "g": "Việc muốn hỏi, muốn làm mà không đủ sức, một mình chẳng thể hoàn thành. Nếu được bên ngoài\ngiúp đỡ, trong tay kết quả tròn đầy.", "s": ""}, "78": {"c": "HẠ TRUNG", "hexagram": "Trạch Thiên Quải", "line_label": "Động Hào Lục", "p": "Thân bất an,\nTâm bất an.\nĐộng tỉnh lưỡng tam nhiên,\nChung triên sự bất than.\nGiờ này tâm trí vẫn chưa yên,\nBiết tính gì đây để khỏi phiền.\nRáng vượt hai ba luồng sóng gió,\nNgày vui vẻ đến được an nhiên.", "b": "Cần tiến mà lại thoái, vất vả mà chẳng nên công cán gì. Gian nan hoàn gian nan, tay không vẫn tay không.\nĐành than thân tủi phận, chứ còn biết làm sao hơn. Xin được quẻ này thì phải nên ngó trước, nhìn sau chớ\nnên liều lĩnh làm bừa, e chịu nhiều điều đáng tiếc.\nNhững việc cầu xin của bạn theo ý quẻ cho hay, bạn còn phải gặp nhiều gian nan lận đận chưa được toại\nnguyện tức khắc mà cần phải ráng sức tìm cách vượt qua những chướng ngại trong bước tiến thì mới\nthành đạt theo ý muốn.\nVì quẻ thơ nói rằng tâm trí của bạn chưa được yên, và còn vấp nhiều trở ngại, nhưng rốt cuộc ngày vui sẽ\nđến nay mai cho bạn.\nQuẻ dạy: Sau cơn mưa trời lại sáng. Thời vận hanh thông đến rồi. Chỉ cần phấn đấu thêm là thành tựu.\nCầu tài, cầu danh đều tốt, sau khi vượt qua cái khó khăn. Đánh số được.", "g": "Hỏi về sức khỏe :- Vận động cho nhiều. Hỏi về sự nghiệp:- Hiện rõ nguy cơ, chạy đôn chạy đáo.\nHỏi về hôn nhân:- không tích cực nên chưa xong, cố gắng thêm mới được.", "s": "77, 88, 80, 70, 7, 8, 87,\n78."}, "79": {"c": "TRUNG HẠ", "hexagram": "Trạch Phong Đại Quá", "line_label": "Động Hào Nhất", "p": "Sự liễu vật vị liễu,\nNhân viên vật vị viên.\nYếu tri đoạn đích tín,\nNhật ảnh thượng lang hiên.\nViệc xong xuôi chuyện chưa rồi,\nNgười tròn vật khuyết, lôi thôi việc làm.\nMuốn hay tin tức rõ ràng,\nMặt trời bóng chiếu hành lang trưa ngày.", "b": "Đường xá đã gian nan nguy hiểm, tiền lương lại hết sạch. Sự nghiệp quả khó mà thành tựu. Tuy nhiên, cái\nnhân đẹp đã phát sinh phân nửa. Ít ra là vào khoảng tháng tám. Nếu ta biết sửa sang đường lối biết cố gắng\ntiến mạnh, thì một sớm một chiều tin mừng cũng sẽ đến với ta.\nNhững việc cầu xin của bạn vẫn còn lận đận khó khăn, chưa thể thành đạt tức khắc, và còn phải chờ đợi\nmột thời gian nữa.\nBởi theo quẻ cho hay: Việc xong mà chuyện chưa xong, người yên mà chuyện chưa yên. Muốn biết\nnguyên do hay tin tức của nó phải chờ mặt trời lên cao chiếu tới lang cang.\nNghĩa là nói công việc cầu xin chưa được trọn vẹn tốt đẹp, cần nên chờ đợi một thời gian nữa mới được\nnhư câu thứ tư đã ẩn tường vậy.\nQuẻ dạy: Chờ lúc nửa năm hay nửa tháng mới có kết quả. Ẫn nhẫn chờ đợi mới hay. Muốn xong gấp cũng\nchẳng được nào. Cầu tài cầu mưu chưa tiện. Đánh số hạp chút ít.", "g": "Vấn đề người và việc, phải giải quyết dứt điểm. Vật liên quan chắc là không có rồi. Được quẻ\nnầy, e có vấn đề rắc rối về tiền bạc, sợ đưa tới thưa gởi kiện cáo.", "s": "77, 99, 70, 90, 9, 7, 79."}, "80": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Phong Đại Quá", "line_label": "Động Hào Nhị", "p": "Mộc hưởng đương xuân phát,\nTam âm hựu phục căn.\nTiều phu bất chi đạo,\nDục khứ tác sài tân.\nCây này phát nở hướng đông,\nCòn bao gốc rễ ăn thông đất lòng.\nTiều phu nào biết bên trong,\nMuốn làm củi chụm chớ hòng chớ mong.", "b": "Tay anh hùng hào kiệt thường dễ bị người bỏ qua, coi như đồ vô dụng. Bởi thế quẻ này cho ta thấy hoàn\ncảnh của con rồng đang gặp lúc thất thế, bị bọn ruồi nhặn khinh khi.\nNhưng rồi một ngày nào đó, mây ùn ùn kéo, mưa rầm rập bay, con rồng nọ bay bỗng tung hoành lúc đó\nmới rõ được cái chân tướng của con linh vật. Đây chỉ là cái tượng của kẻ bị khúc gấp cầu phải được tung\nhoành cho thỏa chí bình sinh.\nTheo quẻ nói rằng việc cầu xin của người rất thông suốt và không gì trở ngại nếu có gì trắc trở rút cuộc\nchẳng đáng lo âu.\nVì quẻ thơ cho ta rõ rằng hiện hoàn cảnh của bạn đang như cây mộc theo hướng đông và gốc rễ ăn sâu\nlòng đất và vững vàng không lo sợ mưa gió làm hại gì cả. Vậy những sự cầu xin của bạn sẽ được toại\nnguyện như ý nguyện cầu đấy.\nQuẻ dạy: Phát phú, phát quan đến nơi. Sự sự như ý sở cầu, mọi điều thông suốt chớ lo. Cầu quan đắc\nquan, cầu lợi đắc lợi. Đánh số hạp.", "g": "Chẳng nên hoang phí của trời cho—Đâu dễ làm ra để sẵn kho—Chẳng biết để dành phung phí\nquá—Ngày sau hối tiếc muộn màng lo.", "s": "8, 80, 18, 28, 88, 38."}, "81": {"c": "HẠ HẠ", "hexagram": "Trạch Phong Đại Quá", "line_label": "Động Hào Tam", "p": "Nhất nguyệt khuyết,\nNhất kính nguyệt.\nBất đoàn viên,\nVô khả thuyết.\nTrăng này đã khuyết lu mờ,\nGương kia bể, cũng phải lờ tốt đâu.\nChẳng lành lại khuyết đành sầu,\nCòn chi để nói, mưu cầu khó quên.", "b": "Trăng khuyết, kiếng vỡ, tất cả đều là những chuyện chẳng lành, chẳng đẹp, chẳng nên. Bởi thế người xin\nđược quẻ này, nếu có đi kiện ai, ngược lại mình đâm thua, nếu có tình duyên cưới hỏi thì rồi ngày tháng\ncũng đổi thay. Nếu tiền của bị mất thì cũng khó tìm về, nếu có việc làm chưa thành thì thôi đừng nói tới\nchuyện thành.\nKhi chẳng may gặp phải quẻ xấu này, thiết tưởng nên tu tâm sửa tính, dốc lòng làm việc lành, lúc đó mới\nmong làm ăn khá, mưu sự thành công được.\nNgười cầu xin được quẻ này, nên tạm đình lại tất cả việc mưu cầu phát triển, hãy giữ cách sống theo cũ là\ntốt hơn. Vì thời vận của người chưa được hanh thông, mà còn xấu lắm.\nNhư lời thơ của quẻ đã nói rằng: Trăng khuyết hương bể, chẳng còn gì để nói nữa mấy lời đó đã đủ cho\nngười rõ rồi. Vậy, người nên chịu đựng nữa, nếu quá vội vã thì hỏng việc, xưa có câu Chờ đến mây tan sẽ\nthấy trời đó.\nQuẻ dạy: Bế tắc, đổ vỡ. Chờ đợi và ẩn nhẫn là hay. Trăng lu gương vỡ thì còn gì nữa? Tất cả công lao đi\nđời. Thua keo này bày keo khác, nhưng phải chờ. Cầu danh cầu lợi đều dở. Đánh số chẳng hay.", "g": "Quẻ nầy chẳng tốt, trăng khuyết gương mẻ, việc muốn hỏi không được vẹn toàn, cơ hội thay đổi\ncũng chưa thấy.", "s": "80, 10, 11, 88, 1, 8, 81."}, "82": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Phong Đại Quá", "line_label": "Động Hào Tứ", "p": "Xa mã đáo lâm,\nTinh kỳ ẩn ẩn nguyệt, phân minh.\nChiều an thảo bạn,\nVĩnh đại tiền trình.\nBiết bao xe ngựa đến môn đình,\nCờ xí giăng giăng thần quỷ kinh.\nTrăng sáng đêm nay đặc biệt sáng,\nChiêu hội kẻ loạn mở tiền trinh.", "b": "Đây là quẻ chỉ việc mưu sự tương hợp, được quý nhân phò trợ. Cho nên tiền trình rất là vĩ đại và lâu dài\nhết sức. Song sau khi đắc ý rồi, thiết tưởng cũng phải giữ gìn cẩn thận, an phận thủ thường chớ có liều lỉnh\nlàm bừa, kiêu căng càn dở, có thế mới hưởng phúc lâu dài được.\nBói được quẻ này quả là thượng thượng đại cát. Công việc cầu xin của bạn hãy mau tiến hành đi đừng\nchần chờ mà mất cơ vận. Thời vận của bạn đang đắc thời, vận hanh thông đấy. Như quẻ đã dạy xe ngựa\nđến cửa nhà cờ xí giăng giăng. Hãy mau bình loạn để tương lai được vinh quang những câu đó đều là may\nmắn tốt đẹp chẳng có gì trắc trở cả.\nVậy những việc cầu xin của bạn ắt thành đạt mỹ mãn toại lòng trong nay mai. Hãy mau lên để nắm lấy\nmay mắn đó.\nQuẻ dạy: Thới lai, vận đến khỏi lo, khỏi đợi nữa. Mọi sự như ý sở cầu. Cầu danh, cầu lợi đều đạt thành.\nĐánh số tốt.", "g": "Quẻ nầy nếu hỏi về việc đánh giặc thì rất tốt. Hỏi về sự nghiệp thì đại phát. Hỏi về thi cử thì đậu\ncao.", "s": "82, 80, 20, 88, 22, 2, 8."}, "83": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Phong Đại Quá", "line_label": "Động Hào Ngũ", "p": "Ngã hà túc, ngã hà túc,\nHải đông, hà bắc, thành danh lục.\nNhất đoạn thần quang,\nTrực xung thiên độc.\nTôi là tinh tú gì trời xanh,\nSông bắc biển đông danh được thành.\nMột đoạn hào quang sáng chói lọi,\nXung thiên trực thượng cửu trùng thanh.", "b": "Quẻ này chỉ cho ta thấy nơi mà ta thành danh, nơi thành danh phải là miền đông bắc. Theo quẻ bói thì mọi\nviệc mưu đồ hành động, nhất định được vui mừng ngoài ý liệu của mọi người. Mọi người tôn vinh ta, quý\nmến ta và ta có thể thẳng tiến trên đường vinh hoa, mãi tới lúc bạc đầu.\nQuẻ thơ tả cảnh người cầu xin rằng: Tôi là tinh tú gì, tôi là sao sáng gì, mà được thành danh bể đông sông\nbắc, như một đoạn thần xưng, xung thẳng mây trời xanh, những lời thơ toàn là may mắn tốt đẹp cả.\nTất cả việc cầu xin của người, đều được toại nguyện mà chẳng lo gì trở ngại, nếu cầu tài còn có thể trúng\nsố nữa là khác, vì câu thứ nhất nói: Tôi là sao sáng gì, lại được thanh danh vậy. Phải chăng đó là nói người\nnên sự nghiệp, còn không biết do đâu mà có như tình hình trúng số vậy.\nQuẻ dạy: Thới Lai Phong Tống, tốt đẹp vô cùng. Lợi danh đều đẹp. Tăm tiếng như cồn. Số rất hạp. Số\nhên: 88, 33, 80", "g": "Khéo chọn cách thức hay ho, nếu được người giỏi truyền cho kinh nghiệm, thì kết quả mới nên,\ngiống như có thần hỗ trợ vậy.", "s": ""}, "84": {"c": "TRUNG TRUNG", "hexagram": "Trạch Phong Đại Quá", "line_label": "Động Hào Lục", "p": "Kim lân nhập thủ,\nĐắc hoàn phòng tấu.\nNhược luân chu tuyền,\nCẩn ngôn châm khẩu.\nLân vàng bắt nắm trong tay,\nVẫn phòng cẩn thận sau này thoát đi.\nGiao du bất cứ việc gì,\nHãy nên kín miệng, vậy thì mới hay.", "b": "Khi được quẻ này thì bất cứ sự việc gì mưu đồ đều được xứng tâm toại ý cả. Tuy nhiên ta vẫn để tâm lo\nlắng đề phòng cẩn thận chớ có phóng túng bừa bãi. Trong lúc giao thiệp với người, tốt nhất phải trầm mặc,\nít nói, chớ có nhiều lời mà thất bại. Xin được quẻ này cần phải thể theo cài ý mà thực hành.\nThơ quẻ nói: Thời vận của người đã lên hương như cá vàng nay nằm trong tay rồi. Nhưng cũng nên cẩn\nthận đề phòng để tránh những điều không hay xảy ra, như quẻ thơ này. Phòng ngừa con cá vàng đó lại\nchạy mất và muốn được yên lành sự việc cầu xin thì phải kín miệng nữa\".\nTheo ý quẻ: Những việc cầu sinh của người được toại nguyện nhưng phải tốn công chăm lo mới nên.\nQuẻ dạy: Cần kín miệng và thận trọng kẻo việc thành, lại hóa ra không. Cầu danh, cầu lợi thông, nhưng\nphòng thất bại. Đánh số hạp. Biểu tượng: cá.", "g": "Vãy vàng ý nói đến tiền bạc, nhắc nhở cho mình nên ít lời giảm nói, nếu gặp bè bạn hỏi mượn\ntiền, cẩn thận coi chừng bị lường gạt.", "s": "80, 40, 44, 88, 4, 8, 84, 48."}, "85": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Thủy Khốn", "line_label": "Động Hào Nhất", "p": "Khuynh nhất bôi,\nTriển sầu mi.\nThiên địa hợp,\nHảo tư vi.\nNày ta rót rượu một ly,\nGọt sầu rửa hận còn gì bận tâm.\nĐất trời hòa hiệp tương thân,\nXin cầu mọi việc ắt lành hanh thông.", "b": "Đây là quẻ nói hoàn cảnh trước lo sau vui, trong khoảng cách cao xa vô cùng vô tận, ta chỉ còn biết cười\ntrong ngấn lệ, để tự liệu tự xếp đặt lấy việc mình. Nhưng một khi trời đất đã giao hòa, cơ thái đã trở lại thì\nđó là cái thời của mình đã đến, lúc mà ta có thể thực hiện được hoài bão của ta hằng ấp ủ.\nBói được quẻ này cứ việc suy nghĩ cẩn thận mà làm, tự nhiên có thần lực tự nhiên tới giúp ta, không có gì\nđáng lo buồn nữa.\nQuẻ thơ khuyên hãy rót ly rượu để rửa hận sầu, tức là ngày nay có rượu ngày nay say, mặc kệ ngày may\nchuyện vui sầu. Nghĩa là dạy người phàm việc chớ nên xem trọng quá hãy cho nó tự nhiên phần nào. Còn\nhai câu sau ý nói chờ khi thời vận đến thì rất dễ dàng thành đạt những việc cầu mưu.\nVậy việc cầu xin của bạn, chẳng có gì đáng lo hãy yên tâm cố gắng cầu tiến, ắt có một tương lai sáng lạng\nđấy.\nQuẻ dạy: Rất tốt đẹp. Cầu được ước thấy. Sự sự thông hạnh. Cầu tài, cầu danh viên quả. Đánh số hạp. Số\nhên: 80, 50, 88, 55, 8, 5, 85, 58.", "g": "Cũng vì chén rượu nên sanh chuyện—Mau mau năn nỉ mới yên vui—Vợ chồng tình cảm dài lưu\nluyến—Chớ để đam mê phá hoại đời.", "s": ""}, "86": {"c": "HẠ HẠ", "hexagram": "Trạch Thủy Khốn", "line_label": "Động Hào Nhị", "p": "Dã quỉ trương hồ xa chủ nhân,\nÁm trung nhất tiễn quỉ hồn kinh.\nHốt nhiên hồng nhật trầm giang hải,\nNan phá không trung sự bất minh.\nThừa phụng quỷ ma hại chủ mình,\nBắn tên lén rút quỷ thần kinh.\nMặt trời bỗng lặn vào sông biển,\nNan giải những điều chửa phân minh.", "b": "Quẻ này chủ về việc đứa tiểu nhân khinh lờn qua mặt. Bọn gian nịnh kết thành bầy lũ, đàn lang sói cản\nđường, đàn hồ ly ghẹo cợt. Đứng trước hoàn cảnh này, cần giữ lòng mình chính trực, làm việc đàng hoàng\nminh bạch không loanh quanh tầm bậy, ấy thế mà chưa khỏi cảnh bị người dèm chê, bị người áp chế đè\nnén.\nBởi thế chẳng may xin phải quẻ này, thiệt tưởng nên rút lui về mà đứng đằng sau người, mong tránh\nnhững điều nguy hiểm trở ngại, chớ có xuất đầu lộ diện, xông lên mà có nguy hại cho mình.\nTheo bài quẻ cho biết người cầu xin được quẻ này, vận thời của người vẫn chưa được hanh thông, bởi vì\ncòn trong cảnh như tớ phản chủ. Tiểu nhân mưu toan và mặt trời lặn tây vậy, toàn là kém may mắn cả.\nVậy tất cả sự cầu xin của người khó mà như ý, nhưng nếu người theo sát vấn đề sở cầu, giải quyết từng\nkhó khăn khi vấp phải thì cũng dễ thở phần nào, dù không thành đạt mỹ mãn.\nQuẻ dạy: Phòng tiểu nhân thất bại. Xấu, mặt trời lặn còn đâu ánh sáng mà đi, nghĩa là đang lúc túng, bế\ntắc. Cầu tài, cầu mưu bất thông. Đánh số không lợi.", "g": "Được quẻ nầy, ví như người chủ có làm điều tệ bạc với thuộc hạ, nó tức giận liều chết trả thù chủ.", "s": "6, 66, 60, 16, 26, 36."}, "87": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Thủy Khốn", "line_label": "Động Hào Tam", "p": "Phúc tinh chiếu,\nCát tú lâm.\nThanh thiên hữu nhật kiến thiên chân,\nLong phi hạ tả đáo minh đình.\nPhước tinh chiếu cát tinh lâm,\nTrời cao quang đãng, trời xanh rõ ràng.\nCó gì mà phải hoang mang,\nRồng bay hạ giáng hân hoan một đời.", "b": "Đây là quẻ chủ việc công thành danh toại, tài lợi thu về như nước, ngũ phúc thật là mỹ mãn khiến gia đình\nphú quý yên vui đến cực độ. Phải chăng đây là nhà trung hiếu gồm đủ cho nên mới có cái sự thiên báo như\nvậy. Xin được quẻ này thật không còn gì là không lợi.\nNgười cầu được quẻ này quả là tốt lắm rồi, thời vận đã đến lúc đời lên hương người hãy mau lên, mưu cầu\nnhững công việc đã định lâu nay, ắt sẽ được toại nguyện như ý muốn.\nBởi quẻ nói, hiện những sao sáng tốt đang chiếu vào bạn và đến với bạn trên đường đời của bạn sáng sủa\nlắm rồi.\nQuẻ dạy: Hỉ!Hỉ! Tốt đẹp vô cùng. Mưu sự đắt quả nguyện cầu. Cầu tài, cầu danh may mắn vô cùng. Đánh\nsố tốt lắm.", "g": "Quẻ nầy tốt lành, được hưởng phước đức ơn Trên hộ trì giúp đỡ.", "s": "8, 7, 78, 87, 70, 80, 77, 88."}, "88": {"c": "HẠ HẠ", "hexagram": "Trạch Thủy Khốn", "line_label": "Động Hào Tứ", "p": "Độc điếu hàn đàm,\nTrung đồ hưng lan.\nThủy hàn ngư bất nhỉ,\nKhông tải nguyệt minh hoàn.\nMột mình câu cá tại hàn đàm,\nChừng nữa ba đào lại nỗi nga ng.\nNước lạnh nào đâu có cá chịu,\nĐành tay trắng chờ trăng huy hoàng.", "b": "Quẻ này chủ cầu mưa chẳng đạt, xuất hành thì thất thế. Cầu tài thì mất vốn, tìm người thì sinh miệng lưỡi,\nkiện tụng thì phải nhờ người, hôn nhân thì không thành, giao dịch thì vô vọng, xem bệnh thì thấy tai họa.\nTóm lại tất cả đều không tốt.\nTheo quẻ thơ tả cảnh tình của người hiện nay. Như người cô đơn câu cá nơi vực lạnh, và nửa chừng lại nổi\nsóng gió thì cá đâu chịu ăn, rút cuộc chờ trăng về thôi.\nĐó ý nói rằng: Công việc cầu xin của bạn khó mà toại theo ý nguyện, dù cố gắng đến đâu, tay trắng vẫn là\ntay trắng, như câu thơ chót nói Đành tay trắng, chở trăng huy hoàng vậy.\nQuẻ dạy: Thất bại, đổ vỡ có thể tù tội, câu cá trong đêm lạnh mà lại có sóng gió nữa, thì cá nào ăn chớ?\nCâu trong đầm nhỏ hẹp, ý là bị giam giữ trong ao tù. Chớ tính, chớ đợi. Cầu tài, cầu danh thất bại. Đánh\nsố chẳng đến đâu, biểu tượng: cá.", "g": "không tốt. Tình hình không thuận lợi nữa, tìm cách rút lui là vừa.", "s": "8, 88, 80, 18, 28, 38."}, "89": {"c": "HẠ TRUNG", "hexagram": "Trạch Thủy Khốn", "line_label": "Động Hào Ngũ", "p": "Bất quý nhất,\nLao tâm lực.\nQuí nhân bàng,\nNghị tá lực.\nSự nghiệp không thành thiếu dốc lòng,\nCam đành phí sức và hao công.\nQuý nhân đứng kế nên nương dựa,\nHãy mượn sức người việc mới xong.", "b": "Quẻ này chủ một mình kinh doanh, lao tâm lao lực, công việc thì nhiều mà công sức may ra chỉ phân nửa.\nTrong trường hợp này, cần phải có quý nhân phò trợ mới mong chấn hưng được thanh danh cho gia đình,\nvà thành tựu được sự nghiệp của mình.\nKhi xin được quẻ này, cần phải lo liệu ngay để đi tìm người giúp đở mình mới được. Theo ý quẻ cho hay,\nnhững việc cầu xin của bạn cần phải nương dựa sức người thì mới thành đạt việc mưu cầu của mình.\nVà phải dốc lòng chuyên nhứt. Chớ đừng cam tâm hưởng ý thì hỏng, mà hóa ra phí sức hao công. Sở dĩ tôi\ndám khuyên bạn như thế, là căn cứ vào lời quẻ chỉ dạy trên đây đó.\nQuẻ dạy: Kiên tâm và dốc chí. Cần nương chí của người mới kết quả. Cầu tài, cầu danh đều phải nương\ndựa. Đánh số hạp.", "g": "Việc muốn hỏi có sự bất đồng ý kiến với nhau, sanh ra cãi cọ lung tung. Phải nhờ người nhiều uy\ntín đứng ra dàn xếp, mọi việc mới có hy vọng.", "s": "80, 90, 99, 88, 8, 9, 98, 89."}, "90": {"c": "THƯỢNG THƯỢNG", "hexagram": "Trạch Thủy Khốn", "line_label": "Động Hào Lục", "p": "Vân tận nguyệt dương trung,\nQuang huy đáo xứ thông.\nLộ đồ phùng thủy thuận,\nThiên lý khoái như phong.\nMây tan trăng sáng giữa trời trung,\nSáng chói đường đi nẻo khắp cùng.\nĐường sá suốt thông và được thuận,\nVận trình ngàn dặm để thành công.", "b": "Mây tạnh ắt trời quang, nhờ đó trăng soi sáng khắp trần gian. Đấy là triệu chứng của công việc kinh doanh\nđều được toại ý, do đó khi xuất hành rất nên đi xa, bởi vì tài lợi sẽ được dồi dào, phong phú thu vào nhiều\ndịp như nước.\nNgoài ra trong gia đình còn vượng cả nhân khẩu tức là sanh con đẻ cái đầy đàn, người ăn kẻ ở, kẻ hầu\nngười hạ đông đủ rộn rịp.\nTóm lại khi họa đã đi rồi thì phúc tất đến, không có gì phải lo nghĩ. Quẻ này chính là cái tượng chứng tỏ\nđiềm trước khó sau để cho Người xin được.\nTheo quẻ cho hay, thời vận của bạn hiện nay, đã như mây tan trăng sáng giữa trời, đường thông nước\nxuôi, vận trình ngàn dặm mau như gió bay. Nghĩa là thời vận của người đã hanh thông, đắc thời lên hương\nrồi chẳng còn trở ngại gì nữa .\nVậy, những sự việc cầu mưu lâu nay của bạn, từ nay sẽ lần lần đắc ý toại nguyện, hãy mau tiến tới đi.\nĐừng chần chừ mất dịp may.\nQuẻ dạy: Mã đáo thành công, buồn xui chèo thuận, đời sắp lên hương. Cầu tài, cầu danh sự sự đắc quả.\nĐánh số thật tốt.", "g": "Hoàn cảnh chuyển sang thuận lợi, tình hình tốt đến rồi. Điều muốn hỏi hoàn toàn tốt đẹp như ý.", "s": "9, 90, 99, 19, 29, 39."}, "91": {"c": "TRUNG TRUNG", "hexagram": "Trạch Sơn Hàm", "line_label": "Động Hào Nhất", "p": "Kiếm kích liệt sơn lâm,\nĐạo tặc ắt tái xâm.\nBài tẩu cầm sưu đinh,\nPhong hầu ấm tử tôn.\nGươm đao bày để núi rừng,\nKẻ gian đạo tặc ắt rình lại xâm.\nPhi thua chạy trốn phi tầm,\nĐược phong hầu, để phước lành đời sau.", "b": "Làm việc nên có dũng, lại có mưu. Đã thế lại còn cần phải có lực lượng hùng hậu để có thể đẩy lui mọi trở\nngại khó khăn, mà đón rước những sao tốt đến với ta. Nhờ đó tiến trình của ta khá cao xa, chưa biết đâu\nmà lường được.\nNgười xin được quẻ này, tức là đã được triệu chứng nhiều hy vọng. Theo ý quẻ cho hay, những việc cầu\nxin của bạn cần phải cố gắng mà làm, và vượt khỏi những gian hiểm thì mới thành đạt sở cầu.\nBởi quẻ nói rằng, việc cầu mưu rất gian nan, mà sự gian nan như bắt kẻ trộm vậy và nếu khi truy tầm bắt\nđược nó, sẽ được ban phong và con cháu sẽ hưởng phước đó vậy, việc cầu mưu của bạn ắt sẽ thành công,\nnhưng phải cố gắng trong việc làm thì mới nên.\nQuẻ dạy: Qua gian nguy thì đắc quả. Cần cố gắng mới nên công. Thời hạnh phúc vàng son sắp đến. Cầu\ntài, cầu danh có khó, sau mới thành. Đánh số rất tốt.", "g": "Hai bên dàn trận đánh nhau, phải có mưu thần bày sẵn, chờ kẻ địch tới. Chắc chắn thắng lợi, thỏa\nlòng mong chờ, thu chiến lợi phẩm.", "s": "1, 9, 19, 91, 90, 11, 99, 10."}, "92": {"c": "TRUNG THƯỢNG", "hexagram": "Trạch Sơn Hàm", "line_label": "Động Hào Nhị", "p": "Ngan thoát thủy thâm chu di lạc,\nLộ dao sơn kiểm hộ an hành.\nXà hành tựu hữu thông tân nhật,\nNguyệt thượng thiên không phận ngoại minh.\nNước sâu bờ rộng dễ đi thuyền,\nNúi hiểm đàng xa khó hiển nhiên.\nNhưng rắn bò hoài vẫn đạt đích,\nTrời cao trăng sáng khắp nơi miền.", "b": "Đây là quẻ chứng tỏ trước khốn khó, sau yên vui. Con người ta cần phải có khổ mới có sướng, lúc đầu có\ngian nan vất vả có chịu đủ mọi thiệt thòi thì mới mong công thành danh toại trong tương lai. Nếu không\nthế thì quyết chẳng gặp hội thanh vân vậy.\nĐây báo là quẻ cho ta một sự việc phi thường của lột con người phi thường thành đạt vĩ đại.\nÝ quẻ dạy rằng: Những việc cầu xin của bạn, tuy rất khó khăn và vấp nhiều trắc trở như trèo leo núi hiểm,\nlặn lội đường xa.\nNhưng bạn bền chí chịu đựng, tiến tới ắt sẽ thành đạt ý cầu trong nay mai, bởi quẻ có ví việc cầu của bạn\nnhư con rắn bò mải vẫn tự nó có ngày đến đích, như trăng giữa trời đẹp đẽ.\nQuẻ dạy: Hết gian nan đến thành tựu. Tuy nhiên phải cố công, mới mong đạt đích. Biểu tượng: Rắn. Cầu\ndanh, cầu lợi phải qua lần khó, mới mong thành. Đánh số hên.", "g": "Việc muốn hỏi, nên tìm cách cho thoáng mà giải quyết, có tầm nhìn xa một chút, mới đạt được\nthành công.", "s": "92, 29, 9, 2, 90, 20, 99, 22."}, "93": {"c": "TRUNG TRUNG", "hexagram": "Trạch Sơn Hàm", "line_label": "Động Hào Tam", "p": "Nghĩ dục hoàn phi vị khả thiên,\nĐể phòng hỉ xứ nhạ câu liên.\nTiền đồ nhược đắc âm nhân dẩn,\nBiến hóa ngư long xuất đại uyên.\nMuốn dọn mà đi chưa thể đi,\nChỗ vui chớ quá lại mê lì.\nTiền đồ nếu được quý nhân giúp,\nBiến hóa ngư long kiến nghiệp kỳ.", "b": "Quẻ này chủ mọi việc đổi thay, tình đời khó lường, trong cái vui cũng có cái đáng lo, đáng sợ. Nhưng nếu\ncó kẻ nhầm giúp ta chỉ vẽ cho ta, thì mới có thể dần dần mà tiến thẳng được, và mới có thể rỡ ràng thân\nthế được.\nQuẻ thơ khuyên rằng: Phàm muốn cầu mưu một việc gì, phải quyết chí một lòng và chớ vì lợi nhỏ mà\nquên lợi to như câu thơ thứ hai nói: Chỗ vui chớ quá lại mê lì.\nHơn nữa, bạn nên nhân hòa thì mới được người giúp ích công việc sở cầu, được như thế việc mưu chẳng\nchỉ thành đạt, mà còn thành công một cách phi thường nữa là khác, như hai câu thơ chót nói Tiền đồ nếu\nđược quý nhân dẫn, biến hóa ngư long kiến nghiệp kỳ vậy.\nQuẻ dạy: Cố gắng, nên công lớn. Hãy vì lợi lớn, mà bỏ lợi nhỏ. Cần có quý nhân đưa đường, dẫn lối cho\nmới hay. Cầu danh, cầu lợi đều hay. Biểu tượng: Rồng. Đánh số tốt.", "g": "Đừng bởi quá mừng mà tối trí—Chớ nên hoan lạc hóa ra phiền.", "s": "99, 33, 90, 30, 9, 3, 39, 93."}, "94": {"c": "TRUNG TRUNG", "hexagram": "Trạch Sơn Hàm", "line_label": "Động Hào Tứ", "p": "Nhất nhân xuất,\nNhất nhân nhập.\nThanh phong minh nguyệt lưỡng tương sai,\nĐộc đắc kim lân hạ điếu đài.\nMột người đi một người vào,\nGió trong trăng sáng, trời cao dặm ngàn.\nKhi ta bắt được cá vàng,\nHãy ngừng tay, chớ mơ màng quá xa.", "b": "Quẻ này chủ trương đạo của đứa tiểu nhân tiêu (kém) mà đạo của người quân tử trưởng (hay). Cho nên\nmột người ra, một người vào, tương phản nhau, chống đối nhau, không thể dung nhau được. Trong trường\nhợp này, nếu khi ta bắt được một con lân vàng rồi thì nên rút lui ngay, tức gọi là công thành thì thân thoái\nđó.\nNgười xin được quẻ này, chớ nên tham lam luyến tiếc nhiều khi mình mưu đồ việc gì. Khi việc đã thấy\nxong, danh đã thấy thành rồi thì nên ngừng, nên nghĩ chớ tham, cần phải có một nền minh triết để giữ\nmình là hơn.\nThời vận hiện nay của người, không tốt không xấu mà trong cảnh bình thường thôi và theo ý quẻ cho biết,\ntuy vậy vẫn còn có lúc may mắn, nhưng khi gặp may thì chớ có ham hố lắm tức là quẻ mách bạn phải làm\nđến mức vừa mà đừng quá sức thì có hại vậy.\nQuẻ dạy: Có gặp may. Nhưng chớ tham lam. Cầu tài, cầu danh lợi chậm và bình thường. Đánh số không\nhạp lắm. Biểu tượng: cá.", "g": "Hai người hợp tác làm ăn—Cớ sao lòng cứ bàng hoàng hồ nghi—Thành công đến, hết lo gì—Hôn\nnhân cầu tự nữ nhi được rồi.", "s": "90, 40, 99, 44, 4, 9, 94, 49."}, "95": {"c": "HẠ HẠ", "hexagram": "Trạch Sơn Hàm", "line_label": "Động Hào Ngũ", "p": "Hỉ vị ân,\nBi vĩ tao.\nĐại vũ cuồng phong xuy cô mộc,\nNhân nhân tạn dạo bất kiên lao.\nSự việc vui mừng còn chữa thôi,\nAi sầu chuyện nọ lại theo rồi.\nMưa to gió bão rung cây cỏ,\nAi nấy đều cho khó vững ôi!", "b": "Bói được quẻ này, nếu có vui lúc đó thiết tưởng chớ nên vui, bởi vì có thể thất ý khiến đau khổ bi thương\nlắm đấy. Hai câu thơ sau đó có ý nói sự nghiệp lung lay, khó có thể đứng vững, chẳng khác gì mưa to gió\nlớn thổi dập nát cây cối dù là cây cổ thụ. Bởi thế cho nên trước hết là phải biết hoàn cảnh để giữ chân cho\nvững.\nNgười xin được quẻ này nên an cư mà nghĩ tránh cài nguy mong thoát được tai họa ngoài ý liệu của mình.\nTheo quẻ cho biết: Những việc cầu mưu của bạn, cần phải cẩn thận lưu tâm chăm chú mới tránh được\nnhững đều không may gây ra, mà không nên đặt cao vọng nữa rồi phiền chí làm chi. Bởi thời vận hiện\nthời của người hiện nay đang như cây cối ở trong cảnh gió bão, bị rung rinh tận gốc.\nVậy bạn nên cố sức và ráng chịu một thời gian nữa chờ khi mây tan gió lặn, thời vận hanh thông rồi mới\ntính lại việc cầu mưu là hay hơn.\nQuẻ dạy: Ẫn nhẫn chờ thời. Đừng nản chí vì thất bại. Đang gặp buồn phiền đổ vỡ. Cầu tài, cầu mưu chẳng\nlợi. Đánh số dở.", "g": "Ở đời lúc vui lúc buồn thay nhau là chuyện bình thường. Đừng nên quá vui mà cũng chẳng nên\nbuồn quá đáng !", "s": "90, 50, 99, 55, 9, 5, 95, 59."}, "96": {"c": "TRUNG TRUNG", "hexagram": "Trạch Sơn Hàm", "line_label": "Động Hào Lục", "p": "Khả dĩ ký thiên lý chi mệnh,\nKhả dĩ thác lục xích chi cô.\nChung kỳ ký đoan vô trì ngộ,\nTiếu hô hô,\nTha hương án thủ.\nCác tự lạc khang hóa.\nCó thể cậy nhờ trăm dặm xa,\nBé con cũng thể cậy trông mà.\nDịp may đã gặp chớ lầm bỏ,\nĐất khách cười vui hưởng phận ta.", "b": "Hễ có lòng tốt trời ắt giúp cho. Quẻ này cho ta biết ta sẽ gặp tri kỷ, người bạn tâm giao, có thể gởi mạng,\ngửi con được. Đối vời người bạn đó, dù công việc có trọng đại đến đâu mà ta nhờ vả, giao phó quyết\nphông phụ lòng ta, phản lại ta. Do đó ta có thể vui vẻ yên tâm được.\nĐây là quẻ chủ sự may mắn, đáng mừng là gặp được người tri kỷ.\nÝ thơ cho rằng: Thời vận của bạn đã được hanh thông như trăm xa cũng nhờ cậy và giúp ích cho mình\nđược chẳng còn sức yếu cô đơn như trước nữa, nên quẻ dạy thêm rằng: dịp may đã đến phải nắm lấy mà\nđừng bỏ lỡ, thì bạn sẽ được vui tươi cuộc đời đó.\nVậy, những việc cầu xin của bạn, phải tiến hành mau đi, đừng chần chờ mà mất dịp uổng.\nQuẻ dạy: Cứ tiến, dịp may đã đến, đừng chần chờ. Cần phải trông cậy vào người giúp đỡ, dù là trẻ con.\nNhưng nó thành công, thì cũng chỉ thành công ở nơi đất khách mà thôi. Cầu tài, cầu danh thuận lợi hơi\nchậm. Đánh số khá hạp.", "g": "Người được quẻ nầy,đúng như mong ước, nay gặp tri âm, kết nghĩa Tấn Tần, hạ sanh quí tử.", "s": "90, 60, 66, 99, 69, 6, 9, 96"}, "97": {"c": "THƯỢNG THƯỢNG", "hexagram": "Bát Thuần Ly", "line_label": "Động Hào Nhất", "p": "Báo đạo thượng lâm,\nXuân sắc tiên minh.\nĐể tiến thoái trước,\nMã thượng hành trình.\nRừng cây đã báo xuân về,\nSắc màu tươi sáng bề bề vui tươi.\nGiương roi đuổi ngựa kịp thời,\nVận trình ngàn dặm, cuộc đời hân hoan.", "b": "Quẻ này khuyên ta hăng hái tiến lên, vượt hết mọi trở ngại, chớ có lơ là, để trôi qua ngày tháng. Nếu đã\ndám dũng cảm hoạt động, khắc phục mọi gian nan để thành công thì cuộc giai ngộ chỉ ở trước mắt. Người\nxin được quẻ này phải biết nắm lấy cơ duyên chớ nên bỏ lỡ.\nThơ quẻ tả cảnh của bạn hiện nay như là mùa xuân đã về với trần gian. Cảnh tình tươi đẹp vui vẻ, đó là ý\nchỉ cho bạn biết rằng, thời vận đã được hanh thông rồi. Không còn bế tắc gì nữa. Và tiếp hai câu sau dạy\nhãy mau vung roi giục ngựa tiến bước để nắm lấy những tốt đẹp may mắn cho cuộc đời sung sướng.\nVậy, những việc cầu xin của bạn nhứt định không gì trở ngại mà ắt thành đạt như ý nguyện, nhưng bạn\nphải ra công mới nên, chớ không phải bất chiến tự nhiên thành.\nQuẻ dạy: Thời thông hạnh, cần cố gắng tranh thủ cho kịp, thì mọi sự như ý sở cầu, vô cùng tốt đẹp. Cầu\nđược ước thấy. Cầu danh, cầu lợi đắc quả. Đánh số hạp. Biểu tượng: Ngựa.", "g": "Mọi việc thuận lợi, thời cơ tốt đẹp đã đến, an tâm lên đường.", "s": "7, 9,97, 90, 70, 99, 77."}, "98": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Ly", "line_label": "Động Hào Nhị", "p": "Thử nhạn thổ huyệt,\nTối khả an thân.\nNhật tung bất kiến,\nTỉnh dạ tuân hành.\nChuột chui hang đất an thân,\nQuả là biết cách, tốt lành vô biên.\nBan ngày dấu kín nằm yên,\nTuần hành đêm tối, có phiền đến ai.", "b": "Người xin được quẻ này nên chủ trương sống ẩn dật nơi sơn lâm. Tránh được những nơi thị tứ chắc cuộc\nđời yên ổn hơn nhiều. Hai câu thơ sau: chẳng thấy lúc ban ngày, chỉ thấy giữa đêm khuya là câu tỷ dụ ý\nnói ban đêm chỉ riêng mình tỉnh mà suy nghĩ đến những chuyện đục trong. Đứng trước những lời nói đại\nngôn khiến ta sinh tiến thoái lưỡng nan thiết tưởng chớ nên nghe, nghe người chỉ là mua lấy nguy cho\nmình mà thôi.\nÝ quẻ khuyên ta rằng, phàm muốn cầu mưu bất cứ việc gì ta hãy biết khôn ngoan, khéo léo thì mới mong\nthành đậu sở dục, nếu không sẽ hư hỏng mọi việc làm.\nBởi quẻ ví những việc cầu mưu của như con chuột, phải tìm chổ vững chắc mà ở và ban ngày giấu mình\nmà ban đêm mới ra thì chẳng lo bị người ta sát hại, nghĩa là việc mưu phải biết hoàn cảnh khôn ngoan và\ntiến hành khéo léo mới nên vậy.\nQuẻ dạy: Cơ cảnh khôn khéo xử sự trong công việc thì ắt thành, cần có công. Cầu tài, cầu mưu thuận lợi,\nchậm. Đánh số thuận lợi. Biểu tượng: Chuột.", "g": "Trước đây cứ muốn cầu an—Đến nay cơ hội bằng vàng hiện ra—Mau mau nắm lấy thời cơ—Bỏ\nqua biết đến bao giờ mới nên.", "s": "90, 80, 99, 88, 9, 8, 89, 98."}, "99": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Ly", "line_label": "Động Hào Tam", "p": "Đã khởi bình sinh chí,\nTây nam hảo khứ du.\nYên triền thập vạn quán,\nKỵ hạc thượng dương châu.\nMau nên phấn khởi chí bình sanh,\nNẻo hướng tây nam rất tốt lành.\nTiền bạc đầy mình ông vấn bó,\nLên đường cỡi hạc đáo châu thành.", "b": "Quẻ này khuyên ta nếu biết làm ăn cần khổ, tất nhiên trở thành giàu có. Tuy nhiên, phát tích phải từ\nphương tây nam, nếu không thì vô ích. Ví thử y theo phương hướng đã chỉ điểm và thản nhiên tiến bước\nthì một ngày kia thế nào cũng đem theo tiền bạc về nhà. Người xin được quẻ này thiết tưởng chớ nên cố\nchấp ý kiến của riêng mình mà sai với lời khuyên dạy này.\nLời thơ nói: Người mau phấn khởi tinh thần làm những việc đã trông mong lâu nay đi, đừng nên lững lờ\nnữa và phải nhắm hướng tây nam ắt sẽ tạo nên nghiệp giàu sang, hưởng lạc nơi thành Dương Châu.\nTheo ý quẻ nói trên, thời vận của bạn đã được hanh thông, những sự cầu xin sẽ được như ý mong muốn,\nkhông gì trở ngại rồi vậy.\nQuẻ dạy: Cố gắng. Đi hướng tây nam, ắt phùng danh, phùng lợi. Biểu tượng: Con hạc. Cầu tài, cầu lợi đạt.\nĐánh số rất tốt.", "g": "- Người được quẻ nầy sẽ được thành công tốt đẹp. Trước đây có gặp một vài trở ngại, nay đã hết rồi,\nkhả năng đủ sức, cứ thẳng đường lên.", "s": "9, 99, 90, 19, 20, 39"}, "100": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Ly", "line_label": "Động Hào Tứ", "p": "Hỉ! Hỉ! Hỉ! Chung phòng bỉ,\nHoạch đắc ly long hạm hạ châu.\nHốt nhiên thất khước,\nHoàn tại thủy lý.\nVui vẻ nên phải phòng sầu,\nHiện nay tuy được hợp chầu long ly.\nBỗng nhiên lại mất thực kỳ,\nMay còn dưới nước, chưa gì đáng lo.", "b": "Quẻ này chỉ cái tượng được mà lại mất. Bóng trong gương trăng đáy bể, tất cả chỉ là ảo ảnh không có\nthực. Trường hợp này cũng thế. Tuy nhiên nếu biết lo lắng giữ gìn cẩn thận, ắt có thể giữ được, khỏi mất\nđể đến nổi tay không. Người xin được quẻ này nên đề phòng hết sức cẩn thận mới được.\nÝ quẻ nói rằng: Những sự cầu mưu của bạn tuy được thành đạt vui vẻ, nhưng cũng nên phòng khi quá vui\nlại sanh việc sầu gây ra những điều không hay, cần phải cẩn thận mới giữ được vui lành chung thủy, nếu\nkhông khó tránh chuyện phiền lòng, như lời quẻ thơ nói hiện nay tuy được hợp chầu long ly, bỗng nhiên\nlại mất thực kỳ vậy. Tuy nhiên như câu chót nói chưa đến đổi đáng ngại lắm.\nQuẻ dạy: Việc thành, không khéo e mất. Cẩn thận, đắn đo trong mọi việc mới thành đạt hoàn toàn. Cầu\ntài, cầu danh được, nhưng phòng tiểu nhân. Đánh số tốt.", "g": "Đề phòng lúc cực tốt sẽ nảy sinh việc không hay xảy đến.", "s": "1, 10, 11, 21."}, "101": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Ly", "line_label": "Động Hào Ngũ", "p": "Quốc hữu hiền sĩ,\nĐĩnh vô ninh thần.\nCan qua bất dụng,\nĐương hưởng thái bình.\nNay trong nước có sĩ hiền,\nNịnh thần xa lánh bằng miền đi xa.\nCần chi động can qua,\nThái bình an hưởng hoan ca đời đời.", "b": "Quẻ này chủ trăm việc đều được như ý, thật là đại cát đại lợi.\nKhi mưu sự thì đắc chí, lúc lo lập công danh thì có thần giúp, khi có người ra đi thì đã sớm trở về, lúc mất\nvật thì đã sớm tìm ra.\nVào những năm lục giáp thì sanh con trai ( Lục giáp: Giáp Tý, Giáp Tuất, Giáp Thân, Giáp Ngọ, Giáp\nThìn, Giáp Dần).\nNếu lo việc hôn nhân thì đều thành tựu.\nNếu chẳng may bệnh hoạn thì chóng lành.\nNgười được quẻ này ắt mừng vui chắc chắn rồi.\nÝ quẻ tả rằng hiện trong nước có hiền sĩ nên bọn nịnh thần mất tích, dao gươm chẳng dùng, thời đã thái\nbình mà ta được an hưởng. Nghĩa là nói người cầu xin được quẻ này thời vận của bạn hanh thông chẳng gì\ntrắc trở cả.\nVậy sở cầu của bạn chẳng những đạt đại đăng khoa kim bảng mà còn đạt thêm nữa, tiểu đăng khoa nhưng\ncũng phải cố gắng chớ nên khoái mà bỏ học hành thì hỏng.\nQuẻ dạy: Đã đến lúc gặp vận hên. Cuộc đời sắp được lên hương vàng mộng. Chỉ cần tu nhân tích đức\nthêm, là chẳng cần lo gì cảnh đời gian khổ nữa. Cầu tài, cầu danh đến hanh thông. Đánh số tốt.", "g": "đời thịnh thái bình , gia đình an vui .", "s": "10,\n1, 2."}, "102": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Ly", "line_label": "Động Hào Lục", "p": "Thái lai bỉ dỉ cực,\nChư sự mạc ưu tâm.\nĐản tu bồi dương hậu phúc,\nTố ta hảo sự hành ta phương tiện,\nNhất điêm đan linh đọc đắc chan.\nRủi đi may đến cùng ta,\nMỗi điều vui vẻ chi mà bận tâm.\nNhưng cần nuôi dưỡng tinh thần,\nLàm điều phước đức là thân tốt lành.", "b": "Quẻ này chỉ rõ cho ta thất thời đã tới, vận đã chuyển Phúc sau hưởng mãi vô cùng.\nTuy vậy vẫn phảo lo làm điều thiện để tích phúc, có thể lòng thành của ta mới cảm kích tới trời nhờ độ\nmới lâu dài được.\nNgười xin được quẻ này nên tuân theo lời chỉ dạy mà cố thực hành.\nTheo ý quẻ cho hay rằng thời vận của bạn hiện nay thì đi xa gặp may đến rồi tức là vận trình hanh thông\nngàn dặm chẳng có gì trở ngại nữa. Nhưng chỉ cần nuôi dưỡng tinh thần và làm điều phước đức. Thì ắt\nquả lành vậy.\nNhư thế những việc cầu xin của bạn hãy nhắm theo việc chính, chớ tính ta thì tất cả sẽ gặp may mắn và\nthành đạt ý nguyện đấy.\nQuẻ dạy: Đi xa ắt gặp may. Chỉ cần nuôi dưỡng thêm tinh thần, đạo đức nữa, là cuộc đời ắt có hạnh phúc,\ngiàu sang. Cầu danh đắc danh, cầu lợi đắc lợi. Đánh số tốt.", "g": "đây là mẫu người biết tu dưỡng tâm tính, tạo công đức, nên hưởng quà lành.", "s": "1, 22, 11, 10."}, "103": {"c": "TRUNG THƯỢNG", "hexagram": "Hỏa Lôi Phệ Hạp", "line_label": "Động Hào Nhất", "p": "Dân lạc nghiệp, quan lại thanh,\nThuấn, Nghiêu chi thê phục kiến vu kim.\nCáo chư nhân tiên thu hồng nghiệp,\nPhục thử vọng minh quân.\nLạc nghiệp dân an quan lại thanh,\nThái bình thạnh thế thấy nay lành.\nCáo tri người, rõ ngàn Thu Mộng,\nNương dựa dịp này gặp Đế Quân.", "b": "Người được quẻ này thực là tùy ngộ nhi an, không có chuyện gì là không được thuận lợi, toại lòng, bước\nbước gặp xuân phong, tưởng không còn gì khang lạc hơn nữa.\nNgười được quẻ này danh cũng có mà lợi cũng có trăm việc điều cát lợi, đều thành tựu.\nKhi được sung sướng thiết tưởng cũng nên nhìn lên mà đáp đền công ơn của hóa công.\nLời thơ của quẻ tả thời vận của bạn hiện nay. Như cảnh thái bình thạnh thế, dân được an cư lạc nghiệp và\ndo đó mộng lớn phải dựa vào dịp này, ắt sẽ được ngộ phùng thánh chúa, để nhận giàu lấy sang.\nVậy, thời vận của bạn đã hanh thông. Sở cầu mưu dễ xuôi gió thuận buồm, thông đạt ý nguyện đấy.\nQuẻ dạy: Gặp thời bình, gặp chúa ắt nên danh và sang cả. Là lúc đạt được mộng lớn, làm tròn chí trai. Cầu\ndanh lợi đều đạt. Đánh số rất hạp.", "g": "Người được quẻ nầy, cho biết đây là người có đầu óc, sắp xếp thuộc hạ ai có bổn phận nấy, bộ\nphận nào cũng liêm khiết công chính.", "s": "10, 11, 3, 13, 33."}, "104": {"c": "THƯỢNG THƯỢNG", "hexagram": "Hỏa Lôi Phệ Hạp", "line_label": "Động Hào Nhị", "p": "An như Thái Sơn,\nỒn như bàn thạch.\nPhóng đởm tiền hành,\nTrung thông ngoại trực.\nYên như hòn núi Thái Sơn,\nOn như bàn thạch, đỉnh đơn vững vàng.\nCứ yên chí, có gan lắm,\nTứ thông bát đạt tiếu đàm ý vui.", "b": "Quẻ này cho biết mọi hành động đều được như ý mưu sự đều được vừa lòng.\nNgười ăn ở hiền lành thì được trời giúp, phúc lộc dồi dào, bền vững lâu dài.\nDo đó cho nên mới lấy hai câu đầu làm tỷ dụ, còn hai câu chót đệ nhất rồi.\nĐây là nột quẻ tốt.\nTheo ý quẻ cho biết, những việc cầu xin của bạn, ắt được hanh thông và ý thành nguyện toại mà không có\ngì trắc trở phiền lo, như hai câu trước đã nói yên như núi Thái Sơn, vững mạnh như bàn thạch.\nNhưng người phải can đảm tiến tới, chớ quá dè dặt thì hỏng việc, vì hai câu sau có câu nhắc ta: Cứ yên chí\nmà đi đều thông suốt mọi nẻo đường và sẽ được vui tươi ý tình vậy.\nQuẻ dạy: Thành đạt đó, nhưng phải có gan làm. Công việc tiến hành tốt đẹp, vững chải và chắc chắn có\nkết quả tốt. Cần can đảm là sự việc xong. Cầu danh đắc danh, cầu lợi đắc lợi. Đánh số hạp, tốt.", "g": "đại cát đại lợi.", "s": "1,\n10, 11, 14, 44."}, "105": {"c": "HẠ TRUNG", "hexagram": "Hỏa Lôi Phệ Hạp", "line_label": "Động Hào Tam", "p": "Nguyệt trung hữu dân quê,\nNhân trung phần bạc trước.\nVân thê túc hạ sinh,\nThử tề hảo lạc phước.\nTrong trăng có một cây đa,\nNgười sao leo nổi thật là khó thay.\nNay chân bỗng mọc thang mây,\nNương theo dựa đó, nhờ đây vận trình.", "b": "Quẻ này chi ngồi thấp mà nghĩ cao, cho nên cảm thấy khó như lên trời.\nNhưng bỗng may được người giúp, khiến công việc hóa nên dễ dàng.\nNgười xin được quẻ này có cái tượng nhờ được người mà công việc mìng thành.\nTuy vậy nhưng thiết tưởng cũng nên đem hết tâm lực của mình để chu toàn mọi việc, chứ chớ nên ỷ lại hết\nvào người khiến có thể hỏng việc.\nÝ quẻ nói rằng: Những việc cầu xin của bạn như là cây đa ở trong cung trăng, muốn leo lên đến đó thật là\nkhó nhưng may thay hiện nay dưới chân lại mọc lên một cầu thang mây. Nên dựa vào đó bước lên mới có\nthể tới được, nghĩa là sự cầu xin khó thành đạt lắm nhưng biết nắm lấy thời cơ và khai thác hoàn cảnh, thì\ncông việc sở cầu cũng chưa đến nỗi tuyệt vọng.\nVậy những việc cầu mưu của bạn phải biết hoàn cảnh, khai thác hoàn cảnh. Khi gặp một cơ hội nào hãy\nnắm lấy ngay thì mới ích lợi cho công việc, ngược lại sẽ thành hư không.\nQuẻ dạy: Cần chộp thời cơ và cần có quý nhân giúp, đồng thời phải nương thế, tạo thế. Tốt đẹp. Chỉ cần\nphương tiện và có nơi dựa là nên. Cầu tài, cầu lợi đều đạt. Đánh số tốt.", "g": "Những mục tiêu lớn và xa, không phải dẽ thực hiện, cần có người hỗ trợ hoặc nâng đỡ thì mới\nbảo đảm việc thành công.", "s": "1, 10, 11, 55, 15."}, "106": {"c": "HẠ HẠ", "hexagram": "Hỏa Lôi Phệ Hạp", "line_label": "Động Hào Tứ", "p": "Thiên giang nhất cô nhạn,\nLiêu lệ thán ly quan.\nThí vân tri quân giả,\nNhi kim hữu kỷ nhan.\nTrên trời một nhạn tiếng sầu ai,\nThan thở đàn thương tủi phận hoài.\nThử hỏi biết mình nay có mấy,\nNgó nhìn chẳng có bạn chân tay.", "b": "Quẻ này ý nói khúc thì cao mà họa thì không người, thực là rời rạc khó lên.\nNgười thì tài nhưng không có chỗ dùng, thà thành thử luân lạc nơi bốc bể biển trời, lòng tràn ngập những\nnổi buồn đáng phàn nàn, khó có thể có ngày mở mày mở mặt.\nNgười xin được quẻ này tưởng cần phải cẩn thận, chớ nên bặt thiệp làm chi chỉ tổ vất vả cuộc đời.\nCô nhạn ly quần tiếng thét thanh thao ai sầu, đó là tả cảnh cô đơn sức yếu hành sự khó khăn và khó thành\nđạt nguyện cầu, nên hai câu sau trong thơ lại tiếp rằng kẻ biết mình còn có ai đâu! Càng nói rõ sự cô đơn\ncảnh tình của người.\nDo đó, ý quẻ muốn nói, những việc cầu xin của người. Khó mà thành công toại nguyện. Vì thời vận của\nngười chưa được hanh thông, sức lực cô đơn và chưa được quý nhân phù hợp.\nQuẻ dạy: Cần có bạn bè, tay chân, để nhờ cậy. Đơn côi một mình như 1 cô nhạn mà thôi. Cầu tài cầu danh\nchẳng lợi. Đánh số bất thông. Biểu tượng: chim nhạn.", "g": "Người được quẻ nầy, cảm thấy lẻ loi cô độc, không chịu nổi, cần phải sửa đổi cách sống trở lại\nmới hòa nhập tốt cộng đồng.", "s": "6, 10, 11, 66, 16."}, "107": {"c": "HẠ HẠ", "hexagram": "Hỏa Lôi Phệ Hạp", "line_label": "Động Hào Ngũ", "p": "Hồng diệp vô nhan sắc,\nĐiêu linh nhất dạ phong.\nLân kê tỉnh ngộ mộng,\nTâm sự tổng thành công.\nLá đỏ sắc màu nay đã phai,\nTiêu tàn tại gió thổi đêm hoài.\nGà làng làm thức giấc trưa mộng,\nTất cả thành không biết hỏi ai.", "b": "Quẻ này cho ta thấy Lượng thì ít mà phúc thì bạc, khiến phí không biết bao nhiêu tâm cơ, rốt cuộc chỉ một\ngiấc mộng hoàn lương.\nNếu như biết giác ngộ, an phận thủ kỷ, được sao hay vậy, như thế lại còn hữu ích cho thâm tâm mình hơn.\nNgười xin được quẻ này nên giữ lòng trung hậu, may ra phúc lộc được dồi dào.\nTheo ý quẻ cho biết rằng: tất cả sự cầu mưu của bạn đều sẽ hóa thành hư không và khó thành đạt, như bốn\ncâu thơ trên nói Lá đỏ phai màu\", gió đêm làm cho lá rụng tiêu tàn, và cái mộng đẹp trong giấc trưa lại bị\nđứt nơi nửa chừng, nên tất cả đều thành không, như vậy sự cầu mưu còn gì hy vọng đâu!\nQuẻ dạy: Chớ tính công việc làm chi cho mệt. Thất bại, đổ vỡ, ẩn nhẫn, chờ thời tốt hơn hết, tính vô công\nmà thôi. Cầu tài, cầu danh bất thành. Đánh số dở, thua là khác. Biểu tượng: con gà.", "g": "vận tốt nhanh qua tiếc chẳng xong, bao nhiêu lí tưởng bổng hoài công, làm sao xoay xở cho thành\ntựu, chẳng lẽ khoanh tay ngồi ngó mông?", "s": "7, 17, 10, 77,\n11."}, "108": {"c": "HẠ HẠ", "hexagram": "Hỏa Lôi Phệ Hạp", "line_label": "Động Hào Lục", "p": "Sự như ma,\nLý đa thác.\nNhật yểm vân trung,\nKhông thành đam các.\nLàm sai hoài việc lôi thôi,\nBao nhiêu sự việc\nchẳng rồi chẳng xong,\nMặt trời nay ẩn vân trung.", "b": "Người xin được quẻ này trong lòng mê muội, không có một chủ trương gì cả, mọi việc lại không được\nsáng suốt, nhiệm ý hành động cũng sai lầm.\nBởi thế cho nên nơi nào cũng bị thất bạichuân chuyên, chông gai, lận đận, tring trường hợp này ắt phải hết\nsức cẩn thận, nhận xét mọi việc tinh vi để hành động may ra mới có cơ thành công được.\nQuẻ thơ tả cảnh tình hiện nay, thời vận chưa được hanh thông, còn nhiều trắc trở gian nan, như lời thơ nói\ntrên. Sự việc còn lôi thôi và cách làm chưa đúng mà sai lạc, như mặt trời ẩn nơi trong mây không sáng\nsủa.\nNhư vậy, những điều mưu tính của bạn đành hóa thành hư không cả, chẳng có một hy vọng nào được\nthành đạt. Nên chờ thời đã là tốt hơn.\nQuẻ dạy: Tính vô ích mà thôi, chờ thời, mặt trời ẩn trong mây, thì làm gì? Công việc dở dang và lôi thôi.\nMưu tính khó thành, cầu tài cầu danh, chẳng đến đâu, đánh số cũng dở.", "g": "Việc muốn hỏi đang lâm vào cảnh hỗn loạn, thời vận không tốt, công tác không tiến bộ, rất khó\nhy vọng hoàn thành.", "s": "88, 8, 11, 10, 18."}, "109": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Địa Tấn", "line_label": "Động Hào Nhất", "p": "Vật tuần cựu triệt,\nCam giá tân xa.\nĐông Tây Nam Bắc,\nỒn bộ khang cù.\nĐừng lái chiếc xe đã cũ xưa,\nThà mua xe mới đi là vừa.\nĐông Nam Tây Bắc chạy thong thả,\nChẳng sợ tai ương nạn đến đưa.", "b": "Quẻ này có cái tượng cách cố đỉnh tân, ngày mai không còn là ngày nay nữa.\nTrở về trước là cả một con đường ghồ ghề đầy chông gai trở ngại, nhưng từ nay đường bằng phẳng thênh\nthang, ta không thể thênh thênh cử bộ, không còn lo ngại điều gì.\nNgười xin được quẻ này quyết rằng khổ tận cam lai, ta bước vào giai cảnh, nơi nào cũng đẹp, ngõ nào\ncũng là rộng rãi cả.\nQuẻ khuyên rằng: Đừng đi xe cũ mà thà đi xe mới, nên mới đắt giá cũng cam nghĩa là xe cũ rẻ tiền mà dễ\như, xe mới tuy mắc tiền nhưng mà máy tốt dễ đi.\nĐó tức là nói: Phàm cầu mưu một sự việc nào, muốn thành đạt theo ý định, thì phải mà cố công chịu đựng\nnhững điều gian khổ mới nên và nếu làm được như thế, sự cầu xin bất cứ cũng đều thông đất, chẳng sợ\nvấp phải điều không hay.\nQuẻ dạy: Cần thay cũ đổi mới mới hay, cầu tài, cầu lợi còn hơi chậm, ẩn nhẫn. Đánh số hạp một phần. Số\nhên: 9, 10, 19, 11, 99.", "g": "Vết xe cũ, chớ nên theo—Đổi thay phương pháp , hiểm nghèo mới qua.", "s": ""}, "110": {"c": "HẠ TRUNG", "hexagram": "Hỏa Địa Tấn", "line_label": "Động Hào Nhị", "p": "Dạ mộng bị thử kinh,\nTỉnh lai bất kiên nhân.\nChung tiêu xưởng tâm,\nTrực đáo thiên minh.\nĐêm khuya giấc mộng giựt mình,\nHết hồn tỉnh dậy chẳng nhìn thấy ai.\nTừ khi đó mắt thức hoài,\nMãi ngay trời sáng chưa phai buồn tình.", "b": "Quẻ này chủ lo lắng triền miên nào là chuyện miệng tiếng gây ra liên tiếp, nào là chuyện quan nha không\nđược thẳng thắn, nào là chuyện người đi không giữ chữ tín, nào là chuyện giao dịch thất bại, nào là điều\nLục giáp bất an tất cả chỉ gây cho mình những điều lo lắng kinh hoàng, khiến đêm nằm thấy ác mộng.\nNgười xin được quẻ này phải hết sức đề phòng mới có thể mong đở lo lắng trong muôn một.\nTheo ý quẻ cho biết: Công việc cầu mưu của bạn, sẽ bị dở dang như lời thơ nói đêm khuya giấc mộng giựt\nmình không hưởng được giấc mộng lành trong đêm nay, nên đành phải thức đến trời sáng mà ý tình buồn\nrầu vẫn chưa thôi, đó là nói rằng: công việc nửa chừng thì bị hư hỏng và rồi cũng sẽ mất luôn dịp may.\nVậy thì những việc mưu cầu cần phải cẩn thận, vững vàng ý định, mà đừng nghe lời người ta nói dại ắt sẽ\nhỏng đó.\nQuẻ dạy: Việc dở dang, nhẫn nại, buồn hơn vui. Hay hơn hết, là nên chờ đợi dịp khác. Vì thời vận chưa\nđến, cầu tài, cầu mưu còn chậm. Đánh số hạp chút ít.", "g": "", "s": "1, 11, 10.\n*Giải thiêm ：Đây là điềm bất tường, gần đây có việc sợ hãi, cần đề phòng.Chú ý cẩn thận vào năm tháng\nngày giờ “Tí” hoặc người tuổi “Tí”."}, "111": {"c": "HẠ HẠ", "hexagram": "Hỏa Địa Tấn", "line_label": "Động Hào Tam", "p": "Thu sương tức hạ nhật viêm,\nTân khoa tiên liểu cựu hoa yên.\nThế tình khan lãnh noãn,\nPhùng giả bất tu ngôn.\nMùa hè nóng hổi thu sương hàn,\nBông mới nở rộ bông cũ tàn.\nSự thế nhân tình nay ấm lạnh,\nGặp nhau im lặng chớ nên bàn.", "b": "Chuyện đời thật không sao nói hết được, chẳng qua cũng chỉ như nước chảy dưới cây, mây trắng hóa cho\nxanh mà thôi. Phải là người đạt đạo mới thấu hiểu được thế thái nhân tình đen bạc ấm lạnh. Người xin\nđược quẻ này nên có ý nghĩ khoáng đạt hơn, khỏi cần mưu tính kế gì thêm mệt.\nTheo ý quẻ nói rằng: Hiện cảnh tình của bạn đang ở trong hoàn cảnh của một thế thái nhân tình ấm lạnh,\nnhư khi trời nóng lạnh bất thường nghĩa là thời vận của bạn hiện nay tắt nẻo không thông, nên quẻ khuyên\nngười chớ nên lắm lời với người ta mà vô ích.\nVật ý quẻ dạy rằng: Thời vận chưa đến, ta hãy chờ đợi và những việc cầu xin của người, không nên vội vã\nvà làm càng rồi sẽ hỏng mất việc.\nQuẻ dạy: Mình hãy tự lo cho mình, chớ trông cậy ai làm gì. Vì nhân tình nào ấm lạnh có ra chi! Mình tự\ntránh mình là hơn, ẩn nhẫn chờ đợi qua thời. Chưa cầu danh, cầu lợi được, đánh số bất thông.", "g": "Muôn việc tùy theo sức của mình mà làm, bắt chước đòi theo kịp người là hành động không sáng\nsuốt.", "s": "1,\n11, 10."}, "112": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Địa Tấn", "line_label": "Động Hào Tứ", "p": "Vị triển anh hùng chí,\nTrì khu bất đạn lao.\nCản tương hưu cửu bộc,\nTây bắc đoạt tiền tiều.\nChí khí anh hùng chưa đạt thông,\nGian lao chẳng sợ quyết cho cùng.\nTiền đồ dám hỏi tốt hay xấu,\nTây bắc hướng đi ắt đạt công.", "b": "Tấn trùng nhỉ khôi phục đất nước, Tiểu bạch chủ việc kết minh. Có lao khổ mới có công cao, lúc đó trời\nmới giao cho trọng nhiệm. Hãy đi về phương Bắc đi, đó chính là nơi phát tích, thâu được công đầu đấy.\nKhi thành công mặc áo gấm về làng, quay lại nhìn mới cảm thấy sung sướng vui mừng, và biết được bản\nsắc của kẻ anh hùng. Người xin được quẻ này nên bắt chước theo sẽ thấy kết quả như nguyên.\nQuẻ dạy rằng: Chí anh hùng chưa toại hãy nên quyết lòng làm tốt và không sợ gian lao, nhắm theo hướng\ntây bắc mà cầu, thì ắt sẽ thành đạt đó, nghĩa là hiện nay thời vận của bạn chưa đạt hanh thông lắm và vẫn\nvấp phải trở ngại.\nNhưng nếu bạn không sợ gian nan, quyết làm cho được thì nhắm hướng tây bắc mà cầu mưu, thì ắt thành\ncông toại nguyện.\nQuẻ dạy: Vận thời chưa thông càng cố gắng hơn và phải cầu hướng tây bắc thì đại công ắt thành. Cầu\ndanh, cầu lợi sắp đạt. Đánh số hạp chút ích.", "g": "Muốn không uổng phí công lao, Phải toan lo liệu cách nào mới hay.", "s": "1, 12, 11, 10, 20, 2."}, "113": {"c": "HẠ TRUNG", "hexagram": "Hỏa Địa Tấn", "line_label": "Động Hào Ngũ", "p": "Kha nhiêm trầm trầm,\nChung nhật hôn hôn.\nLôi môn nhất chấn,\nThế kiện thân khinh.\nBệnh tình đau nặng trầm trầm,\nCả ngày rên rỉ mất thần khổ đau.\nChờ khi sấm sét khơi màu,\nRồi khi mới khỏi mới mau phục lành.", "b": "Quẻ này chỉ rõ hoàn cảnh của kẻ lâu ngày bị khốn quẩn ở cấp dưới. Lòng lúc nào cũng buồn bã âu sầu\nchẳng khác chi kẻ trầm kha túy sinh mộng tử. Bỗng giai tín vụt truyền tới tức thì hoạt động ráo riết ngay,\nchẳng khác chi gió thuận thuyền xuôi, buồm lái trẩy mau. Người xin được quẻ này trước thì lo nhưng sau\nmừng.\nTheo quẻ cho biết hiện nay thời vận của bạn như người đau ốm trầm trọng, rên rỉ mê man cả ngày, mất\nthần khổ đau.\nNên việc cầu mưu chưa có một lối thoát khả dĩ thành đạt, mà phải chờ đợi một thời gian nữa mới được\nnhư lời thơ dạy Chờ khi sấm sét khơi màu, rồi mới mau lành.\nQuẻ dạy: Đang gặp thời vận bất ổn. Cần chờ đợi, cho mưa tạnh gió tan ắt sẽ gặp may. Cầu danh, cầu tài\nchưa đến đâu cả. Đánh số không hạp.", "g": "Như hỏi về tật bệnh thì hiện giờ chưa thể thuyên giảm , phải chờ đến ngày giờ thích hợp mới tìm\nđược danh y. (ở hướng Đông)", "s": "1, 10, 33, 13, 3."}, "114": {"c": "HẠ TRUNG", "hexagram": "Hỏa Địa Tấn", "line_label": "Động Hào Lục", "p": "Dị phi dị,\nNan phi nan.\nHốt địa khởi ba lan,\nKhốn tiếu lưỡng tam phiên.\nCông việc dễ mà chẳng dễ đâu,\nKhó mà chẳng khó đến lo sầu.\nNhưng này sóng gió bỗng nhiên nổi,\nHoan tiếu mấy phen mới hết âu.", "b": "Công việc tuy dễ mà thực chẳng dễ, do đó, chuyện cười khóc vô thường. Thế rồi đất bỗng nổi sóng,\nchuyện khó xảy ra, ngoài ý dự liệu, khiến điều vui trở lại thành buồn, điều sướng hóa ra khổ công việc\nthành rồi mà đâm ra phí cả tâm lực, chẳng lợi ích gì.\nNhững việc cầu xin của bạn, chiếu theo ý quẻ cho hay, dễ không dễ, mà khó chẳng khó, và thành đạt hay\nkhông, tất cả do người định lấy.\nTuy nhiên việc cầu lúc này, ắt khó tránh được những sự trắc trở hay gian nan. Nhưng nếu cứ cố gắng mà\nkhông sợ gian lao tiến tới, dốc lòng đến cùng, thì vẫn có hy vọng tùy ý toại nguyện.\nQuẻ dạy: Cố gắng và tự mình tính lấy mình, thành bại điều do ở ta và tài ba, cùng ý chí của ta, chứ chẳng\ndo ai cả. Cầu tài, cầu danh còn lận đận. Đánh số chưa hay.", "g": "Việc muốn hỏi, đang lâm vào tình trạng ngưng trệ phiền phức, phải chờ đến lúc tình thế biến\nchuyển, mới có hướng giải quyết cụ thể.", "s": "4, 10, 11, 44"}, "115": {"c": "HẠ TRUNG", "hexagram": "Hỏa Sơn Lữ", "line_label": "Động Hào Nhất", "p": "Lộ bất thông,\nMân bế tất.\nCẩn thận đề phòng,\nVân tàn nguyệt bắc.\nCửa nẻo đường đi đã bịt bùng,\nBốn phương bế tắc chẳng nào thông.\nNay trăng lại bị mây che phủ,\nMọi việc mưu cầu hãy cẩn phòng.", "b": "Quẻ này chỉ cái tượng tuyệt môn đại lộ, mọi việc điều bất lợi, đã thả mồi bắt bóng, lại còn có thể bị ám\ntoán hiểm nguy.\nNgười xin được quẻ này cần nên ẩn cư tuyệt tích, lo điều hội ngộ, mặt khác phải dốc chí làm nhiều điều\nthiện, có thể may ra tai họa mới có thể giải được.\nTheo ý quẻ cho biết, hiện nay thời vận của bạn chưa được hanh thông như cửa nẻo, đường đi đều bị bịt\nbùng, bốn phương đường xa bế tắc không thông thì còn làm sao? Vả lại còn cảnh trăng bị mây che phủ, thì\nthấy là u tối lắm rồi.\nVậy những việc cầu xin của bạn, khó mà thành đạt toại ý trong lúc này, phải đợi chờ một thời gian nữa,\nhơn nữa những việc làm hiện nay, cần cẩn thận đề phòng điều không đưa đến.\nQuẻ dạy: Xấu, đừng tính gì cả, cẩn trọng đề phòng, chỉ nên chờ đợi dịp khác là hơn. Cầu tài, cầu danh\nchẳng lợi, đánh số không hạp thua.", "g": "bất tường (chẳng lành)", "s": "5, 11, 10, 55, 50."}, "116": {"c": "TRUNG HẠ", "hexagram": "Hỏa Sơn Lữ", "line_label": "Động Hào Nhị", "p": "Oa giốc, răng đau lợi,\nNhị kim dĩ biến thông.\nThảo đầu nhân tiêu nhữ,\nNghi thủy bất nghi trung.\nMối lợi nhỏ nhoi nay đã thông,\nVận trình hứa hẹn sẽ kỳ phùng.\nNhưng mà cây cỏ cười răm rộ,\nCó thủy nào đâu thấy có chung.", "b": "Quẻ này cho biết lâm vào cảnh tàn khổ, cần nên dành dụm tằn tiện ngay cả những vặt vảnh nhỏ nhặt, tùy\nhoàn cảnh của mình mà ăn tiêu. Nếu ta tự do phóng túng, tiêu pha hoang phí thì một khi tiền của đã ra đi\nkhó có thể trở về. Chàng đau cỏ ( Thảo đâu nhân) dùng để chỉ chữ hoàng kim. Người xin được quẻ này rất\nnên tiết kiệm dè dặt, chớ nên phung phí quá trớn.\nNhững việc cầu mưu của bạn hiện nay tạm được, hanh thông phần nào và tương lai nhiều hứa hẹn trong\nviệc cầu xin. Nhưng đường đi nước bước phải lưu ý cẩn thận, nếu sơ ý sẽ vấp điều không hay và sự nên\ncông trong cũng bị tiêu tan mà trở thành hư không, như câu thơ chót của quẻ nói trên có thủy nào đâu có\nchung. Vậy người nên chú ý.\nQuẻ dạy: Làm việc phải có đầu, có đuôi, có thủy, có chung thì việc thành đạt vững chắc. Còn không, chỉ là\ngiai đoạn mà thôi, cầu danh lợi còn lâu. Đánh số hạp chút ít.", "g": "Đừng vì lợi nhỏ mà bỏ mất việc lớn, thấy sự việc gì mới xuất hiện cũng nên xét rõ cho kỹ lưỡng,\nkẻo hỏng việc, giữ theo lối cũ mà làm.", "s": "60, 6, 10, 11, 66."}, "117": {"c": "TRUNG THƯỢNG", "hexagram": "Hỏa Sơn Lữ", "line_label": "Động Hào Tam", "p": "Châu ngọc tẩu bàn trung,\nĐiền viện định phụ phong.\nHưu ngôn mưu vị thông,\nThử khứ tiện hạnh thông.\nGiờ đây châu ngọc mâm trong,\nNhứt định ruộng vườn sẽ phú phong.\nChớ nói mưu cầu chưa toại nguyện,\nNay đi vạn sự được hanh thông", "b": "Quẻ này chủ điều tốt lành, người ăn ở có nhân ắt giàu có. Từ nay, khỏi cần lo mưu sắp kế, lo lắng xoay\nxở, mà vành nhọc vẩn đầy rương, thóc lúa vẫn đầy kho, thực không có chỗ nào mà không phải giai cảnh.\nTuy được vậy thiết tưởng vẫn một lòng hòa mục hiếu nữa để vun trồng cội phúc.\nÝ quẻ cho biết: Vận trình của bạn đã đến lúc lên hương như châu ngọc đang sắp trong mâm, và như ruộng\nvườn được mùa. Nên quẻ thơ khuyên tiếp rằng, chớ nên than thở nữa, mà từ đây trở đi ắt được hanh thông\ntrong mọi việc cầu mưu đấy.\nVậy những việc mưu tính của bạn hãy mau tiến tới, đừng chần chờ than thở mà mất những giờ phút may\nmắn ấy.\nQuẻ dạy: Thời vận thái đến rồi. Đừng phân vân, than thở nữa, thành công vận đến cứ thế mà đi, cầu tài,\ncầu lợi đắc quả, đánh số hạp.", "g": "", "s": "7, 11, 10, 1, 77."}, "118": {"c": "THƯỢNG THƯỢNG", "hexagram": "Hỏa Sơn Lữ", "line_label": "Động Hào Tứ", "p": "Nguyệt dĩ minh,\nHoa tái phát.\nSự du du,\nVô bất hợp.\nTrời cao trăng sáng khắp nơi,\nBông hoa đua nở hồng tươi sắc màu.\nMọi điều công việc về sau,\nChẳng còn trắc trở, việc nào cũng xong.", "b": "Trăng sáng hoa tươi, đó là chỉ cái tượng vô cùng hưng thịnh. Do đó không có điều gì mưu cầu mà lại\nkhông được, không người nào gặp gỡ mà lại không phải đồng chí đồng tâm. Người xin được quẻ này khỏi\nphải lo lắng thắc mắc, cứ việc yên tâm tiền tiến.\nQuẻ nói: Trăng đã sáng và hoa đua nở, nghĩa là nói thời vận của bạn đã đến lúc hanh thông. Vận trình\nmuôn dặm, nhiều hứa hẹn tốt đẹp trong việc cầu mưu của người đang tính toán đúng như hai câu sau nói\ntiếp rất rõ, tất cả công việc về sau, chẳng còn trắc trở, việc nào cũng xong. Vậy bạn hãy nắm vững ý định,\nđể tìm lấy cái may mắn đang chờ đợi người đi.\nQuẻ dạy: Gặp thời cây sắt trổ bông. Giàu sang vinh hiển hơn đời, cầu tài, cầu mưu sẽ được đắt quả. Đánh\nsố trúng.", "g": "Người được quẻ nầy, việc muốn hỏi đang ở trạng thái tốt nhất,mọi điều xứng ý toại lòng.", "s": "8, 80, 1, 11, 10, 88."}, "119": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Sơn Lữ", "line_label": "Động Hào Ngũ", "p": "Mung lung thu nguyệt ánh chu môn,\nLâm ngoại ô thanh viển tự tâm.\nTự hữu quý nhân lai tiếp dẫn,\nHà tu xảo ngữ tự lưu canh.\nMờ ám trăng thu chiếu cửa nhà,\nTiếng chim rừng kêu dội truyền xa.\nQuý nhân tự đến và dìu dắt,\nLời ngọt làm chi như quỷ tà.", "b": "Quẻ này có cái triệu sắp sửa phi đằng hùng tiến, cho nên khỏi cần phải lời hay nói khéo, ráo riết tranh\ncạnh mà làm gì. Người xin được quẻ này chỉ cần biết đợi thời mà hành động, ắt có giai ngộ. Đây là một\nquẻ có cái tượng hạnh thông.\nTheo ý quẻ cho biết rằng: Những việc cầu xin của bạn không tốt mà chẳng xấu, chưa chắc thành công\ncũng không thấy hỏng như trăng thu tuy mờ ám mà vẫn còn ánh sáng chói rọi. Song quẻ lại nói tự có quý\nnhân đến dìu dắt, chẳng cần lời ngọt như tà ma.\nVậy những việc cầu xin của bạn hiện nay, tuy còn trong cảnh lừng chừng chưa được sáng tỏ lắm, nhưng\ncứ kiên nhẫn chờ đợi và tự nhiên đừng quá cưỡng cầu, thì việc cầu cũng sẽ được toại nguyện chẳng lo.\nQuẻ dạy: Sắp hanh thông thời vận đến nơi, hữu xạ tự nhiên hưởng, nên có tiếng đồn xa, làm quý nhân tìm\nđến giúp đỡ. Nhưng đừng nói nhiều, để tự họ giúp. Cầu tài, cầu lợi thông, Đánh số hạp.", "g": "Bổn mệnh có quí nhân giúp đỡ, cứ an tâm giữ phận mà hưởng phước.", "s": "9, 99, 11,\n10, 90."}, "120": {"c": "HẠ TRUNG", "hexagram": "Hỏa Sơn Lữ", "line_label": "Động Hào Lục", "p": "Sự vị khoan,\nTâm bất an.\nNghi lự cửu,\nThủy thái nhiền.\nViệc chưa xong, bụng chẳng yên,\nTinh thần căng thẳng lắm phiền mỏi thân.\nCàng suy nghĩ, lắm băn khoăn,\nRồi đâu vào đó, sẽ lần hết lo.", "b": "Quẻ này có cái tượng: phải mưu tính cẩn thận trước đã rồi sau mới hành động. Châu công xưa kia nằm suy\nnghĩ cho tới sáng đâu có phải vì hiếu danh, mà là suy tính cẩn thận để khi hành động không bị vấp đó thôi.\nNgười xin được quẻ này tất nhiên khi gặp việc cần phải suy nghĩ một phen cẩn thận trước đã để tránh khỏi\nthất bại tai hại.\nHiện nay thời vận của bạn chưa được toại ý. Vẫn còn bế tắc, còn phải chờ đợi một thời gian nữa, mới thấy\nsáng sủa. Vậy việc cầu xin của bạn, nên ráng chờ đã. Dù suy tính đến đâu cũng vậy thôi, nên nhớ câu thời\nđến mọi việc thông.\nQuẻ dạy: Bôn ba mấy, chẳng qua thời vận, chờ đợi rồi sau việc cũng sẽ đâu vào đấy. Chớ lo. Cầu tài, cầu\ndanh còn chậm. Đánh số hạp chút ít.", "g": "Việc muốn hỏi hiện giờ chưa thể giải quyết ngay được, phải chờ thời gian rồi mọi việc sẽ đâu vào\nđấy thôi.", "s": "1, 2, 20, 10, 22, 11."}, "121": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Trạch Khuê", "line_label": "Động Hào Nhất", "p": "Hư danh hư vị cửu tram tram,\nLộc mã đương cầu vị kiên chân.\nNhất phiên thái vân thu hậu chí,\nKhứ niên phong vật nhất thời tan.\nHư danh, hư vị lặng tiếng lâu,\nHiện chưa thấy rõ chức đang cầu.\nMây màu một đám sau thu đến,\nĐồi cách năm xa đuổi mọi sầu.", "b": "Quẻ này ý nói vận thời chưa tới, không thể cưỡng cầu. Song khi thời đã tới thì dù có không muốn cũng\nkhông thể chống lại. Sau mùa thu thì giai tín đưa về, đấy chính là nhất đương sinh (vào khoảng tháng\nmười). Và sau khi đã vào được giai cảnh, ta quay đầu nhìn lại ắt không khỏi cảm khái. Người xin được\nquẻ này thực có cái hy vọng thương đạt (tiến tới) vậy.\nTheo ý quẻ nói: Lâu nay thời vận của bạn có tiếng mà không có miếng, đều là hư không, và trên thực tế\nchẳng thỏa mãn theo ý muốn gì, mãi đến hiện nay cũng vậy, mà còn phải chờ đến sau mùa thu thì lúc đó\nmới thể thành đạt nguyện cầu. Vậy nên nhẫn nại chờ đợi một thời gian nữa. Công việc xin cầu mới có thể\nmạnh tiến và được tốt đẹp kết quả\nQuẻ dạy: Bất mãn, chờ đợi thu sang thì mới tốt. Chớ hấp tấp và nóng nảy, cuộc đời từ từ đi lên thì mới\nhay. Con người có lúc thái, lúc bỉ, hơi sức nào mà buồn. Cầu danh, cầu lợi còn chờ. Đánh số cố mới nên\ncông.", "g": "Suốt năm cứ loay hoay tính toán mà chỉ được những kết quả không có thực . Phải chờ đến sau\nmùa Thu (hoặc trung niên trở đi) thời vận mới thực sự tốt.", "s": "10, 11, 1, 2, 22, 12, 21, 20."}, "122": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Trạch Khuê", "line_label": "Động Hào Nhị", "p": "Chỉ! Chỉ! Chỉ!\nHữu chung hữu thủy.\nTự nguyệt như hoa,\nThủ thành nhi dĩ.\nThôi! Thôi! Thôi!\nĐã có thủy chung rồi.\nTrăng sáng hoa tươi nở,\nChỉ cần gìn giữ thôi.", "b": "Quẻ này khuyên ta nên biết tri túc nghĩa là biết đủ. Duy chỉ có tri túc mới có thể bảo vệ được thủy chung.\nVà cũng chỉ duy có tri túc mói có thể giữ được thành cục. Trăng có lúc khuyết lúc tròn. Hoa có lúc nở lúc\ntàn, đó là cái đạo tuần hoàn đi đi rồi lại lại. Người xin được quẻ này cũng y như vậy.\nÝ quẻ cho biết những việc cầu xin của bạn, mỗi người có một số phận riêng biệt khác nhau, nghĩa là số\nphận của mình trời đã định sẵn rồi. Chớ phải do người muốn hay không muốn, đó là thuộc phần mầu\nnhiệm huyền cơ, khó mà giải nghĩa bằng khoa học.\nNên quẻ khuyên rằng: Cảnh tình của bạn hiện nay đã đẹp như trăng như bông, chỉ cần giữ gìn.\nQuẻ dạy: Đừng tham vọng. Tùy sức tùy tài mà tính, thì hay hơn. Thời vận đến rồi đó, cứ tiến tới làm ăn, là\ntốt. Tham vọng quá thành thất vọng đó. Cầu tài, cầu danh được vừa phải. Đánh số hạp.", "g": "", "s": "2, 1, 12,\n21, 22, 11, 20, 10.\n*Giải thiêm ：việc thành bại được thua ở đời không sao ra ngoài lý nhân quả mà rán cầu thêm, hãy bằng\nlòng với cái mình đang có là tốt."}, "123": {"c": "THƯỢNG THƯỢNG", "hexagram": "Hỏa Trạch Khuê", "line_label": "Động Hào Tam", "p": "Minh nguyệt toàn viên,\nNhan sắc han nhiên.\nPhong vân tương tổng,\nHòa hợp vạn niên.\nTrời tịnh khí lành trăng sáng tròn,\nCảnh thanh tươi đẹp sắc như son.\nGió hoa mưa thuận theo như ý,\nMuôn hiệp thuở hòa hết mỏi mòn.", "b": "Quẻ trên đây chủ hòa hợp đoàn viên, không thực mà cũng không hư, phúc lộc dài lâu, vĩnh bảo vô cương.\nNgười xin được quẻ này chắc chắn an cư lạc nghiệp hưởng phúc suốt đời không hết.\nTheo ý quẻ cho biết, người cầu xin được quẻ số này, ắt gặp rất nhiều may mắn. Cầu tài có tiền, làm ăn\nphát đạt, cầu công danh sẽ được lên chức, thi đậu, mưu danh thuận lợi, nhất là cầu về tình duyên, ắt được\nvợ hiền, chồng sang, và vô cùng hạnh phúc. Tóm lại, quẻ ý cho rằng: Người cầu xin được quẻ này thì thời\nvận hanh thông, vạn sự như ý.\nQuẻ dạy: Tốt đẹp, sự sự như ý sở cầu thời, đến thì mọi việc đã thành. Trăng sáng tròn cảnh xinh tươi, đẹp\nđẽ quá rồi, lo gì nữa . Cầu tài, cầu danh đắc lợi. Đánh số hạp tốt.", "g": "Rất tốt. Việc muốn hỏi bạn đã đạt được trọn vẹn rồi, giờ chỉ tô điểm cho đẹp thêm mà thôi.", "s": "3, 2, 1, 10, 20, 30, 12, 13, 22, 33."}, "124": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Trạch Khuê", "line_label": "Động Hào Tứ", "p": "Nhân phi Khổng, Nhan, Thùy năng vô quá,\nQuá nhi hối cải, nhưng phục vô quá.\nHoa khai bất túc bằng,\nKết quả phương vi chuẩn,\nPhóng khai hoài bảo ý hân hân.\nAi như Khổng Lão mà không sai,\nSai biết sửa thì mới là tài.\nHoa mới nở đâu đáng vui sướng,\nChờ khi kết trái bông sẽ phai.", "b": "Quẻ này chỉ cái tượng: hồi tâm hướng thiện, thanh thản vô tư. Hoa nở đó là thủy, kết quả đó là chung. Lúc\nđầu thì chưa thiện, nhưng về sau lại thiện, bởi thế, không có gì đáng lo ngại. Người xin được quẻ này xin\nchớ lấy đó mà gọi là đủ.\nÝ quẻ nói, sự sống cuộc đời con người làm sao tránh được thất bại buồn đau cũng như ai mà không có sự\nsai lầm nhưng người ta biết sai mà sửa đổi thì vẫn được tốt lành. Tức là hảy rút kinh nghiệm thất bại rồi\ncải tiến thì sẽ trở nên thành công. Và hơn nửa quẻ khuyên rằng, đối với công việc sở cầu đừng lấy thành\nbại mà làm vui buồn, cứ cố tiến tới đến cùng, đến lúc đó mới biết rõ ràng tốt xấu và đó là kết quả chính\nxác vậy.\nSai biết sửa thì tốt. Đánh số hạp.", "g": "Người được quẻ nầy, hoặc sắp thành hôn, hoặc đã kết hôn, hai bên tâm đầu ý hợp, sinh hoạt đủ\nđầy. Như hỏi về việc hùn hạp, thì được tốt phát đạt to.", "s": "4, 8, 3, 48, 83, 38, 84, 43"}, "125": {"c": "HẠ HẠ", "hexagram": "Hỏa Trạch Khuê", "line_label": "Động Hào Ngũ", "p": "Cư hạ bất thân thượng,\nNhân tâm dĩ tán ly.\nSự cơ chung nhất thất,\nThiên bách tận thành khôi.\nỞ dưới khó mà thân với trên,\nLòng người biến đổi nào lâu bền.\nSự cơ, rút cuộc có điều mất,\nTrăm việc thành tro chẳng cái hên.", "b": "Cờ lầm một nước, toàn bàn đều hỏng. Người ta sống ở trên đời, việc trước hết là phải đắc nhân tâm. Đắc\nnhân tâm thì được nhiều người giúp, thất nhân tâm thì chẳng ai nhìn. Xử thế tiếp vật mà không biết điểm\nthen chốt đó thì hoàn công rồi cũng hỏng hết. Người xin được quẻ này thiết tưởng nên thận trọng, chớ nên\ncoi thường.\nTheo ý quẻ cho biết, việc cầu xin của bạn, khó đạt kết quả mỹ mãn, hãy nên ngừng lại, nếu có tiến hành đi\nnữa cũng chẳng đến đâu, nhứt là việc cầu tình duyên càng phải nên cẩn thận.\nQuẻ dạy: Xấu, làm ăn, giao du chớ vội cao. Đi tính chuyện vợ chồng không hợp. Nên ẩn nhẫn chờ thời là\nhơn. Mọi việc đều bế tắc chẳng ra gì cả. Cầu danh, cầu lợi thì còn xa xôi. Đánh số không mấy hạp.", "g": "Người trên thì có tánh cao ngạo, thiên lệch; kẻ dưới thì không tâm gắn bó, chắc chắn một ngày\nnào đó, chuốc lấy thất bại chẳng sai.", "s": "10, 20, 50, 11, 22, 55, 12, 25, 1, 2, 5."}, "126": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Trạch Khuê", "line_label": "Động Hào Lục", "p": "Ngột ngột trần ai cữu đãi thời,\nU song tịch tỉnh hữu thùy tri.\nNhược phùng thanh tữ nhân tương đấu,\nTài lợi công danh tự khả kỳ.\nBàn ghế bụi đầy dơ quá lâu,\nAi hay êm tịnh ta đang sầu.\nNếu khi may mắn quý nhân giúp,\nTài lợi công danh chẳng khó cầu.", "b": "Quẻ này chủ nữa đời lận đận gian lao, thiếu người giúp đở, khiến đến nơi ngồi bó gối nơi tham sơn cùng\ncốc, khó có thể thoát khỏi cảnh bùn lầy nước đọng. Trong trường hợp này, cần phải có một người có lực,\ncó đầy đủ phương tiện tiếp dần cho thì mới hy vọng có tương lai. Người xin được quẻ này nên thận trọng\nchớ có vội tiến, và cũng không nên buồn than làm gì. Hãy chịu khó đợi chờ một thời gian về sau cũng có\ntin mừng.\nQuẻ ý cho biết, hiện nay thời vận của người, tình cảnh đang như những bàn ghế dơ bụi, và êm tịnh đáng lo\nbuồn, nhưng đó chỉ là một thời gian ngắn phải chịu vậy thôi, chớ không thể bế tắc mãi, cũng như trên nói\nbàn ghế, người không dùng tới thì bụi bặm, khi người dùng đến ắt lau chùi sạch sẽ.\nVậy những cầu xin của bạn hãy chờ đợi, không nên vội cầu, như hai câu sau nói nếu khi may mắn quý\nnhân giúp. Tài lợi công danh chẳng khó cầu đâu.\nQuẻ dạy: Chờ đợi và cần có quý nhân giúp cho mới mong thành đạt. Ẫn nhẫn và cố gắng tìm bạn bè, hoặc\nngười trước giúp đỡ cho, mới mong làm nên. Cầu tài, cầu danh, cần có kẻ giúp. Đánh số chẳng mấy thông\nlắm.", "g": "Người được quẻ nầy,thời vận chưa thông thuận, có chí mà chưa đạt công danh, phải tìm cho\nđược người trên giúp, may ra mới thỏa mộng công hầu.", "s": "1, 2, 6, 10, 20, 60, 12, 26, 11, 22, 66."}, "127": {"c": "HẠ HẠ", "hexagram": "Hỏa Thiên Đại Hữu", "line_label": "Động Hào Nhất", "p": "Hổ phục tại lộ đo,\nHành nhân mạc loạn hồ.\nLộ bàng tu tử tế,\nTai họa tự nhiên vô.\nHổ phục ma giữa đường việc hải hồn,\nNgười im tiếng chớ lung tung.\nVà xe phải trái nên nhìn kỹ,\nVậy mới yên lành họa mới không.", "b": "Quẻ này khuyên ta nên hết sức cẩn thận trong mọi hành động, chứ không thể tụn tưởng vào vận số vào thế\nlực, địa vị để tự do hành động, không nên kiêng dè, người được quẻ này chớ lầm lẫn đó.\nNgoài ra còn phải hết sức cẩn thận, trong bất cứ mọi công việc, có thế thì bất luận niên tai nguyệt hối, cự\nhoạn kỳ tai, cũng đều không thể hại đến thân được.\nCọp đang nằm giữa đường tức là cản đường người đi, vậy đi làm sau được. Câu này đã thấy rõ ràng tất cả\nsự cầu mưu của bạn khó mà thành đạt.\nNgoài ra quẻ còn cân nhắc người, phàm việc mưu cầu phải im hơi lặng tiếng tức là giữ bí mật mà làm và\ntính toán cho kỹ, thì mới tránh được những điều không may có thể đưa đến cho bạn.\nQuẻ dạy: Bất thông, bất lợi. Mọi việc này đình đốn là hơn. Biểu tượng: cọp. Cầu tài, cầu danh còn xa.\nĐánh số dở.", "g": "Bình tỉnh suy nghĩ giải quyết công việc, chứ nếu quá lo lắng sợ hãi thì e kết quả không được như\ný.", "s": "1, 2, 7, 27, 12, 10, 20, 70, 11, 22."}, "128": {"c": "HẠ HẠ", "hexagram": "Hỏa Thiên Đại Hữu", "line_label": "Động Hào Nhị", "p": "Hòa bất hòa,\nĐồng bất đồng.\nPhiên vân phúc vũ kỷ thành không,\nTiến thoái tu phòng chung thiếu công.\nHòa đồng chẳng có hòa đồng,\nTrở mây làm gió hao công chẳng thành.\nDầu là hết sức khôn lanh,\nTiến lui cẩn thận mới lành được yên.", "b": "Quẻ này cho thấy đối với người quân tử, ta đã tuyệt, mà đối với kẻ tiểu nhân, ta cũng chẳng được họ mến\nyêu. Bởi thế cho nên trên đường đời lui tiến, lận đận mãi cũng chẳng nên công trạng gì, phải chăng đó là\nmột cái lỗi lớn của mình? Người xin quẻ này rất nên gấp rút sửa mình nếu có lỗi thì thật hết sức tích cực,\ntrái lại nếu không thì cũng nên suy gẫm để tiến bộ chứ chớ nên ngồi lỳ đó mà lãnh đủ tai họa.\nTheo ý quẻ cho biết như hòa mà chẳng đồng, nghĩa là nói công việc cầu mưu của bạn còn nhiều trắc trở và\nchưa được thuận lợi dầu là cố sức đến đâu cũng chỉ hao công mà thôi hơn nữa những việc cầu mưu phải\ncẩn thận nữa thì mới được yên lành.\nQuẻ dạy: Dừng lại, chớ tính, bất lợi, bị ngăn cản, trở ngại. Cần tùy thời, tùy thế và nhớ khôn lanh, may ra\nsau này mới hay mà thôi. Cầu tài, cầu danh chẳng lợi. Đánh số bị thua.", "g": "Không tốt. Nếu hỏi về sự nghiệp, phiền não không ngừng. Nếu hỏi về tình cảm hoặc hôn nhân thì\nchê tướng kỵ thần không hợp nhau, tới lui cẩn thận.", "s": "28, 12, 21, 82, 1, 2, 8, 11.\n20."}, "129": {"c": "TRUNG THƯỢNG", "hexagram": "Hỏa Thiên Đại Hữu", "line_label": "Động Hào Tam", "p": "Đông biên sự,\nTây biên thành.\nPhong vật nguyệt hoa minh,\nCao lâu lộng địch thanh.\nViệc này là của chuyện đông,\nBên tai hai đứa lại cùng đổi trao.\nChung vui hiệp sức lẫn nhau,\nMột mình tiến tới mộng bao ý tình.", "b": "Làm công việc ở bên Đông nhưng lại thành ở bên Tây, đó tức là cầu bỉ lại được bỉ. Hai câu thơ chót để chỉ\ncái cảnh của người ngồi cao trông xuống, tiêu dao tự tại. Người xin được quẻ này phải nên lạy tạ ông xanh\nđã cho mình nhiều phước đức, đổi thời cần phải làm nhiều điều thiện để tích nhiều âm chất, mong cuộc\nđời được hạnh phúc dài lâu.\nTheo ý quẻ thơ nói: Việc của bên đông mà bên tây có hai người cùng nhau, hiệp sức một lòng mưu cầu\nviệc gì đó, nghĩa là không liên can gì đến bạn mà bạn lại lưu tâm đến.\nTức là quẻ muốn nói rằng: Phú quí sanh tớ, ăn ở và vợ con đều do trời định, chớ phải người đời có thể\ncưỡng cầu mà được.\nVậy những điều cầu xin của bạn hãy nên lấy câu: Tận nhân lực tri thiên mạng để sống trong đường đời là\nhơn.\nQuẻ dạy: Tốt, có điều phải có tay giúp đỡ của bạn bè, mới mong thành tựu. Cầu tài, cầu danh được lợi.\nĐánh số được.", "g": "Được quẻ nầy, việc đang mưu tính gặp nhiều phân tán , về sau bất ngờ kết quả tốt lại đến.", "s": "1, 2, 9, 20, 12, 11, 99, 22."}, "130": {"c": "THƯỢNG THƯỢNG", "hexagram": "Hỏa Thiên Đại Hữu", "line_label": "Động Hào Tứ", "p": "Sự đoàn viên,\nVật chu toàn.\nNhất lai nhất vãng,\nBình độ thanh thiên.\nViệc này việc nọ đã xong,\nChâu toàn mọi vật, tấm lòng yên lành.\nTới lui đi lại dễ nhanh,\nThản nhiên thẳng tiến, công thành vinh quang.", "b": "Quẻ này chủ trương: tiếp thế xử vật phải hết sức chu đáo, tế nhị, nếu trong cuộc giao tế mà ta chu toàn\nđược, lại năng tới lui cùng người, thì người sẻ thân thiết ta, giúp đở ta, khiến ta có thể dễ dàng thẳng tiến\ntrên con đường sáng lạng của tương lai. Người xin được quẻ này, nếu có tính mưu đồ một việc gì thì nên\nlấy ý niệm viên dung làm trước.\nTheo ý quẻ cho hay rằng: Công việc đã xong sự việc cũng vẹn toàn, tới lui chẳng còn trễ nải, thản nhiên\nbước tiến trời xanh, đó là một quẻ rất may mắn vô cùng.\nVậy việc cầu xin của bạn, ắt thuận lợi thành công, chẳng chỉ Tiểu Đăng Khoa như ý sở cầu, dù là Đại\nĐăng Khoa cũng được trúng cử, nên danh bảng vàng.\nQuẻ dạy: Tốt đẹp, rực rỡ. Sự sự hanh thông, như ý nguyện cầu. Cầu tài, cầu danh đắc lợi. Đánh số tốt. Số\nhên: 13, 1, 3, 10, 30, 33, 11.", "g": "Quẻ nầy rất tốt, việc muốn hỏi được thuận lợi đầy đủ. Được quẻ nầy tài vận thông suốt, lợi lộc\ntăng tiến, tiền bạc dồi dào.", "s": ""}, "131": {"c": "HẠ HẠ", "hexagram": "Hỏa Thiên Đại Hữu", "line_label": "Động Hào Ngũ", "p": "Thiển thủy khởi phong ba,\nBình địa sinh kinh cực.\nNgôn ngữ lự sâm thương,\nDo khủng vô đoan ích.\nNước cạn mà nay sóng nổi cao,\nĐất bằng bỗng lại mọc gai cào.\nLời ăn tiếng nói nên suy nghĩ,\nCẩn thận đề phòng chuyện khổ đau.", "b": "Quẻ này chỉ gia đình bất hòa, thân hữu khinh thị, giao mà không có thiện giao, lúc đầu thì thắm nhưng sau\nthì nhạt, ai có ý nấy, câu chuyện lủng củng, không hợp, bẽ bàng. Ầy cũng vì vậy nên ngờ vực nhau là\nkhông được thực thà rồi đâm ra lo lắng nghi ngờ.\nNgười xin được quẻ này nên phải lo lắng đề phòng ngoài ra cũng rất cần phải tử tế với tất cả mọi người\ntrong khi chung sống với nhau trong xã hội. Nước đã cạn mà còn nổi phong ba, đường đi đất bằng mà mọc\nđầy chông gai, đó là mách cho ta hay rằng, hiện nay thời vận còn bế tắc, chưa thể mưu cầu sự nghiệp.\nVà hơn nữa còn phải dè dặt đến lời ăn tiếng nói, để tránh những điều không hay xảy ra mà phải mang tai\nhọa.\nĐề phòng mọi việc, cẩn tắc vô ưu. Xấu. Thủ phận hay hơn, phòng miệng tiếng, quang sự thị phi. Cầu danh\ncầu lợi còn lâu. Đánh số không hạp.", "g": "Vận suy đang đến, nên phải hết sức cẩn thận lời ăn tiếng nói mới tránh được thị phi. Ít nói hay tốt\nnhất là “Không nói”.", "s": "10, 30, 11, 33, 1, 3, 13, 31"}, "132": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Thiên Đại Hữu", "line_label": "Động Hào Lục", "p": "Thu nguyệt vân khai hậu,\nHuấn phong vũ quá thì.\nNhược phùng sở quốc cựu tri kỷ,\nĐẳng nhàn bất tiến bất tu nghì.\nĐến lúc mây tan trăng sáng rồi,\nCũng như mưa gió đã êm thôi.\nNếu may gặp lại người tri kỷ,\nNhàn tiếu chớ nghỉ việc mới trôi.", "b": "Quẻ này chủ đến lúc mùa thu và mùa hạ giao nhờ được thế lực của người bạn tri tâm tri giao tận tâm tiến\ncử nên chẳng chút phí công pho nào mà có chỗ sở cậy nên khỏi phải nghi ngại. Đây là một quẻ trung cát.\nÝ quẻ khuyên hãy nên chờ đợi chớ nóng nảy về công việc, ý nói đến lúc mây tan, trăng sáng, mưa gió êm\nhòa, thì công việc cầu mới nên.\nNhứt là công việc cầu mưu của bạn cần phải được sự giúp sức của người bạn thân và tin cậy vào người\nbạn thân đó, thì công việc đó mới thành đạt vậy.\nQuẻ dạy: Chờ đợi vần thái đến. Chớ cưỡng cầu, bất lợi. Cần có sự giúp đỡ và phải tin tưởng, mới mong\nthành sự. Mọi việc còn đang chờ. Đánh số hạp chút ít.", "g": "Ở nơi quê hương thì làm việc ổn định, nếu xa quê gặp được bạn thân ngày xưa giúp đỡ. Nhưng\nđừng yêu cầu quá khả năng của họ mà sanh ra không hay.", "s": "32, 13, 31, 23, 1, 3, 2, 33, 22."}, "133": {"c": "THƯỢNG THƯỢNG", "hexagram": "Hỏa Phong Đỉnh", "line_label": "Động Hào Nhất", "p": "Tâm dĩ định,\nSự hà ưu.\nKim lân dĩ thượng điếu,\nCông danh nhất võng thu.\nGiờ đây lòng đã bình yên,\nMọi điều công việc chẳng phiền chẳng âu.\nCá vàng nay đã dính câu,\nCông danh tài lợi lượm thâu một xuồng.", "b": "Quẻ này chủ hưởng ứng muốn xuất trần tiêu sái cửa son nhà trắng chắc đã vào đâu? Phú quý đến tay mà\ntại sao đến nổi lận đận chốn lâm truyền, không thể phát lộ được cái chí khí của mình? Người được quẻ này\nnên lấy đấy làm một viên thuốc định tâm đơn.\nNgười cầu xin quẻ này, thực là may mắn thay, tất cả về công ăn việc làm, cứ theo sự trù liệu tiến tới đi,\nchớ đừng lo ngại gì nữa.\nBởi như hiện nay thời vận của bạn đã lên hương rồi vận xấu đã qua, như bài thơ quẻ trên đây nói rõ. Vậy\nbạn hãy cố gắng và nắm lấy thời cơ, để thành đạt ý nguyện đấy.\nQuẻ dạy: Tốt đẹp, cầu được ước thấy, sự sự hanh thông chẳng còn lo âu gì nữa . Cầu tài, cầu danh hạnh\nđạt. Đánh số tốt đẹp.", "g": "tốt lành. Việc muốn hỏi, một khi lòng tính, chắc chắn được nên, công thành danh tựu vững bền.", "s": "30, 10, 33, 13, 1, 3, 31."}, "134": {"c": "HẠ HẠ", "hexagram": "Hỏa Phong Đỉnh", "line_label": "Động Hào Nhị", "p": "Ý mê kỷ bất mê,\nSự khoan tâm bất khoan.\nYếu tri đoan đích tích,\nDo cách lưỡng trùng san.\nÝ mờ nay đã hết mờ,\nViệc làm vạn khó lờ đờ chưa xong.\nCon đường thất bại, hay thành công,\nCòn xa cách biệt, hai trùng núi non.", "b": "Tuy rằng không có chỗ nào cho ta không hiểu rõ, nhưng sao khi lao mình vào công cuộc doanh nghiệp, ta\nmới thấy có những mối âu lo lớn lao đáng sợ. Nếu muốn ra sao ta chỉ còn cách chờ xem hạ hồi phân giải\nmà thôi. Trước mắt thì như vậy nhưng thực sự lại khác.\nNgười xin được quẻ này chỉ đành miễn cưỡng ức chế, đến lúc việc xảy ra mới có thể biết.\nTheo ý quẻ cho biết thì hiện nay tâm ý của người yên tịnh chớ không còn lờ đờ như trước nữa, lẽ ra những\nviệc mưu tính được sáng trí hơn nhưng khổ nỗi sự việc vẫn chưa thuận tiện, vì còn trở ngại. Tóm lại thời\nvận hiện tại của bạn xấu chưa được thông, tất cả việc cầu chưa thể toại lòng, mà phải chờ một thời gian\nnữa .\nQuẻ dạy: Xấu, bế tắc. Chờ đợi mới tốt. Cố cưỡng cầu, sẽ thất bại buồn phiền. Cầu tài, cầu danh, chẳng đến\nđâu cả. Đánh số, e bị thua.", "g": "- công việc chưa thể lạc quan được.", "s": "13, 34, 10. 30. 40. 43. 31. 11. 33, 44."}, "135": {"c": "HẠ TRUNG", "hexagram": "Hỏa Phong Đỉnh", "line_label": "Động Hào Tam", "p": "Tiếu trung sinh bất túc,\nNội ngoại kiến sấu khốc.\nVần tán nguyệt quang huy,\nChuyển họa dương thành phúc.\nTuy cười vẫn chưa đủ đầy,\nTrong ngoài sầu lệ khổ thay nổi mình.\nMây tan trăng lại sáng tinh,\nHọa đi phước đến, vận trình hanh thông.", "b": "Quẻ này chỉ cái tượng lúc khóc khi cười, trong lòng bất định. Tai họa xảy tới không ngờ, thử hỏi mấy ai\nkhông cảm thấy nguy?. Tuy nhiên công việc một sớm một chiều được phô bày rõ ràng thì gặp hung lại\nhóa cát. Phải chăng đó là nhờ sự phò trợ của các đấng thần linh?\nNgười xin được quẻ này nên suy xét tinh vi để hiểu biết rõ ràng mà giải quyết nghi vấn.\nVận thời của bạn sắp bước vào cảnh lành như mây sắp tan mà trăng sáng rực vậy. Nên việc cầu ấy số được\ntoại nguyện trong tương lai rất gần nhưng phải nhẫn nại chờ đợi lần lần sẽ gặp lương duyên đấy.\nTốt một nửa, cần nhẫn nại chờ đợi. Sắp đến cảnh sung túc vận thời may mắn đến, chớ lo. Sau cơn mưa\ntrời lại sáng. Cầu tài, cầu danh đắc quả, nhưng phải chờ. Đánh số có hạp chút ít.", "g": "Công việc gần đây xuất hiện một số trục trặc khó khăn, nhưng có thể khắc phục được, chuyển\nxấu thành tốt không hề gì.", "s": "53, 35, 31, 13, 1,\n3, 5, 55, 33, 31."}, "136": {"c": "TRUNG THƯỢNG", "hexagram": "Hỏa Phong Đỉnh", "line_label": "Động Hào Tứ", "p": "Song tiền thước táo chính phiên phiên,\nƯu lự toàn tiêu hỉ tự nhiên.\nNhất nhân tiêu liệu nhất nhân thoái,\nTiền đồ hoàn hữu hảo nhân duyên.\nChim kêu bay múa trước thềm nhà,\nVui vẻ tự nhiên sầu đã qua.\nTiến thối có người chung phụ giúp,\nSau cùng duyên nợ đẹp cùng ta.", "b": "Chim hót líu lo đó là để báo tin mừng. Tiền đồ tiến lui rõ ràng, tương lai cơ duyên thực không còn gì tốt\nđẹp hơn, thế thì vui sướng đó là chuyện tất nhiên. Đây là quẻ thượng cát.\nTheo bốn câu thơ nói trên, cảnh tình của bạn hiện nay đã là hanh thông, như chim đã bay múa và sau này\nvận trình sẽ hanh thông ngàn dặm. Những việc cầu xin của bạn ắt được thành đạt như ý muốn, nhứt là việc\ntình duyên, càng đắc tâm ứng thủ mỹ mãn lương duyên đấy.\nSắp đến lúc hanh thông. Mọi việc cầu xin đều xuôi chèo, mát mái. Được có kẻ giúp đỡ tận tình, lo gì\nchẳng thành. Cầu tài, cầu duyên đến đạt. Đánh số thông.", "g": "Mọi việc được an bài thỏa đáng, không có xung đột nữa. Nếu hỏi về nhân duyên, tức có thể kết\nhợp.", "s": "60, 30, 10, 63, 36, 13, 31, 6, 3, 2."}, "137": {"c": "HẠ HẠ", "hexagram": "Hỏa Phong Đỉnh", "line_label": "Động Hào Ngũ", "p": "Kinh cực sinh bình địa,\nPhong ba khởi tứ phương.\nỶ lan trù trướng vọng,\nVô ngữ đổi tà dương.\nĐất bằng nảy mọc chông gai,\nBốn phương sóng gió họa tai xóm làng.\nSầu ngơ ngẩn, dựa lan can,\nChẳng lời nhìn ngó, trời chiều tối tăm.", "b": "Quẻ này chủ sống trong cảnh âu lo, không làm ăn gì được, đầy lòng nghi ngại do dự, chỉ đành gửi gắm nỗi\nniềm cho gió thổi mây bay, phó mặc thân phận cho trời xanh lia định đoạt.\nNgười xin được quẻ này trăm việc không việc nào thành, tuy vậy, nhưng vẫn mong một biến cố ngoài dự\nliệu.\nÝ quẻ cho biết: Tình cảnh cũng như thời vận hiện nay của bạn, chưa được hanh thông mà còn bế tắc. Như\nthơ quẻ tả rằng Đất bằng mọc chông gai, sóng gió tràn ngập bốn phương.Và ngơ ngẩn dựa lan can xem\ntrời lặn về núi, tất cả tình cảnh đó đều là buồn thảm. Chẳng chút nào sanh khí.\nVậy những việc cầu xin của bạn, nên phải nhẫn nại chờ đợi một thời gian nữa là tốt hơn, vì đường đi còn\nchông gai quá. Nhưng chờ đợi đó không phải có ý bỏ hẳn, mà là sửa soạn chờ dịp tiến tới, để thành đạt ý\nnguyện đó.\nChỉ có cách ẩn nhẫn chờ thời và an phận thủ thường. Cầu gì thì cũng đều thất bại. Đánh số ắt thua.", "g": "Có việc phiền muộn xảy đến, trong lòng buồn bã không ai giải nổi.", "s": "73, 37, 13, 31, 7, 3, 1, 33, 77, 11."}, "138": {"c": "THƯỢNG THƯỢNG", "hexagram": "Hỏa Phong Đỉnh", "line_label": "Động Hào Lục", "p": "Mưu dĩ định,\nSự hà ưu.\nMinh nguyệt thượng trùng lâu,\nVân trung khách điểm đầu.\nKế hoạch mưu cầu đã định rồi,\nĐâu còn sự việc lo lôi thôi.\nSáng trăng soi bước lên lầu các,\nKhách ở trong mây cũng hở môi.", "b": "Quẻ ở trên chủ thanh vân đắc lộ, dĩ nhiên là hanh thông. Trăng lên lầu ý nói tiến lên được. Khách trong\nmây chỉ kẻ quý nhân. Sự nghiệp tăng tiến ngày một thêm xuân, đấy là tất cả mọi đều mong mỏi trong\nlòng, đây lại còn là một quẻ đại cát.\nNhững việc cầu mưu của bạn, nếu kế hoạch chu toàn thì chẳng có gì đáng lo nữa, mà chỉ nên có việc tiến\ntới, ắt sẽ thành công toại nguyện theo ý muốn, như quẻ thơ đã nói trong câu thứ 3 sáng trăng soi bước lên\ntrùng lầu, đó là mách cho bạn tỏ rằng, đây là may mắn lắm đấy.\nMay mắn, thời vận hanh thông, cứ tiến tới, bạn sắp được giàu sang, công danh đạt thành rồi. Đánh số rất\nhạp.", "g": "đại cục đã an bài , chẳng cần phải lo âu chi nữa.", "s": "38, 13, 31, 8, 3, 1, 30, 10, 80, 11, 33."}, "139": {"c": "TRUNG THƯỢNG", "hexagram": "Hỏa Thủy Vị Tế", "line_label": "Động Hào Nhất", "p": "Kỳ, kỳ, kỳ,\nĐịa lợi dữ thiện thì.\nĐăng hoa truyền tín hậu,\nĐộng tĩnh tống tương nghi.\nKỳ kỳ lạ lạ kỳ kỳ,\nThiên thời địa lợi chẳng gì khác nhau.\nKhi bông đèn báo tin sau,\nMọi điều mưu tính sắc màu hân nhiên.", "b": "Quẻ này chủ anh lợi xứng lòng, chẳng cầu mà vẫn được. Tuy rằng do địa lợi thiên thời mới được toại,\nnhưng cũng là nhờ nhân hòa mới thành công như vậy. Từ nay về sau, ta có thể thong dong thẳng bước lên\nđài vinh quang, ngất ngưởng trên gác tía lầu son không còn có gì đáng lo ngại nữa.\nNgười xin được quẻ này dù có không tự lấy làm mừng thì thiên hạ cũng vì mình mà mừng thay.\nXưa có câu Thiên địa hợp vạn vật hưng nghĩa là trời đất hòa hợp thì tất cả sinh vật ắt phồn thịnh. Nay quẻ\ncho hay thiên thời và địa lợi đều được hết cả tức là ý chí thời vận của người đã hanh thông rồi. Vậy những\ncông việc cầu xin còn gì ngần ngại mà chẳng thành công.", "g": "Việc muốn hỏi, thành bại là do thiên thời địa lợi.", "s": ""}, "140": {"c": "HẠ HẠ", "hexagram": "Hỏa Thủy Vị Tế", "line_label": "Động Hào Nhị", "p": "Ngộ bất ngộ,\nPhùng bất phùng.\nNguyệt trầm hải dê,\nNhân toại mộng trung.\nGặp không gặp, có điều chi,\nPhùng không phùng, thực quái kỳ lạ thay.\nTrời trăng đã lặn biển tây,\nCòn người nghê ngủ, thắm đầy mộng mơ.", "b": "Quẻ này chủ cái tượng: kẻ thất phu táng chí, người bạn nữ thương xuân. Hai câu thơ sau ngụ ý khuyên\nrăng rất sâu xa. Người xin được quẻ này thiết tưởng chớ lấy điều đặc thất mà ban lòng khiến lo rầu táng\nchí.\nChi bằng phó mặc tự nhiên hòng mong điều đạt quan trong cõi thế.\nTheo ý quẻ cho hay, việc cầu xin có thể hiệp, tính thời vận của người chiếm quẻ thì chưa gặp. Song việc\nđời do người ta tạo nên, đúng như có câu nói Sự bại lâu vì nên hãy cố gắng hăng hái cầu tiến, cũng có thể\nchiến thắng.", "g": "Việc muốn hỏi đang ở tình trạng quá xa vời mộng mị.", "s": ""}, "141": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Thủy Vị Tế", "line_label": "Động Hào Tam", "p": "Ấm trung phòng tịch lịch,\nThai nghi hôn vô thực.\nChuyển nhản hắc vân thu,\nSuy xuất phù tang nhặt.\nThình lình sét đánh dội vang,\nẤu lo hồi hộp chẳng màng đến ai.\nLát mây đen sẽ mắt phai,\nMặt trời chói sáng đất đai sắc màu.", "b": "Quẻ cho thấy: bọn tiểu nhân mưu hại. Tuy bị mưu hại nhưng tìm rõ được nguyên nhân khiến ta không có\ncách gì biện bác cho mình, hơn nữa cũng khó gột rửa được tiếng xấu. Được cái chỉ là bị vu oan nhất thời,\ncho nên vẫn thấy cái ngày sáng sủa buổi xưa. Trong trường hợp, thiết tưởng cũng không nên ôm giận kẻ\nkhác.\nNgười xin được quẻ này cần có cái độ lượng khoan hồng, chớ nên căng thẳng đối chọi với lũ tiểu nhân.\nÝ quẻ nói: Thình lình sét đánh vang dội, làm cho người phải hoảng hồn, thành ra phải lo âu, công việc sẽ\nbị hư hại, nhưng chẳng sao. Lát nữa mây đen sẽ tan mất mà mặt trời sẽ xuất hiện chói sáng khắp nơi.\nNghĩa là nói: Công việc cầu mưu của bạn bắt đầu tuy gặp khó khăn nan giải, nhưng người cứ bình chí, rút\ncuộc ắt được như chí vậy.", "g": "Việc đang lo rầu chỉ là bịa đặt vu cáo, rồi sẽ nhanh chóng sáng tỏ mà thôi.", "s": ""}, "142": {"c": "TRUNG TRUNG", "hexagram": "Hỏa Thủy Vị Tế", "line_label": "Động Hào Tứ", "p": "Lợi tại trung bang xuất chiến binh,\nKỹ phiên thanh nghị tại vương đình.\nPhượng hàm đan chiếu qui dương bạn,\nĐắc hưởng giai danh tứ hải vinh.\nLợi tại trung bang trận chiến binh,\nRửa tiêu cái nhục xưa trung đình.\nPhụng đưa vua lệnh báo quê thổ,\nLạc hưởng danh thơm bốn bề vinh.", "b": "Quẻ này chủ có công mà lại bị oán. Tuy vậy nhưng nhờ có lòng son ngay thẳng mà về sau sự thật được\nphơi bày khiến tiếng thơm trở lại với mình. Sở dĩ được thế cũng là nhờ ở những lời thanh nghị, chứ nếu\nkhông thì tâm thực chẳng bao giờ được yên.\nNgười xin được quẻ này chỉ cần luôn giữ vững lòng son của mình là đủ.\nQuẻ này là quẻ thất nhi phục đắc nghĩa là mất mà được lại. Nói một cách khác những việc mưu cầu ban\nđầu có lẻ sẽ bị thất bại trước rồi mới thành công sau.\nVậy những việc cầu xin của người, hãy kiên trì tiến tới mà đừng nên nản lòng mới nên công, như xưa có\ncâu Thế gian không có việc chi khó chỉ sợ lòng người không bền.", "g": "Người hiện nay bói được quẻ nầy, không dễ gì tìm ra giải pháp thỏa hiệp với đối phương. Phải\ntìm cách chuyển đổi sang đối tượng khác mới mong hy vọng thành công.", "s": ""}, "143": {"c": "HẠ HẠ", "hexagram": "Hỏa Thủy Vị Tế", "line_label": "Động Hào Ngũ", "p": "Kham thán nhoại biên ưu,\nLưu ly, ta mạc vận.\nÝ tự cánh khiên triền,\nTâm loạn, thần điên đảo.\nThan thở việc ngoài đã quá lâu,\nNay trong nhà lại chuyện thêm sầu.\nÝ tình chẳng được ngày yên dạ,\nĐiên đảo tinh thần biết tính đâu.", "b": "Quẻ này chủ táng loạn lưu ly nối gót mau tới trong thì lo, ngoài thì ngại, không thể nào đề phòng nổi. Đây\nlà quẻ có cái tượng: tiến thoái lưỡng nan, mình muốn khóc mà không khóc được. Người xin được quẻ này\nchỉ mong sao giữ mình là đã may mắn lắm.\nQuẻ thơ nói: Bạn hiện đang lo phiền nhiều việc, tinh thần điên đảo buồn khổ, không biết làm cách nào giải\nquyết những việc đang vấp phải.\nNói cách khác: Hiện nay thời vận của bạn chưa được hanh thông. Những việc cầu xin của bạn khó mà\nđược toại nguyện trong lúc này, phải trải qua một thời gian nữa , thì mới có thể mưu tính việc một cách\nthành công.\nQuẻ dạy: Xấu, bế tắc. Chớ cưỡng cầu tính e bất lợi. Ẫn nhẫn cho qua vận bỉ, thời xấu sau mới hay. Cầu\ndanh, cầu lợi đều bất thông. Đánh số dở.", "g": "Điềm chẳng lành, người được quẻ nầy đang phải lo âu việc công cũng như việc tư, nguy khốn vây\nquanh lớp lớp.", "s": "3, 4, 1, 43, 14, 34, 41, 11, 44, 33."}, "144": {"c": "TRUNG THƯỢNG", "hexagram": "Hỏa Thủy Vị Tế", "line_label": "Động Hào Lục", "p": "Nhất trùng thủy,\nNhất trùng sơn.\nPhong ba, đạt thản nhiên,\nHồ trung biệt hữu thiên.\nNước non, non nước tiếp liền,\nNgày nay sóng gió điềm nhiên an nhàn.\nĐường đi bằng phẳng khang trang,\nBầu kia trong đó, ẩn tàn trời riêng.", "b": "Quẻ này chủ trải khắp nơi gập ghềnh khó đi mới tới được chỗ bằng phẳng. Lao khổ thì có đấy nhưng quả\nthực nguy hiểm thì chưa có. Trong hồ nọ, tự có riêng một cảnh, lúc đó, mới tin rằng bặt thiệp giang hà\ncũng không phải là phí công vô ích, trái lại nhờ đó mới tới được nơi giai cảnh. Đây là quẻ thuộc loại trung\ncát.\nQuẻ cho biết non nước tiếp liền, một cảnh thanh bình, gió sóng êm lặng, đường lộ thẳng bằng, là chỉ cho\nbạn hay rằng, thời vận của bạn đẹp đẽ như thế, tức là đời của bạn lên hương đó.\nNhững việc mưu của bạn ắt gặp nhiều may mắn, và quý nhân đến giúp cho công việc thành đạt mỹ mãn,\ncứ nắm giữ ý định tiến hành đi, chớ lo có gì trở ngại nữa .\nThời vận hanh thông. Giàu sang danh lợi đến kỳ. Cầu tài cầu lợi rất mát mái, xuôi chèo. Đánh số càng\nhạp.", "g": "Nếu hỏi việc trong cơ quan , tuy hiện có sóng gió nhưng sau vẫn được yên. Nếu hỏi việc nhà thì\nnhờ phụ nữ giỏi sắp đặt, cũng được yên.", "s": "40, 41, 44, 14, 1, 4, 10, 11."}, "145": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Chấn", "line_label": "Động Hào Nhất", "p": "Ngộ hiểm bất tu ưu,\nPhong ba hà túc kỵ.\nNhược ngộ thảo đâu nhan,\nChỉ xích thanh vạn lộ.\nKhi gặp hiểm nghèo ta chẳng âu,\nCòn về sóng gió cũng không sầu.\nĐường đi nước bước công danh lộ,\nPhải ngộ những người sanh cỏ dầu.", "b": "Hai câu đầu nói: họa hoạn nhỏ nhặt, chẳng đáng lo sợ, chỉ nhờ ở mình chính trực vô tư mà thôi. Người đau\ncỏ tức là những người mà họ có chữ thảo đau, ví dụ như họ Hoàng, Tô, Cát� (thuộc bộ thảo là cỏ).\nGặp được những người họ này là những người có thế lực, mới mong được sự giúp đỡ tích cực. Đó phải\nchăng cũng còn là một cái duyên đã được định sẵn từ trước. Quẻ này là quẻ đại cát.\nCăn cứ ý quẻ, vận thời của bạn đã đến lúc hanh thông, chẳng còn có gì đáng lo âu nữa. Hơn nữa những\nviệc cầu mưu ắt được thành công, toại nguyện, và ngày thành công ấy chớ không còn bao xa nữa.\nVậy những việc mưu tính của bạn, hãy cấp tiến đi, sự vui mừng đang chờ bạn đấy. Tiến tới thì thành công.\nKhông có gì ngăn trở cả, công danh tài lợi dạ thành. Đánh số ắt trúng.", "g": "cát tường , chuyển xấu ra tốt. Nếu gặp quí nhân, thì sẽ nổi tiếng. (Quí nhân đây muốn nói đến\nngười mà tên có bộ “thảo đầu” .(艹—Ví dụ:- 葵 : quỳ)", "s": "41, 14, 45, 54, 5, 4, 1."}, "146": {"c": "TRUNG HẠ", "hexagram": "Bát Thuần Chấn", "line_label": "Động Hào Nhị", "p": "Thuyền trạo trung lưu cấp,\nHoa khai xuân hựu ly.\nSự ninh âm bất tĩnh,\nNhạ khởi hứa đa nghi.\nThuyền nan đang chạy giữa dòng sông,\nHoa nở phùng xuân đáng lẻ hồng.\nKhổ nổi việc yên tâm lại loạn,\nTự làm biết mấy chuyện hao công.", "b": "Quẻ này khuyên ta chớ nên vọng tưởng, trái lại chỉ nên giữ mình cẩn thận để tránh họa, làm điều thiện để\ntích phúc, phó mặc cho lòng trời. Ầy chính nhờ vậy mà chuyện thất ý lại hóa ra đắc ý, chuyện vô vọng lại\ntrở thành hữu vọng.\nNếu không theo thế, mà đâm ra nghi ngờ lo lắng thì chỉ tổ tâm làm cho tâm loạn mà thôi. Người xin được\nquẻ này nên cần chú ý.\nÝ thơ nói: Lẽ ra thời vận của bạn hiện nay, không phải xấu, mà là hanh thông đấy. Như hai câu thơ ở trên\nThuyền chạy, giữa dòng sông hoa nở phùng xuân . Vậy còn gì đáng chê. Nhưng khổ thay ý tâm của bạn\nkhông được yên tịnh, nên những băn khoăn đó, chỉ tại mình thôi.\nViệc cầu xin của bạn đều được thong dong đường đời, không gì gọi là may mắn lắm. Xưa có câu Tri túc\nthường túc bất tri túc thường âu. Hãy lấy đó ở đời thì sẽ vui vẻ luôn luôn.\nVận may quá rủi chỉ tại ta. Thua keo này gỡ keo khác, lo gì nhưng hiện tại vẫn đang xấu, chớ tính, chờ đời\nđã. Cầu tài danh đều dở. Đánh số chưa tốt.", "g": "tâm tình rối loạn, tính toán công việc đầy sự âu lo. Chời đến sang năm mới gặp vận may, đi ra\nngoài du lịch đề phòng bất trắc. Hôn nhân xuất hiện u ám buồn rầu.", "s": "41, 14, 64, 46, 6, 4, 1."}, "147": {"c": "THƯỢNG THƯỢNG", "hexagram": "Bát Thuần Chấn", "line_label": "Động Hào Tam", "p": "Khả súc khả sừ,\nPhiến ngọc thốn châu.\nĐình đình ổn ổn,\nTiền ngộ lương đồ.\nHãy nên chia dựng mến yêu,\nNhư dành châu ngọc ít nhiều cũng sang.\nĐường đi ổn định khang trang,\nTiền đồ ngàn dặm, vận đang sắc màu.", "b": "Quẻ này chủ tích đức lại tổ tông mà hưởng đức lại con cháu. Phiến ngọc tấc châu chỉ công đức. Còn câu\nsau nói mọi việc đều được thuận lợi toại nguyện có thể nắm chắc trong tay, chứ không còn nghi ngại điều\ngì nữa. Người xin quẻ này có thể tin tưởng rằng cứ cầu là ứng.\nÝ quẻ dạy rằng: Ở đời hãy hòa thuận được tức như giữ được nhiều châu ngọc vậy, ắt bước tiến trên đường\nđời của bạn chẳng những được thong dong bình an mà về tương lai còn sẽ được rạng rỡ nữa là khác. Vậy\nnhững việc cầu xin của bạn, nếu là mưu tính đúng đắn ắt thành đạt toại nguyện.\nĐến thời rồi, lo gì nữa. Chỉ cần tu nhân, tích đức cho nhiều., thì đường đời tương lai ắt sẽ rộng mở nhiều\nhơn hiện tại. Cầu tài cầu danh đắc quả. Đánh số ắt trúng.", "g": "Chẳng nên lãng phí thời gian, gặp vận tốt hãy bắt tay xây dựng tương lai tốt đẹp ngay đi.", "s": "4, 7, 1, 47, 14, 41, 74, 17."}, "148": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Chấn", "line_label": "Động Hào Tứ", "p": "Tiểu tử tảo xu đình,\nThanh vân cửu vấn trình.\nQuý nhân lại trợ lực,\nHoa tạ tử hoàn thành.\nĐứa này sớm đến triều đình,\nLâu nay hoài bảo tiên trình công danh.\nQuý nhân giúp tức việc thành,\nHoa tàn quả chín tốt lành hương thơm.", "b": "Quẻ này chủ hiếu tử được phúc, hãy ra khỏi nhà mà tính chuyện làm ăn, tự nhiên sẽ có người giúp đỡ. Hoa\nrụng thì quả kết, lúc đó, điều vui mừng sẽ đầy nhà. Người xin được quẻ này có cái mừng song thu danh\nlẫn lợi.\nÝ quẻ nói rằng: Những việc cầu xin của bạn đã nuôi mộng từ lâu như đứa trẻ mong đạt công danh và đã\nsớm vào triều đình hầu vua để được ban phong vậy.\nNhưng phải có quý nhân giúp đỡ, thì ý nguyện mới thành và công việc cầu rút cuộc cũng sẽ thành đạt chỉ\nchờ đợi thời gian nữa thôi. Bởi câu chót của quẻ thơ nói Hoa tuy tàn mà quả lại chín, tốt lành hương thơm.\nVận thái đến kỳ, chỉ cần thêm bàn tay quý nhân giúp là đại công ắt thành. Có thể được phong tặng chức\ndanh cao. Tốt đẹp cho mọi sự cầu. Đánh số tốt.", "g": "Hãy gấp giải thích dạy dỗ cho con cái biết lo tương lai sự nghiệp. Có thể gặp quí nhân nâng đỡ mà\nlàm nên danh phận.", "s": "8, 4, 1, 84, 48, 14, 41."}, "149": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Chấn", "line_label": "Động Hào Ngũ", "p": "Nhất tam lưỡng sự,\nNhất sự lưỡng tam.\nTân hoa khô thụ,\nTrực đãi giao xuân.\nMột lòng hai việc lắm suy tư,\nMột việc hai lòng lại bơ thờ.\nBông mới cây tàn đầu vĩnh cửu,\nHanh thông phải đợi một xuân sơ.", "b": "Quẻ này chủ thời cơ chưa tới, mưu vọng đều không thành bất tất phải phí tổn tâm sức. Mọi việc đều mơ\nhồ, ta quyệt phải đợi tới lúc vật đổi sao dời mới có thể thành tựu được. Người xin được quẻ này nên gác\nlại nổi niềm, vui với hoàn cảnh chớ có vội vã tiến gấp làm gì.\nÝ quẻ nói rằng: Vận thời của bạn hiện nay, như đang trong tình trạng nan phân. Chẳng biết làm sao, nên\nvận trình chưa được thông, dù có may mắn gì cũng như bông mới, cây khô chẳng được lâu bền. Cầu còn\nlận đận chưa thể Nhứt phàm phong thuận. Mà chỉ chờ đợi năm tới như câu thơ nói Hanh thông phải đợi\nxuân sơ.\nChưa thông, chờ đợi. Trong tình trạng nan phân, thì công việc làm sao mà chạy, mà thành. Ẫn nhẫn, chờ\nthời mới hay. Mọi sự cầu đều dở. Đánh số thua.", "g": "Người được quẻ nầy vì tâm ý không chuyên chú vào công việc, nên gặp một số khó khăn nho\nnhỏ thôi, phải hết sức tập trung vào việc làm mới mong tiến triển tốt.", "s": "9, 4, 1, 49, 14, 94, 41, 19."}, "150": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Chấn", "line_label": "Động Hào Lục", "p": "Đại sự khủng nan do,\nTàn hoa bất tái biến.\nViệc lớn lâu nay tính khó thành,\nTại vì vận xấu khắp chung quanh.\nHoa tàn cũng khó xanh tươi lại,\nTrời định cho rồi người phải đành.", "b": "Quẻ này chủ tình huống hết sức gieo neo, gia đình không được yên vui. Phàm việc không thể muốn theo ý\nmuốn được, duy chỉ có điều có tu tâm tu tỉnh cho tâm địa tốt lành, thì ách vận mới mong dời đi được.\nNgười xin được quẻ này nên lấy việc làm yếu vụ còn việc khác hãy gác đó.\nBài quẻ đã nói rất rõ: khuyên người nên an phận, chờ đợi thời vận là tốt hơn. Chớ nên ước những gì quá\ncao đẹp mà không hay, vì hiện nay tình cảnh cũng như số vận như quẻ xin được quá xấu vậy.\nQuá xấu, bế tắc. Nên ẩn nhẫn chờ cơn giận bỉ qua. Trời định sẵn số phận rồi, không thể cưỡng cầu mà\nđược. Mọi việc cầu đều xấu. Đánh số không tốt.", "g": "Thời cơ đã qua rồi—Ánh sáng sắp tắt thôi—Muốn mưu đồ việc lớn—Như bẻ nạng chống trời.", "s": "5, 1, 15, 51, 10, 50."}, "151": {"c": "HẠ HẠ", "hexagram": "Lôi Địa Dự", "line_label": "Động Hào Nhất", "p": "Mạc đạo sự vô ngoa,\nKỳ trung tiến thoái đa.\nQuế luân viên hựu khuyết,\nQuang thái cánh tha ma.\nỞ dưới khó mà thân với trên,\nLòng người biến đổi nào lâu bền.\nSự cơ rút cuộc có điều mất,\nTrăm việc thành tro chẳng cái nên.", "b": "Quẻ này chủ gièm người cao hơn mình khiến kẻ hiền sĩ mất tiếng tăm, thăng trầm vinh nhục, điên đảo vị\ntrí.\nChớ có nói thiên đạo bất công, mà phải nói việc người không nhất định, mặt trăng đã khuyết lại giảm cả\nánh sáng. Người xin quẻ này có thể lấy đó để biết được cái điều mình muốn biết.\nTheo ý quẻ cho biết, việc cầu xin của bạn khó mà thành công, nếu là công việc đã xong. Còn sở cầu này\nmới chỉ là ý định thì nên ngừng lại, nếu có tiến hành đi nữa cũng chẳng đến đâu.\nMọi sự tính toán nên đình đốn, thì tốt hơn hết. Tình thì thất bại, đau buồn chứ chẳng ích chi. Cầu xin mọi\nsự đều dở. Đánh số không mấy hạp.", "g": "Việc đang tốt bị đụng chạm nhiều thứ thành xấu.", "s": "1, 5, 51, 15, 50, 10."}, "152": {"c": "HẠ HẠ", "hexagram": "Lôi Địa Dự", "line_label": "Động Hào Nhị", "p": "Mạc thán sự trì lưu,\nHưu ngôn bất đáo đầu.\nTrường can chung nhạn thủ,\nNhất điêu thượng kim cầu.\nĐừng than công việc chậm lâu,\nVà cũng đừng nói có đầu không đuôi.\nCần câu khi nắm tay rồi,\nLo gì cá chạy ẩn vào hố sâu.", "b": "Quẻ này báo trước: việc có điều nguy hiểm, trước mặt xem ra vô cùng gian nan.\nSong lễ mừng được sóng qua gió lặng, rốt cuộc không còn chướng ngại.\nRồi một buổi đẹp trời, ta có chỗ tựa nương, sẽ có thể bắt được con cá vàng.\nĐây chỉ là cái tượng của trường hợp khai hoa thì sớm nhưng kết quả thì chậm đó thôi.\nNgười xin được quẻ này nên vững tâm chờ đợi.\nThan thở chẳng có lợi gì và không thể giải quyết được chi mà phải cố gắng cầu tiến như muốn bắt cá ở sâu\nvực thẳm, phải có cần câu, đó là ý quẻ mách cho bạn hay đấy.\nVậy muốn thành đạt những việc cầu xin, hãy cố gắng tạo nên một hoàn cảnh thuận tiện cho bước tiến dễ\ndàng, rồi ắt vạn sự như ý.\nMuốn thành công phải có phương tiện và người giúp. Cố gắng mới thành. Cầu mọi sự còn chậm. Ẫn nhẫn.\nĐánh số hạp chút ít.", "g": "Hãy nhẫn nại mà làm việc đi, sau cùng thì có kết quả tốt thôi !", "s": "52, 51, 45, 1, 5, 2, 25,"}, "153": {"c": "HẠ HẠ", "hexagram": "Lôi Địa Dự", "line_label": "Động Hào Tam", "p": "Sự tiền ưng hữu kỵ,\nVị động khủng tiến chí.\nDục vãng thả trì trì,\nHoàn tu tá thế lực.\nViệc nên tính trước khi làm,\nHãy phòng công việc ngổn ngang không xong.\nMuốn đi cũng phải thong dong,\nChung vai chung sức người đông mới thành.", "b": "Quẻ này chủ sự bạo hố bằng hà, chỉ có tốn chứ vô ích, bởi thế, ta nên cẩn thận trì trọng, lại phải làm sao\nđược cả thế lực giúp sức của kẻ khác thì công việc mới thật tận thiện tận mỹ.\nNgười xin được quẻ này may sao còn chưa có nhảy ra một cách lỗ mãng.\nTheo ý quẻ cho hay về những việc cầu xin của bạn nên cần có thời gian để tính toán, như câu thơ quẻ của\ncâu thứ ba nói: Muốn đi cũng phải thong dong và cũng phải nương dựa sức người để mà tiến đến mục\nđích của mình.\nThực vậy việc cầu xin của bạn là nguyện cầu khác thường. Vì vậy nên cần phải đòi hỏi thời gian nữa,\ncũng như sự giúp sức của người thì mới mau thành.\nTính toán chắc chắn. Cần có kẻ giúp sức, mới nương thế, mà tạo cho mình cái thế. Cầu danh cầu lợi cần\nkẻ giúp. Đánh số thông, tính kỹ.", "g": "Hà tất phải sốt ruột, rán tìm người giúp đỡ, công việc sẽ thành thôi.", "s": "3, 51, 15, 53, 13, 31."}, "154": {"c": "HẠ TRUNG", "hexagram": "Lôi Địa Dự", "line_label": "Động Hào Tứ", "p": "Túc bất an,\nDư bất an.\nLưỡng sự tương đắc,\nƯu lai khước hựu hoan.\nNgồi chẳng yên thì đi chẳng yên,\nLàm điều suy tính lắm sanh phiền.\nViệc nào cũng phải mà phân giải,\nBuồn bực làm chi vui lại liền.", "b": "Quẻ này chủ băn khoăn trước ngã ba đường, tiến thoái lưỡng nan.\nTrong trường hợp này, Người xin nên lượng sức mình đối với sự việc trước rồi hãy hành động, để có thể\ntránh được hậu hoạn về sau khiến phải hối hận.\nTheo ý quẻ cho hay thì hiện thời tình cảnh của bạn rất băn khoăn lo âu lắm điều suy nghĩ và không yên,\nnhưng bạn chớ quá buồn rầu làm chi. Tất cả mọi việc đều có thể giải quyết được, nghĩa là sức người thắng\ntrời vậy. Muốn thành đạt ý nguyện thì hãy cố gắng ắt thành công.\nXấu vừa, đang buồn lo. Tính toán nên suy nghĩ kỹ rồi hãy làm. Thời vận chưa thông. Chờ đợi thời gian\nnữa, mới mong. Cầu mưu, cầu lội còn chậm. Đánh số hạp chút ít.", "g": "Cũng giống như chuyện “Tái Ông mất ngựa” thôi. Vì mình kém phước nên có lúc phải chịu cảnh\nbất bình thường. Tuy hiện nay hoàn cảnh không hay lắm, nhưng nếu đồng tâm hiệp lực thì có kết quả tốt\nthôi.", "s": "4, 5, 1, 54, 45, 15, 51, 14."}, "155": {"c": "HẠ TRUNG", "hexagram": "Lôi Địa Dự", "line_label": "Động Hào Ngũ", "p": "Đỉnh chiết túc,\nXa thoát bức.\nHữu quý nhân,\nTrùng chỉnh tục.\nCái vạc ba chân nay đã gãy,\nBánh xe trục trặc lại mòn lần.\nRất may được gặp quý nhân giúp,\nSửa chữa phục hồi đều tốt lành.", "b": "Hai câu đầu có cái triệu phá hoại, cái tượng tan nát bỗng gặp được quý nhân có thế lực, chấn chỉnh lại cơ\nđồ, sửa chữa lại chiêng trống, tái tạo lại kiền khôn. Người xin được quẻ này chủ trước lo mà sau vui, trước\nkhó mà sau dễ.\nHiện nay tình cảnh của bạn giống như cái vạc bị gãy chân, bánh xe trục trặc không được may mắn và tốt\nđẹp. Nhưng lại ngộ phùng quý nhân giúp đỡ, sửa chữa những điều hư hỏng, nên được tốt lành như thường.\nNhư vậy những việc cầu xin của bạn cứ yên tâm bền chí thì rút cuộc sẽ được tốt đẹp, dẫu có gì trắc trở ban\nđầu cũng chẳng sao cả.\nBế tắc gặp quý nhân khai thông nên đạt thành. Cần tìm quý nhân mới mong xong việc. Đánh số hạp chút\nít, cần người góp bàn vào, mới hay.", "g": "- việc muốn hỏi mới đầu rất trở ngại nhưng mệnh có quí nhân giúp đỡ nên công việc được chỉnh\nđốn thuận lợi.", "s": "55, 51, 15, 1"}, "156": {"c": "TRUNG HẠ", "hexagram": "Lôi Địa Dự", "line_label": "Động Hào Lục", "p": "Tham tường ngôn ngữ,\nBa đào dương phí.\nSự cửu vô thường,\nThời gian bất lợi.\nNhững câu ngôn ngữ hãy tham tường,\nHiện tại ba đào đang nổi vươn.\nCông việc để lâu tuy chẳng hại,\nThời gian bất lợi chuyện cầu nương.", "b": "Quẻ này báo trước: Niên vận không được tốt, mọi việc đều không lợi. Cày cấy cần phải phòng thất bát,\nbuôn bán cần phải phòng lổ vốn. Chuyện thi phi xảy ra hằng ngày. Bệnh tật thì liên miên không dứt.\nNgười xin được quẻ này nên nhớ rằng dữ nhiều mà lành ít, họa sớm mà phúc muộn, cho nên tất cả phải\ncẩn thận.\nÝ quẻ cho rằng: Tình đời éo le. Phàm tính toán làm ăn việc gì phải suy nghĩ cho kỹ, chớ nên vội vã hành\nsự, mới thu lượm được kết quả mỹ mãn. Hơn nữa, hiện thời vận của bạn đang ở trong cảnh ba đào chưa\nđược hanh thông lắm.\nVậy việc cầu xin của bạn hãy tính kỹ chờ đợi, và đừng nản chí trên đường đời mới mong thành đạt ý\nnguyện.\nẪn nhẫn chờ thời. Tính toán kỹ mọi việc. Và chớ cưỡng cầu bất lợi. Mọi việc cầu xin còn đình trệ. Đánh\nsố ít thông.", "g": "Người được quẻ nầy, e rằng có việc thưa kiện hoặc ngày trước có hợp đồng với ai đó, mà nay\nkhông thỏa thuận được. Sự việc đó gây ra thị phi khẩu thiệt thời gian lâu dài.", "s": "6, 5, 1, 51, 15, 56, 65, 16, 61."}, "157": {"c": "TRUNG THƯỢNG", "hexagram": "Lôi Sơn Tiểu Quá", "line_label": "Động Hào Nhất", "p": "Quý khách tự tương thân,\nCông danh thùy thủ thành.\nHoạch kim tu tích đức,\nNgưỡng vọng thái dương thắng.\nTự mình quý khách hãy thương nhau,\nPhú quý công danh có khó nào.\nKhi được bạc vàng làm phước đức,\nNgưỡng đầu sẽ thấy trời lên cao.", "b": "Quẻ này chủ đã là người chính nhân quân tử thì tự nhiên có kẻ hiền giả bắt bạn với mình. Họ đẩy hoặc họ\nkéo khiến mình có thể phi thăng trong khoảnh khắc dễ như trở bàn tay. Nhờ đâu mà được như vậy? Nhờ ở\ntích đức mà thôi.\nDuy chỉ có tích đức thì ngày sau mới có cảnh mặt trời lên tươi sáng, mặt trăng soi xinh đẹp, đấy chính là\ncái tượngcủa cái lòng thiện ác mà ta có thể biết được. Người xin được quẻ này nên cố gắng lên.\nQuẻ dạy rằng, mọi việc cầu xin của bạn trước hết nên làm lành, làm phước và cần có sự giúp sức của\nngười khác. Những sự mưu cầu ắt được thành công mỹ mãn và sau khi thành đạt ý nguyện chớ nên quên\nviệc làm phước giữ đức, được vậy cuộc đời sẽ như mặt trời rạng đông, ngày càng lên hương.\nCần tu nhân tích đức, thì mọi sự đều thông. Khi giàu sang vinh hiển cũng chớ quên sự làm lành, như vậy\ncuộc đời sẽ trường cửu giàu sang. Đánh số hạp, tốt.", "g": "Người được quẻ nầy đang hiển đạt, nhưng phải chú ý đến việc làm phước đức, nếu không sẽ bị\nmất hết.", "s": "7, 5, 1, 51, 15, 57, 75, 17."}, "158": {"c": "HẠ HẠ", "hexagram": "Lôi Sơn Tiểu Quá", "line_label": "Động Hào Nhị", "p": "Vô cớ khởi ba lan,\nSở cầu sự nhật nan.\nTiêu đàm chung hữu kỵ,\nĐồng tâm sự giác hoan.\nĐất bằng nay lại khởi ba lan,\nMọi việc cầu xin khó thuận đàng.\nĐùa giỡn nói chơi đều phải tránh,\nĐồng tâm hiệp sức mới sầu tan.", "b": "Quẻ này chủ biến cố xảy ra bất ngờ, công việc khó có thể xong. Tai họa thường do miệng mà ra, sự giao\nthiệp tốt ở chỗ tâm giao. Người xin phải quẻ này khi gặp việc bất tất phải sợ khó, nhưng cần phải giữ gìn\nkín đáo, không phải bạn tâm giao không nên bàn tính chuyện trò, như thế ta có thể chuyển buồn ra vui\nđược.\nHiện nay vận thời của người chưa được thông như quẻ nói: Bình địa khởi ba lan, việc cầu lắm gian nan.\nCần phải tránh những chuyện đùa giỡn nói chơi, mà phải cố gắng tính toán sao mới được thành.\nNhư vậy những việc cầu xin của bạn hãy tính toán sao cho kỹ chớ nên vội vã làm e có hại, và khi tiến\nhành cũng phải để ý và cần sự giúp sức của kẻ khác, thì công việc mới được thuận tiện và yên ổn.\nKhó khăn, bế tắc. Cần có người nâng đỡ, giúp sức, may ra mới thành. Cầu mưu, cầu lợi, cũng phải có kẻ\ngiúp. Đánh số chẳng mấy tốt.", "g": "Trước mắt việc không hay lắm, nhưng trên dưới nếu biết đồng tâm hiệp lực với nhau, thì lo gì\nchẳng thành tựu.", "s": "8, 5, 1, 51, 15, 58, 85, 18."}, "159": {"c": "TRUNG TRUNG", "hexagram": "Lôi Sơn Tiểu Quá", "line_label": "Động Hào Tam", "p": "Cù phong suy khởi hắc vân phi,\nNhật tại thiên tâm già bắt đắt.\nNhàn thời vô sự tiệm tương quan,\nCao nọa y thiên vô khắc bác.\nGió thổi mây đen khắp xứ bay,\nTrăng sao nào sợ bị lu mờ.\nTuy mây trước mắt hơi làm ngại,\nRút cuộc lo gì chuyện chẳng may.", "b": "Quẻ này cho biết: Bị người ta hại, nhưng rốt cuộc chẳng việc gì. Sở dĩ có trường hợp đặc biệt này là do ở\nchỗ ta hiểu biết sâu rộng mà ra. Có đôi chút tai hại thì cũng chẳng đủ để lo ngại trong tâm. Xưa nay,\nnhưng kẻ đạo cao đức trọng, dù có bị dèm chê, mưu hại tới đâu cũng chẳng phải là điều đáng sợ hãi lắm.\nTheo ý quẻ: Hiện nay vận trình của bạn như trăng sao giữa trời chẳng sợ mây đen phủ mất nghĩa là số vận\nhiện nay của bạn đang đắc thời. Chẳng ngại việc không may xảy đến cho mình. Căn cứ lời quẻ nói trên.\nNhững việc cầu xin của người rút cuộc sẽ thành công, toại nguyện, tuy có gặp chút trở ngại cũng chẳng\nđáng kể.\nĐang vận hên. Chẳng lo gì cả. Tuy nhiên cũng có vài cản trở, nhưng được lướt qua. Thời vận còn thái,\nchẳng lo. Sự sự hanh thông. Đánh số hạp.", "g": "Việc hoặc người muốn hỏi, giống như mặt trăng ở trên trời, trong sạch không bụi dơ, mây đen\nkhông thể làm cho bẩn hay cốt trói nó được vậy.", "s": "9, 5, 1, 95, 59, 19, 15, 51."}, "160": {"c": "HẠ TRUNG", "hexagram": "Lôi Sơn Tiểu Quá", "line_label": "Động Hào Tứ", "p": "Nhân ỷ lầu,\nHứa đa sầu.\nĐiềm nhiên tiến bộ,\nSự thủy vô ưu.\nNgười dựa lan can sầu thiết sầu,\nChẳng còn biết nghĩ đâu và đâu\nĐiềm nhiên tiến bộ vận thông đã,\nLúc đó mọi điều mới hết âu.", "b": "Tựa bên lầu thường thì suy nghĩ vẩn vơ một mình thì thường để cho sầu buồn vấn vương chín khúc. Chi\nbằng ta có thái độ điềm nhiên đối với thế sự là hơn vì rằng mọi việc đều được hóa công an bài cả từ trước.\nHãy phó mặc cho hóa công, nỗi buồn lo của ta tự nhiên tan biến.\nNgười xưa có câu: Sớm nay có rượu sớm nay say (Kim triều hữu tửu kim quý) biết đâu lại chả là một đạt\nquan đáng ca ngợi? Người xin được quẻ này há lại không lấy đó để suy lường. Người cầu được quẻ này ắt\nlo buồn không thể tả và thời vận của bạn ắt lận đận, và sự may mắn còn xa lánh đây.\nNhưng đừng nên vì vậy mà thối chí nản lòng, hãy ráng chờ qua một thời gian, để cái xui đi cái may đến thì\nlúc đó sẽ vui vẻ cuộc đời như hai câu sau của quẻ thơ nói: điềm nhiên tiến bộ vận thông, lúc đó mọi điều\nmới hết lo âu.\nĐang lo buồn vì thời vận bất tề. Nhưng chẳng sao, ẩn nhẫn qua cơn bỉ vận, thì mọi việc điều thông. Mọi\nsự còn chờ đợi. Đánh số nên tính toán kỹ.", "g": "Một mình suy tính lo âu, tưởng như công việc đâu đâu cũng buồn. Sao chẳng chịu , thấy xa hơn,\nBuồn không cơ sở !--Sạch trơn nổi buồn.", "s": "16, 6, 1, 61, 60, 10."}, "161": {"c": "TRUNG THƯỢNG", "hexagram": "Lôi Sơn Tiểu Quá", "line_label": "Động Hào Ngũ", "p": "Nhất điểm trước Dương xuân,\nKho chi đóa đóa tan.\nChí truyên phương ngọ hợp,\nThiết kị nhị nhị tam.\nXuân sắc nay rảy đãy trở về,\nCành khu hoa nở rủ ham mê.\nNhưng làm công việc phải chuyền chí,\nKỵ nhứt lòng ta chứa trễ bê.", "b": "Quẻ này chủ khuyên ta giao hữu phải cẩn thận. Ví may mà được bạn tốt thì có khác chi cây khô gặp ánh\ndương xuân, cành khô mấy chốc mà hoa lá xum xuê. Bởi thế ta nên phải chú ý kết hợp những người bạn\ntốt, có thế thì về sau ta mới có được những người sống chết với ta, kiệt lực cùng ta.\nCó kẻ không nghe lời khuyên này, lại đi giao du với những kẻ hai lòng, trước tử tế sau đen bạc, thì đừng\ntrách sau đời ta lận đận tan thương. Người xin được quẻ này nên lấy đó làm răn.\nÝ quẻ cho biết rằng thời vận của bạn đang đến lúc đã lên hương. Như xuân đã về với nhân gian, như cành\nkhô lại trổ hoa đầy.\nNhững việc cầu xin của bạn ắt được thành công toại nguyện trong những ngày gần đây. Nhưng phải cố\ngắng chăm chú trong việc cầu, chớ nuôi tánh bê trễ thì mới nên công.\nThời đen, vận thông. Chỉ cần kiên chí hành động, chớ bê trễ, là mọi sự thành đạt. Cầu danh, cầu lợi điều\nđắc quả. Đánh số hên.", "g": "phải đặc biệt coi trọng việc tập trung chú ý vào công việc, mới sớm đạt được kết quả tốt.", "s": "11, 61, 16, 6, 1."}, "162": {"c": "HẠ HẠ", "hexagram": "Lôi Sơn Tiểu Quá", "line_label": "Động Hào Lục", "p": "Đạo lộ tiêu giao,\nMộn đình bế tắc.\nVụ ủng khứ hề,\nVân khai kiến nhật.\nĐ ường đi này vẫn xa xăm,\nVườn tanh cửa khép tối tăm mịt mù.\nRáng chờ sương gió êm ru,\nViệc làm mới dễ cần cù nên công.", "b": "Quẻ này chủ trước quẫn nhưng sau hạnh thông, từ (Bác) chuyển sang (Phục) quẻ. Lúc đầu cuộc đời ta như\nmây mù bao phủ lo lắng triền miên, nhưng may thay chung cục trời quang mây tạnh, ánh thái dương lại\nóng ánh trên không, đường ngõ lại người qua kẻ lại, hạnh phúc trở về với ta như ta hằng mong ước.\nBởi thế cái điều quan trọng trong xử thế phải là: lo rằng chính mính lại không biết mình mà thôi. Người\nxin được quẻ này chớ nên biếng nhác phó mặc mà cũng chớ nên tự tục tự mãn.\nTheo ý quẻ nói, hiện nay vận trình của bạn, chưa được may mắn như quẻ đã tả như vườn vắng tanh, cửa\nkhép, cảnh tình còn buồn lắm, phải ráng chờ thời gian nữa mới được.\nVậy công việc cầu mưu của bạn trong thời gian gần đây, nên ngừng lại chờ đợi, sau cố gắng mà làm, sẽ\nđược toại nguyện.\nBất thông, bất lợi. Cần ẩn nhẫn chờ thời, chờ sóng gió đi qua mới hay. Cầu tài lợi đều dở, chậm. Đánh số\nbất minh.", "g": "Nên chờ thời cơ thuận tiện mới làm, đừng nôn nóng.", "s": "16, 2, 62, 1, 6, 2, 26, 12."}, "163": {"c": "TRUNG TRUNG", "hexagram": "Lôi Thủy Giải", "line_label": "Động Hào Nhất", "p": "Ngư thượng điên,\nTy luân nhược.\nThư nhập nan,\nLục tái trước.\nCá ăn mồi đã dính câu,\nSợi dây quá yếu nào đâu vững vàng.\nNên công bắt cá gian nan,\nKhỏi cần cố gắng mới màng nên công.", "b": "Quẻ này chủ công việc không phải dễ. Cần phải đem hết tâm lực tích cực thực hiện thì mới mong thành\ntựu. Nếu nữa đường đứt gánh, chưa xong đã bỏ, thì công việc chẳng những không thành công mà tâm lực\ntrước đây cũng đều mất sạch. Người xin được quẻ này nên phải coi đó làm một lời khuyên chân thực nhất.\nNhững việc cầu xin của bạn vừa tính qua và bắt đầu trong công việc xem rất dễ dàng như con cá đã ăn câu\nrồi thấy chắc ăn, nhưng bất ngờ dây câu quá yếu khó kéo nổi con cá lên.\nCăn cứ ý quẻ nói trên bạn muốn toại nguyện trong công việc gì thì phải dốc lòng cố công như trong quẻ\nthơ nói: Phải cần cố gắng mới màng nên công.\nTưởng nên công hóa thành dở vào lúc chót, vì tài trí kém mà ra. Cần cố gắng mới mong đạt. Cầu trí, cầu\ndanh bị cảnh trước hay, sau dở. Đánh số nên tính toán kỹ. Biểu tượng: Cá.", "g": "Sẽ gặp được cơ hội tốt hoặc thuận lợi về tiền bạc, nhưng do không đủ điều kiện nên không đạt\nđược kết quả, cần phải nỗ lực thêm mới có hy vọng.", "s": "3, 6, 1, 63, 16, 36, 13,\n31."}, "164": {"c": "THƯỢNG TRUNG", "hexagram": "Lôi Thủy Giải", "line_label": "Động Hào Nhị", "p": "Tương dẫn tánh tương khiên,\nẤn cần hỉ tự nhiên.\nThi vi vô bất lợi,\nSầu sự chuyển đoàn viên.\nNày đây tương dẫn cách tương khiên,\nVui vẻ ân cần lại tự nhiên.\nChẳng có điều gì mà bất lợi,\nViệc buồn cũng biến chuyện đoàn viên.", "b": "Quẻ này chủ công thành danh toại, trăm việc đều hanh thông, nỗi buồn tiêu tan hết, điều vui tới tràn trề.\nĐây là một loại quẻ thượng cát.\nÝ quẻ cho rằng: Cảnh tình của bạn hiện nay có người nâng đỡ cho nhau. Vui vẻ đắc lực nữa chẳng có chi\ntrở ngại dù có việc buồn phiền, hay không xứng ý, rút cuộc cũng vui vẻ.\nVậy cầu xin của bạn cứ tiến hành đi sẽ gặp nhiều may mắn và được quý nhân giúp đỡ để thành công sở\ncầu chẳng có gì đáng trở ngại thời vận lên hương là hanh thông rồi.\nThời vận đến, khỏi lo gì nữa. Có quý nhân giúp. Buồn rầu đã qua. Cầu tài, cầu danh đắc quả. Đánh số hên.", "g": "Người được quẻ nấy, bình thời hay giúp đỡ người , tạo được mối quan hệ tốt đối với xã hội, nên\nmọi việc đều thuận lợi.", "s": "4, 6, 1, 64, 61, 16, 14, 41."}, "165": {"c": "TRUNG HẠ", "hexagram": "Lôi Thủy Giải", "line_label": "Động Hào Tam", "p": "Nghi, nghi, nghi.\nNhất phiên tiếu bải nhất phiên bi.\nLạc hoa mãn địa vô nhân tảo,\nĐộc đối tây phong trướng đại my.\nNghi nghi tất cả việc đều nghi,\nCười ngất một phen rồi sầu bi.\nĐầy đất đỏ lòm người chẳng quét,\nGió mây thấm thía giọt sầu mi", "b": "Quẻ này chủ ly khai cùng bạn hữu, đoàn thể để ở một mình, tâm trạng vô cùng nghi ngại, buồn vui thay\nđổi vô thường.\nNgười xin phải quẻ này có cái tượng của kẻ nghi ngờ đầy bụng khiến chán nản, lìa xa mọi người không ai\ncó thể làm cho vui được.\nThời vận chưa thông, mưu sự nên thành đó là ý của quẻ thơ nói cho hay. Vậy nên sở cầu của bạn hãy tạm\ngác lại một thời gian nữa, để chờ khi thông vận chuyển lối thì lúc đó mới tiến hành những việc cầu mưu\nthì tốt hơn.\nChưa thông thời vận hãy chờ đợi thời cơ đến. Mọi việc đang trì trệ, gặp cảnh lo âu. Công danh tài lợi chưa\nthông, nên chờ. Đánh số chẳng hên lắm.", "g": "Phải thận trọng đối với những việc sai trái , cố tránh đừng làm. Suy nghĩ đôi ba lần rồi mới làm,\nđể tránh lâm vào cảnh “quá vui sanh buồn khổ”.", "s": "5, 6, 1, 16, 65, 61, 15, 51."}, "166": {"c": "TRUNG TRUNG", "hexagram": "Lôi Thủy Giải", "line_label": "Động Hào Tứ", "p": "Thượng hạ bất hòa đồng,\nLao nhi vị hữu công.\nXuất môn thông đại đạo,\nTòng thử bảo sơ chung.\nTrên dưới không hòa lại chẳng đồng,\nLao tâm đến mấy cũng hao công.\nKhi ra khỏi cửa đến đường cái,\nTừ đó vận trình mới hanh thông.", "b": "Quẻ này chủ hiện tại chưa làm được việc gì cả. Có cố tâm tiến tới, cũng không thể thành công. Tuy nhiên,\nnếu dám xuất hành ra đi thì chắc hẳn có thể tiến bộ được. Người xin quẻ này nên xuất hành ra khỏi cửa,\nchứ chớ nên ru rú ở nhà.\nTrên dưới chưa hòa đồng nghĩa là thời vận của người chưa hanh thông nên làm gì cũng chưa nên ý nguyện\nchỉ hao công thôi. Đó là ý quẻ mách cho bạn hay đấy.\nNhưng quẻ lại nói rằng khỏi cửa đến đường cái, nghĩa là nói với bạn rằng phàm mưu tính việc gì đều cần\nphải tính xa, tính rộng thì công việc sở cầu mới có thể thành công mà không bị nguy hại. Nếu không ra\nkhỏi nhà, tức là ý chí chật hẹp không thấy sáng sủa, nên tính toán đều chẳng đến đâu.\nCần đồng tâm hiệp lực và cần phải khoáng đạt, phải tính toán mới thành. Cầu tài, cầu danh có hy vọng.\nĐánh số có thể có kết quả, nhưng nhỏ thôi.", "g": "Trong một tập thể mà chín người mười ý, cách tốt nhất là tách riêng ra , mới có hy vọng bảo vệ\nthành quả của mình.", "s": "6, 1, 61, 16, 66."}, "167": {"c": "THƯỢNG THƯỢNG", "hexagram": "Lôi Thủy Giải", "line_label": "Động Hào Ngũ", "p": "Đại sự khả thành công,\nHữu ích hoàn vô ngại.\nVân trung chân tiểu nhân,\nBác tại tam thu hậu.\nViệc to có thể thành công,\nGặp may lợi ích hanh thông vững vàng.\nNgười trong mây báo tin sang,\nTam thu sau, ắt vinh quang cuộc đời.", "b": "Quẻ này chủ thuận buồm xuôi gió, có thể yên tâm tiến tới. Đã có người bầu bạn giúp đỡ thì không có lý gì\nkhông thành công. Qua mùa thu, tin mừng sẽ liên tiếp tới với ta. Đây là một quẻ thuộc loại đại cát.\nQuẻ thơ cho hay hiện nay vận trình của bạn đã được hanh thông, nên những việc cầu mưu của bạn sẽ được\nthành công toại nguyện chẳng còn gì trở ngại nữa.\nNhưng quẻ nói cuộc thực sự hân hoan, huy hoàng cũng phải chờ ba năm nữa, muốn thành công sự ngiệp\nto lớn cần phải có một thời gian khá dài như xưa có câu \"tam niên hữu thành\".\nVậy bạn muốn mưu cầu cuộc đời giàu sang, nên phải kiên nhẫn bền chí, ắt có ngày hanh thông. Thời vận\nthông, nhưng phải chờ ba thu nữa, mới tốt. Cầu danh đạt. Đánh số, tốt đẹp.", "g": "nhờ người khác chỉ bày, việc làm được thuận lợi, “ba thu” mới thành tựu công việc.\nChú giải “Tam thu”= “Ba thu” :- có những nghĩa sau :- ba năm, ba tháng của mùa thu hoặc tháng thứ ba\ncủa mùa thu.", "s": "6, 7, 1, 16, 17, 61, 76,\n67."}, "168": {"c": "HẠ HẠ", "hexagram": "Lôi Thủy Giải", "line_label": "Động Hào Lục", "p": "Tang du thôi mộ cảnh,\nKhuyết nguyệt khủng nan viên.\nNhược ngộ truy đáo khách,\nPhương tri hỷ tự nhiên.\nĐừng đi nữa, tối đêm khuya,\nMột khi sơ ý e dè gặp ma.\nHãy nên nhớ, nhớ thật xa,\nRủ bè kết bạn, mới là yên thân.", "b": "Quẻ này cho biết: cơ duyên chưa tới, e rằng không có cơ hội tốt đẹp.\nTrong trường hợp này, ta cần phải có người trung gian để giao dịch hợp tác, thì hoàn cảnh tự nhiên khoa\nthư, mặt sầu bỗng tươi tỉnh hẳn lại.\nNgười xin phải quẻ này nên lấy điều nhẫn nại làm hơn.\nTheo ý quẻ cho biết. Việc cầu xin của bạn, khó khăn như ý quẻ nói nếu nhứt định cầu tính cho nên. Việc\nphải cố công thì may ra cưỡng thành, vì quẻ thơ khuyên rằng đừng đi nữa trong đêm khuya, e rằng gặp ma\ntác quái, làm hỏng công việc, nếu cần phải đi thì nên rủ bè kết bạn cùng đi chơi mới tránh được những sự\nkinh tâm.\nVậy việc cùng cầu xin của bạn, 1 là ngừng bước bỏ qua ý định chờ đợi dịp khác, 2 là muốn tiến tới phải\nsuy tính cho kỹ và nên nhờ sức giúp đỡ của đông người, thì mới nên việc.\nBất thông, phòng kẻ phản bạn và kẻ bất lương phá hoại. Cầu tài có sự góp sức của đông người, hay hợp\ntác với người thì việc mới mong thành công. Đánh số, không mấy hạp.", "g": "Sự việc đã đến chỗ cùng đồ mạt lộ rồi, không có hy vọng gì thay đổi tình thế nữa đâu. Đừng nên\nquá ngoan cố , hãy tìm phương mà “bỏ của lấy người” đi !!!", "s": "6, 8, 1, 16, 61, 68, 86, 18."}, "169": {"c": "TRUNG TRUNG", "hexagram": "Lôi Hỏa Phong", "line_label": "Động Hào Nhất", "p": "Biến thư tiên hậu sự,\nGian hiểm vãn lai nan.\nNhược đắc thanh phong tiện,\nBiển chu viễn quá san.\nChuyện xưa trong sách có ghi,\nBiết bao gian hiểm chẳng gì là vui.\nNếu khi gió thổi buồm xuôi,\nThuyền nan một mảnh, tới lui vạn trình.", "b": "Quẻ này chủ tránh dữ tìm lành, không thể làm gì bậy được. Lúc đầu tuy vô cố mà bị khốn quẩn, nhưng về\nsau sẽ được nhiều phương tiện để thoát hiểm. Tóm lại họa phúc tùy người mà đổi thay biến hóa, thiên đạo\nthiệt vô tư vậy. Người xin được quẻ này nên tùy theo hoàn cảnh của mình mà chọn và xét cho cẩn thận.\nTheo ý quẻ nói rằng, những sự cầu mưu đã qua chẳng gì được may mắn và đều gặp lận đận, gian nan, mà\nkhông có gì gọi là vui vẻ.\nTừ nay về sau nếu gặp gió thanh nghĩa là quý nhân dìu dắt nước bước đường đi, thì vận trình sẽ vô cùng\nthênh thang như câu thơ chót trên đã nói: Thuyền nan một mảnh, tới lui vạn trình.\nGian nan qua rồi. Muốn thành công bây giờ, phải nhờ tay quý nhân giúp đỡ. Cầu tài danh cần có người\ngiúp. Đánh số được lợi nhỏ.", "g": "Việc muốn hỏi khó được như ý, gắng chờ thời cơ thuận lợi mới nên.", "s": "9, 6, 1, 16, 69, 91, 61, 19."}, "170": {"c": "TRUNG THƯỢNG", "hexagram": "Lôi Hỏa Phong", "line_label": "Động Hào Nhị", "p": "Mạc thán tàn hoa,\nHoa khai khô thụ.\nỐc đầu xuân ý,\nHỉ tiếu hi hi.\nChớ tưởng hoa tàn mà lại than,\nHoa tàn, lại nở trên cây tàn.\nQuanh nhà xuân sắc khắp vườn ruộng,\nVui sướng tươi cười trời phước ban.", "b": "Quẻ này chủ đắc ý sau khi ta thất ý, nên vui sau khi ta lo buồn. Hoàn cảnh thuận lợi về với ta ngoài dự\nliệu. Đây là quẻ thuộc loại trung cát.\nQuẻ nói rằng: Hiện tình cảnh của bạn như là hoa tàn, làm ăn và tất cả việc mưu cầu không được hanh\nthông. Nhưng chẳng sao vận mạng sắp đến như cây tàn, cành khô lại trổ bông. Hơn nữa, xuân sắp tràn về\nkhắp vườn nhà, cảnh sắc vui tươi và người vui vẻ vô cùng.\nVậy thì sự cầu xin của bạn chớ nên lo âu, sẽ được toại nguyện thời gian gần đây. Nhưng đừng làm chuyện\nthất đức mới nên.\nHết cơn vận bỉ đến hồi thái lai. Cầu tài, cầu danh sắp đạt. Đánh số thông.", "g": "Người được quẻ nầy đang có việc chẳng như ý, nhưng tín hiệu chuyển đổi tốt đã có.", "s": "1, 7, 10, 17, 71, 70."}, "171": {"c": "TRUNG TRUNG", "hexagram": "Lôi Hỏa Phong", "line_label": "Động Hào Tam", "p": "Nhất sự tống thành không,\nNhất sự hoàn thành hỉ.\nNhược ngộ khẩu biên nhân,\nTâm hạ kham bằng ủy.\nViệc này đã hỏng thành không,\nVẫn còn việc nọ hanh thông ý tình.\nGặp người miệng lưỡi thông minh,\nTa cần ủy thác giúp mình mới nên.", "b": "Quẻ này có cái tượng: Được một nửa, mất một nửa, mất khu đất bên đông nhưng lại được đám dâu bên\ntây. Chỉ khi nào gặp người thân hữu họ có chữ (khẩu) ở bên lúc đó ta mới có thể tin tưởng mà ủy thác cho\ncông việc của ta.\nNgười xin được quẻ này không nên băn khoăn lo lắng mà làm gì. (Chữ họ có chữ khẩu ở bên như các chữ:\nĐường, Lã, Châu, Nghiêm, Kiều..).\nThơ quẻ đã nói rằng: Một việc đã hỏng, một việc kia còn nên nhưng cần phải nương dựa sức người giúp\nmình mới có kết quả tốt đẹp. Thực vậy, chúng ta sống trên xã hội nhân quần, cần phải có sự giúp đỡ lẫn\nnhau thì mới có thể sanh tồn và cầu tiến được.\nVì giống như việc đời đâu phải mọi việc đều vừa ý toại lòng, ắt có được này mất nọ. Vậy bạn hãy nên tự\nnhiên nghĩa là: Tận nhân lực tri thiên mạng thôi.\nNhất thất, nhất đắc. Đừng lo. Nhưng cần phải có sự hỗ trợ. Cầu tài, cầu danh nên nhớ kẻ giúp. Đánh số\nhạp chút ít.", "g": "Công việc đang tiến hành năm ăn năm thua, cần gia tăng thỏa hiệp với người. Nếu tìm được chỗ\nthân tín nói giúp, mới có hy vọng thành công.", "s": "71, 1, 17, 11, 7."}, "172": {"c": "TRUNG TRUNG", "hexagram": "Lôi Hỏa Phong", "line_label": "Động Hào Tứ", "p": "Dục đắc nguyệt trung thỏ,\nTu bằng đào lý chi.\nCao sơn lai tiếp dẫn,\nSong hỉ chiêu sông my.\nTrong trắng con thỏ quả là hay,\nMuốn được phải nhờ trò giúp thầy.\nThăng tiến non cao mà tiếp nối,\nMới nên công nghiệp được tròn đầy.", "b": "Quẻ này chủ người giúp ta chính quay lại làm đệ tử cho ta. Bởi thế, họ chạy lại giúp ta một cách tận tâm.\nCâu thơ sau: Song hỉ chiêu đôi mày dùng để ngụ cái ý trên. Người xin được quẻ này có cái may là nhờ\nngười mà thành sự, nếu độc lực thì chỉ vô công nhọc sức.\nTheo ý quẻ cho biết những việc cầu mưu của bạn muốn được như thỏ ở cung trăng quả là hơi khó đấy,\nnhưng muốn được như ý muốn thì cần phải có sự giúp đỡ của đàn em đông, phải có kẻ có thế lực giúp đỡ,\nmới có thể nên công nghiệp sở cầu, như hai câu thơ thứ hai và thứ ba đã ẩn ý ở trên vậy.\nCao vọng quá e khó thành đạt, muốn thành công phải có sự giúp đỡ. Cầu danh, cầu lợi cần nhờ kẻ giúp.\nĐánh số tốt.", "g": "Đạt mục đích không dễ chút nào, ngoại trừ có năng lực siêu phàm hỗ trợ.", "s": "2, 7, 1, 27, 72, 17, 12, 21, 72."}, "173": {"c": "TRUNG THƯỢNG", "hexagram": "Lôi Hỏa Phong", "line_label": "Động Hào Ngũ", "p": "Sự toại vật ưu phiền,\nXuân phong hỉ tự nhiên.\nCách thùy tam xích điếu,\nĐắc ý hoạch lân tiên.\nViệc cầu toại nguyện chớ ưu phiền,\nTươi đẹp gió xuân vui tự nhiên.\nBa thước dây câu cứ thả đó,\nCá kia nó sẽ dính câu liền.", "b": "Quẻ ở trên đây chủ xuân phong đắc ý, tên gấm thêu hoa. Buông ba thước câu ngụ ý khuyên ta làm điều\nthiện. Phàm người ham làm điều thiện, không có gì là không được như nguyện. Cho nên người xin được\nquẻ này nên tích nhiều âm công để vun trồng cây phúc thêm tươi tốt.\nNhững việc cầu mưu của bạn ắt được toại lòng vừa ý, chớ lo âu, đó là ý quẻ mách cho hay đấy. Vì thời\nvận hiện nay như gió xuân tươi đẹp, vui vẻ tự nhiên tốt đẹp đó, nên chẳng có gì đáng lo buồn cả, và cứ thả\ncâu khơi khơi cũng có cá cắn câu. Vậy việc cầu của bạn cứ tiến hành đi, đừng nên bỏ lỡ dịp may hiếm có.\nVận thời hanh thông: Bất chiến tự nhiên thành không làm cũng nên việc, tốt đẹp lắm. Sự sự thông đạt.\nĐánh số hên. Biểu tượng: cá.", "g": "đại cát , việc muốn hỏi đạt kết quả như ý, mừng vui không ngớt.", "s": "3, 7, 1, 37, 73, 72, 27, 23."}, "174": {"c": "TRUNG TRUNG", "hexagram": "Lôi Hỏa Phong", "line_label": "Động Hào Lục", "p": "Viên hựu khuyết,\nKhuyết hựu viên.\nThời thời khắc khắc yếu chu tuyền,\nThời lại tài kiếm duyên.\nKhuyết tròn, tròn khuyết không chừng,\nMau làm công việc chớ đừng lơ mơ.\nKhôn ngoan giao thiệp mưu cơ,\nThời lai vận đến nên thơ cuộc đời.", "b": "Quẻ này nói: Vinh khô đắp đổi, giàu nghèo lên xuống, chẳng được duyên dung trọn vẹn. Tuy rằng giỏi\ngiao dịch với đời, biết cơ hội thử thời đấy nhưng rốt cuộc cũng chỉ vô duyên. Người xin được quẻ này cần\nphải chú trọng hai điểm: thiên thời và nhân hòa.\nTheo quẻ thơ cho hay hiện nay vận thời của bạn như đêm trăng khuyết tròn không chừng, nghĩa là vận\ntrình của bạn chưa được hanh thông, còn lận đận lắm.\nVì những việc mưu cầu khó mà như ý, nhưng chẳng sao, phàm mưu cầu việc gì, nếu biết khôn ngoan ứng\nphó thì cũng có thể thành đạt sở cầu và hy vọng.\nLưng chừng bắt quyết, cứ tiến tới đi, thời đến là thành. Có hy vọng thành tựu việc cầu xin. Đánh số cẩn\nthận.", "g": "Muốn cho kết quả tròn đầy—Phải do mình có cơ may đúng thời—Nếu như biết việc biết đời—\nLo chi chẳng được thảnh thơi lâu dài.", "s": "4, 7, 1, 14, 41, 17, 71, 47."}, "175": {"c": "HẠ HẠ", "hexagram": "Lôi Trạch Quy Muội", "line_label": "Động Hào Nhất", "p": "Thừa bệnh mã,\nThượng nguy ba.\nPhòng thất túc,\nKiên ta dà.\nCưỡi ngựa ốm đau lên hiểm đèo,\nNguy nan nào kể hết ôi eo.\nĐề phòng cẩn thận trặc chân ngã,\nLúc đó chần chờ thấy khổ nghèo.", "b": "Quẻ này chủ động chẳng bằng tỉnh, tiến chẳng bằng thoái. Tuy chỉ mong được an phận thủ kỷ thế mà cũng\nchẳng xong. Nào chuyện thị, nào chuyện phi, thị phi đều biết cả, thế mà cũng chẳng thể tránh. Bởi thế cho\nnên nếu không biết nghe lời răn dạy ắt sẽ hối không kịp. Người xin phải quẻ này cần phải lo lắng giữ\nmình, cốt thiết chớ có vọng cầu phi nhạn.\nÝ quẻ tả cảnh tình của bạn hiện nay như cưỡi ngựa ốm mà leo lên ngọn đèo hiểm nghèo, đường đi rất là\nkhó khăn, quẻ nhắn nhủ bạn hãy nên cẩn thận đề phòng những điều bất trắc xảy ra khó lường trước được.\nNhững việc cầu xin của bạn khó được hài lòng, mà còn phải cẩn thận đề phòng thì mới yên lành. Bất\nthông, bất lợi. Đề phòng tai nạn hiểm nghèo. Còn nhiều gian nan, chớ tính. Biểu tượng: Ngựa. Đánh số e\nthua.", "g": "Nhà dột lại gặp mưa đêm—Thuyền đang mục, gió dữ liền tấn công—Việc đời dè dặt trong lòng—\nTrước sau suy tính mới hòng việc nên.", "s": "5, 7, 1, 57, 75, 17, 71, 15."}, "176": {"c": "HẠ HẠ", "hexagram": "Lôi Trạch Quy Muội", "line_label": "Động Hào Nhị", "p": "Lưỡng sự dĩ hòa đồng,\nKhinh chu ngọ tiện phong,\nĐạo mô nhân đắc ý,\nCa xướng cầm lưu trung.\nGiờ nay tâm trí vẫn chưa yên,\nBiết tính gì đây để khỏi phiền.\nRáng rượt hai ba luồng sóng gió,\nNgày mai vui đến khỏi lo phiền.", "b": "Quẻ này có cái tượng nói cười mà định được loạn.\nTuy bị lầm đường, bềnh bồng trên dòng xiết, nhưng vẫn đắc ý hát ca.\nNếu không có gió thuận thuyền nhẹ thì thử hỏi làm sao mà dám có thái độ như vậy?\nNgười xin được quẻ này phải chủ trương cuộc sống hòa đồng, coi hiểm nguy như bước trên đường phẳng.\nViệc cầu xin của bạn, theo ý trong quẻ còn phải nhiều gian nan lận đận, chưa thể toại nguyện tức khắc.\nCần phải ráng sức tìm cách vượt qua những chướng ngại trong bước tiến, thì mới thành đạt theo ý muốn.\nXấu, chỉ nên ẩn nhẫn chờ thời qua cơn vận bỉ, hãy làm là hơn. Có hy vọng phần nào. Những việc cầu tài,\ncầu danh còn xa, cần phải gặp vài ba lần gian nan, mới may ra. Đánh số bất minh.", "g": "được cá chớ quên nôm, cũng đừng thừa gió bẻ mănng mà mang khốn.", "s": "17, 71, 76, 16,\n16, 67, 17, 1, 7, 6"}, "177": {"c": "HẠ TRUNG", "hexagram": "Lôi Trạch Quy Muội", "line_label": "Động Hào Tam", "p": "Thượng tiếp bất ổn,\nHạ tiếp bất hòa.\nTương triền tương nhiều,\nBình địa phong ba.\nTiếp với trên không vừa ý ta,\nNối liền dưới, chẳng thấy tình hòa.\nNan phân, nan giải dằn co mãi,\nSóng gió đất bằng bỗng nổ ra.", "b": "Quẻ này có cái tượng: Vô duyên với kẻ khác, trống xuôi kèn ngược, lủng củng lỉnh kỉnh, chẳng được yên\nổn vui tươi, lúc nào cũng thiếu hòa khí. Người xin được quẻ này phải nên cẩn thận đề phòng là hơn.\nQuẻ thơ tả rằng, muốn giao tiếp trên dưới đều không được, sự việc lại dằn co mãi, đó là ý quẻ nói hiện\nthời vận của bạn rất xấu, không chút nào gọi là may mắn.\nNhững việc cầu xin ắt khó thành đạt và giải quyết theo ý muốn, hãy cẩn thận trong việc làm ăn. Mọi sự\nkhông như ý, chớ tính. Nên chờ thời cơ đến là hơn. Phòng gian nguy hoạn nạn. Đánh số dở.", "g": "", "s": "8, 7,\n1, 17, 71, 81, 18, 78.\nLời bàn của Thông Huyền Lão Nhân:\n(Chị em cùng đi lấy chồng, rồi lại cùng bị đưa về nhà mẹ)\nQuẻ này có tượng vô duyên với người, chẳng được yên ổn, lúc nào cũng thiếu hòa khí. Người được quẻ\nnày nên cẩn thận đề phòng là hơn. Vì người trên kẻ dưới đều không thuận hợp. Hiện giờ thời vận của bạn\nrất xấu, mưu cầu rất khó thành đạt, mọi sự không như ý, nên chờ thời cơ khác đến thì hơn."}, "178": {"c": "HẠ HẠ", "hexagram": "Lôi Trạch Quy Muội", "line_label": "Động Hào Tứ", "p": "Bạch ngọc mông trần,\nHoàng kim mai thế.\nCửu cửu quang huy,\nDã tu nhân cữ.\nVàng chôn dưới đất, ngọc đầy bụi,\nSang quý gì chỉ cũng ẩn thân.\nÁnh sáng tuy rằng chưa giảm bớt,\nĐào lên được nó mới hay lành.", "b": "Bịch ngọc, hào kim, quý báu biết bao nhiêu. Nhưng vàng ngọc chôn trong đất, có khác chi sỏi đá. Tuy vậy\nvàng ngọc vẫn long lanh sáng đẹp, chẳng bao giờ biến chất, đáng tiếc là chỉ tiếc cho bọn ngu phu tục\nchẳng thấy chẳng hay mà thôi. Rồi một sớm được tìm ra, vàng ngọc đâu có giảm giá được đâu. Người xin\nđược quẻ này có cái tượng của kẻ có tài mà không được dùng, đền nổi mai một mất thanh danh.\nHiện nay thời vận của bạn như vàng ngọc bị chôn dưới đất và bị bụi trần phủ đầu, tuy vẫn sáng sủa. Và\nnếu muốn những vàng ngọc thành đồ hữu dụng và vật quý, thì phải đào lấy lên mới được. Nghĩa là nói\nviệc cầu của bạn như đến chỗ tuyệt vọng mà vẫn còn hứa hẹn lắm, song phải cố sức thì mới nên công, chớ\nkhông phải ngồi không nói suông mà thành được.\nPhải cố gắng trong công việc. Vàng ngọc bị chôn và đầy bụi, thì ánh sáng đã mất hiệu quả và giảm sự quý\ngiá rồi. Phải có kẻ giúp đào lên và phủi bụi đi, thì mới tốt trở lại. Cầu xin gì, nên có kẻ giúp mới thành.\nĐánh số nên tính toán kỹ.", "g": "Bất luận là gia đình hay đoàn thể ngoài xã hội, nếu người trên kẻ dưới không hòa hợp được với\nnhau, là mầm móng của sự thất bại cầm chắc.", "s": "17, 77, 71, 7, 1."}, "179": {"c": "TRUNG TRUNG", "hexagram": "Lôi Trạch Quy Muội", "line_label": "Động Hào Ngũ", "p": "Bối hậu, tiếu hi hi,\nTrung hành đạo tối nghi.\nSở cầu chung hữu vọng,\nBất tất chựu song my.\nSau lưng hé miệng hả cười,\nTrung dung triết khuyết đổi người thích nghi.\nĐôi mày nhăn nhíu làm chi.\nSố cầu hy vọng chẳng gì đáng lo.", "b": "Quẻ này chủ đi không đo đường tắt, bởi thế ngoài lo nhưng trong lòng trong tâm thực yên. Công việc có\nhy vọng thành, đó là lẽ đương nhiên, hà tắc lo lắng băn khoăn cho thêm khổ. Người xin được quẻ này cứ\nviệc an tâm thả sức hành động.\nÝ quẻ dạy rằng sở cầu của bạn ắt được thành công toại nguyện chẳng có gì trở ngại nhưng phải nhớ khi\ntiến hành công việc phải đi đúng đạo.\nTrung dung tức là đừng quá vội, hay quá chậm, quá nóng hay quá nguội quá hăng say, hoặc thối chí... thì\ncó hại cho sự làm và hãy tùy theo hoàn cảnh mà tiến thành.\nNên giữ trung dung trong việc làm, là sự ắt thành, nghĩa là việc gì cũng nên giữ mức vừa phải là hay. Cầu\ndanh, cầu lợi, hy vọng. Đánh số hạp một phần.", "g": "Ước nguyện trong lòng nhất định được, cần chi mặt mày nhăn nhó sầu buồn ?", "s": "9, 7, 17, 71, 91, 19, 7"}, "180": {"c": "HẠ HẠ", "hexagram": "Lôi Trạch Quy Muội", "line_label": "Động Hào Lục", "p": "Tiều tụy vô nhân vấn,\nLâm gian thính đo quyện.\nNhất thành sơn nguyệt dịch,\nThiên lý lệ quyên quyên.\nTiều tụy nào ai có biết đâu,\nTrong rừng nghe tiếng đỗ quyên sầu.\nNối trăng tiếng sáo lừng vang dội,\nNgàn dặm lệ tràn khắp Á Ấu.", "b": "Quẻ này chủ lạc phách tha hương, không người cứu giúp. Cho nên khi nghe tiếng quyên lơ lững gợi sầu,\ntiếng dịch rên rỉ kêu buồn thì trong lòng bi thiết thê lương. Người xin quẻ này xuất hành có tai họa, hơn\nnữa có bệnh hoạn phải đề phòng.\nTheo ý quẻ cho biết, hiện nay cảnh tình cũng như thời vận của bạn như bông hoa ủ rũ chẳng ai màng\nngắm đến, như ở nơi rừng nghe tiếng kêu sầu của chim quốc trong đêm trăng núi rừng lại nổi lên tiếng\nsáo, thì trước cảnh tình đó bạn thử nghĩ xem vắng tanh lạnh lẽo đến mức nào, dù là tâm gan sắt đá cũng\nphải sầu thảm.\nVậy việc cầu xin của bạn hãy nên an phận là hơn, nếu có mà cầu đi nữa, cũng khó thấy được một kết quả\ntốt đẹp.\nMọi việc bế tắc. Buồn rầu, lo âu hay hơn hết là chớ tính toán, chờ đợi thời là hay. Biểu tượng: chim đỗ\nquyên. Đánh số không hạp.", "g": "Quẻ nầy nói đến tình cảnh đôi trai gái yêu nhau, nhưng vì sông núi cách ngăn, nên nhớ nhau\nthành bệnh. Hoặc nói đến hạng người mệnh vận đen đũi bao vây, tâm sự chứa nhiều thương cảm.", "s": "18, 8, 1, 81, 10, 80."}, "181": {"c": "TRUNG THƯỢNG", "hexagram": "Lôi Thiên Đại Tráng", "line_label": "Động Hào Nhất", "p": "Hoa lạc chính phùng xuân,\nHành nhan tại bán trình.\nSự thành hoàn bất tựu,\nSách bạn lưỡng tam tuần.\nHoa tàn nay gặp xuân lại,\nĐường đi một nửa sao phai ý đầu.\nViệc tuy thành chẳng còn lâu,\nĐành chờ tháng nữa thì lâu mới thành.", "b": "Lẽ ra hoa tàn phùng xuân là một việc may mắn cho bông hoa, nghĩa là người cầu xin quẻ được gặp may\nmắn, nhưng lại vì ý chí lưng chừng nên làm cho sự cầu mưu không thành.\nBởi đó phải chờ lại một dịp khác thì sự cầu mưu mới nên. Đó là ý quẻ mách cho hay. Vậy việc cầu lo của\nbạn phải nắm lấy cơ hộivà bền chí tiến tới, đừng do dự, đắn đo thì mới được.\nSự thành, nhưng vì chần chờ, bất quyết, mà hóa ra hỏng, phải chờ dịp khác. Một tháng nữa việc mới nên.\nPhải cố gắng, nhất quyết mới được. Cầu tài, cầu danh có hy vọng. Đánh số được lợi nhỏ.", "g": "Quẻ nầy nói riêng cho những người làm quan, được vận tốt, đường công danh phát triển cao\nthêm.", "s": "2, 8, 1,\n12, 18, 81, 82, 21."}, "182": {"c": "HẠ THƯỢNG", "hexagram": "Lôi Thiên Đại Tráng", "line_label": "Động Hào Nhị", "p": "Lăng ba hương lý thụ thâm ân,\nQuế điện sa song ân thụ tần.\nTòng thử uy danh sơn nhạc trọng,\nQuang huy trực thượng vị ty luân.\nHoa tàn nay gặp xuân lại,\nĐường đi một nửa sao phai ý đầu.\nViệc tuy thành chẳng còn lâu,\nĐành chờ tháng nữa thì lâu mới thành.", "b": "Quẻ này chủ người ra không thể về ngay được, mưu sự còn chưa nhất định, ân tín lại bị quở trách cho nên\nmuốn hiểu được rõ ràng, thực chưa phải lúc. Song chẳng bao lâu nữa ta lại có cái thế chẻ tre, cái vui đón\ntrăng, giải hết những mối ưu phiền lâu nay. Người xin được quẻ này nên nhẫn nại chờ đợi, chớ có vội vã\nhấp tấp.\nLẽ ra hoa tàn phùng xuân là một việc may mắn cho bông hoa, nghĩa là người cầu xin quẻ được gặp may\nmắn, nhưng lại vì ý chí lưng chừng nên làm cho sự cầu mưu không thành.\nBởi đó phải chờ lại một dịp khác thì sự cầu mưu mới nên. Đó là ý quẻ mách cho hay. Vậy việc cầu lo của\nbạn phải nắm lấy cơ hộivà bền chí tiến tới, đừng do dự, đắn đo thì mới được.\nSự thành, nhưng vì chần chờ, bất quyết, mà hóa ra hỏng, phải chờ dịp khác. Một tháng nữa việc mới nên.\nPhải cố gắng, nhất quyết mới được. Cầu tài, cầu danh có hy vọng. Đánh số được lợi nhỏ.", "g": "Bất cứ việc gì cũng không gặp thời, sớm nhất là trong vòng một tháng sẽ gặp trở ngại, mọi việc\ntrở thành rắc rối lôi thôi.", "s": "2, 8, 1,\n12, 18, 81, 82, 21."}, "183": {"c": "TRUNG TRUNG", "hexagram": "Lôi Thiên Đại Tráng", "line_label": "Động Hào Tam", "p": "Dục hành hoàn chỉ,\nBồi hồi bất dĩ.\nĐông dao mạc cưỡng,\nĐắc chỉ thả chỉ.\nMuốn đi sao lại không đi,\nNgã ba quanh quẩn làm chi ngập ngừng.\nChớ nên rung động lưng chừng,\nViệc gì vừa phải, nhớ đừng quá mong.", "b": "Quẻ này chủ mọi việc khôngcó hy vọng bao nhiêu, tuy rằng lòng không phải là không có chủ kiến. Nhưng\nthật ra thời cơ quả gặp khó. Chi bằng hãy tỉnh lự trầm tư, ẩn dật nơi ruộng vườn, như thế lại đỡ hại. Người\nxin quẻ này nên chủ ý lời khuyên.\nQuẻ ý nói rằng: Này khuyên dạy người làm gì cứ làm đi đừng quá cưỡng cầu và nên để việc tự nhiên. Nói\ncách khác quẻ này khuyên người nên tận nhân lực đi, đừng nên suy tính về lợi hại quá, còn việc thành đạt\nthế nào ắt có Trời định cho.\nCăn cứ vào quẻ ý nói trên. Về sự cầu xin của bạn: việc tình duyên sẽ thành đạt và hạnh phúc, nếu đặt ái\ntình chí thượng, còn việc tương lai nên thuận theo. Câu thứ tư trong quẻ, mong cầu việc gì đều phải vừa\nxứng với sức mình, đừng nên làm những chuyện vượt quá tài năng, nếu không khó được hạnh phúc. Cũng\nnhư người xưa có câu: Tri túc thường túc, bất tri túc thường âu vậy.\nTính gì cứ tính đi đừng lưng chừng và cũng đừng quá tham vọng, quá sức mình thì việc mau thành. Cầu\ntài, cầu danh chậm. Đánh số, tính toán kỹ mới xong.", "g": "Quẻ nấy chỉ cho người vì bất đắc dĩ phải làm công việc ngoài ý muốn, nếu tránh né được thì cũng\nnên tránh, miễn cưỡng làm cũng chẳng ra gì .", "s": "3, 8, 1, 38, 83, 18, 81, 13, 31."}, "184": {"c": "TRUNG TRUNG", "hexagram": "Lôi Thiên Đại Tráng", "line_label": "Động Hào Tứ", "p": "Tâm hạ sự an nhiên,\nChu tuyền thượng vị toàn.\nPhùng long tuân hữu cát,\nNhân nguyệt vĩnh đoàn viên.\nHiện nay lòng dạ đã an nhiên,\nNhưng chưa châu toàn theo ý liền.\nCần phải gặp rồng mới may mắn,\nTrăng người lúc đó vĩnh đoàn viên.", "b": "Quẻ này chủ xử cảnh rất thuận lợi bình an, nhưng tiếc vẫn chưa có hy vọng đạt đích mỹ mãn. Điều kiện\ncần thiết là phải gặp được năm tháng hên may, hoặc gặp được rồng (người quân tử) lúc đó mới có điều vui\nmừng tới cửa. Người xin được quẻ này nên tỉnh tâm mà chờ đợi.\nÝ quẻ cho hay tất cả công việc đã yên dạ không gì đáng lo cả nhưng chưa được toại nguyện lập tức thôi.\nCông việc cầu xin rốt cuộc ắt sẽ đưộc thành đạt vẹn toàn như trăng ngày rằm.\nVậy những việc cầu xin của bạn sẽ được may mắn thành công. Nhưng bền chí chờ đợi quú nhân chỉ dẫn\nđường đi nước bướcthì hay lắm như câu thứ ba nói \"Cần gặp rồng mới may mắn\"\nSắp đến vận thái. Chờ rồng đến thì hay. Biểu tượng: Rồng. Cầu tài, cầu danh, sắp đạt. Đánh số thông. Số\nhên: 18, 84, 81, 48, 14, 41, 4, 8, 1.", "g": "Việc muốn hỏi, tuy chưa giải quyết trọn vẹn, nhưng yên tâm, không có gì đáng lo lắng cả. Gặp\n“Rồng” (tức năm Thìn hoặc người tuổi Thìn) sẽ được điều lành đến.", "s": ""}, "185": {"c": "TRUNG HẠ", "hexagram": "Lôi Thiên Đại Tráng", "line_label": "Động Hào Ngũ", "p": "Mộng lý thuyết quan sơn,\nBa thâm hạ điều nan.\nDanh lợi chung hữu vọng,\nMục hạ vị khai nhân.\nNằm mộng chiêm bao chuyện núi sông,\nThả câu nơi sóng khó vừa lòng.\nLợi danh rút cuộc có hy vọng,\nNhưng tiếc giờ đây vận chưa phùng.", "b": "Quẻ này chủ nghĩ vơ nghĩ vẫn, như người ngây nói mộng. Việc chưa có trải qua, chưa thấy khó. Tuy nhiên\nkhông phải vì khó mà chịu chết già trong cửa sổ. Thực ra công việc thuận lợi và được toại lòng chỉ vào hồi\nvãn niên mà thôi. Người xin được quẻ này thiết tưởng không nên ngã lòng phải cố tiến mới được.\nTheo ý quẻ thì tương lai hứa hẹn đầy tốt đẹp như câu thứ ba trong thơ nói: Danh lợi rút cuộc có hy vọng\nnhưng bạn phải đợi chờ một thời gian nữa thì mới gặp may.\nVậy những việc cầu xin của bạn cần phải nhẫn nại chịu đựng, chớ nóng lòng thì sẽ dần dần được toại\nnguyện. Xưa có câu: Hữu phúc tự nhiên lai đó.\nNên chờ đợi, thời gian sắp đến rồi. Cần ẩn nhẫn chờ thời, chớ bôn ba. Cầu danh cầu lợi còn chậm. Đánh\nsố hạp.", "g": "Tưởng đâu là được thay đổi hoàn cảnh hoặc công tác mới, ai dè không biết tại sao lại chẳng có\ngì.Mai ra về sau có thể được cơ hội tốt, còn bây giờ thì chưa có gì lạc quan cả.", "s": "5, 8, 1, 85, 58, 18, 15, 51."}, "186": {"c": "THƯỢNG THƯỢNG", "hexagram": "Lôi Thiên Đại Tráng", "line_label": "Động Hào Lục", "p": "Tam tiến khai vân lộ,\nDoanh cầu chỉ nhạc thành.\nHứa đa nhàn khẩu ngữ,\nPhiến tác tiếu đa canh.\nBa mũi tên bay ngàn dặm xa,\nDanh cầu mọi sự được điều hòa.\nDù bao tiếng nói xì xào đó,\nRút cuộc trở thành khúc nhạc ca.", "b": "Quẻ này chủ gặp dữ lại hóa lành, ngộ nạn mà chẳng có việc gì, tưởng bị họa mà lại hóa ra phúc. Cho nên\nnhững việc kinh doanh mong cầu, lập tức thành công. Người xin được quẻ này thiết tưởng chớ nên lấy\nnhững lời nói nhảm nhí làm nhục chí mình khiến lầm lạc, không kịp hối.\nQuẻ ý cho biết rằng: hiện thời vận tinh của bạn cầu xin đang lên hương như ba mũi tên bắn đi xa ngàn\ndặm đấy. Nên sự cầu xin đều thành đạt ý nguyện chẳng có gì đáng trở ngại cả.\nDù có khó khăn rắc rối cũng thành không có, mà còn được vui vẻ như hai câu thơ chót của quẻ đã ẩn tả ở\ntrên. Vậy những sự cầu mưu của bạn ắt thành đạt như ý nguyện. Đừng ngồi không tán rỗi, để mất dịp may\nđó.\nRất tốt đẹp, vận thái lên rồi, còn có tiếng tăm đi xa là khác. Cầu danh, cầu lợi theo ý sở cầu. Đánh số hạp\ntốt.", "g": "Quẻ nầy thuộc về đại vận hanh thông, đối với việc mưu tính hay lập nghiệp mà nói tới.", "s": "6, 8, 16, 18, 61, 86."}, "187": {"c": "HẠ HẠ", "hexagram": "Lôi Phong Hằng", "line_label": "Động Hào Nhất", "p": "Hưu quyến luyến,\nNgọ tiên trình.\nChung náo loạn,\nXuất môn đình.\nChớ nên quyến luyến hoài hoài,\nTương lai có hại, rồi mai hận đời.\nNếu không ắt loạn tả tơi,\nBỏ nhà bỏ cửa, nào hơi yên lành.", "b": "Quẻ này chủ có những kẻ biếng nhác chẳng cố sức làm việc, kẻ biếng nhác chỉ vụ lấy yên thân, nên để lỡ\ncả tiền đồ. Họ suốt ngày đắm chìm trong tửu sắc cho nên nổi. Rồi ra đi để tránh, thử hỏi lúc đó phải hỏng\nhết cả chương trình kế hoạch xây dựng từ trước tới nay.\nTheo ý quẻ cho biết: Những cầu xin của bạn trong thời gian gần đây, chưa thể thành đạt ý nguyện nếu theo\nđuổi mãi cũng chỉ mòn thời gian quý báu mà thôi. Và tương lai của bạn ắt không được tốt đẹp lắm.\nCăn cứ nội dung của quẻ thơ, chớ không dám lắm lời làm buồn lòng người xin. Nếu bạn chỉ mới 20 tuổi\nthanh xuân thì càng nên theo quẻ dạy mà làm thì mới nên vậy.\nKhó mong, khó thành. Đừng lưu luyến làm gì, nếu là tình duyên, thì nên dứt bỏ, phải dứt khoát, quyết\nđịnh và cố gắng, thì tương lai mới nên. Cầu danh lợi còn chậm. Đánh số, chưa thông.", "g": "Đừng vì người yêu hoặc quê hương mà quyến luyến chẳng thể lên đường, có thể làm hỏng đại\nsự. Nên mạnh dạn ra đi sớm, tránh được điều rối loạn sinh tai họa.", "s": "7, 8, 1, 87,\n78, 18, 17, 81, 71."}, "188": {"c": "TRUNG TRUNG", "hexagram": "Lôi Phong Hằng", "line_label": "Động Hào Nhị", "p": "Vạn lý ba đào tĩnh,\nNhất thiên phong nguyệt gian.\nLợi danh vô trở cách,\nHành lộ xuất trùng quan.\nTuy nay ngàn dặm ba đào,\nMột ngày trăng gió hàng hàng sáng trong.\nCông danh tài lợi dễ phùng,\nThong dong bước khỏi ải trùng hoan ca.", "b": "Quẻ này chủ có vui chớ không lo, có được chớ không có mất. Thực ra danh lợi song thu, xuất hành yên\nổn, tôn vinh an lạc. Đây là một hào thuộc loại Đại cát.\nHiện nay thời vận của bạn được hanh thông lắm. Như bài quẻ nói ngàn dặm ba đào đấy. Nhưng chẳng sao,\nsẽ có ngày gió êm trăng sáng thì lúc đó tài lợi chẳng khó gì và sẽ vượt khỏi những khó khăn trở ngại.\nVậy những việc cầu xin, thì xin hãy bền chí và cố gắng bước tiến ắt được toại nguyện một ngày không xa.\nCông danh có ngày thành đạt. Chỉ cần có chí thực hiện và cố gắng là nên. Ẫn nhẫn, thời cũng sắp đến rồi.\nCầu tài, cầu danh đến hơi chậm, chớ nản. Đánh số, được nhưng ít lợi.", "g": "đại cát.", "s": "18, 8, 1, 81, 88."}, "189": {"c": "HẠ TRUNG", "hexagram": "Lôi Phong Hằng", "line_label": "Động Hào Tam", "p": "Khát vọng mai cơ họa bính,\nMạn lao tâm, như tróc ảnh.\nNgộ hồ long, phượng khả tỉnh.\nNhìn ngó mai giải khát được,\nĐói xem bánh vẽ càng thêm sầu.\nBắt hình bóng, chỉ hao tâm lực,\nGặp Hồ Long số mới nên màu.", "b": "Quẻ này cho biết: Mưu sự hoàn toàn hỏng hết, trăm việc không việc nào thành, thực là nhọc mà chẳng có\ncông gì. Gặp khúc gấp này, chỉ còn cách đợi, đến khi rồng cọp gặp nhau (tức là Thìn với Dần), lúc đó cơ\ntrời mới chuyển có lợi cho mình, phải chăng đó là mệnh số tiền định? Người xin được quẻ này chớ nên\ncưỡng cầu.\nÝ quẻ nói: Chưa làm vua mà sắm long bào như hai câu trước nói ngó mai mà trị khát, đói mà vẽ bánh, đó\nđều là việc thiếu thông minh. Cho nên sở cầu của bạn sẽ trở như hai câu sau nói: Bắt hình bóng chỉ hao\ntâm lực mà thôi chẳng thu lượm được kết quả nào cả.\nVậy bạn muốn thành đạt ý nguyện, hãy cố gắng nhằm thực tế sự việc và kế hoạch trong đời sống thì mới\nnên công.\nThực tế, chớ mơ mộng và đừng tha mồi bắt bóng vô ích mà thôi. Chờ gặp Hồ Long, năm Dần và Thìn, thì\nmay ra mới định, mới nên, Biểu tượng: Rồng, Hổ. Mọi sự cầu, chậm đánh số cẩn thận.", "g": "Người được quẻ nầy , quen có những ảo tưởng trong đầu, không tốt đâu, cần sửa đổi ngay.", "s": "9, 8, 1, 18,\n19, 81, 91, 89."}, "190": {"c": "TRUNG TRUNG", "hexagram": "Lôi Phong Hằng", "line_label": "Động Hào Tứ", "p": "Sự mê tâm bất nề,\nSự khoan tay bất khoan.\nNhất trường hoan hỉ họ,\nBất cửu xuất trùng quan.\nViệc mê tâm, chẳng bị mê,\nViệc xong nhưng bụng e dè vẫn lo.\nMột khi vui vẻ hô to,\nChẳng lâu ra ải hẹn hò ngày mai.", "b": "Quẻ này chủ cứ vừa vui vừa buồn, mọi người đều theo ý mình. Hiện tại thì cuộc đời bình thản tầm thường,\nnhưng chẳng bao lâu nữa hồng vận tới, mọi việc đều giải quyết xong êm đẹp hết. Người xin được quẻ này\nduy chỉ có khắc phục, kiên trì hết mức để đợi.\nTheo ý quẻ cho hay rằng: Công việc sở cầu trước mặt vẫn chưa toại ý phải đợi một thời gian nữa, mà thời\ngian ấy chẳng là bao lâu như bài thơ trên đã nói. Vậy trong lúc chờ đợi bạn hãy nên suy tính trước biến\ntiến. Khi rủi đi ắt thuận tiện cho việc cầu mưu.\nThời may sắp đến, chỉ nên chờ đợi một mà thôi. Đừng lo, cứ tiến hành đi, cầu mưu lợi có chậm. Đánh số\nthì nên tính toán kỹ.", "g": "Một mình làm việc sao nên—Nhọc nhằn mà vẫn tuổi tên lu mờ--Được người trợ giúp bây giờ--\nMới mong việc lớn có cơ hội thành.", "s": "19, 9, 1, 91, 10, 90."}, "191": {"c": "HẠ HẠ", "hexagram": "Lôi Phong Hằng", "line_label": "Động Hào Ngũ", "p": "Dạ bán đọ vô thuyền,\nKinh đào khủng nhạ thuyên.\nNguyệt tà vân đạm xứ,\nAn tín hữu nhân truyền.\nNửa đêm nào có thuyền sang sông,\nSóng gió bão bùng làm hết hồn.\nNơi mà trăng xế mây ảm đạm,\nCó kẻ đưa tin báo đến ông.", "b": "Quẻ này chủ sự kinh khủng đến tột độ, bất cứ cái gì cũng như nhìn thấy binh đao ma quái vô cùng ghê\nrợn. Phải đợi đến lúc thời qua cảnh đổi, mới có thể nhận được tin tức xác thực nhưng than ôi tình thế đã\ntrễ. Bói được quẻ này quả là chẳng lành.\nQuẻ nói: Nửa đêm sang sông không đò và sóng gió hãi hùng, đó là ý nói hiện nay vận trình của bạn còn bế\ntắc, mà chưa được hanh thông, việc cầu mưu của bạn còn lận đận lắm chưa nên việc đâu, mà còn gặp\nnhiều gian nan nữa là khác. Nhưng chẳng sao, đến lúc cùng lại có nẻo thông, như được tin tức báo cho\nviệc hay. Chữ trăng xế nói sắp rạng đông là may mắn.\nĐang bấp bênh sóng gió. Nửa đêm sang sông đã không đò, mà còn gặp sóng gió nữa , thì làm sao mà\nsang? Gian nan lận đận. Chờ sáng, trăng xế, sóng êm thì sẽ có kẻ giúp, mà nên việc. Cầu danh lợi còn\nchậm. Đánh số ắt thua.", "g": "Người được quẻ nầy, không nên mạo hiểm làm việc, phải nghiên cứu kỹ thiên thời, địa lợi, nhân\nhòa rồi làm, mới tránh khỏi sơ xuất.", "s": "1, 9, 91, 19, 11."}, "192": {"c": "HẠ HẠ", "hexagram": "Lôi Phong Hằng", "line_label": "Động Hào Lục", "p": "Sự khổ ly lưu,\nNhân bất xuất đầu.\nVãng lai bế tắc,\nYếu kiến vô hữu.\nNếu là việc đã trễ lâu,\nNgười thì khó xuất đầu nên công.\nRất e bế tắc chẳng thông,\nChỉ là thấy cái hư không bẽ bàng.", "b": "Quẻ này rất xấu, mưu sự thì thất bại, mất vật thì khó tìm, xuất hành thì gặp hiểm, Lục giáp thò có tai, nằm\nbệnh thì thấy quỷ, cầu tài thì lỗ vốn, đi lại thì chẳng lành, gia sự thì chẳng yên. Người xin được quẻ này\ncần phải tu nhân sửa đức để mong tránh bớt phần nào.\nQuẻ báo cho hay người cầu được quẻ này, thì vận thời chưa được hanh thông, việc cầu còn nhiều trở ngại,\nkhó mà thành đạt như ý muốn, nhứt là đối với những việc mưu tính đến giờ vẫn chưa thấy một tia hy vọng\nnào. Nên bỏ hẳn chớ nên theo dõi nữa , vì quẻ nói rất rõ chẳng ích gì cả.\nTóm lại, phàm mưu tính việc gì nếu bắt đầu vấp phải trắc trở không được thuận xuôi thì nên ngừng bước,\nnếu không sẽ có sự không đẹp đưa đến cho mọi người.\nBất thông. Dừng lại là hơn. Nên chờ thời vận hanh thông, hãy tính. Cầu danh, cầu tài, khó đạt, đánh số\nchẳng nên công.", "g": "Theo đuổi hoặc đang làm việc gì, cũng phải cẩn thận nắm bắt tình hình rõ ràng rồi làm mới ít sai\nsót.", "s": "29, 92, 19, 12, 2, 9, 1, 91."}, "193": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Tốn", "line_label": "Động Hào Nhất", "p": "Vạn lý phiến phàm chuyến,\nBá bình lắng bất loạn.\nHành hành vô trở trệ,\nViên xứ cánh thông tân.\nMuôn dặm buồm giương bước vận trình,\nSóng êm vẫn thấy tâm hồn kinh.\nCứ đi chẳng có gì lo ngại,\nCàng tới càng xa càng ý tinh.", "b": "Quẻ này có tượng: Thanh vân đắc lộ (ý nói vận hên) cá nhảy chim bay (ý nói bay nhảy tung hoành được)\ncứ hễ ra khỏi cửa là thành công, nhất là càng ra xa càng tốt. Đây là triệu chứng Đại Cát. Người xin được\nnên cấp tốc đi xa ngay.\nTheo ý quẻ cho biết, người cầu được quẻ này tốt lắm, những việc cầu mưu của bạn ắt được thành đạt như\ný. Tuy hơi băn khoăn, lo âu, nhưng chẳng gì đáng ngại.\nBởi theo quẻ thơ phán rằng, hiện thời vận của người như là mảnh buồm giương đưa đẩy muôn dặm vận\ntrình. Tuy sóng êm vẫn kinh hồn, nhưng đi chẳng gì trở ngại, càng đi xa càng được hanh thông. Vậy\nnhững dự tính cầu mưu, hãy nên tiến tới để những may mắn đang chờ.\nTốt đẹp. Thời lai phong tống đằng vương các, tạo chu bột nên danh. Chớ lo, chớ sợ. Đánh số hạp.", "g": "Việc muốn hỏi được thuận lợi ổn thỏa cả, ngày sau còn phát triển thêm, chắc chắn là thắng cuộc\nthôi.", "s": "3, 9, 1, 91, 19, 13, 31, 93."}, "194": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Tốn", "line_label": "Động Hào Nhị", "p": "Thân lịch kinh đào,\nĐông phương tiêu hao.\nThái bình thân thái,\nMục hạ toàn tảo.\nMùa hè nóng hổi thu sương hàn,\nBông mới nở rộ, bông cũ tàn.\nSự thế nhân tình nay ẩm lạnh,\nGặp nhau câm miệng chớ nên bàn.", "b": "Quẻ này chủ tai bay vạ gió nhưng bất quá chỉ tạm thời. Rồi một sớm, dương xuân trở lại, gió đông về bao\nnhiêu mây mù ảm đạm tan lui, thì lúc đó là lúc có thể làm được đủ việc, lo được đủ chuyện, bất tất phải\ntiến thì tiến gấp lui lại lui nhanh. Nếu cần ngừng thì ngừng, nếu cần đi ta đi thong thả mà hành động,\nchẳng có gì đáng lo muộn đâu.\nTheo ý quẻ nói rằng: Hiện cảnh tình của bạn đang ở trong cảnh nhân tình thế thái ấm lạnh, như khí trời\nnóng lạnh bất thường nghĩa là thời vận của bạn không thông, nên quẻ khuyên chớ nên lắm lời với người\nmà ta vô ích.\nVậy ý quẻ dạy ta rằng: Thời vận chưa đến. Ta hãy chờ đợi và những việc cầu xin của bạn không nên vội\nvả lắm, làm càn rồi sẽ hỏng.\nThời bất thông, chớ tính chuyện gì. Nên chờ thời là hay. Công danh tài lợi còn chậm, đánh số e bị thua. Số\nhên: 4, 9, 1, 19, 14, 92, 49, 91.", "g": "Quẻ nầy thích hợp với những người cáo lão nghỉ hưu, rất thuận lợi. Nếu hỏi về việc khác , thì đây\nnói, việc có nguy hiểm nhưng không đáng ngại, chẳng ảnh hưởng gì đến bản thân mình.", "s": ""}, "195": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Tốn", "line_label": "Động Hào Tam", "p": "Hạc tự vân trung xuất,\nNhân tòng nguyệt hạ quy.\nTân hoan doanh lưỡng giáp,\nBất dụng xu sòng my.\nCon hạc từ mây bay khỏi mây,\nDưới trăng cũng có kẻ về đây.\nBiết bao vui vẻ hiện đầy mặt,\nChớ nhìn nhau mà mất cái hay.", "b": "Nói hạc ở trong mây, người đội trăng có ý ám chỉ thế giới thần tiên. Ở đây ám chỉ nhân vật dưới thời thịnh\nthế. Đã gọi thịnh thế thì người dân còn có chi lo ngại nữa mà chẳng vui tươi ca hát. Người xin được quẻ\nnày là được quẻ tốt đó.\nQuẻ ý nói hạc từ mây ra dưới trăng tức có người đến, và vẻ mặt đầy vui không còn nét nhăn mày lo nghĩ,\nnghĩa là vận tình của bạn đã được hanh thông, sung sướng, nhàn rãnh như con Hạc Tiên trên mây rồi,\nchẳng còn chi trắc trở nữa.\nVậy những việc dự tính của bạn cứ yên lòng mà tiến hành, sẽ gặp được may mắn thành đạt ý nguyện, chớ\nlo ngại gì cả.Thời vận thông, có tin may đưa đến, có kẻ giúp đỡ. Cầu tài, cầu danh, đều thông đạt. Đánh\nsố, tốt. Biểu tượng: con Hạc.", "g": "cát tường , không có gì bất lợi .", "s": "5, 9, 1, 15, 19, 91, 59, 95."}, "196": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Tốn", "line_label": "Động Hào Tứ", "p": "Thâm đàm ngư thả điếu,\nU cốc điều khả la.\nChỉ dụng tràng cửa tâm,\nBất tất sinh nghi hoặc.\nCá ở thâm đàm vẫn thể câu,\nBắt chim trong núi chẳng lo sầu.\nNhưng ta hãy giữ bền tâm trí,\nChớ chán nghi ngờ mất nhịp cầu.", "b": "Quẻ này có ý khuyên ta: Vất vả bao lâu sắp thành, chớ có bê trễ, chuyện Ngu Công rời núi tuy chứng tỏ\nNgu Công cực thực ngu, nhưng lại cho biết rằng chỉ có những kẻ cực ngu như Ngu Công mới có hằng\n(bền tâm cứ lớn mãi).\nViệc làm nếu chậm trễ lại do dự thì biết đến bao giờ mới xong được. Người xin được quẻ này nên kiên\nnhẫn trì chí, chớ nghe lời cám dỗ, chê dèm của người đời.\nViệc cầu xin của bạn, dầu có khó khăn mà vẫn vượt qua, rồi sẽ đi đến kết quả tốt đẹp, nếu kiên chí chịu\nđựng đeo đuổi sở cầu.\nNhư bài thơ quẻ đã nói: Cá trong vực thẳm chim trong rừng núi có thể bắt được, mà chẳng khó khăn lắm.\nSong ta phải bền chí chờ đợi, cá chim đó ắt tự nhiên ăn câu, vào lưới của bạn đã giăng sẵn. Chẳng lo nó\nthoát khỏi đâu.\nThời vận gần lúc hanh thông, đừng lo cho mệt và cũng đừng nghi ngờ, việc sắp thành công danh, tài lợi\nsắp đạt. Đánh số hên. Biểu tượng: Cá, Chim.", "g": "Nếu đủ sức nhẫn nại, công việc sẽ thành, khỏi nghi ngờ gì nữa.", "s": "19, 96, 16, 91, 69, 6, 9, 1."}, "197": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Tốn", "line_label": "Động Hào Ngũ", "p": "Tiến bất an,\nThoái bất khả.\nThượng hạ tương tòng,\nMinh châu nhất lõa.\nBước chân tiến tới phập phồng,\nLui thì chẳng được vì không ngõ vào.\nMột lòng góp sức cùng nhau,\nMinh châu một hột sắc màu sáng tươi", "b": "Quẻ này có cái tượng: Tiến thoái lưỡng nan, chuyển rời chẳng quyết, cho việc đắc thất (được hoặc mất)\nquá quan trọng. Chỉ vì một viên ngọc quý minh châu mà đến nổi phí hết cả cuộc đời. Ôi! Chỉ tại vì lòng\ntham quá độ mà khổ thân đó thôi. Người xin được quẻ này khi lâm sự nên lấy nghĩa lý làm trọng chứ\nkhông nên lo lắng quá về chuyện đắc thất.\nHiện bạn đang lâm cảnh tiến thoái lưỡng nan, lo âu cho bước đi của mình, không đạt được một hy vọng về\ntương lai, lắm lúc sinh ra nản lòng. Nhưng hai câu cuối trong quẻ khuyên bạn nên một lòng cùng nhau góp\nsức người xung quanh, ắt sẽ gặp may mắn như hột châu sáng chói.\nLúc đầu dở, sau hay, thời vận thông. Chỉ cần đồng tâm hiệp lực và có sự cộng tác của người, là việc đạt\nthành. Cầu mưu lợi phải nhờ người. Đánh số có sự góp sức thì tốt.", "g": "Việc muốn hỏi, đang lâm vào cảnh tiến thối lưỡng nan, có liên quan đến sự đoàn kết nội bộ. Cần\nchỉnh đốn lại mới có hy vọng thành tựu.", "s": "9, 7, 1, 19, 17, 97, 91, 71."}, "198": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Tốn", "line_label": "Động Hào Lục", "p": "Trước trước chiêm tiện cơ,\nKỳ trang lộ bất mê.\nTục triều vô hợp ý,\nSạ miễn thị hòa phi.\nMuôn điều nắm dịp trước tiên,\nRồi đây công việc tự nhiên dễ dàng.\nTuy giờ này, ý chữa nhàn,\nNhưng đều tránh được những đàn thị phi.", "b": "Quẻ này chủ tâm linh thủ mẫn, khéo léo xếp đặt. Rất thích y theo lối cũ mà hành động chứ không bước\nquẹo sang đường khác. Trong trường hợp này tuy nhiều lúc không đắc ý mấy nhưng có thể tránh được\nmiệng tiếng thị phi, đó kể ra cũng điều hết sức may mắn rồi vậy. Người xin được quẻ này chớ nên nản\nlòng, mà bỏ hết cái chí bình sinh của mình.\nTất cả sự mưu cầu của bạn, cần nhứt phải nắm lấy cơ hội trước, rồi việc cầu mưu sau này mới dễ dàng\nthành đạt, tuy hiện giờ chưa được vừa ý xong cũng tránh được những điều chưa hay xảy đến cho bạn, đó\nlà ý muốn quẻ nói đó.\nVậy phàm mưu tính việc gì phải suy xét kỹ lưỡng trước, nắm vững công việc và trọng tâm, cũng như biết\nchụp lấy cơ hội, thì mới nên công, ít nhứt cũng tránh được không may.\nCần chộp lấy thời cơ, tuy còn lận đận, nhưng cuộc đời sắp lên hương, lo gì. Cầu danh lợi tuy chậm, nhưng\nthành đạt. Đánh số hạp. Số hên 8, 9, 1, 19, 18, 98, 91.", "g": "Việc làm định hướng đúng—Ta cứ thế mà làm—Lời ra tiếng vào ấy—Bỏ mặc chớ bận tâm.", "s": ""}, "199": {"c": "HẠ HẠ", "hexagram": "Phong Thiên Tiểu Súc", "line_label": "Động Hào Nhất", "p": "Tước táo cao chi thượng,\nHành nhân cổ độ đầu.\nBán đồ bất liễu sự,\nNhất mô chuyện sinh sầu.\nChim kêu chiu chít nhánh cây cao,\nBến cũ vắng tanh có kẻ nào?\nDự việc nửa đường nay chửa hết,\nTrời lặn xế chiều sầu biết bao.", "b": "Quẻ này khuyên ta sớm mưu đồ cơ nghiệp, chớ nên lần lửa tháng năm, khiến lúc về già lòng thêm hối tiếc.\nNgười xin được quẻ này chớ nên hiểu lầm, rồi chần chừ do dự để mất tuổi xuân hoạt động.\nCả bài thơ của quẻ tả cảnh bạn cầu xin về thời vận hiện nay đều là những lời buồn bã, chẳng có câu nào\nmay mắn. Những cầu xin của bạn chưa được tốt đẹp và hanh thông cần phải giữ mình chăm nom con cái\ngia đình cho chu toàn và nhẫn nại chờ thời là hơn.\nVận bỉ, chớ tính chuyện mà hỏng. Nên chờ đợi ẩn nhẫn chờ thời. Cố nhân bạn bè đều mất cả, còn biết\ntrông cậy vào đâu. Cầu danh lợi còn xa. Đánh số chẳng lợi. Biểu tượng: Chim.", "g": "Dư luận không đồng tình—Cho rằng việc không tốt—Trót đã làm phân nửa—Sầu muộn bởi gốc\nnầy.", "s": "19, 9, 99, 91."}, "200": {"c": "THƯỢNG THƯỢNG", "hexagram": "Phong Thiên Tiểu Súc", "line_label": "Động Hào Nhị", "p": "Tạo thạch đắc tạo ngọc,\nĐào sà đắc đào châu.\nNhãn tiền mục hạ,\nHà dụng trù trừ.\nĐục đá may thay được ngọc vàng,\nĐào trong đất cát gặp châu sang.\nGiờ đây mọi việc đều hay cả,\nTính toán làm chi mệt xác thân.", "b": "Trong cuộc đời bình thản, bỗng nhiên rực sáng lạn. Phàm trăm việc vui mừng đều do ở chỗ bất ngờ xảy\nđến. Đấy quả là việc kỳ lạ. Tuy nhiên phải nhớ rằng rút cục chỉ có cái tâm quang minh chính đại mới có\nthể giải quyết được hoàn toàn mà thôi.\nNgười xin được quẻ này cần phải biết yếu lý \"đầy vơi\" và cái nghĩa \"khiêm ích\" chớ nên quên bản lai diên\nmục các sự vật (tức là cái tính chất thực nằm trong mọi công việc).\nNgười cầu được quẻ này, thật là đáng mừng. Vì quẻ nói thời vận của bạn đã đến lúc lên hương như cục đá\nđược ngọc, đào cát gặp được châu báu, thiệt là may mắn thay.\nVậy tất cả sự mưu tính cứ cố gắng tiến tới. Phần thành công ắt nằm trong tay trong một ngày gần đây,\nchẳng có gì đáng lo ngại.\nTốt đẹp. Mọi sự đều gặp may mắn. Mua vé số. Đánh số rất hạp, khỏi cần tính, việc cũng đắc quả.", "g": "Người được quẻ nầy, thời vận đang đến giai đoạn rất tốt, đừng chần chờ chi nữa, hãy mau bắt tay\nvào việc, sẽ thu hoạch nhiều kết quả ngoài ý muốn.", "s": "2, 20, 22."}, "201": {"c": "HẠ HẠ", "hexagram": "Phong Thiên Tiểu Súc", "line_label": "Động Hào Tam", "p": "Vô đoạn phong vũ thôi xuân khứ,\nLạc tân chi đầu đào lý hoa.\nĐào bạn hữu nhân ca thả khốc,\nBiết ai tâm sự rối như tơ.\nBỗng nhiên mưa gió giục tìm xuân,\nRụng hết hoa cánh chẳng có gì.\nBên cạnh vườn đào người hát giỡn,\nBiết ta tâm sự lắm ly bì.", "b": "Quẻ này chủ Lưu Ly mất việc bàng hoàng chẳng có chỗ tựa nương, lang thang cầu bơ cầu bất như chó bị\nhỏa tai. Tâm loạn lòng rối như tơ vò. Người xin được quẻ này nên thực hiện chữ nhẫn triệt để. Ngoài ra\nkhông còn phương pháp nào khác.\nÝ quẻ nói rằng, việc cầu xin của bạn khó mà được toại ý bởi quẻ đã ẩn tả cảnh của bạn như trời xuân bỗng\nbị mưa gió làm cả vườn hoa trái tiêu tan chẳng còn cảnh xanh tươi như trước.\nDo đó, còn gì may mắn mà nói. Vậy nên bạn hãy giữ theo lối sống cũ, chớ nên vội vã và cao vọng, phải\nchờ qua một thời gian nữa là hay hơn.\nẪn nhẫn chờ thời. Đang bị hãm vận, thì còn làm gì được nữa. Cầu danh lợi nên chờ đợi. Đánh số chưa\ntiện.", "g": "cảnh tốt chẳng dài lâu, hoa đẹp không nở hai lần, xa lánh những kẻ tiểu nhân lôi cuốn vào chỗ bại\nhoại thì mới tránh được tai họa cho mình.", "s": "21, 2, 1, 10, 20."}, "202": {"c": "THƯỢNG THƯỢNG", "hexagram": "Phong Thiên Tiểu Súc", "line_label": "Động Hào Tứ", "p": "Lư uyển nhất thời xuân,\nĐình tuyền hoa sắc tân.\nTruyền lai hảo tiêu tức,\nThảo mộc tân hân hân.\nThảo vườn nay lại trở xuân thời,\nTrước cửa hoa thơm sắc liễu tươi.\nTin tức rao truyền báo hỷ sự,\nNước, cây mừng rỡ nói chi người.", "b": "Quẻ này chủ mưu vọng thành tựu, hân hoan vui mừng, công danh tài lợi, không có gì là không toại ý,\ngiống in như cây cỏ được mùa khí ấm áp của mùa xuân giúp cho được nẩy cành xanh ngọn. Người xin\nđược quẻ này cá cái tượng đãi cát.\nThảo vườn xuân và cây có sắc màu thơm tươi, đó là cảnh xuân sắc vui tươi và đó cũng là quẻ ý cho biết\nhiện nay thời vận của bạn đó. Vậy nghĩa là hiện nay, thời vận của bạn đã đến là hanh thông, từ nay về sau\ntất cả sự mưu tính ắt được gió xuôi thuận buồm, vạn sự như ý.\nThời vận hanh thông. Vạn sự như ý sở cầu. Cứ tiến hành, ắt đắc quả. Đánh số hạp.", "g": "những điều muốn hỏi đều được cát tường như ý .", "s": "2, 20, 22."}, "203": {"c": "HẠ HẠ", "hexagram": "Phong Thiên Tiểu Súc", "line_label": "Động Hào Ngũ", "p": "Môn ngoại sự trùng điệp,\nẤm nhân đa ngộ hợp.\nHiền xử tuy trợ xảo,\nĐiểu điểu chung nam hợp.\nCửa ngoài sự việc điệp trùng,\nẤm nhân hội ngộ tương phùng biết bao.\nTuy hiền nữa giúp chẳng sao,\nNhưng chung quy việc làm hao công trình.", "b": "Quẻ này chủ chính không thắng tà, quả bất địch chúng. Tuy nhà có hiền phụ đấy, nhưng vẫn khó xếp đặt\ncho ổn thỏa mọi việc. Đây chính là lúc im hơi lặng tiếng ẩn dật qua ngày.\nNgười xin được quẻ này nên đề phòng miệng tiếng, xa kẻ gian nịnh, bắt chước như Đào Tiềm đời Tần ẩn\ndật, xa lánh hết mọi người là hơn.\nQuẻ này cho biết vận trình còn hơi trắc trở dầu cố làm cầu mưu đến đâu trong lúc này vẫn chưa được toại\nnguyện mà lại hao công mất giờ nữa.\nNhững người cầu được quẻ này tốt hơn là nên ngừng những việc đang mưu tính nhứt là việc khuếch\ntrương kinh doanh.\nVận bất tề, nên đình đốn công việc là hơn. Cưỡng cầu tính ắt chẳng đến đâu, còn hao công, tốn của là\nkhác. Cầu việc còn lâu. Đánh số chưa thuận.", "g": "Việc muốn hỏi đang bị kẻ tiểu nhân cản trở quấy rối, là công việc không phải ở trong nhà, nên con\ntrai con gái có muốnn giúp đỡ cũng khó mà thành.", "s": "2, 3, 23, 32, 30, 20."}, "204": {"c": "THƯỢNG THƯỢNG", "hexagram": "Phong Thiên Tiểu Súc", "line_label": "Động Hào Lục", "p": "Sự hữu thiện,\nDiện hữu quang.\nChung thủa hảo thương lượng,\nHồ trung nhật nguyệt trùng.\nCông việc hanh thông tâm trí vui,\nMặt mày sáng sủa nét tươi cười.\nChung quy mọi việc dễ thương lượng,\nBầu bí vinh hoa hưởng cuộc đời.", "b": "Quẻ này chủ tâm kiềm tính, đến đâu là cái lợi đến đó. Khi ý vui đã tới thì đâu còn biết năm tháng dài lâu\nnữa. Ấu cũng là nhờ công thành viên mãn, nên mới có cái thiện quả như vậy. Người xin được quẻ này nên\nđo sâu đò cao để giữ bằng được chung cục tốt đẹp cho đời mình.\nNgười cầu được quẻ này, thực là may mắn vô cùng. Cuộc đời sắp lên hương đấy, tất cả việc cầu mưu\nchẳng có gì trở ngại mà là Nhứt phàm phong thuận. Và hơn nữa, những sự cầu mưu sẽ thành đạt hơn\nngoài ý định.\nCâu thơ chót nói trong bầu bí chứa đựng vinh hoa. Nghĩa là sự cầu mưu sẽ được thần linh giúp đỡ, nên sự\nthành công ắt là huy hoàng vậy. Tốt đẹp. Thời vinh hoa, phú quý đã đến. Đánh số tốt.", "g": "Quẻ nầy chủ về việc có được vợ hiền, gia đình hòa thuận, sih hoạt hạnh phúc, lại cũng nói đến\nviệc đàn bà có thai (tin mừng)", "s": "24, 2, 4, 42,\n20, 40"}, "205": {"c": "TRUNG TRUNG", "hexagram": "Phong Trạch Trung Phu", "line_label": "Động Hào Nhất", "p": "Ám khứ hữu minh lai,\nƯu tâm dự khả hài.\nChung tu thành nhất tiếu,\nMục lục mạc nghi thai.\nMờ ám đi rồi đến rõ ràng,\nẤu sầu tâm sự tự nhiên tan.\nChung quy mọi việc thành vui vẻ,\nHiện tại chớ nên mà nghĩ hoang.", "b": "Quẻ này chủ sự cứu người té ra lại cứu mình báo ơn ai ngờ lại mang ơn. Trước lo sau vui, quả thực là một\ncâu chuyện cười. Người xin được quẻ này nên cố gắng làm đẹp những khó khăn, khỏi lo không được\nhưởng phúc.\nCông việc cầu mưu của bạn cho hay hiện nay tuy chưa được vừa ý lắm còn hơi trắc trở, song rút cuộc việc\nđâu vào đó ắt sẽ vui vẻ thành đạt như ý cầu. Nhưng bạn phải một lòng với việc cầu, thì mới thành công,\nnếu không hậu quả có thể trái ngược như câu chót của quẻ thơ đã nhắn nhủ vậy.\nViệc tính hơi chậm, nhưng được thành tựu. Chỉ cần cố gắng là đạt. Cầu danh lợi còn lâu, nên chờ. Đánh\nsố, cần tính kỹ.", "g": "tối đi sáng đến, sáng đi tối đến, trong cõi u u minh minh vốn có số định sẵn.", "s": "25, 5, 2, 20, 50, 52"}, "206": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Trạch Trung Phu", "line_label": "Động Hào Nhị", "p": "Bảo kính vô trần nhiễm,\nKim điêu dĩ tiền tài.\nDã phòng thiên ý hợp,\nChung bất nhạ trần ai.\nMãnh Hổ nay đang chiếm núi sâu,\nRa hang tiếng rống quỷ thần sầu.\nTinh thần phấn chấn dương oai võ,\nHá sợ người đông giết hại đâu.", "b": "Quẻ này cho biết gặp được kẻ quang minh do đó ắt được hưởng sự kính quý vui vầy. Rồi đây trời lắng dân\nnghe, trời nhìn dân ngỏ, những hành vi của mình đều tương hợp với ý trời, như thế thì bao giờ mà có\nchuyện vất vả trần ai nữa. Đây là một quẻ đại cát và đại lợi.\nTheo ý quẻ cho biết việc cầu xin của bạn đều được toại nguyện như ý và may mắn, chẳng có gì đáng lo âu\ncả, bởi trong ý quẻ nói rất rõ ràng rằng: hiện vận số của bạn như con cọp dữ đang chiếm cứ một núi sâu,\nđó là ý nói được địa lợi, có địa lợi tức là có ưu thế, tức nắm chắc phần thắng vậy.\nNhư thế việc cầu xin lo chi không thành, nhứt là hai câu chót dương oai võ và chẳng sợ người đông, thì\ncàng nói rõ về đường công danh ắt sẽ gặp may mắn vì số mệnh đó. Thời đến vang danh. Sự sự tốt đẹp, sở\ncầu. Biểu tượng: Cọp. Đánh số hạp.", "g": "việc tốt đến hai lần, người được quẻ nầy rất chính trực, cao quí, được hưởng ơn trời rất nhiều, mọi\nviệc đều như ý.", "s": "6, 2, 26, 62, 20, 60."}, "207": {"c": "THƯỢNG THƯỢNG", "hexagram": "Phong Trạch Trung Phu", "line_label": "Động Hào Tam", "p": "Hòa hợp sự,\nĐàm tiếu thanh.\nHỉ ân tại bán trình,\nBản độ đạp thanh vân.\nHoa quỳ nở hướng phía đông,\nTrung thành nhứt chi son lòng biết bao.\nCửa nhà mở rộng đón chào,\nVui thay hưởng lạc thanh cao thái bình.", "b": "Quẻ này chủ sự nghiệp thành đạt, không phí mất chút sức nào. Bằng trình đã có phận chứ chẳng phải\nchuyện ngẫu nhiên. Cho nên hễ cầu thì hẳn ứng, hễ tiến cũng được tốt. Người xin được quẻ này có cái\ntượng: hễ đến nơi thì được tiếp rước.\nSự cầu xin của bạn thành đạt hanh thông không có khó khăn trở ngại và sự cầu xin chẳng những được\nthuận lợi mà còn đặng nhiều hạnh phúc nữa bởi ý quẻ cho hay bông quỳ đang hướng về mặt trời nở, người\nlại trung thành hết lòng và mở rộng cánh cửa đón chào ta, nhứt là câu chót nói rõ hưởng lạc thái bình.\nVận thái vô cùng thành đạt, cầu mưu cầu duyên, cầu tài đắc lợi. Đánh số hạp.", "g": "tốt, việc hôn nhân đã định rồi, tin tức được cao thăng đang đến, song hỉ lâm môn, đời người rất\nvui.", "s": "27, 72, 2, 7, 20, 70."}, "208": {"c": "HẠ HẠ", "hexagram": "Phong Trạch Trung Phu", "line_label": "Động Hào Tứ", "p": "Hoa tàn nguyệt khuyết,\nKính phá thoa phân.\nHưu lai hư vãng,\nSự thủy an ninh.\nTrăng đã khuyết rồi hoa lại tàn,\nKim thoa gãy bể kính tiêu tan.\nTừ đây nên nhớ đừng lui tới,\nCông việc mới yên và dễ dàng.", "b": "Quẻ này chủ hung triệu: Nhà cửa thì gây tai sinh họa, vợ chồng thì ly tán, tiền tài sự nghiệp thì thua lỗ thất\nbại, kiện tụng thì quan tư ức hiếp. Người xin được quẻ này cần phải giữ gìn, tự giới cẩn thận mới mong\nthoát khỏi tai bay vạ gió.\nThơ quẻ phán rằng: Trăng khuyết hoa lại tàn, thoa gãy, kính bể nát, qua hai câu trên, thì người ta sẽ biết\nđược thời vận của bạn hiện nay như thế nào rồi.\nVậy những việc cầu xin của bạn khó được toại nguyện trong lúc này, còn riêng về bệnh hoạn cũng phải ra\ntâm cứu chữa, thì mới tránh được điều không may. Bế tắc, bất thông. Nên chờ vận thái đến là hơn, đánh số\nkhông hạp.", "g": "rất là xấu, mọi việc đều không nên làm. Về việc hôn nhân thì không xứng ý với nhau, sợ rằng phải\nchịu cảnh chia tay ly biệt.", "s": "28, 20, 80, 8, 2, 82."}, "209": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Trạch Trung Phu", "line_label": "Động Hào Ngũ", "p": "Môn ngoại hảo âm lai,\nSinh ý ưng hữu khánh.\nDanh lợi cánh hữu thiện,\nNhạn hàng chung câu trận.\nCông danh lắm lắm đáng ghi,\nNhưng trong thực tế có gì hân hoan.\nTu hành chính quả mới mong,\nTrường xuân muôn thuở phước hồng dài lâu.", "b": "Quẻ này có tượng: Mọi việc đều được như ý, mậu dịch (như buôn bán) được hưng vượng. Kẻ gần thì vui,\nngười xa thì tới tất cả đều giữ được sự tử tế hào hiếu thông cảm lẫn nhau. Tuy nhiên, người xin được quẻ\nnày vẫn phải lo cái nỗi đau lòng của Khuất Nguyên thưở nọ, mà cần nên lưu tâm từng phút từng giây,\nmong tránh những điều bất hạnh.\nQuẻ nói công danh dù nhiều, mà trên thực tế lại chẳng có gì bởi trong cuộc đời chết là hết, chẳng đem\ntheo, nên công danh tiền tài đều như mây khói, chẳng có gì đáng cả, nên người muốn muôn thuở bất hủ thì\nhãy tu hành là hơn. Ý quẻ dạy rằng việc cầu xin của bạn tuy được thông thái nhưng phải làm việc phước\nđức thì mới được hưởng bền.\nCần tu hành, thì phú mới trường. Tiền tài, danh vọng như đám mây nổi giữa trời. Chết là dứt nợ ưu phiền.\nĐánh số tốt.", "g": "Quẻ nầy thì lúc đầu rất tốt, việc có nhiều triển vọng thành tựu, nhưng về sau có sự ngăn trở của\nanh em. Hoặc trong anh em có người bị thương tổn.", "s": "29, 9, 2, 92, 20, 90."}, "210": {"c": "TRUNG TRUNG", "hexagram": "Phong Trạch Trung Phu", "line_label": "Động Hào Lục", "p": "Vạn lý hảo gian san,\nPhong sa tận nhật nhàn.\nDĩ thôn câu thượng nhĩ,\nHà tất ngộ ba lan.\nNúi non muôn dặm cảnh thanh bình,\nBụi cát rãnh nhan trời sáng tinh.\nCá đã nuốt mồi đâu dễ thoát,\nXá chi sóng nổi gió thình lình.", "b": "Quẻ này khuyên ta: Đã vào được gia cảnh, ắt không để xảy ra vấp váp thất bại. Tuy nhiên, lúc nào cũng\nphải nhớ trong thì cốt giữ thiện tâm, ngoài thì cố làm thiện sự, có thế mới được lâu bền. Lúc thất ý, nếu\nbói được quẻ này thực rất ứng nghiệm.\nÝ quẻ cho là việc cầu xin của bạn đáng ra chẳng có gì trở ngại nhưng không may lại vấp phải chuyện lôi\nthôi làm cho việc không được thuận lợi như trong quẻ dạy, là núi non thanh bình, trời sáng rạng không cát\nbụi và giống như cá nuốt lưỡi câu vậy, nhưng thình lình lại gặp sóng gió.\nNhư vậy bạn muốn thành đạt thì tôi khuyên bạn hãy nên dễ dãi phần nào phàm khi nói đến việc gì hãy đối\nxử với nhau, phải biết người biết ta mới mong thành.\nTốt, việc thành, nhưng đề phòng giờ chót. Không đến nổi thất bại, cần cố công. Cầu danh, cầu lợi đạt.\nNhưng phải cố gắng hết sức mới nên. Đánh số được. Biểu tượng: Cá.", "g": "Tình hình chuyển sang xấu. Hy vọng thành công ban dầu bị những sự thiếu tính toán chính xác\nlàm hỏng việc.", "s": "21, 1, 2, 10, 20, 12."}, "211": {"c": "HẠ HẠ", "hexagram": "Phong Hỏa Gia Nhân", "line_label": "Động Hào Nhất", "p": "Song yến hàm thư vũ,\nChỉ nhật nhất tề lai.\nTịch mịch yêm lưu khách,\nTòng tứ hạ điếu đài.\nSong yến ngậm thư múa nhảy hoài,\nTrông chờ nó đến là ngày mai.\nNào ngờ nơi vắng giữ hành khách,\nTừ đó cần câu đã hết xài.", "b": "Quẻ này có cái tượng: Xuất u cốc mà lên cây kiều mộc. Đôi én ngậm thư, đó là đem tin mừng tới. Câu thứ\n3 nhắc tới tích Nghiêm Tử Lăng. Còn câu thứ 4 nói đến chuyện Khương Tử Nha. Lặng bỏ nơi ẩn dật đi\ngiúp Hán Quang Võ mà làm đến Quốc Sư. Nhờ vứt cần câu, bỏ phiến đá trên sông Vi mà trở thành thượng\nphu Văn Võ Vương nhà Châu. Người xin được quẻ này có hy vọng gặp hội phong vân.\nVề việc cầu xin của bạn, theo ý quẻ cho hay thì khó được vừa ý như bạn mong muốn, công việc hiện đang\ntrông đợi chắc thất bại nhiều hơn thắng lợi. Vì câu thứ ba trong quẻ tả cảnh người khách đi đường hiện bị\nlạc giữ nơi vắng, và câu thứ tư nói cần câu hết xài, nghĩa là người hành khách không đi đến nơi, và không\ncần câu, thì lấy gì câu được cá vậy.\nBế tắc. Tin âm vắng bặt. Chờ đợi vận thái là hơn. Biểu tượng: Chim. Đánh số e cháy túi.", "g": "Sự việc hoặc người chờ tin, nội ngày mai là có tin tức.", "s": "11, 21, 1,\n2, 12"}, "212": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Hỏa Gia Nhân", "line_label": "Động Hào Nhị", "p": "Vọng khứ kỷ trùng san,\nCao thâm tiên khả phan.\nCử mục thiên thượng khán,\nMinh nguyệt tại nhân gian.\nDòm ngó quả là núi mấy trùng,\nCao châm cách trở khả lần thông.\nNgửng đầu nhìn lại trời xanh nọ,\nTrăng sáng nhân gian chiếu khắp vùng.", "b": "Quẻ này cho biết: Công việc coi như khó mà thực ra lại dễ, chỉ cần dốc thực lực ra mà làm tới, khỏi ngại\nkhông đạt tới thành công. Trời xanh, trăng sáng, tượng trưng cho cảnh Tiên, cảnh Phật, cho nên đối với\nngười khổ hạnh tất nhiên chẳng còn gì phải vất vả khó khăn mới tới những kết quả siêu phàm này. Người\nxin được quẻ này sẽ đem hết mình mà thực hiện để tìm lấy hiệu quả tốt đẹp cho mình.\nTheo ý quẻ cho biết việc cầu xin của bạn bắt đầu ngó thấy rất là khó khăn như cách xa mấy trùng núi núi\ncao đấy, nhưng nếu người không nản chí cứ theo đuổi, thì thành công ắt không khó chi đâu, như câu hai\ncủa quẻ có nói dù núi cao biển sâu cũng lần lần vượt qua và sự thành công to tát như trăng chiếu khắp nơi\nvậy.\nTrước khó, sau dễ. Thành đạt lớn, cứ tiến tới. Đánh số đẹp.", "g": "Việc muốn hỏi quá cao sâu không thể đoán chắc được, nhưng yên lòng đừng sợ, sẽ có ngày sáng\ntỏ thôi.", "s": "2, 12, 1, 21, 22."}, "213": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Hỏa Gia Nhân", "line_label": "Động Hào Tam", "p": "Dụng chi tắc hành,\nXa chi tắc tàng.\nNhất kỵ xuất trùng quan,\nGiai âm chỉ xích quan.\nDùng thì sẽ ắt nên công,\nNếu mà từ khước, hư không chẳng còn.\nKhi cưỡi ngựa, khỏi núi non,\nTin lành trước mắt, vận son sắc màu.", "b": "Hành tang tức là xuất xứ: \"Dụng chi tắc hành, xã chi tắc tàng\". Xuất tức là xuất thế: đi ra ngoài đời như tu\nhành ẩn dật. Xử tức là xử thế: đi vào đời như làm quan, hoạt động tranh đua với đời.\nQuẻ này chủ việc tiến thoái ra vào. Tuy bảo rằng mọi việc do tiền định, thế nhưng vẫn phải lo tính tiến lui\nra vào. Người xin được quẻ này cứ hễ xuất quan ra khỏi nhà là có giai nhân tới. Như thế có nghĩa là càng\nđi xa thì càng lợi cho mình. Người con trai chí ở 4 phương thiết tưởng chớ nên lưu luyến gia đình mà lỡ\ndịp.\nÝ quẻ nói rằng, những sự cầu mưu của bạn đều có thể làm nên, nhưng phải quyết chí dốc lòng, cố công\nmới được, đừng nên hai bụng vá lưng chừng thì mới được. Đồng thời, bước đầu chỉ có gặp khó khăn, cũng\nráng sức tìm cách vượt qua rồi sẽ gặp may mắn đấy, như quẻ thơ đã nói, khỏi núi non tin lành trước mặt\nvậy.\nViệc gần thành chớ nản chí. Vận may đến rồi còn lo gì? Biểu tượng: Ngựa. Đánh số hên.", "g": "dùng người nên dùng cái khí tiết và cái tài của người đó, rồi để cho họ tự do làm việc theo ý họ,\nnhất định sẽ sớm thành tựu công việc.", "s": "2, 1, 3,\n31, 13, 21, 12, 32."}, "214": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Hỏa Gia Nhân", "line_label": "Động Hào Tứ", "p": "Tích đức thi công hữu tử tôn,\nSát nhau tế thánh cập linh thần.\nCông danh lưỡng tự thành toàn nhật,\nHồi thủ san hà vạn vật tân.\nTích đức thi ơn con cháu lành,\nLàm bò cúng tế khắp chung quanh.\nCông danh nếu lúc được thành tựu,\nKhi thấy núi sông biển đổi tên.", "b": "Quẻ này chủ rõ rồi đây mình đắc chí, mọi người đều sửng sốt, nhìn nhau tự hỏi, không còn cái nhìn bằng\nnửa con mắt như ngày xưa nữa. Quả thực là hai hoàn cảnh phân chia rõ rệt, như trời vực cánh chia cao\nthấp. Mổ trâu tế thần dụng ý tạ ơn trời đất quỷ thần.\nNgười xin được quẻ này nên nhớ rằng hạnh phúc vinh dự sở dĩ có được là nhờ ở công trình, tích thiện, nếu\nkhông, ắt khó thành toàn dụ được. Những sự cầu mưu của bạn, phải lấy thiện làm căn bản, lúc đó mới có\nthể thành đạt nguyện cầu, đó là lời dạy của quẻ, nếu làm được như thế ắt hữu cầu tất ứng.\nThực vậy, làm ơn cho người ta, tự nhiên được người thương mến, mà việc khó khăn của mình ắt người sẽ\ngiúp ta. Vậy lo chi không giải quyết được công việc. Tu nhân tích đức, việc thành công ắt đạt. Đánh số\nthông hạnh.", "g": "làm thiện tích đức, giúp đỡ xóm giềng, tương lai được quả báo tốt.", "s": "2, 14, 41, 21, 24, 1, 4, 42."}, "215": {"c": "HẠ HẠ", "hexagram": "Phong Hỏa Gia Nhân", "line_label": "Động Hào Ngũ", "p": "Thế lộ thả bình di,\nVân trung nhất nhạn chi.\nĐào hoa kinh sâu vũ,\nThủy bạn nữ tần đề.\nPhải ra sức chớ ỷ ta,\nHãy nên ẩn nhẫn bước qua cửa sầu.\nHang con cóc lại thả câu,\nTrên cây bắt cá, xây lầu trên mây.", "b": "Câu đầu ý nói đường đời được bình an vui tươi. Câu hai ý nói anh em chết chóc chia ly. Câu ba ý nói vợ\ncon gia đình tán vong tan tác. Còn câu chót ý nói bị thủy tai hỏa hoạn sạch không. Vậy quẻ này báo cho ta\nbiết họa tới nơi, bao mộng tưởng đều không thành. Bởi thế, Người xin được quẻ này phải mau mau tu\ntỉnh, cầu mong tránh gở được phần nào.\nTheo quẻ thơ nói: Bạn hãy nên cố gắng mà làm, và đừng đạt cao vọng quá, thì mới được thư thả phần nào.\nNếu không kết quả cầu sự cầu của bạn ắt như thả câu trong hang cóc, bắt cá trên cây và xây lầu trên mây,\nrút cuộc chỉ là hư không, mà lại tốn công hao sức thôi, chẳng ích lợi gì cả.\nCao vọng quá ắt xôi hỏng bõng không. Tính toán phải tùy sức tùy tài. Đang bế tắc, chờ đợi, nên thực tế,\nđánh số dỡ. Biểu tượng: Chim.", "g": "Quẻ nầy đối với việc trai gái yêu nhau , việc định đoạt hôn nhân hay việc hùn hạp với\nngười…đều không có lợi. Như hỏi việc khác, thì cũng bị sóng gió trùng trùng .", "s": "2, 1, 5, 15, 21, 25, 52,12."}, "216": {"c": "HẠ TRUNG", "hexagram": "Phong Hỏa Gia Nhân", "line_label": "Động Hào Lục", "p": "Môn ngoại khởi can qua,\nThân cừu lưỡng bất tri.\nChu y lâm nhật nguyệt,\nThủy giáo tiếu khà khà.\nTrong nhà nay lại can qua,\nThù địch hai đàng, chẳng chịu hòa.\nHãy đợi chu ý lắm nhựt nguyệt,\nBây giờ mới thể cười ha ha.", "b": "Quẻ này chủ gia đình bất hòa, huynh đệ khích tướng, vợ chồng ngủng nghỉnh, tình trạng này sở dĩ có chỉ\ntại chê mình hèn. Nhưng một buổi sáng đẹp trời, áo gấm về làng, võng lộng nghênh ngang, công danh\nlừng lẫy, lúc đó gia đình mới mặt mày vui vẻ, đón rước linh đình. Người xin được quẻ này chớ trách chi\nnhân tình thế thái mà chỉ nên cố gắng xây dựng bản thân để có chút huy hoàng mà thôi.\nQuẻ nói trong nhà này nổi binh đao thân thù hai đàng không chịu nói hòa, đó là ý nghĩa trong việc cầu xin\ncòn gặp nhiều lôi thôi chưa được thuận ý mà phải chờ đến khi có quý nhân nương dẫn đường đi nước\nbước thì lúc đó công việc mưu tính mới trôi chảy thông suốt.\nBạn nên bền lòng chờ đợi chớ nên vội vã, thì lần lần sẽ thấy hanh thông và có thể thành đạt sở cầu. Lôi\nthôi, dang dở, e bị quan sự. Đề phòng và cẩn thận chờ đợi, vận chưa thông. Đánh số dở.", "g": "đề phòng trong nhà bất hòa, anh em hại nhau, thân nhân trở thành thù oán. Hết sức dè dặt mới\nđược .", "s": "2, 1, 6,\n61, 12, 21, 26."}, "217": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Thủy Hoán", "line_label": "Động Hào Nhất", "p": "Hữu nhất thân,\nHoạch nhất lộc.\nSự đoàn viên,\nMôn ngoại sách.\nNgười này quả thực tài,\nBắt được một con nai.\nTất cả việc toàn vẹn,\nVận may chờ cửa ngoài.", "b": "Con hươu chữ Hán gọi là Lộc: Lốc cùng âm với lộc (tài lợi bổng lộc). Đã có tài lộc thì gia đình sao chẳng\nđoàn viên vui vẻ như nơi chợ búa nhộn nhịp tưng bừng. Đây là một hào được coi như trung cát.\nNhững việc cầu xin của bạn theo quẻ thơ trên ẩn tả cho rằng vận trình được hanh thông, tất cả việc cầu\nmưu ắt được như ý định nhưng bạn nên cố gắng bỏ công, thì mới thành công mỹ mãn, vì câu thơ chót nói\nvận may chờ cửa ngoài, vận đã đến mà người phải bước ra ngoài đón lấy.\nThời vận đến, nên cố gắng sức và hãy đón lấy chớ để mất. Đánh số thông.", "g": "Việc muốn hỏi chắc thành, nhưng đề phòng hậu hoạn là :- nếu được tiền bạc thì bị người khác\nchiếm đoạt, nếu là người phối ngẫu thì có kẻ thứ ba theo bám.", "s": "17, 27, 21, 72, 12, 2, 1,\n7."}, "218": {"c": "HẠ HẠ", "hexagram": "Phong Thủy Hoán", "line_label": "Động Hào Nhị", "p": "Nhĩ vãng vô thu lợi,\nHoa khai hựu cập thu.\nNghiêm sương vật tiến chí,\nThoái bộ bất tồn lưu.\nRa đi chẳng có lợi gì,\nMùa thu hoa nở còn gì sắc hương.\nĐâu đâu sương phủ đầy đường,\nRút lui để khỏi đau thương hận buồn.", "b": "Quẻ này chủ sự ra đi nhưng bất lợi, mọi việc đều chẳng thuận lợi tí nào. Giao dịch buôn bán thì lỗ vốn, gia\nnghiệp thì điêu linh. Phải nên gấp rút về để cố thủ, ấy thế mà chưa chắc đã giữ gìn được gì. Trái lại, còn\nliều lĩnh tiến hành thì thế nào cũng gặp bất trắc. Người xin trúng quẻ này cần nhớ để làm răn.\nNhững việc cầu xin của bạn theo quẻ thơ trên ẩn tả cho rằng vận trình được hanh thông, tất cả việc cầu\nmưu ắt được như ý định nhưng bạn nên cố gắng bỏ công, thì mới thành công mỹ mãn, câu thơ chót nói\nvận may chờ cửa ngoài, nghĩa là vận đã đến người phải bước ra ngoài đón lấy.\nThời vận đến, nên cố gắng sức và hãy đón lấy chớ để mất. Đánh số thông.", "g": "không tốt .", "s": "17, 27, 21, 72, 12, 2, 1,\n7."}, "219": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Thủy Hoán", "line_label": "Động Hào Tam", "p": "Tân nguyệt vi câu,\nThanh phong tác tuyến.\nCử võng yên ba,\nCẩm lân dị kiến.\nTrăng mồng ta lấy làm câu,\nGió thanh làm chi, chẳng sầu không may.\nLưới chài sống động cũng hay,\nDù là biển động bắt ngay dễ dàng.", "b": "Ba câu trên miêu tả cảnh thâm sơn cùng cốc, yên hà phong nguyệt, nói người quân tử lui về ẩn dật, bắt\nchước ngư ông cất vó nơi khỏi sóng, ngắm trăng trong cảnh khuya, hóng gió mát buổi trưa hè. Còn câu\nsau ngụ ý không nên gặp kẻ đại nhân, mà chỉ nên tùy ngộ nhi an (tùy theo cảnh ngộ mà an vui với cái đạo\ncủa thánh hiền). Người xin trúng quẻ này chỉ nên lui về ẩn dật, gặp các bậc đại nhân rất bất lợi đó.\nQuẻ này ý chỉ rằng, phàm cầu việc gì đều phải biết tận dụng hoàn cảnh chung quanh. Cũng như về thiên\nthời phải nắm lấy, thì mới dễ dàng thành công. Như quẻ nói trên lấy trăng mồng làm câu, lấy gió làm dây\ncâu, để bắt cá trong biển vậy. Và mặt khác, quẻ cũng ám chỉ rằng cầu mưu vào đầu tháng thì thuận lợi\nhơn.\nThời vận thông cứ tiến thành. Đánh số tốt.", "g": "Tốt. Mọi việc đều đến tay như ý, bên trái bên phải đều có nguồn nước.", "s": "2, 1, 9, 91, 92, 12."}, "220": {"c": "HẠ TRUNG", "hexagram": "Phong Thủy Hoán", "line_label": "Động Hào Tứ", "p": "Tiên quan tỏa,\nTục đề phòng.\nTiểu tiết bất tri giới,\nNhân tuân thành cự ương.\nTrước tiên phải rõ điều cần,\nĐề phòng tiểu tiết mới lành, mới yên.\nNếu không biết giữ điều kiêng,\nTai ương đưa tới rất phiền ngay.", "b": "Giữ lời cũng như đề phòng, cả hai điều chỉ sợ người ta vấp ngã mang khốn, nhất trong khi không chấp\nthuận hành động khiến lụy tới đức lớn. Hai câu chót bất quá chỉ là những câu chú ước cho mạnh nghĩa hai\ný trên đó thôi. Người xin được quẻ này nên chú ý tích cực thực hiện.\nTheo ý quẻ cho hay phàm người cầu xin việc gì trước hết phải hiểu rõ trên phương diện cần thiết, nghĩa là\nnắm vững trọng tâm, công việc cũng phải suy nghĩ cho kỹ, thì mới tránh được việc không hay xảy ra.\nCũng như mới mong thâu lượm được kết quả tốt đẹp.\nVậy việc cầu xin của bạn hơi khó đấy, nên phải cẩn thận đo lường cho kỹ chớ nên sơ ý thì hỏng. Cần nắm\ntrọng tâm công việc và nghiên cứu kỹ, mới nên. Cầu mọi sự chưa thông. Nên cố gắng. Đánh số, chưa mấy\nthông.", "g": "vì cái nhỏ mất cái lớn. Không sợ mọi điều, chỉ sợ rũi ro. Đóm lửa của ngôi sao mà có thể đốt cháy\ncánh đồng.", "s": "22, 20, 2."}, "221": {"c": "HẠ THƯỢNG", "hexagram": "Phong Thủy Hoán", "line_label": "Động Hào Ngũ", "p": "Yến ngữ oanh đề,\nHoa khai mãn viên.\nỶ lan xuân thụy giác,\nVô ngữ liễm sầu nhân.\nHoàng oanh chim én ào ào,\nVườn hoang rực rỡ xuân màu sắc hương.\nDựa lan can mộng hoàn lương,\nThiết tha trong dạ buồn thương ý tình.", "b": "Quẻ này chỉ cái tượng của một hoàn cảnh bình thường, an hưởng tự nhiên, tha hồ vui thú nhàn lạc, chẳng\nthèm để ý tới thị phi, đắc thất. Nếu lại còn vun trồng cây đức, tô bồi cành nhân, thì có thể nói đó chính là\ntriệu chứng của cả một cuộc hưng thịnh. Người xin được quẻ này cần nên giữ câu \"Tri chỉ bất nhục\" (biết\nđủ mà ngừng lại thì không bị nhục).\nÝ quẻ nói rằng hiện thời chim mừng, hoa nở đã báo xuân về tới nhân gian nhưng bạn còn say mê với giấc\nngủ để ráng quên những u sầu, người xin được quẻ này đang lúc gặp thời lẽ ra phải thừa dịp này phấn khởi\ntinh thần đề mưu đó sự nghiệp nhưng lại cầu an và than thở.\nCăn cứ vào lời dạy của quẻ, bạn hãy cố tạo hoàn cảnh mến người mến cảnh, tùy thuộc vào hoàn cảnh mà\nhành động. Có câu nhân định thắng thiên, hãy suy nghĩ câu đó ắt hữu ích hơn.\nThời đến rồi, hãy lo tính đi, còn chần chờ phân vân và cầu an làm gì? Cái may không đến lần thứ hai.\nĐánh số hạp.", "g": "Thời vận đã chuyển đổi, mọi việc có thể tiến hành không còn trở ngại nữa.", "s": "21, 22, 2, 1, 12."}, "222": {"c": "TRUNG THƯỢNG", "hexagram": "Phong Thủy Hoán", "line_label": "Động Hào Lục", "p": "Lao tâm lao tâm,\nLao tâm hữu thành.\nThanh phong tá lực,\nHoan tiếu tiền đình.\nLao tâm nữa lại lao tâm,\nLao tâm vất vả cố làm mới nên.\nHãy nhờ sức gió phụ bên,\nTương lai vui vẻ mới đều sự công.", "b": "Quẻ này nói: Có lao tâm khổ trí thì công việc mới thành tựu, và quyết chắc không một việc gì là không\nxong. Nếu được sức nhiều người giúp thêm thì tự nhiên được phúc vô bờ bến. Người xin được quẻ này\nquả thực là \"Hoàng thiên bất phụ khổ tâm nhân\" cứ hễ có công là được hưởng phúc.\nBạn xin được quẻ này thì phải vất vả bận tâm thật nhiều với việc cầu mưu thì mới được nên phận. Ngoài\nra, còn phải nhờ sức của kẻ khác đỡ thì tương lai mới sáng lạng hơn.\nTheo ý quẻ này thì bạn hãy dẹp mọi sự tự ti mặc cảm để nhận sự giúp đỡ của kẻ khác và mình cũng phải\nra công cố gắng, thì ắt thành danh toại.\nTuy lao tâm, khổ trí, nhưng việc thành. Chỉ cần có sự giúp đỡ của người, thì hay. Đánh số, được nhưng ít\nlợi.", "g": "Tùy thời mà lưu ý , suy nghĩ kỹ lưỡng để bổ sung thiếu sót của công việc, tiền đồ mới xán lạn.\n(燦爛 = rực rỡ)", "s": "22, 2, 20."}, "223": {"c": "HẠ HẠ", "hexagram": "Phong Sơn Tiệm", "line_label": "Động Hào Nhất", "p": "Tiến bộ thả bồi hồi,\nXuân phong liêu nhứ phi.\nThủy tân hành khách quyện,\nChâm bạn đa nghi thai.\nSao đang bước tiến lại ngừng,\nGió xuân thổi liễu lưng chừng lay lay.\nMé sông hành khách mệt thay,\nĐêm khuya ôm mối sầu tây nản buồn.", "b": "Quẻ này chủ trong cái cát có cái hung, mệnh vận chưa thông. Đường vào ba thực khó đi, lại còn có cái ý\nđổi rời nhưng không quyết, phiêu bạt vô định. Người xin được quẻ này cần phải mười phần lưu ý mới\nđược.\nCảnh tình của bạn lẽ ra đang ở trong cảnh vui vẽ không có phiền não, nhưng vì bạn mưu tính lưng chừng.\nVì thiếu sự quả quyết cho nên cảnh tình trở nên kém đi và bạn trở nên buồn nản.\nDo đó những việc cầu mưu cần phải cố gắng và chuyên tâm quả quyết mà làm mới thâu lượm được kết\nquả tốt đẹp.\nĐáng lẽ hay, hóa dở. Vì tại ta, cần phấn đấu, thì cuộc đời mới nên hương. Đánh số không hạp.", "g": "Mọi việc cứ tuần tự mà tiến tới sẽ ổn, qua thời gian việc sẽ thành mặc dù có bị chút ít trở ngại từ\nbên ngoài tác động vào.", "s": "2,\n3, 23, 32."}, "224": {"c": "TRUNG TRUNG", "hexagram": "Phong Sơn Tiệm", "line_label": "Động Hào Nhị", "p": "Ngọc thạch dơ chung muội,\nHà kham tiểu hối đa.\nChung vô cửu,\nTiếu kha kha.\nNgọc thạch tuy rằng có ám mờ,\nĐâu cần lo nghĩ việc nhỏ đó.\nBàn đi tính lại chung vô lối,\nVui vẻ cười to chớ dại khờ.", "b": "Quẻ này có cái tượng: Hiện thường có những tiểu hối (điều hối hận ăn năn nhỏ). Bởi thế cho nên viên\nngọc nằm trong đá vẫn còn bị che lấp không sáng tỏ được. Tuy nhiên về sau vẫn giữ được không lỗi lầm\ngì. Cuối cùng vẫn có thể vui cười hể hả. Người xin được quẻ này xử sự nên phải lấy việc trầm định tinh\nthần làm quý, cũng cần phải có thái độ thung dung để bổ túc vào, chứ không nên lo lắng buồn phiền làm\nchi.\nQuẻ thơ nói rằng: Loại ngọc thạch vốn là loại vật quý, sáng, chói, nhưng có khi sắc màu của nó vẫn bị ám\nmờ, chớ nên lấy làm kỳ lạ và đừng xem trọng những điều nho nhỏ bất ngờ.\nÝ quẻ muốn nói rằng: Sự cầu xin của bạn đắt thất đều do mình định lấy không nên kêu ngạo, cũng đừng\nthối chí. Cứ tiếp tục tiến tới. Thành công ắt về ta. Vậy sự cầu xin của bạn cố gắng đi sẽ được toại lòng.\nXưa có câu hữu chí cảnh thành. Hãy nên lấy làm kim chỉ năm đó.\nChớ lo chuyện tiểu tiết, công việc đã tính, cứ thực hành đi. Thì sự ắt thành. Đánh số được.", "g": "Việc muốn hỏi do vì có sự mê muội của người nên gây ra nhiều lỗi nhỏ, nhưng không có trở ngại\nlớn.", "s": "22, 4,\n42, 24."}, "225": {"c": "TRUNG TRUNG", "hexagram": "Phong Sơn Tiệm", "line_label": "Động Hào Tam", "p": "Thuỳ dực dao thiên khứ,\ngiai nhân tị nan hành,\nnhất đồ kinh tể ý ,\nhựu thị mãn viên xuân.\nCánh nào bay đến trời xa\nĐều do lánh nạn thoát qua hiểm nghèo\nNổi sợ hãi, hết còn đeo\nGiờ đây chỉ thấy Xuân theo đầy nhà.", "b": "(Lời quẻ nói rằng: Chim Hồng Nhạn từ từ bay đến chỗ đất cao. Chồng đi chinh chiến không quay về,\nngười vợ không thể nuôi con cái. Hào này hung hiểm. Nhưng có lợi về chống giặc cướp.)\nTheo ý thơ của Khổng Minh, quẻ này có tượng biết nạn mà tránh. Hiện nay vận thời của bạn tuy chưa\nđược hanh thông, mà phải trôi nổi vô định, để ẩn tránh sự rủi ro, nhưng nếu người người biết tính toán\nkhéo léo thì sau này sẽ được vui vẻ thịnh vượng. Bạn hãy chờ một thời gian ngắn nữa và xử sự cho không\nkhéo thì việc ắt thành.", "g": "Nương tựa với nhau để trốn thoát, tránh khỏi tai họa khủng khiếp đe dọa tánh mạng. Bỏ lại đàng\nsau những tai họa đã xãy ra, cuối cùng cũng về đến nơi an toàn trong cuộc sống.", "s": ""}, "226": {"c": "THƯỢNG TRUNG", "hexagram": "Phong Sơn Tiệm", "line_label": "Động Hào Tứ", "p": "*Thi ：\ngiai tín chí ,\nkhai tiếu nhan ,\nphi đằng nhất khứ ,\nbát vân thướng thiên .\ntín mừng đến,\nnở nụ cười,\nmột phen bay mạnh,\nđẩy mây lên trời.", "b": "(Chim hồng nhạn từ từ bay vào rừng cây, đậu ở trên cành cây. Haò này không có tai họa.)\nQuẻ này chủ về cảnh tinh hiện đang khốn quẫn nhưng sắp hanh thông. Nay mai sẽ có tin mừng về những\nmưu cầu của bạn, chỉ cần tiến tới thì sẽ đạt thành sở nguyện. Bạn hãy nhắm thẳng mục tiêu mà tiến tới,\nchẳng có gì cản trở. Thời vận sắp hanh thông, công thành danh toại.", "g": "Đây là một quẻ rất tốt, toàn là những tin tức tốt đẹp vui mừng. Cơ hội tốt đến, vững bước đường\nmây, thẳng đến cửu trùng.", "s": ""}, "227": {"c": "Hạ Hạ", "hexagram": "Phong Sơn Tiệm", "line_label": "Động Hào Ngũ", "p": "*Thi ：\nthanh chiên không thủ cựu ,\nchi thượng sào sanh phong ,\nmạc vị nhất thời hỉ,\nhoàn nghi thử tượng hung .\n-Dịch:-\nchăn xanh trống như cũ,\nổ trên cây sanh gió,\nđừng bảo đến lúc vui,\nvẫn là thời vận xấu.", "b": "(Chim Hồng nhạn từ từ bay lên đỉnh núi. Người đàn bà nhiều năm không mang thai, không biết làm sao.\nHào này tốt đẹp.)\nNgười được quẻ này cần phải hết sức để tâm đề phòng, chớ có sao nhãng. Cái mền dù có xinh đẹp mà\nkhông có người dùng đến thì cũng như không, chim ở trên cành mà bị nổi gió, ý nói thời vận của bạn hiện\nvẫn đang xấu, chưa được hanh thông, nhưng đó chỉ là tạm thời. Những mưu cầu của bạn hiện nay khó mà\nđược toại nguyện. Mọi sự đều phải chờ đợi.", "g": "không tốt. Cần gia tăng đề phòng, cảnh khó khăn vẫn như cũ, lại còn bị mưa gió vùi dập thêm\nnữa.", "s": ""}, "228": {"c": "Trung Trung", "hexagram": "Phong Sơn Tiệm", "line_label": "Động Hào Lục", "p": "*Thi ：\nmạc ngôn kinh cức ác ,\nchung vi loan phượng thê ,\nmục tiền ưng hữu đãi ,\nhà dụng tảo trù trừ .\n-Dịch:-\nChớ bảo gai chông khó,\nsau cũng hợp phượng loan,\ntrước mắt tuy có nạn,\nđừng lo sớm làm gì .", "b": "Chim Hồng Nhạn từ từ bay về xa xôi. Lông vũ đẹp đẽ của nó có thể dùng làm trang sức trong các điển lế.\nHào này tốt đẹp.\nQuẻ này có tượng đang lúc khó khăn, khuyên bạn lúc này nên an phận mà chờ đợi, về sau dần đần sẽ có\ncơ duyên tới. Người có lúc được lúc mất. Vận mạng có lúc bĩ lúc thái, hiện tại chỉ cần chờ ít lâu mà thôi.\nNhững mưu cầu của bạn ắt sẽ gặp may mắn về sau và sẽ được toại ý.", "g": "Tuy có trở ngại, nhưng rồi cũng được loan phượng một nhà. Nếu hỏi việc khác, tuy thấy có nhiều\nngăn trở công việc, nhưng cuối cùng cũng được như ý nguyện mà thôi.", "s": ""}, "229": {"c": "Thượng Trung", "hexagram": "Phong Địa Quan", "line_label": "Động Hào Nhất", "p": "*Thi ：\nthượng hạ hoà ,\nưu sầu quyết ,\nthiên chướng vân ,\nnhất luân nguyệt .\n-Dịch:-\ntrên dưới hòa thuận,\nkhông xãy ưu sầu,\nngàn mây che phủ,\ntrăng vẫn tròn đầy.", "b": "(Giống như đứa bé đang xem xét. Hào này đối với tiểu nhân không xấu, nhưng đối với quân tử lại bất lợi.)\nQuẻ này chủ về hòa thuận thì không lo buồn. Mây giăng trên đầu núi, trăng chiếu sáng bầu trời, là nói dù\ncó xui rủi thì cũng có lúc lại hanh thông. Người được quẻ này nên cố gắng hòa thuận với mọi người, vận\ntrình của bạn đã đến lúc hanh thông, chẳng có gì đáng lo âu nữa. Nhuwcngx mưu cầu của bạn tuy còn gặp\nkhó khăn, song rốt cuộc sẽ thành theo ý muốn. Nên cố gắng.", "g": "gia hoà vạn sự hưng . (cửa nhà hòa thuận, muôn việc thịnh hưng)", "s": ""}, "230": {"c": "Thượng Trung", "hexagram": "Phong Địa Quan", "line_label": "Động Hào Nhị", "p": "*Thi ：\nngọc xuất côn cương thạch ,\nchâu ly cổ độ than ,\nhành tàng chung hữu vọng ,\ndụng xả bất vi nan .\nDịch:-\nTìm ngọc trong khối đá\nThuyền lìa bến cũ đi\nViệc làm có kết quả\nNghĩ kỹ chẳng lo gì .", "b": "(Nhìn trộm khe cửa. Hào này có lợi với nữ nhân.)\nQuẻ này có tượng nếu thấy tiến được thì hãy tiến, nếu cần ngừng thì nên ngừng. Người được quẻ này phải\nthuận theo tự nhiên, chớ nên cưỡng cầu. Những mưu cầu của bạn sẽ được toại nguyện, nếu bạn nếu biết\nnắm lấy vận may. Quẻ này phái nữ có lợi hơn phái nam.", "g": "Việc gì hoặc người nào mà nếu suy nghĩ tường tận như nước chảy hết , đá hiện ra, mới tránh khỏi\nnhững khó khăn về sau.", "s": ""}, "231": {"c": "Hạ Trung", "hexagram": "Phong Địa Quan", "line_label": "Động Hào Tam", "p": "*Thi ：\nmục hạ ý nan thư ,\nhữu khách lai từ từ ,\nkim xa tuy lịch hiểm ,\nlận tất hữu chung dữ .\n-Dịch:-\ndưới mắt ý không thoải mái,\ncó khách đến từ từ,\nxe vàng tuy trải qua nhiều nguy hiểm,\ncó tiếc giữ rồi thì cũng hết mà thôi.", "b": "(Xem xét hành vi của chính mình để quyết định lẽ tới lui.)\nQuẻ này có tượng hiện tại bạn đang có nhiều điều phải lo nghĩ, chưa thư thả lắm, nhưng sẽ có người đến\ngiúp đỡ, khi đó việc mới giải quyết được. Những mưu cầu phải chờ đợi một thời gian, tuy gặp nguy nan\nnhưng cũng vượt qua. Cầu tài cầu danh đều nên chờ đợi.", "g": "dưới gác mang tâm sự rối rắm chẳng tháo mở được, chờ hay thăm khách đều không gặp, ngày sau\nlưu lại mối hận trong lòng.", "s": ""}, "232": {"c": "Trung Trung", "hexagram": "Phong Địa Quan", "line_label": "Động Hào Tứ", "p": "*Thi ：\nkhả dĩ kí ,\nkhả dĩ thác,\nsự trì trì,\nvô suyễn thác .\n-Dịch:-\ncó thể gởi,\ncó thể giao,\nviệc chậm rãi,\nkhông lầm lẫn.", "b": "(Xem xét sự sáng sủa của quốc gia để kính phục vua.)\nQuẻ này chủ về được quý nhân giúp, có thể mưu tính việc làm ăn. Tuy nhất thời chưa có gì tốt đẹp, nhưng\ncũng được an lành. Người xin quẻ này đặc biệt chú ý tới việc kết bạn, đem hậu tình ra mà giao du là tôt\nnhất. Những mưu cầu của bạn cần được người giúp sức, dù chậm nhưng công việc chắc chắn thành công.", "g": "Việc muốn hỏi có thể ủy thác cho người khác làm giúp, nhưng họ tiến hành quá chậm chạp trì\nhoãn, tốt nhất là đừng nhờ họ.", "s": ""}, "233": {"c": "Hạ Hạ", "hexagram": "Phong Địa Quan", "line_label": "Động Hào Ngũ", "p": "*Thi ：\nkhủng cụ ưu tiên,\ngiai tại mục tiền,\nnhược phùng minh giám ,\nchỉ phá không truyền.\n-Dịch:-\nE rằng phải lo lắng,\nsầu khổ buồn bã xãy ra trước mắt mà thôi.\nNếu được người chỉ bảo cho thì có thể vượt qua nguy hiểm.", "b": "Xem xét hành vi của chính mình, quân tử sẽ không có tai họa.\nQuẻ này chủ về hiện đang ở trong tình cảnh lo lắng sợ hãi, tai vạ tuy tới gần, giống như đã có ngay trước\nmặt, nhưng may nhờ có những người tốt giúp đỡ khiến gặp dữ mà hóa lành. Mọi chân tướng sự việc đã\nhiện rõ thì không còn phải lo ngại gì nữa. Hiện thời vận của bạn vẫn còn bế tắc chưa được hanh thông, cho\nnên mọi sự mưu cầu cần phải cẩn thận hành sự, thì mới tránh được tai ương. Tốt nhất là nên tạm ngưng,\nchờ qua một thời gian rồi mới tính.", "g": "Việc muốn hỏi đang hoạn nạn lo lắng rất nhiều, nếu được người chỉ cho chỗ sai lầm, thì mới có\nthể đổi nguy ra an được.", "s": ""}, "234": {"c": "Hạ Trung", "hexagram": "Phong Địa Quan", "line_label": "Động Hào Lục", "p": "*Thi ：nguyệt yểm vân gian ,\nhôn mê đạo lộ ,\nvân tán nguyệt minh ,\ntiệm nghi tiến bộ .\n-Dịch:-\ntrăng bị mây che,\ntối tăm đường sá,\nmây tan trăng hiện,\nlần lần tiến bộ.", "b": "(Xem xét hành vi của người khác, quân tử sẽ không có tai họa.)\nQue này có tượng hiện đang bị khốn quẫn, trở ngại. Do đó cần đợi hoàn cảnh dần đân trở lại sáng sủa, lúc\nđó thấy tiến được hãy bước tới. Người được quẻ này nên im hơi lặng tiếng đợi thời cơ, chớ nên lỗ mãng\ntiến vội mà hỏng việc. Làm gì nên chờ ngày rằm, việc có thể thành công.", "g": "Việc muốn hỏi tạm thời gặp khó khăn bế tắc, không tìm được lối ra . Phải phá bỏ các chướng ngại\nvật rồi mới làm lại được tốt.", "s": ""}, "235": {"c": "Thượng Thượng", "hexagram": "Phong Lôi Ích", "line_label": "Động Hào Nhất", "p": "*Thi ：\nđạo lộ cuồng chiêu hô,\nphong ba nhất điểm vô,\nthời quai tâm tự loạn,\ntoàn trượng quí nhân phù.\n-Dịch:-\nTrên đường sợ la hoảng\nCó sóng gió chi đâu\nLúc rối tâm tự loạn\nNhờ quí nhân hết rầu.", "b": "Có lợi trong việc xây dựng Kiến trúc. Hào này rất có lợi không có tai họa.\nQuẻ này có tượng tâm tình hỗn loạn không phải do hoàn cảnh mà do mình. Toàn là nhờ quý nhân phò trợ,\nhiện nay cảnh tình của bạn là trên con đường bằng phẳng, không có một chút sóng gió, vậy thì còn gì mà\nbuồn rầu. Những mưu cầu của bạn chắc chắn thành tựu, mọi việc hanh thông.", "g": "tất cả các điều kiện đều có đủ rồi, không có sóng gió nguy hiểm gì cả. Vì đang lo lắng nhiều thứ\nquá nên trong tâm không an định mà sanh sợ hãi. Nếu được quí nhân chỉ điểm cho thì sẽ hết sợ.", "s": ""}, "236": {"c": "Trung Thượng", "hexagram": "Phong Lôi Ích", "line_label": "Động Hào Nhị", "p": "*Thi ：\nlâm uyên phóng câu ,\nthanh tuyệt điểm ai ,\ncự ngao tuỳ đắc ,\nbất dụng nghi sai .\n-Dịch:-\nVực sâu buông câu,\nsạch không chút bụi,\nngao lớn bắt được,\nchẳng phải hồ nghi.", "b": "Có người đem đến con rùa rất đắt tiền. Đây là điều đang cần. Hào này cát tường về lâu dài. Vua cử hành lễ\ntế trời, tốt đẹp.\nQuẻ này có tượng làm là được, nhanh chóng mà còn dễ dàng, mọi việc đều thuận lợi. Hiện thời vận của\nbạn đã đến lúc len hương. Vận trình ngàn dặm cũng giống như thả câu nơi vực sâu, nước trong thấy đáy\nvà bắt cá lớn dễ dàng, còn gì để lo lắng?", "g": "Vì muốn giàu nên phải đi vào đường hiểm trở, cứ siêng năng mà làm, nhẫn nại mà đợi kết quả tốt\nđến, chứ sao lại lúc nắm lúc thả thì biết đến khi nào mới đến nơi.", "s": ""}, "237": {"c": "Hạ Trung", "hexagram": "Phong Lôi Ích", "line_label": "Động Hào Tam", "p": "*Thi ：\nvô trung ưng hữu trực ,\ntâm sự hoàn thành thích ,\nvân tán nguyệt trùng viên ,\nthiên lí phong phàm cấp .\n-Dịch:-\nkhông giữa nên có thẳng,\ntâm sự lại thành lo,\nmây tan trăng lại hiện,\nmuôn dậm buồm thuận mau.", "b": "(Liên quan đến việc mở rộng công trình kiến trúc, không có tai họa, đó là điềm ứng nghiệm. Rồi sau đó,\ntrên đường đi tay cầm ngọc khuê đến báo cáo với Vương công.)\nQuẻ này có tượng sự đời hễ khuyết rồi lại đầy, tan rồi lại hợp. Người được quẻ này không có gì phải lo.\nMọi việc đều hanh thông. Cầu tài, cầu danh đều tốt.", "g": "trung bình, việc muốn hỏi nên lấy câu:- “Mây tan trăng hiện sáng ngời lo chi” để noi theo thì sẽ\nhết lo lắng sợ sệt.", "s": ""}, "238": {"c": "Trung Thượng", "hexagram": "Phong Lôi Ích", "line_label": "Động Hào Tứ", "p": "*Thi ：\ntạo hoá sanh lai tín tự nhiên ,\nsoái chinh thiên lý phước miên miên ,\ncông danh đắc tựu thần minh trợ ,\nxà thố tương phùng định biến thiên .\n-Dịch:-\nTạo hóa sanh ra,\ntự nhiên có niềm tin,\nvị tướng đi đánh giặc ngàn dậm được hưởng phước lâu dài,\ncông danh được thần minh trợ giúp, nếu gặp “rắn” hay”thỏ” sẽ biến chuyển tốt.", "b": "Giữa đường báo cáo với Vương công, Vương công nghe theo. CÓ lợi cho việc dời nhà dời nước.\nQuẻ này có chủ về thần linh giúp mà nên công danh. Sự thay đổi sẽ xảy ra vào những tháng năm Tỵ hoặc\nMão. Những mưu cầu của bạn ắt sẽ thành công như ý muốn.", "g": "Rất tốt. Người được quẻ nầy vốn là người có phước phần lớn, được thần minh phù trì. Công việc\nnếu gặp người tuổi Tỵ hoặc tuổi Mão (hay năm Tỵ năm Mão) sẽ trở thành tốt.", "s": ""}, "239": {"c": "Hạ Trung", "hexagram": "Phong Lôi Ích", "line_label": "Động Hào Ngũ", "p": "*Thi：\nđại trượng thần uy ,\nquần ma tiêu diệt ,\ndiệt liễu hựu tu uy ,\nthần uy diệc cực lực ,\nlao lao kí thủ ,\nmiễn chí cửu hậu thất trật .\n-Dịch:-\nNhờ đến sức thần\nTiêu diệt bầy ma\nDiệt rồi lại sợ uy\nUy thần cũng có sức\nTrói buộc lại mình\nPhải lo tính trước\nMới khỏi lụy thân.", "b": "Có điềm ứng, chỉ cần có lòng nhân ái, không cần bói hỏi, hết sức tốt đẹp. Có điềm ứng khác, nhân ái là\nđức hạnh của ta.\nQuẻ này có tượng hoàn toàn nhờ cậy vào oai thần mới có thể tiêu diệt được quần ma. Người được quẻ này\nphải tu tâm tích đức, và hết sức thận trọng mới được. Những mưu cầu của bạn phải đắn đo suy nghĩ cho\nkỹ, phải ăn ở xử xự cho hợp lý hợp tình, thì chẳng có gì đáng lo. Mưu cầu có vài trắc trở nhưng vẫn thành.", "g": "Nhờ vào sức bên ngoài trợ giúp để đạt mục đích sau cùng, nhưng phải có cách khống chế ngoại\nlực nầy. Nếu không, bị ngoại lực chi phối trói buộc mình thì chẳng khác nào mang món nợ suốt đời.", "s": ""}, "240": {"c": "Trung Trung", "hexagram": "Phong Lôi Ích", "line_label": "Động Hào Lục", "p": "*Thi ：\nđạo tất kiên tâm ,\nkiên tâm tất đạo thành ,\nkiến công huân ,\ntảo hồi trình ,\ntạo mao am ,\ntu chân thân ,\nnhất nhật phi thăng ,\ntiên ban liệt danh .\n-Dịch:-\nĐạo phải do kiên tâm\nKiên tâm thì đạo thành\nLập công lớn xong rồi\nMau mau sớm trở về\nCất am tranh, tu chân thân,\nngày kia phi thăng, ghi tên sổ Tiên.", "b": "Chẳng những không được lợi ích, có khi còn bị người công kích. Giữ chí không bền thì hung hiểm.\nQuẻ nói phàm mưu cầu việc gì tất phải có đủ căn cơ, bền tâm vững chí thì mới thành việc lớn, lập được\nđại công danh. Cầu danh, cầu lợi đều tùy vào tâm chí và hành động của bạn.", "g": "Cố gắng làm một người lập được sự nghiệp công danh. Nhưng sau đó không nên đam luyến vào\nhoạn lộ, tham lam vướng mắc vào lợi lộc mà khổ thân. Cần giác ngộ tu hành để được hưởng sự tiêu dao\nkhoái lạc.", "s": ""}, "241": {"c": "HẠ TRUNG", "hexagram": "Bát Thuần Khảm", "line_label": "Động Hào Nhất", "p": "Nhất niệm đạo thượng đường,\nNhất niệm nhập địa ngục.\nĐịa ngục thượng đường,\nTiện phân vinh nhục,\nChí lập niệm đầu yếu chân,\nBất khả túy nhân mục lục.\nMột bên lên chỗ thiên đàng phân minh.\nChọn đường lập chí phải tính,\nChớ nên theo kẻ lình bình thì nguy.", "b": "Quẻ này dạy ta nhất thiết tự mình phải làm chủ lấy mình, chớ nên nghe người dèm pha, để đến nổi vinh\nnhục không phân biệt được, rồi cho là bên nào cũng được cả. Một ý nghĩ đã sai thì thân ta rớt xuống hố\nsâu nhơ nhuốc. Bởi thế Người xin được quẻ này nên phải lập lấy phương châm cho đời mình để tránh lỗi\nlầm.\nÝ quẻ nói hai đàng địa ngục rất rõ ràng, bạn khi chọn lựa phải lý trí và khôn khéo chớ nên tùy ý theo\nngười làm xấu thì nguy lắm nghĩa là nói sự phải trái rất rõ ràng nên phải làm những điều chính đáng, mà\nđừng theo tà vậy, thì việc cầu mưu của người mới mong có kết quả tốt đẹp và ngược lại.\nĐạo đức làm đầu, chớ theo đường tà vậy thì nguy lắm. Cầu danh lợi tùy tâm và hành động của ta, đánh số\ntốt chút ít.", "g": "Được vinh dự hay nhục nhã là do cái gốc “ một niệm” thiện ác mà ra cả. Nếu cứ bắt chước theo\nngười, ai sao tôi vậy, thì một đời tầm thường trôi qua, há chẳng phải là điều đáng tiếc lắm sao?", "s": "2, 4, 1, 14, 41, 21, 42, 24."}, "242": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Khảm", "line_label": "Động Hào Nhị", "p": "Dương đặt quần, Nhật đối dân,\nPhùng ngưu khẩu, tiện giảo nhân.\nQuân thần hữu tả kinh, nhất cá nhân, nhất cá thần,\nTu trượng chân thần, chưởng cứu thương sinh.\nĐàn dê trâu cố cắn người,\nQuân thần hoảng hốt tơi bời không yên.\nPhải cầu sức mạnh thần tiên,\nChúng sanh được cứu, thương thiên hữu phù.", "b": "Quẻ này chủ lục súc nhiều tai nạn, khiến người chăn dắt cũng phải kinh sợ. Nhà nông bói phải quẻ này tai\nhại không nhỏ. Tuy nhiên dịch lệ nhất thời qua đi thì nhà nhà mới được yên vui như thường.\nCông việc cầu mưu của bạn còn gặp lận đận, gian nan, và trong thời gian gần đây khó mà thành đạt, hãy\nnên xem xét cho kỹ, phải nương nhờ sức người khác phụ giúp mới thì nên công, vì công việc của bạn có\nlắm tiểu nhân phá hoại, như lời quẻ nói, con Dêâ, Trâu, ý nói tiểu nhân phá hoại vậy. Cầu mưu của bạn\ncần phải lưu ý cẩn thận và nương vào kẻ có sức mới được.\nĐang bị tiểu nhân phá hoại, khó mong, cần có tay trợ hữu, hay quý nhân giúp. Cầu tài danh còn xa, vì tiểu\nnhân phá. Đánh số dở, biểu tượng, Trâu, Dê.", "g": "Những câu thơ trên quá gần với huyền học mơ hồ, không thích hợp với ngày nay. Tốt hơn là xin\nlại quẻ khác.", "s": "2, 4, 42, 24."}, "243": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Khảm", "line_label": "Động Hào Tam", "p": "Nhược thị hữu duyên nhân,\nNhất chỉ tiện hồi thủ.\nChấp mê bất ngộ giả,\nLầu dẫn dã bất tâu.\nNếu là người có nợ duyên,\nChỉ cần một tiếng tức liền trở về.\nSay mê mãi chẳng ê hề,\nDù kêu cách mấy nào bề chịu đi.", "b": "Quẻ này nói sự mê lầm của người ta thực chỉ là tại người có duyên hay vô duyên mà ra. Một lỡ lầm thành\nngàn đời hận. Quay đầu về ấy kiếp trăm năm. Bởi thế cần phải giác ngộ sớm. Nếu trễ thì không kịp nữa\nđâu. Người xin trúng quẻ này phải nên cảnh tỉnh ngay.\nTheo quẻ cho biết: Những điều cầu xin của bạn, cần phải dùng lý trí mà xét nét tiến hành. Tuy nhiên cuộc\nđời lên hay không cũng có phần thuộc về số phận. Như bài thơ đã nói: “Người có duyên kêu một tiếng tức\nliền trở về” cho nên phàm làm việc muốn được thành tựu thì phải có lý trí vậy.\nDở, bất minh, bất thông. Chớ say mê một thứ gì, cần dùng lý trí để xét nét công việc. Cầu tài danh chưa\nthấy lợi, chỉ còn cách ẩn nhẫn chờ thời, mới mong. Đánh số chẳng lợi.", "g": "Việc muốn hỏi đã đi vào đường rẻ, xin hãy sớm quay đầu. Người xin được quẻ nầy là người\nkhông có duyên lành hoặc cá tính không tin vào chuyện hư ảo.", "s": "3, 4, 2, 42, 24, 34, 43, 32."}, "244": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Khảm", "line_label": "Động Hào Tứ", "p": "Nguyệt luân đông thăng,\nThanh quang khả ấp.\nVạn lý vô vân,\nHải thiên nhất bích.\nTrời trăng đã mọc hướng đông,\nSáng trời soi chiếu trên không vùng trời.\nMuôn ngàn dặm, sáng cuộc đời,\nTrời cao đất rộng vui tươi càng lành.", "b": "Quẻ này có cái tượng: Thanh vân đắc lộ, có nhiều kỳ ngộ, trăm việc đều như ý, không chuyện gì làm là\nkhông thành, không lợi. Trời giúp người lành, lẻ đương nhiên như thế. Đây là quẻ đại cát mà Người xin\nđược thiết tưởng nên lấy đó làm mừng.\nTheo quẻ thơ nói trên vận thời của bạn đã đến lúc phú khứ thái lai. Vậy mọi sự dự tính khuếch trương gì\ntrước đây hãy nắm lấy cơ này mà làm đi, tất cả sẽ tốt đẹp đang chờ đó.\nVận thông, thời đến. Sự sự hanh thông, xuôi chèo mát mái, còn gì nữa mà lo. Cứ tiến hành. Cầu danh lợi\n10 phần đắc quả. Đánh số tốt.", "g": "Có vận tốt đang đến, có thể tha hồ thu hoạch tốt lành, công việc không có gì trở ngại, từ nay về\nsau hoàn cảnh rất thuận lợi.", "s": "44, 24, 4, 2, 40."}, "245": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Khảm", "line_label": "Động Hào Ngũ", "p": "Nam nhi nhược đắc phong hầu an,\nBất phụ nhân gian tấu nhất tao.\nCông thành thân thoái,\nYên hà tiếu ngạo,\nThoát khước tử lai duy.\nPhượng thị nam nhi đạo.\nNam nhi nếu được ngày ban phong,\nĐã báo lòng thành với khổ công.\nHãy rút lui trở về quy ẩn,\nÁo bào từ khước chí nam nhi.", "b": "Quẻ này chủ tiến trình xa rộng. Cần nên xuất tận khả để hành động. Nhưng sớm ra lại nên sớm về. Về để u\ndu nơi lâm tuyên, hưởng hết cái phúc thanh nhàn của cõi nhân gian. Người xin được quẻ này có cái tượng:\nkẻ hiệu sinh đáng sợ (hậu sinh khả úy). Tuy nhiên, lúc đắc thời chớ cậy thông minh tài ba, mà không theo\nđúng phương châm tiến nhanh mà lui gấp.\nViệc cầu xin của bạn theo ý quẻ cho hay sẽ được tốt lành chẳng có gì đáng lo ngại. Nhưng công việc êm\nthắm rồi bạn phải nên giữ gìn và chớ lo yêu cầu quá cao. Vì quẻ có nói rõ: nếu ngày được ban phong rồi,\ntức là đừng ham mê tục lụy nữa, đó là khuyên người phàm mưu việc gì chỉ cần đến mưu vừa phải thôi\nvậy.\nCông thành, thâm thối là hay. Chớ đam mê chuyện vàng son, hoa mộng, mà hóa dở. Công danh tài lợi có.\nĐánh số hạp phần nào.", "g": "Sau khi lập được đại công, hoặc là được phong hầu, hoặc là thoái ẩn núi rừng. Người nào chọn\ncái sau mới thật là đúng con đường của bâc đại trượng phu.", "s": "4, 2, 5, 24, 45, 42."}, "246": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Khảm", "line_label": "Động Hào Lục", "p": "Tâm mục hồ ly,\nMê hoặc thế nhân.\nThế nhân bất sát,\nDiên cửu khuynh thân.\nChồn này cáo nọ xấu xa,\nRủ nhau mê hoặc nhiễm tà thế nhân.\nNếu ai say đắm mất thần,\nLâu ngày thất bại nguy thân thiệt mình.", "b": "Quẻ này báo động: Có lũ gian tà mê hoặc. Có kẻ dùng lời ngon ý ngọt để dụ dỗ, sắc đẹp duyên tình để\nquyến rũ, nịnh hót để thủ lợi, khiến cho mình phải chịu nhiều điều tai hại thế mà vẫn không giác ngộ.\nNgười xin trúng quẻ này nên phải cẩn thận đề phòng trước. Chớ gần tiểu nhân chớ gần bọn yêu phụ, đuổi\nhết lũ gian tà, chớ nghe lời dèm pha nịnh hót. Có thế thì mới tránh được cái hại tán nhân bại sản.\nTheo ý quẻ cho hay người cầu xin được quẻ này hiện vẫn chưa được hanh thông, còn trong cảnh đen tối,\nchớ nên tính toán việc gì trong lúc này. Nếu người cố mà cầu mưu thì chẳng thu lợi được kết quả nào,\nngược lại còn có thể bị những điều không hay đưa đến.\nBởi theo ý quẻ đã dạy trên đây, bạn hãy ngừng lại, để chờ lúc vận thời hanh thông rồi sẽ tốt hơn. Dừng lại,\nchớ tính toán. Dở lắm, bị nhiều tiểu nhân đang múa mép, khua môi rù quyến. Nếu tiến hành ắt thất bại.\nĐánh số dở. Biểu tượng: Chồn, Cáo.", "g": "Trên đời có rất nhiều sự mê hoặc làm hại bản thân, người trí nên tránh xa nó, xem nó là “Chồn\nquỉ”.", "s": "6, 4, 2, 24, 42, 62, 46."}, "247": {"c": "HẠ TRUNG", "hexagram": "Thủy Phong Tĩnh", "line_label": "Động Hào Nhất", "p": "*Thi：\nMộ địa cuồng phong khởi ,\nđại thụ tận hân dương ,\nchi diệp vị điêu linh ,\nbồi thực chung vô dạng .\n-Dịch:-\nĐất rộng khởi cuồng phong,\ncây lớn chịu lảnh đủ,\ncành lá chưa bị rụng ,\nchẳng cần phải vun bón.", "b": "Nước giếng toàn là bùn, không thể dùng để ăn uống, đến cầm thú cũng không đến uống nước ở cái giếng\ncũ đó.\nQuẻ này chủ về nghịch cảnh ập tới, ngoài cả dự liệu. Nhưng may mà nhờ có căn cơ vững chắc nên rốt\ncuộc cũng không sao. Những mưu cầu của bạn giai đoạn đầu ắt sẽ gặp nhiều khó khăn, nhưng cố gắng tìm\ncách vượt qua thì sẽ thành đạt ước nguyện.", "g": "hữu kinh vô hiểm . (bị nạn mà không sao cả)", "s": ""}, "248": {"c": "TRUNG TRUNG", "hexagram": "Thủy Phong Tĩnh", "line_label": "Động Hào Nhị", "p": "*Thi ：\như nhật vượng tướng ,\npháp yếu thôi tầm ,\ntứ vi tuyền nhiễu ,\nđối địch xung doanh .\n-Dịch:-\nmặt trời rỗng mà tướng vượng,\nchỗ trọng yếu của pháp phải gắng tìm,\nbốn bề bị vây nhiễu,\nphải xung phá kẻ địch mà ra.", "b": "Nước đọng dưới đáy giếng chỉ có loài cá nhỏ mới sống được. Dùng tên bắn loại cá nhỏ đó may ra còn\nđược, dùng bình đến múc nước sẽ bị vỡ.\nQuẻ này có tượng đang ở trong cảnh nguy. Người được quẻ này nên khéo léo mà giữ mình. Chớ có\nkhoanh tay ngồi nhìn mà khốn đốn. Phàm mưu cầu việc gì, trước mắt chớ tưởng là tốt lành, cần phải cố\ngắng và giữ gìn cật lực mới được.", "g": "Đừng coi thường cái tướng giả bên ngoài, phải thâm nhập và tìm hiểu kỹ cái chân tướng của nó.", "s": ""}, "249": {"c": "TRUNG HẠ", "hexagram": "Thủy Phong Tỉnh", "line_label": "Động Hào Tam", "p": "Vinh khô tràng định mạc ta thương,\nTân khổ tha bàng,\nAn hưởng gia thương.\nVị tha nhân tác giá y thường,\nKim nhật quân thường,\nTha nhân cải hoán biệt nhân thường.\nVinh nhục định rồi chớ hận than,\nQuê người sao sánh kịp quê mình.\nLàm may áo cưới người ta hưởng,\nSướng khổ luân hồi chi phải màng.", "b": "Quẻ này có tượng: Làm người khách lạ chốn tha hương cuộc đời có vất vả gian nan mới có thể ngồi\nhưởng cảnh yên vui vườn nương. Người xin được quẻ này có thể tự tìm lấy chân lý cho mình mà ăn ở thì\nthế nào cũng vui sướng thịnh vượng.\nÝ thơ cho biết tất cả sự vinh hoa nhục sướng khổ đều đã có số định sẳn chớ nên than thở làm chi, ở quê\nngười sao bằng quê mình sung sướng. May áo cưới mà người hưởng, nhưng thiên lý luân hồi, có ngày\nngười làm mình hưởng. Nghĩa là việc đời không nê cưỡng cầu hãy cho nó tự do phát triển, bởi việc đời\nnhư Phật gia nói ”sắc sắc không không” vậy.\nThế thì việc cầu xin của bạn cần phải bền lòng và giữ tâm lương thiện, cố gắng ắt có ngày sẽ được toại\nnguyện. Than mà chi tất cả đều có số mệnh. Nên ở ăn hiền đức, thì có ngày trời cho của mà hưởng. Cầu\ndanh, lợi vừa phải. Đánh số được.", "g": "nên hư do trời định, chẳng nên vì không như ý mà sầu buồn, phải biết vui với mình có. Người\nđược quẻ nầy e rằng ngày sau vận chẳng tốt.", "s": "9, 4, 2, 24, 42, 49, 94."}, "250": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thủy Phong Tỉnh", "line_label": "Động Hào Tứ", "p": "Nữ nhi dại,\nHỉ lâm môn,\nGiá lương nhân.\nThiêm tử tôn,\nĐồng bái thu,\nCảm hoàng ân.\nNay con lớn, hỷ đến nhà,\nTìm vui duyên nợ để mà kết hôn.\nSanh con đẻ cái nối dòng,\nTrời ban phước đức ta cùng tạ ơn.", "b": "Quẻ này chủ trồng dưa được dưa, trồng đậu được đậu, gái lớn thì gả chồng, ai cũng biết có làm thì phải có\năn, không ai lại đem phần đến cho. Nếu tích cực làm việc để trở thành người tốt, thì lo gì mà không có kết\nquả tốt đẹp. Người xin được quẻ này nên cố gắng nhiều hơn thì phải đẹp.\nTheo ý quẻ nói, hiện nay thời vận của bạn đã đến lúc lên hương rồi như con đã trưởng thành vậy. Cho nên,\nnhững việc cầu mưu của bạn, hãy nên bước tối đi, sẽ thành đạt ý muốn. Như quẻ nói, đi tìm được duyên\nnợ cho chúng rồi, thì ắt sinh con đẻ cháu cho mình vậy.\nThời vận hanh thông hạnh phúc đầy đủ. Chẳng lo gì nữa. Đánh số tốt.", "g": "Tốt lành đối với việc hôn nhân của con gái. Nam nữ đã có giao ước, sẽ thành gia thất thêm người\nthêm của , đáng gọi là chúc mừng vậy.", "s": "25, 5, 2, 50, 20, 52."}, "251": {"c": "HẠ HẠ", "hexagram": "Thủy Phong Tỉnh", "line_label": "Động Hào Ngũ", "p": "Mộc sinh hỏa,\nKhẩu bất tâm.\nPhùngđiên tác chứng,\nHàn nhiệt tương xâm.\nCây sanh lửa, việc đã thành,\nSao làm miệng lưỡi cứng câm tiếng truyền.\nCàng thêm bệnh tật khùng điên,\nNhiệt hàn xâm thể, triền miên hại mình.", "b": "Quẻ này chủ trong lo ngoài sợ, đồng thời kéo thới ví như: khi ốm can mộc (can thuộc gỗ) đã vương thì\nđiên khùng ắt gây nên tâm hỏa lại bốc cháy, thì nóng lạnh tất sinh ra. Lúc đó thì dù có hàng trăm hàng\nngàn lương y thì cũng chỉ khoanh tay ngồi nhìn mà thôi. Đâu là một quẻ hung (độc dữ) rất đáng lo ngại.\nTheo ý quẻ cho biết, vận trình của bạn rất xấu, khó mà làm nên việc gì trong thời gian này. Cũng như cầu\nxin một việc gì khác. Cũng khó được như ý, vậy cần phải ngừng công việc tính toán lại và phải đề phòng\nnhững đều không may đưa đến, bởi quẻ đã mách rõ ở hai câu thơ trước, một cách bất minh rồi.\nBế tắc chẳng làm gì được. Thận trọng và ngừng ngay việc đang tính toán. Đánh số dở.", "g": "Rất xấu. Nên hết sức thận trọng về lời nói, đề phòng bất trắc để khỏi bị hậu quả xấu về sau. Nếu\nhỏi về bệnh, phải chú ý chữa chạy đúng mức mới được.", "s": "2, 5, 1, 51,\n52, 25, 21, 12."}, "252": {"c": "HẠ HẠ", "hexagram": "Thủy Phong Tỉnh", "line_label": "Động Hào Lục", "p": "*Thi：\nhưu hưu hưu ,\nquá liễu tam niên hựu lục chu ,\nbất mãnh tỉnh ,\nhoạ đáo đầu .\n-Dịch:-\nthôi thôi thôi,\nkhoảng chừng ba năm rưỡi trở lại đây,\ncó hành động xấu, không chịu tỉnh ngộ sửa đổi,\ntai họa lớn đến, hối hận chẳng kịp.", "b": "Miệng giếng đã đặt bánh quay, không cần đậy, có điềm ứng rất tốt đẹp.\nQuẻ này chủ về có sự lầm lạc đã lâu. Người được quẻ này cần phải có sự tỉnh ngộ thì mới có hy vọng mưu\ntính làm ăn thành công. Nếu không nhất định sẽ gặp nhiều bất trắc. Vận trình của bạn hiện còn bế tắc chưa\nđược hạnh thông, nên an phận chờ thời sẽ rất tốt đẹp.", "g": "Ba năm rưỡi gần đây, có những hành động khác thường, cần phải ngừng lại. Tăng cường thêm sự\nphàn tỉnh về việc quá khứ mà cải sửa lại, mới tránh được hậu quả nặng nề.", "s": ""}, "253": {"c": "HẠ HẠ", "hexagram": "Thủy Thiên Nhu", "line_label": "Động Hào Nhất", "p": "Nạm lan khởi hỏa,\nNghiệt sức tao ương.\nDự phòng đắc lực,\nDiệt hỏa thành khang.\nBây giờ lửa cháy lan can,\nTrong nhà súc vật nguy nan cùng mình.\nHãy mau cứu vớt chớ khinh,\nDẹp tiêu mối họa, tâm tình sẽ yên.", "b": "Quẻ này tượng: Lửa bốc cháy trên lan can, khiến lũ nghiệt súc chết sạch. Chúng chết tất nhiên chẳng hại\ngì cho mình. Tuy nhiên, nếu không đề phòng cẩn thận lửa ắt bén cháy khắp nhà, nguy hại đến toàn thể cơ\nnghiệp và an ninh của mình. Bởi thế, Người xin được quẻ này nên đề phòng cẩn thận, chớ để cho tai vạ tới\nchân mới nhảy, thì nguy đó.\nThời vận còn xấu, làm ăn chưa nên, nên chịu đựng một thời gian nữa, để nghiên cứu công việc trước đã\nrồi hãy bắt tay vào việc, thì mới nên. Đó là ý quẻ muốn mách cho bạn vậy.\nBất minh, bất thông. Nên lo việc cấp kỳ trước đã, hơn là đi tính chuyện, bao đồng xa xôi. Sau đó, hãy tính\ntới việc khác. Cầu tài danh còn lâu. Đánh số dở.", "g": "Nếu mọi việc đều có sự phòng bị chu đáo thì đở bị thiệt hại về sau.", "s": "25, 3, 23, 35, 53, 52, 2, 5."}, "254": {"c": "TRUNG THƯỢNG", "hexagram": "Thủy Thiên Nhu", "line_label": "Động Hào Nhị", "p": "Dĩ ngoại tâm đầu nguyện,\nThủy tri chí, khí thân.\nTam sơn tu bả ác,\nTần tần định thái bình.\nMột khi đã toại nguyện cầu,\nMới hay thành đạt bấy lâu chí mình.\nBa non nắm giữ cho mình,\nLuôn luôn ắt được thái bình cảnh vui.", "b": "Quẻ này tượng: Toàn gia bình yên thịnh vượng, danh lợi được cả hai. Việc tốt đẹp vui mừng. Cầu mưu thì\ncó duyên, xuất hành thì đại cát, việc cưới hỏi nhất định thành. Người xin được quẻ này an nhiên thụ hưởng\nhạnh phúc, khỏi cần phải nghi ngờ gì.\nTheo ý quẻ thơ nói trên việc cầu thành hay bại, nên hay không đều do hai chữ ”trung trinh” mà định đoạt.\nVì câu chót nói: ”luôn luôn ắt được thái bình cảnh vui” và tiếp câu thứ ba là: ”ba non nắm giữ trung\ntrinh”. Bởi vậy việc cầu mưu của bạn cần phải kế hoạch có đầu có đuôi và đừng nản lòng mà cố gắng\ncùng thì ắt sẽ nên công trong việc cầu.\nTất cả việc tính toán, cần tính toán nghiên cứu kỹ, trước lúc thực hành, thì mới mong thành sự. Ý quẻ\nkhuyên: thận trọng. Chờ đợi. Đánh số được.", "g": "Công việc sẽ thành, nhưng phải bỏ đi sự sợ hãi, vì nó làm cho việc tính toán bị lệch lạc đi, có thể\nkhiến cho công trước bị mất.", "s": "54, 45, 25, 24, 42, 2, 5, 4."}, "255": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thủy Thiên Nhu", "line_label": "Động Hào Tam", "p": "Phúc tinh chiếu ánh,\nQuế tử hương văn.\nMãn thiên tinh đẩu,\nQuang diệu bức nhân.\nSau trời sáng chiếu đời ta,\nMùi thơm cây quế tràn hòa khắp nơi.\nKhông trung sao sáng đầy trời,\nQuả là sáng sủa chói ngời hoàng huy.", "b": "Quẻ này tượng đủ: Phúc thọ phú quý, nhất tề đều tới. Mọi người đều ca tụng, mọi nhà đều tính phục. Đây\nchính là hội tam đường khai thái (xuân về tốt đẹp đó). Người xin được quẻ này coi như quẻ thượng cát.\nPhước tinh cao chiếu, quế thơm tràn khắp, đó là cảnh vinh hoa phú quí vậy. Nghĩa là người cầu được quẻ\nnày, tức là thời vận đã đến hanh thông, những việc cầu mưu ắt kết quả mỹ mãn. Chẳng còn gì trở ngại\nnữa.\nVậy bạn hãy mau tiến hành những như đã định, để nắm lấy may mắn mà số phần đã dành sẵn. Tốt đẹp.\nGiàu sang vinh hiển đến kỳ cầu danh, cầu lợi đắc quả. Đánh số, thông.", "g": "đại cát đại lợi , được thần minh phù hộ độ trì. Vào tháng tám của mùa Thu, gặp được quí nhân\ngiúp đỡ.", "s": "2, 5, 55, 52, 25."}, "256": {"c": "HẠ HẠ", "hexagram": "Thủy Thiên Nhu", "line_label": "Động Hào Tứ", "p": "Đông Nam Bắc tương lai thành cố khứ,\nYên kế địa, thương sinh vô tồn tế.\nNhược yến dại phấn hùng tâm,\nThủy nguyên bất tri hà xứ.\nĐông Nam lượng đất thành như không,\nBá tánh phương kia cũng khổ cùng.\nMuốn khởi hùng tâm cứu thế nạn,\nBiết đâu được có nước nguồn sông.", "b": "Quẻ này chủ đại nạn sắp đến, kiếp số khó tránh: 3 phương Đông, Nam, Bắc đều không phải là chỗ yên\nthân. Duy chỉ còn phương Tây là phương bình tỉnh yên ổn, tới đây còn mong là có làm được việc gì.\nNhưng lại tiếc phải cái nơi đất khách quê người có định kế lâu dài được không. Người xin được quẻ này\ncần nên cấp tốc lo liệu chớ có do dự chậm trễ thì may ra mới đỡ được phần nào tai hại.\nTheo ý quẻ cho biết việc cầu xin của bạn muốn thành đạt thực là khổ nhọc, vì hai câu sau nói: Muốn khởi\nhùng tâm cứu thế nạn, mà chẳng biết được nước sông ở đâu. Nghĩa là nước nguồn sống của vạn vật,\nkhông nước thì làm sao sống. Vậy việc cầu xin của bạn muốn thành đạt, thì phải chịu gian nan, cố gắng\nkhông ngừng thì mới có thể an ủi phần nào.\nMuốn nên công, phải gắng sức. Công việc tính toán vô cùng khó. Hãy chờ thời là hơn, bôn ba tranh đấu\nchẳng có ích gì. Đánh số, không hạp.", "g": "Tình hình đang rất nguy hiểm, lo lắng đến gần rồi. Như muốn tìm đường sống nơi đất chết, nên\ntrước tìm cầu cho được nguồn nước cứu được sinh mệnh con người.", "s": "2, 5, 6, 25, 26, 62, 65, 56."}, "257": {"c": "HẠ TRUNG", "hexagram": "Thủy Thiên Nhu", "line_label": "Động Hào Ngũ", "p": "Hà dự mạn trù trừ,\nTử hữu nhật, sinh hữu thời.\nPhiêu phiên nhất vãng,\nTâm thượng vô nghi.\nSống chết ngày giờ định sẵn rồi,\nLàm chi tính toán lắm lôi thôi.\nCứ cho công việc tự nhiên đến,\nLòng dạ yên vui yên chỗ ngồi.", "b": "Quẻ này chủ sống chết có mạng, giàu sanh tự trời. Việc tới trước mắt mà cứ gãi đầu gãi tai, ra rồi lại vào,\nbăn khoăn do dự, nghi ngại, lo âu thì còn làm được gì nữa. Quẻ này chính ra là một cái phép tử lý cầu sinh\n(trong cái chết tìm cái sống) đó. Người xin trúng quẻ này cần phải nuôi cái khí \"Hạo nhiên\" để tỏ chí\ncương cường khiến người ngoài kính phục.\nQuẻ nói rằng sanh có giờ, và chết có ngày, nghĩa là cuộc đời của bạn sống trên trần gian sự vui khổ, giàu\nnghèo, đã định sẵn rồi, dầu bạn có cưỡng cũng chẳng được, là trời định vậy.\nVậy việc cầu xin của bạn hãy để cho nó tự nhiên, như xưa có câu: ”Mệnh trung hữu thời chung tu hữu,\nmệnh trung vô thời mạc cưỡng cần”, bạn nên lấy câu đó tự suy nghĩa ắt bớt được khổ não trong hoàn cảnh\nthiếu nầy.\nHãy ẩn nhẫn chờ thời. Khi thời đến, như cánh chim tung trời. Lo gì, chí nguyện chẳng toại. Đánh số, chưa\nthuận lắm.", "g": "Tất cả những gì đến với con người đều do định số, cho nên không cần phải quá lo âu sợ hãi làm\ngì.", "s": "25, 75, 57, 27, 72, 2, 5, 7."}, "258": {"c": "HẠ HẠ", "hexagram": "Thủy Thiên Nhu", "line_label": "Động Hào Lục", "p": "Húc nhật chính đương không,\nQuang huy vũ trụ trung.\nHán gia hỏa thịnh đức,\nTiến thoái tự thung dung.\nVắng tanh đi lại làm chi,\nHết hồn hú vía tại vì làm gian.\nSài lang nếu cản nữa đường,\nRa tay chém, việc mới thường yên tâm.", "b": "Quẻ này chủ sự thịnh vượng về phúc đức của cha ông tổ tiên cho nên nhờ đó mà được thịnh vượng. Từng\nngày trông khác gì lửa bốc cháy ngùn ngụt càng ngày càng cao lớn, và không còn có cái lý củ lỗ ăn xuôi\nnữa.\nCâu thơ chót có ý nói không có gì bất hòa hoặc kình địch với ai. Đây là một quẻ chỉ rõ ở đời không có\nchuyện gì đáng sợ hãi cho mình cả, khiến khi bói được nhất định sẽ thấy mọi việc thuận lợi và thích đáng.\nViệc cầu xin của bạn trong thời gian này chưa thể nào thành đạt và cần phải vượt qua nhiều trở ngại nữa\nmới được. Vì lời quẻ dạy rằng sài lang cản đường cần diệt trừ mới vững tâm.\nĐang gặp nhiều cản trở hiểm nguy. Có kẻ phá hoại, cần phải thanh toán, xong mới yên tâm toan tính và\nviệc may ra mới tiến hành tốt đẹp. Đề phòng tiểu nhân. Cầu mọi sự chưa thông. Đánh số, dở.", "g": "Công việc đang làm bổng gặp khó khăn nguy hiểm,cần phải có dũng khí để trừ. Sự tình có thể\nthuận lợi chứ không đến nổi tuyệt vọng dù có xãy ra nhiều việc đáng sợ đi nữa.", "s": "58,\n52, 85, 25, 8, 5, 2."}, "259": {"c": "TRUNG TRUNG", "hexagram": "Thủy Trạch Tiết", "line_label": "Động Hào Nhất", "p": "Vãng lai hành tịch xứ,\nThốt nhiên trước nhất kinh.\nSài lang nhược dương đạo,\nTrảm diệt phương xứng tâm.\nVắng tanh đi lại làm chi,\nHết hồn hú vía tại vì làm gian.\nSài lang nếu cản nữa đường,\nRa tay chém, việc mới thường yên tâm.", "b": "Quẻ này chủ việc tìm liễu hỏi hoa, ép mình là điều phi nghĩa. Cho nên kinh sợ, bỗng vụt tới với mình. Tuy\nắt là phải trừ diệt cho bằng hết, như thế lại càng tỏ ra mình là một tay hào hiệp. Như thế thì khi có phải\nkinh sợ chăng nữa cũng chẳng hề gì.\nViệc cầu xin của bạn trong thời gian này chưa thể nào thành đạt và cần phải vượt qua nhiều trở ngại nữa\nmới được. Vì lời quẻ dạy rằng sài lang cản đường cần diệt trừ mới vững tâm.\nĐang gặp nhiều cản trở hiểm nguy. Có kẻ phá hoại, cần phải thanh toán, xong mới yên tâm toan tính và\nviệc may ra mới tiến hành tốt đẹp. Đề phòng tiểu nhân. Cầu mọi sự chưa thông. Đánh số, dở.", "g": "Quẻ nầy có liên quan đến sách lược dùng binh chế ngự địch của Ngài Gia Cát Khổng Minh , nói\nlên thực lực hai bên tương đương với nhau.", "s": "58,\n52, 85, 25, 8, 5, 2."}, "260": {"c": "HẠ HẠ", "hexagram": "Thủy Trạch Tiết", "line_label": "Động Hào Nhị", "p": "Bát môn phân bát vị,\nCửu tinh bố cửu phương.\nThanh xích hoàng bạch hắc,\nNgũ sắc quyển cầm trang,\nGiao phong đối lũy,\nLưỡng lưỡng tương đương.\nBốn góc bốn phương chia tám môn,\nChín sao bố trí chín nơi dòm.\nXanh vàng đỏ trắng đen năm sắc,\nCuốn gói hành trang vượt núi non.", "b": "Quẻ này chủ lòng lo đối phó phí mất bao tâm cơ. Lỡmà lầm chỉ một ly, ắt sai đi một dặm. Nếu muốn cầu\nchiến thắng không có thế tương đương ắt không thể lực địch. Người xin được quẻ này thiết tưởng cần phải\nsuy nghĩ cẩn thận, chớ có coi thường.\nNgười cầu được quẻ này, đối với sự việc cầu mưu hãy nên cân phân cho kỹ, đắn đo thực sâu thì công việc\nmới có thành tựu như ý, vì quẻ này hai câu đầu ý vẻ toàn thuộc những lời mưu kế bố trận, và hai câu sau\nẩn ý mách bạn phải hiểu biến hóa như sắc màu thì mới vượt khỏi khó khăn và thành công, vậy bạn hãy tự\nđo lường và suy kỹ càng.\nPhải mưu mô, tính toán kỹ càng và phải biết quyền biến, thì việc mới thành tựu. Đánh số tốt", "g": "khuyên người không nên sống trong cảnh mê muội mờ ám , uổng phí một đời.", "s": "29,\n25, 95, 92, 9, 5, 2."}, "261": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thủy Trạch Tiết", "line_label": "Động Hào Tam", "p": "Chung thân bất tập thương,\nTại thể khước uổng nhiên.\nLuân hồi bất năng miễn,\nVĩnh lạc khâm thạnh tạm.\nCả đời chẳng học việc cao siêu,\nPhí uổng ngày giờ cuộc sống nhiều.\nRút cuộc luân hồi chẳng thấy lạ,\nLạc vào hầm hố thấy mình tiêu.", "b": "Quẻ này có cái tượng: Không thích ở dưới, chỉ cố tranh dành với trên, 2 câu thơ sau là 2 câu thơ cảnh cáo.\nHố hốc ngụ ý chỉ địa ngục. Người xin được quẻ này cần phải quay về cảnh ngộ ngay, dùng câu này mà\nkhắc vào bên hữu chỗ ngồi thường ngày.\nQuẻ ý nói rằng phàm cầu mưu bất cứ việc gì phải đứng đắn đàng hoàng chớ nên sanh tâm tà ma và phải cố\ngắng chăm chú việc cầu mưu thì mới nên công, ngược lại bạn chỉ uổng công hao tài chẳng một kết quả\nnào.\nVậy bạn hãy lưu ý việc mưu cầu mới mong được yên vui tóm lại hiện nay vận trình của người còn xấu.\nXấu, mọi việc bế tắc. Sự sự bất minh. Hay hơn là chờ thời. Đánh số chẳng hạp.", "g": "Người được quẻ nầy, có thể được một trai và một gái, hoặc có khả năng song thai một đôi nam\nnữ. Việc khác cũng tốt, âm dương điều hòa.", "s": "26, 60, 20, 62, 2,\n6."}, "262": {"c": "TRUNG THƯỢNG", "hexagram": "Thủy Trạch Tiết", "line_label": "Động Hào Tứ", "p": "Lưỡng ca tử nữ,\nĐồng đáo tề hành.\nÂm dương hòa hợp,\nMưu tác hoan hân.\nHai đứa trai gái của ai,\nĐến cùng một lượt chung vai đồng hành.\nÂm dương hòa phước may lành,\nMưu cầu sự nghiệp công thành hân hoan.", "b": "Quẻ này có tượng: Chồng hiền vợ tốt, cầm sắc hết sức hào hòa. Vợ chồng lúc nào cũng phu xướng phụ\ntòng, hợp tác chặt chẽ, cổ vũ nhau. Vô cùng vui vẻ đầm ấm. Người xin được quẻ này chẳng có gì là đáng\nlo ngại băn khoăn.\nHai chữ trai gái của câu một dịch ra chữ Tàu hợp lại có nghĩa là Hảo tức là tốt, và câu ba, câu bốn cùng\nnói rõ là âm dương hòa phước may lành, mưu cầu sự nghiệp công thành hân hoan. Người xin được quẻ\nnày là may mắn lắm.\nVậy việc cầu xin của bạn sợ gì gì mà không may không tốt cứ việc tiến hành theo ý đã định đi tốt lắm. Có\nâm dương hòa hợp là may mắn lắm rồi, có kẻ giúp công đắc lực lo gì chẳng thành. Cầu danh đắc danh, cầu\nlợi đắc lợi. Đánh số tốt.", "g": "Việc muốn hỏi còn nghi nan chưa giải quyết được, nhưng đừng lo, sẽ nhanh chóng thấy lối thoát\nmà thôi.", "s": "61, 26, 21, 62, 12, 2, 6, 1."}, "263": {"c": "TRUNG THƯỢNG", "hexagram": "Thủy Trạch Tiết", "line_label": "Động Hào Ngũ", "p": "Trung hữu huyền cơ phú,\nKệ minh phương hiển lộ.\nMãnh nhiên ngộ thiền quang,\nĐả phá quân môn lộ.\nHuyền cơ trong đó có ngâm ca,\nGà gáy rồi đây trời sáng hòa.\nTỉnh ngộ thiềm quan người sẽ thấy,\nVận trình vượt bước dặm ngàn xa.", "b": "Quẻ này chỉ rõ: Lúc đầu tuy chấp mê, nhưng cuối cùng cũng tỉnh ngộ. Bỏ dao rựa, quỳ xuống đất, quy y\nliền thành Phật đổi hẳn bộ mặt, y như là hai người khác nhau vậy. Người xin được quẻ này rất nên nhắc lại\nlời này nhiều lần, chớ có thấy cơ hội tới mà không làm.\nViệc cầu xin của bạn theo ý quẻ cho biết diều cần nhứt là phải hiểu là công gì, thì làm mới thành công như\nquẻ thơ câu thứ ba nói tỉnh ngộ thiềm quan người sẽ thấy vậy.\nCòn trong việc cầu xin của người nếu thấu hiểu và nắm vững được sự việc mà làm thì ắt gặp được nhiều\nmay mắn và nhiều hứa hẹn trong tương lai đó.\nPhải nghiên cứu kỹ công việc trước khi thực hành thì sự việc thành đạt chắc chắn. Thời vận tốt đến rồi, lo\ngì. Đánh số tốt. Biểu tượng: Gà.", "g": "Ngoài cái ý vận tốt, còn nói lên ý nữa là, có lúc chính những sự hưởng cái phước lại trở thành\ngánh nặng cho mình.", "s": "26, 2, 62, 22, 6."}, "264": {"c": "TRUNG TRUNG", "hexagram": "Thủy Trạch Tiết", "line_label": "Động Hào Lục", "p": "*Thi ：\nmão nhật nhi xuất lâm ,\nngọ thời chính phước lâm ,\nmão sanh ư dần ,\nphương kiến thiên tâm .\n-Dịch:-\nTrẻ Mão Nhật ra rừng,\ngiờ ngọ là phước đến.\nMão từ Dần sanh,\nmới thấy lòng trời.\n*Giải：Thiên thời cứ theo thứ tự mà vận chuyển, làm việc gì cũng không nên trái với phép tắc của tự\nnhiên .\nLời bàn của Thông Huyền Đạo Nhân\nTiết chế quá sức, Hào này có hung hiểm. Nhưng khó khăn đã qua.\nQuẻ này chủ về nhà nghèo, cơm không đủ no, áo không đủ ấm. Ra ngoài kiếm ăn, lang thang khắp bốn bể\nnăm hồ như thế còn hay hơn. Người được quẻ này, ở nhà, ở quê hương làm ăn, không lợi bằng đi xa, càng\nđi xa, càng khá giả hơn.", "b": "", "g": "", "s": ""}, "265": {"c": "THƯỢNG TRUNG", "hexagram": "Thủy Sơn Kiển", "line_label": "Động Hào Nhất", "p": "*Thi ：\nnhật trung bất quyết ,\nnhật đáo phương minh ,\nnhất trường hảo sự ,\nlục nhĩ đồng thành .\n-Dịch:-\ntrong ngày chưa quyết định,\nmặt trời đến thì rõ ràng,\nmột bề việc tốt,\nba người cùng đi.\n*Giải ：Việc muốn hỏi trong một hai ngày tới chưa có thể quyết định được. Mặt trời đến thì mọi việc sẽ\nsáng tỏ. Nên có được ba người cùng bàn bạc công việc mới thành công.\nLời bàn của Thông Huyền Đạo Nhân\nLúc ra đi rất gian nan khó khăn, lúc quay trở về thì vinh quang.\nQuẻ này có tượng trước khó sau dễ, chủ về phải gặp năm mão (hay ngày mão), mới có thể xuất đầu lộ diện\nđược, và phải đợi tới năm ngọ hay giờ ngọ thì mới thấy có phúc tinh đến nhà. Người được quẻ này, mọi\nmơu cầu phải có một ké hoạch chu toàn, nếu không hỏng việc.", "b": "", "g": "", "s": ""}, "266": {"c": "TRUNG TRUNG", "hexagram": "Thủy Sơn Kiển", "line_label": "Động Hào Nhị", "p": "*Thi ：\ncô tú thị yêu tinh ,\nviên hầu cập thụ tinh ,\nnhập sơn ngộ thử diệu ,\nmê liễu tánh hoà tâm .\n-Dịch:-\nsao lẻ loi chính là yêu tinh\nkhỉ vượn và yêu tinh của cây\nvào núi gặp điều kỳ diệu nầy\nmê mờ giữa tâm và tánh.\n*Giải ：Quẻ nầy chỉ cho người bị cô độc hoặc có sự nhầm lẫn nặng.\nLời bàn của Thông Huyền Đạo Nhân\nBề tôi ở cảnh gian nan, lỗi không do bản thân.\nQuẻ chủ về việc trước kia đã không thể dự đoán, chỉ đợi khi thời vận tốt đến thì mới hay. Ngụ ý nói người\nđược quẻ này đang ở trong hoàn cảnh khó khăn, mà lại không chịu trông xa nhìn rộng, để dự tính mọi\nviệc. Mọi mưu cầu phải trải qua một thời gian chờ đợi, đến lúc đó công việc mới toại ý.", "b": "", "g": "", "s": ""}, "267": {"c": "HẠ HẠ", "hexagram": "Thủy Sơn Kiển", "line_label": "Động Hào Tamị", "p": "*Thi：\ntrích lậu thanh thôi kê xướng ,\ntoản hành nhân trục đội phóng ,\nvãn độ quan tân ,\ntiền trình vô lương.\n-Dịch:-\ntiếng mưa rơi làm cho gà gáy\nđẩy người đi gom lại thành đoàn\nbuổi chiều qua bến sông cửa ải\ntiền trình không có lương thực.\n*Giải：toàn lực đối phó, ắt là công việc mới thành.\nLời bàn của Thông Huyền Đạo Nhân\nLúc ra đi thì gian nan, lúc quay trở về thì tốt đẹp.\nQuẻ này chủ về bọn tiểu nhân gian hiểm làm loạn tâm tính người ta. Vì vậy, khi giao du bạn bè phải thật\ncẩn thận, lập trường phải cương quyết, liệu việc phải sáng suốt. Người được quẻ này tốt nhất là phải nên\nra đi. Thời vận hiện nay của bạn còn bế tắc, phải cố gắng nhiều, đề phòng tiểu nhân quấy phá.", "b": "", "g": "", "s": ""}, "268": {"c": "TRUNG THƯỢNG", "hexagram": "Thủy Sơn Kiển", "line_label": "Động Hào Tứ", "p": "*Thi ：\nnhân tại thiên nhai ngoại ,\ncửu phạp tín âm lai ,\ngia nhân tần vọng nhãn ,\nthảo mộc sướng hung hoài .\n-Dịch:-\nngười ở ngoài góc trời\nđã lâu không có tin tức\nngười nhà nhiều lần trông ngóng\ncây cỏ nằm dài nhớ kỷ niệm.\n*Giải：Người đang nhung nhớ nầy đang ở xứ xa, đã lâu không có tin tức nên những kỷ niệm xưa sống lại\ntrong lòng.\nLời bàn của Thông Huyền Đạo Nhân\nRa đi gian nan, quay trở về vẫn gian nan.\nQuẻ này chủ về nên ra đi, về sẽ được quý hiển. Người được quẻ này phải thận trọng, chớ có vì khó khăn\ntrở ngại mà bỏ mất cái chí khí của mình. Vận trình của bạn sắp hanh thông và hãy tiếp tục làm những việc\nmình dự tính, đừng bỏ dở nửa chừng.", "b": "", "g": "", "s": ""}, "269": {"c": "HẠ HẠ", "hexagram": "Thủy Sơn Kiển", "line_label": "Động Hào Ngũ", "p": "*Thi ：\ngiá khoả thụ hạ ,\nnhất huyệt sinh thành ,\nnhược thiên thử thổ ,\nphước lộc biền trăn .\n-Dịch:-\nnhững cái cây nầy,\nmột lổ sinh ra,\ndời đến đất nầy,\nphước lộc ít oi.\n*Giải ：Có hai ngụ ý:-\n1/- muốn cho mệnh vận hanh thông, phải ở nơi gần cái giếng xưa có cây khô kế bên.\n2/- cơm áo gạo tiền có tăng lên, nhưng không thể làm nhà đẹp được.\nLời bàn của Thông Huyền Đạo Nhân\nRất gian nan, mau mau chạy đi.\nQuẻ này chủ về người đi xa không có tin tức, khiến người ở nhà ngóng trông mòn mỏi. Ý muốn nói,\nnhững mưu cầu của bạn còn lâu lắm mới có thể đạt thành. Hiện vận số của bạn chưa được hanh thông, dù\ncó làm thế nào cũng khó mà toại ý. Đợi thời cơ mà thời cơ chẳng đến. Cầu tài, cầu danh đều dở.", "b": "", "g": "", "s": ""}, "270": {"c": "TRUNG TRUNG", "hexagram": "Thủy Sơn Kiển", "line_label": "Động Hào Lục", "p": "*Thi ：\ncung canh lũng mẫu ,\nhình thần tự lao ,\nvô câu vô hệ ,\nkỳ lạc đào đào .\n-Dịch:-\nrán cày ruộng sâu,\nhình dáng mệt mõi,\nnếu đừng vướng mắc nhiều,\nniềm vui sẽ dạt dào.\n*Giải ：Trong sinh hoạt, nếu đừng nhờ vả người khác quá mức, thì thân thể tuy nhọc nhằn nhưng tinh\nthần rất sảng khoái.\nLời bàn của Thông Huyền Đạo Nhân\nLúc ra đi gian nan, lúc quay về có thành quả lớn lao. Hào này cát tường, đại nhân xuất hiện có lợi.\nQuẻ này chủ về di dời thì có lợi. Người được quẻ này rất nên tự tu dưỡng, cố gắng chăm chú vào công\nviệc, tuy hơi khổ cực vất vả, song sau cùng sẽ gặt hái được nhiều kết quả tốt đẹp. Những mưu cầu của bạn,\ncần phải chịu đựng nhiều vất vả, thì mới đạt thành.", "b": "", "g": "", "s": ""}, "271": {"c": "HẠ HẠ", "hexagram": "Thủy Địa Tỷ", "line_label": "Động Hào Nhất", "p": "*Thi ：\nhoạ lai kiến quỉ ,\nquỉ bệnh yêm triền ,\nkim dương đắc lộ ,\nthân thoát tai ương .\n-Dịch:-\nhọa đến thấy quỉ,\nbệnh quỉ triền miên,\ndê vàng được đường,\nthân thoát tai ương.\n*Giải ：Nạn lớn đến mình, tâm bị bệnh quỉ nhận chìm nên trói buộc chẳng thả ra, chỉ trừ khi có hai vật\nliên quan là “Kim” (vàng) và “Dương” (dê) đến cứu mới được.\nLời bàn của Thông Huyền Đạo Nhân\nCó điềm ứng đoàn kết, giúp đỡ nhau thì không tai vạ dù có tai họa cũng không sao.\nQuẻ này chủ về hiển đạt giàu sang chẳng bằng an nhàn ẩn dật. Người được quẻ này nên làm những công\nviệc tự do, không bị ràng buộc là tốt nhất. Cố gắng chăm chú làm công việc của mình tuy hơi khổ cực vất\nvả, song sau cùng sẽ gặt hái nhiếu kết quả tốt đẹp.", "b": "", "g": "", "s": ""}, "272": {"c": "HẠ TRUNG", "hexagram": "Thủy Địa Tỷ", "line_label": "Động Hào Nhị", "p": "*Thi ：\ncấp khởi hành ,\ncấp khởi hành ,\ntiền đồ khứ ,\nkết đồng minh ,\nchỉ thủ kình thiên trụ ,\nsử sách hảo tiêu danh .\n-Dịch:-\ngấp lên đường,\ngấp lên đường,\nđường trước mắt, có đồng minh,\ntay đở trụ chống trời,\nsử sách nêu danh tốt.\n*Giải ：Người được quẻ nầy đang nhận một sứ mệnh cực kỳ hiểm nghèo, tính cách vô cùng quan trọng,\nnhưng cuối cùng cũng đạt được thành công.\nLời bàn của Thông Huyền Đạo Nhân\nGiúp đỡ từ bên trong – Hào này tốt đẹp.\nQuẻ này chủ về đau ốm rất bất lợi. Phải đợi tới năm Ất mùi thì mới thoát được tai họa, bệnh hoạn, và mọi\nviệc sẽ dần dần trở nên thuận lợi. Hiện thời vận của bạn giống như bị tà ma phá rối, cho nên mưu sự khó\nthành, phải chờ một thời gian nữa.", "b": "", "g": "", "s": ""}, "273": {"c": "TRUNG TRUNG", "hexagram": "Thủy Địa Tỷ", "line_label": "Động Hào Tam", "p": "*Thi ：\nthâm sơn cứ mãnh hổ ,\nhổ khiếu xuất sơn oa ,\ndương uy đẩu tẩu ,\nhà phạ nhân đa .\n-Dịch:-\nmãnh hổ ở rừng sâu\nhổ gầm thành hang núi\nuy thế phấn chấn\nnào sợ người đông.\n*Giải ：\nhùng tráng uy nghiêm ,\nsự quả cảm anh dũng có thể chế phục được mọi người.\nLời bàn của Thông Huyền Đạo Nhân\nGần gũi với người.\nQuẻ này chủ về phải nhờ sức của số đông mới có thể thành đạt. Hiện thời vận đã đến lúc hanh thông, sự\nmay mắn đang chờ bạn, hãy mau tiến bước. Tương lai sán lạn chớ lo.", "b": "", "g": "", "s": ""}, "274": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thủy Địa Tỷ", "line_label": "Động Hào Tứ", "p": "*Thi ：\ntam thiên môn ,\ntứ địa hộ ,\nbố trận thành ,\nminh tụ lộ ,\nquân mã tề bôn ,\nminh cổ tiến bộ .\n-Dịch:-\nba cửa trời,\nbốn cửa đất,\nbày thành trận,\nsáng rực đường,\nquân và ngựa đồng hợp chạy,\ntrống thúc tiến lên.\n*Giải ：Chúng ta khi làm việc, trước tiên chế định được sách lược tốt, thì mới có khả năng đạt được kết\nquả như ý.\nLời bàn của Thông Huyền Đạo Nhân\nThân thiện với người ngoài. Hào này tốt đẹp.\nQuẻ này chủ về không xuất hiện thì thôi, một khi xuất hiện thì mọi người phải kinh hồn bạt vía hết. Đã có\noai danh như vậy thì đánh đâu mà chẳng thắng, mưu cầu gì mà chẳng thành. Người được quẻ này nên xuất\nhiện tung hoành một phen, mọi việc sẽ như ý.", "b": "", "g": "", "s": ""}, "275": {"c": "TRUNG TRUNG", "hexagram": "Thủy Địa Tỷ", "line_label": "Động Hào Ngũ", "p": "*Thi ：\nsơn sơn sơn ,\nsơn thượng kiến mâu ,\nbất tỉ nhân gian đống vũ ,\nkhước như thiên thượng vân đàm .\n-Dịch:-\nnúi núi núi,\ntrên núi thấy cỏ tranh,\nchẳng bì với nhà cửa to lớn của người,\nmà những thứ đó chỉ là mây chùm trên trời thôi\n*Giải：nếu biết tri túc thì được vui lâu dài.\nLời bàn của Thông Huyền Đạo Nhân\nMột nhóm người tụ tập. Vua đi săn bắn, họ bao vây ba mặt, cầm thú chạy trốn mà họ cũng không truy\nđuổi, người dân không hoảng sợ. Hào này tốt đẹp.\nQuẻ này chủ về phàm làm việc gì cũng cần phải có đủ trí dũng, có vậy khi lui thì có thể giữ, Lúc tiến thì\ncó thể đánh. Người được quẻ này khi lâm sự phải biết lo liệu mọi việc mới có thể thành đạt. những mưu\ncầu của bạn rất là khó khăn, cần phải đem hết tài trí, sức lực ra mới được. Cầu việc òn chậm, cầu tài phải\ntính toán cho kỹ lưỡng.", "b": "", "g": "", "s": ""}, "276": {"c": "TRUNG TRUNG", "hexagram": "Thủy Địa Tỷ", "line_label": "Động Hào Lục", "p": "*Thi ：\nlai khứ nguyên vô định xứ ,\nthời lai thời khứ an thân ,\nbạt thiệp vô lự ,\nvinh nhục bất kế .\n-Dịch:-\nđi lại không nơi nhất định,\ngiờ đi giờ đến an thân,\nlăn lóc không lo,\nvinh nhục chẳng màng.\n*Giải ：Người được quẻ nầy, một đời lận đận, bôn ba khắp nơi tìm kế mưu sinh, miễn là tại chỗ trú ngụ\nđược vui thì con đường bôn ba vẫn an toàn.\nLời bàn của Thông Huyền Đạo Nhân\nTụ tập ở một nơi mà không thấy người đứng đầu. Hào này hung hiểm.\nQuẻ này chủ về nên sống trong cảnh thanh đạm, mà không nên tham cảnh phồn hoa. Người được quẻ này\nlà bậc quân tử hiền nhân, nên ẩn cư nơi am thanh cảnh vắng, chớ bon chen với người đời làm gì. Mưu cầu\ncủa bạn không nên quá cao vọng. Cầu danh khó thành, cầu tài đắc lợi nhỏ thôi.", "b": "", "g": "", "s": ""}, "277": {"c": "TRUNG TRUNG", "hexagram": "Thủy Lôi Truân", "line_label": "Động Hào Nhất", "p": "Lai khứ nguyên vô định xứ,\nThời lai thời khứ an thân.\nBạt thiệp vô lự,\nVinh nhục bất kế.\nLại đi chẳng định nơi nào,\nBốn phương tự ý làm sao cũng tùy.\nLỗi non nước có hại chi,\nTrên đời vinh nhục kể gì mà lo.", "b": "Quẻ này tượng: Kẻ giang hồ vui cùng trời đất, tùy cảnh ngộ mà yên thân, tuy cuộc sống phong trần lận\nđận quan san đâu có kể gì. Trèo đèo vượt suối, chẳng bao giờ quan ngại, nếu không phải người đạt nhân\nchí khí khá lớn lao cao thượng thì làm sao như thế được. Người xin được quẻ này nên rất suy nghĩ tới đó.\nCâu nói phú quý trời đã định, ta có cần cầu chi, đó là ý quẻ muốn mách bạn vậy. Do đó, những việc cầu\nxin của bạn hãy cho nó tự nhiên là hơn, tuy nhiên cũng phải sự tại nhân, nghĩa là mình cũng phải lo lắng\nviệc cầu. Tóm lại người cầu được quẻ này không tốt lắm, mà chẳng xấu lắm, nhưng sự mưu cũng được\ntoại nguyện phần nào thôi.\nBình thường, khuyên người chớ lo, cứ để thời đến là hay, cứ xem việc đời giấc mộng, nào có sá gì. Đánh\nsố hạp ít.", "g": "Ở đời không thể được như sự mong muốn cùa con người, ta chỉ nên đừng thái quá mà cũng đừng\nbất cập (kém cỏi, thua sút). Được như thế thì đâu còn gì thành vấn đề để lo âu phiền muộn.", "s": "27, 7, 2, 72, 77."}, "278": {"c": "TRUNG TRUNG", "hexagram": "Thủy Lôi Truân", "line_label": "Động Hào Nhị", "p": "Hữu tử trường, thành thủy cục,\nThời ngộ hỏa, phản phát phúc.\nBất tất quá ưu tiên,\nNhân tâm khổ bất túc.\nKhi nào nước lên lại ròng,\nGặp thêm lửa ắt hanh thông vận trình.\nQuá lo chỉ hại thần kinh,\nLòng tham vô độ hoàng đình chưa an.", "b": "Quẻ này có cái tượng: Thủy hỏa ký tế (nước lửa đều hay) lại có thêm phúc thanh. Tuy nhiên thế tình\nthường đứng túi này trông túi nọ, ở Lũng (Tây) lại nhìn Thục (Ba), phần nhiều chẳng hội đủ, cho nên lúc\nnào cũng lo âu băn khoăn nơm nớp. Người xin quẻ này chớ nên có thái độ như vậy, trái lại lấy việc an\nphận thủ kỷ làm quý.\nQuẻ ý cho hay người cầu được quẻ này, vận trình cũng như những việc cầu mưu đều được bình thường\nkhông tốt, mà chẳng xấu và nên đừng nuôi lòng quá tham thì có hại, phải lượng sức mình mà tính mưu,\ncông việc mới dễ thành công hơn và mới tránh được điều không xảy đến. Mong bạn hãy ngâm kỹ hai câu\nsau của bài thơ sẽ rõ ý quẻ đấy.\nChớ tham, chớ lo, cứ để từ từ thời vận đến, thì mọi sự ắt hanh thông Cầu sự chưa thông lắm, chờ đợi, đánh\nsố phải cẩn thận.", "g": "Những gì mình chưa thông thạo quen biết thì chớ nên liều lĩnh đi vào, nếu như hoàn cảnh bắt\nbuộc phải theo , cần nhất là có bạn bè hướng dẫn.", "s": "8, 7, 72, 2, 27, 82, 28."}, "279": {"c": "TRUNG THƯỢNG", "hexagram": "Thủy Lôi Truân", "line_label": "Động Hào Tam", "p": "Hắc dạ lý đồng tiền vãng,\nNhất hữu trị, yếu trước hoang.\nLao lao ky,\nTu kết đảng.\nĐừng đi nữa, tối đêm khuya,\nMột khi sơ ý e dè gặp ma.\nHãy nên nhớ, nhớ thật xa,\nRủ bè kết bạn, mới là yên thân.", "b": "Quẻ này chủ hai người đồng tâm hiệp lực, lợi có bạc vàng. Sách có chữ: Tam nhân đồng hành tất hữu ngã\nsư, đông người thì mạnh sức, mạnh sức thì dễ nâng. Nếu trái lại cô chưởng ắt năng minh. Cái ý sâu xa là\nnhư vậy. Người xin há lại không biết điều đó sao.\nTheo ý quẻ cho biết. Việc cầu xin của bạn, khó khăn như ý quẻ nói nếu nhứt định cầu tính cho nên. Việc\nphải cố công thì may ra cưỡng thành, vì quẻ thơ khuyên rằng đừng đi nữa trong\nđ[IMG]file:///C:/DOCUME%7E1/ADMINI%7E1/LOCALS%7E1/Temp/msohtml1/01/clip_image007.gif[\n/IMG]êm khuya, e rằng gặp ma tác quái, làm hỏng công việc, nếu cần phải đi thì nên rủ bè kết bạn cùng đi\nchơi mới tránh được những sự kinh tâm.\nVậy việc cùng cầu xin của bạn, 1 là ngừng bước bỏ qua ý định chờ đợi dịp khác, 2 là muốn tiến tới phải\nsuy tính cho kỹ và nên nhờ sức giúp đỡ của đông người, thì mới nên việc.\nBất thông, phòng kẻ phản bạn và kẻ bất lương phá hoại. Cầu tài có sự góp sức của đông người, hay hợp\ntác với người thì việc mới mong thành công. Đánh số, không mấy hạp.", "g": "đại cát đại lợi , việc muốn hỏi, cái khó khăn sẽ bị đột phá, từ đó đi vào con đường bằng phẳng.", "s": "6, 8, 1, 16, 61, 68, 86, 18."}, "280": {"c": "HẠ TRUNG", "hexagram": "Thủy Lôi Truân", "line_label": "Động Hào Tứ", "p": "Trập long dĩ xuất thế,\nDầu dốc thủ tọa thành.\nVân hưng vũ trạch,\nĐắc tế thương sinh.\nRồng con nay đã chào đời,\nĐầu sừng đầy đủ giỡn chơi tinh thần.\nMưa nhuần mây nổi bay thăng,\nCứu giúp thiên hạ xa gần biết ơn.", "b": "Quẻ này chủ bất nhật hạ sơn để giúp đời cứu người trong lúc gian nan, chẳng khác chi kẻ ra làm quan để\nquản thi âm đức, người thương gia buôn bán để làm lợi cho dân, người làm điều thiện an ủi người bằng\ntiền tài, bằng điều lành ý tốt. Đây là một trong những quẻ đại cát.\nTheo ý quẻ cho biết từ nay về sau, trong năm này thế nào bạn cũng được thong dong hơn trước, vì quẻ ví\ncảnh tình của bạn như con rồng con nay đã ra đời và đầy đủ sừng giác, hơn nữa lại được thiên thời.\nVậy trong năm nay, kể từ khi cầu xin được quẻ khổng minh thời vận ắt được hanh thông rồi. Hãy tiến\nhành những gì đã định đi, ắt sẽ được toại nguyện đấy. Biểu tượng: Rồng. Đánh số hạp.", "g": "một khi phát sanh tai họa ngoài ý muốn, không thể thu thập được lợi lạc gì, phải tìm cho ra đối\nsách khắc phục hiệu quả, mới giải trừ được nạn khó.", "s": "9, 7, 2, 27,\n72, 97, 92."}, "281": {"c": "THƯỢNG THƯỢNG", "hexagram": "Thủy Lôi Truân", "line_label": "Động Hào Ngũ", "p": "Hỏa thế huân thiên,\nThiên biên tân xích.\nNgộ tế thủy nguyên,\nThứ hữu để cách.\nThế lửa đang xung xung,\nGốc trời nhuộm đỏ hồng.\nNgộ phùng nơi nước suối,\nCông việc mới hanh thông.", "b": "Quẻ này có cái tượng: Thủy hỏa ký tế (nước lửa tốt đẹp hoàn toàn). Nếu có lửa mà không có nước thì\nkhông tránh được hư hỏng mất một mặt. Người xin được quẻ này nên biết cái đạo điều chỉnh khiến mọi\nvật được quân bình hòa hợp y như tượng thủy hỏa ký tế.\nLửa mạnh nước yếu, đó lời quẻ chỉ cho người hay rằng có thời thiếu vận và ngược lại. Trong lúc này bạn\nchưa có thể như ý nguyện cầu được. Cần phải chờ đợi thời gian nữa, và trong thời gian chờ đợi nên suy\ntính một kế hoạch tốt đẹp như quẻ nói để thực hành thì đắc quả, việc đi tìm nguồn nước vậy.\nCần tìm sự giúp đỡ của quý nhân. Như cảnh lửa cháy đi tìm nước, thì việc mới thành. Đánh số hạp chút ít.", "g": "Nội dung ngụ ý nói địa điểm công tác tốt nhất là phương Nam. Nếu tìm kiếm đi về hướng ấy ắt\ngặp. Việc giao du tuy không rộng rãi, nhưng cũng có tri kỷ.", "s": "28, 80, 20, 2, 8."}, "282": {"c": "HẠ HẠ", "hexagram": "Thủy Lôi Truân", "line_label": "Động Hào Lục", "p": "Hướng nam hữu đạo đạo,\nThừa mã nhận hành châu.\nBất tri ngô nhân xướng,\nCách hữu nhất tri âm.\nHướng nam đường xá thênh thanh,\nTiện đi ngựa tiến vào hàng châu thành.\nĐâu cần hòa với ngô nhân,\nVần phòng ngộ kẻ tri âm hòa mình.", "b": "Quẻ này cho biết: Người tri âm rất ích, Người xin được quẻ này chớ có giao du bừa bãi, và nhất là chớ có\nlầm đường lạc lối đi vào trong ngõ bí, hẻm cụt, khiến đến đều chịu lụy.\nMưu cầu nên nhắm vào hướng Nam mắt dễ dàng thành đạt hơn, đó là trọng tâm lời nhắn của quẻ đấy. Và\nquẻ cũng nhắc bạn rằng, đừng nên làm theo người ta cứ chiều theo ý định của mình mà làm tự nhiên cũng\ncó quý nhân giúp cho công việc thành tựu như quẻ đã ám chỉ ở hai câu sau bài thơ trên.\nTốt đẹp, cứ đi về phương Nam mà tính thì sự ắt thành. Biểu tượng: Ngựa. Đánh số tốt.", "g": "Nhà có của cải tuy không nhiều nhưng biết kinh doanh thì kết quả tốt. Người được quẻ nầy cũng\ncó ý nói là, không dễ gì rời gia đình đi lập nghiệp phương xa.", "s": "1, 8, 2, 82,\n81, 21, 12, 28."}, "283": {"c": "TRUNG TRUNG", "hexagram": "Thủy Hỏa Ký Tế", "line_label": "Động Hào Nhất", "p": "Hữu điền nhất mẫu,\nTần khả vân canh.\nVô cùng thu hoạch,\nĐộ tại tây thành.\nRuộng vườn một mẫu sẵn nơi đây,\nTa hãy chăm lo việc cày cấy.\nKết quả vô cùng thu lượm khá,\nThành công mọi sự tại phương tây.", "b": "Quẻ này chủ lợi tuất sinh ra tuy ít ỏi, nhưng vẫn còn hơn ngồi rồi ăn không. Thực ra ví thử vườn ruộng ít\nỏi nhưng cố sức chăm nom thì mùa thu về, mùa màng hẳn phong nấm. Ở đời trăm việc nhỏ đến đâu cũng\ncó chỗ an ủi của nó, chớ có cho rằng nhỏ rồi xem thường rồi bỏ lơ qua. Người xin được quẻ này thử nghĩ\nkỹ xem.\nQuẻ thơ nói rằng hiện vận trình của bạn như mẫu ruộng sẵn có, cứ việc hái cắt được mùa chẳng lo hao sức\nuổng công, nghĩa là bạn đã được hanh thông thời vận, hãy cố công mà, thế nào cũng thành đạt sở nguyện,\nnhưng đại lợi là phương Tây vì câu kết của thơ quẻ có nói rõ.\nThời lại, vận đến, bạn đã thành tựu, về sau càng thành tựu hơn, nhứt là phương Tây. Đánh số hạp.", "g": "Quẻ nầy ngụ ý về chỗ làm rõ của tai nạn, hoặc chỉ tướng mạo hay tài trí ó chỗ thiếu sót, nhưng\ntrời sanh vạn vật, ắt phải có cái sở trường của nó.", "s": "2, 8, 3, 28 83, 23 32."}, "284": {"c": "TRUNG TRUNG", "hexagram": "Thủy Hỏa Ký Tế", "line_label": "Động Hào Nhị", "p": "Vật hiền nhi vô thần,\nTật túc truy bất cập.\nNạp nhật noãn tuyệt trung,\nTán cẩu hà xứ mịch.\nĐừng chê đứa ấy không môi,\nChạy nhanh ai đuổi xem coi được bằng.\nChui vào hang thú ẩn thân,\nChó săn khó kiếm đâu tầm được ra.", "b": "Hai câu thơ đầu ý nói: Một lời đã nói ra, 4 con ngựa tứ đuổi cũng không kịp. Còn hai câu sau ý nói: người\nvàng thì kín miệng, cho nên ít bị lầm oán trách. Người xin được quẻ này cần phải cẩn thận hết sức lời ăn\ntiếng nói.\nQuẻ mách rằng: Phàm việc mưu cầu chớ nên chê khen việc gì, nhứt là người chê thì ta lại làm được thành\ncông hơn, ví dụ người ta đều tính chuyện làm ăn to lớn mà ta lại chỉ tính làm ăn việc nhỏ, thì ắt vững bền\nvà chằc ăn đó là ý quẻ muốn nói vậy.\nNhững sự cầu xin của bạn phải khôn lanh, ứng phó hoàn cảnh, ắt được toại nguyện sở cầu. Chớ khinh\ncông việc. Cứ tiến hành làm, nhiều việc nhỏ gọp lại thành lớn, và thành tựu chắc hơn. Đánh số hạp. Số\nhên: 2, 8, 4, 84, 24, 48, 42.", "g": "Cứ bền lòng làm việc đến đâu thu hoạch đến đó. Không cần có sự kiêu hãnh mà vẫn thành công\nở đời.", "s": ""}, "285": {"c": "TRUNG TRUNG", "hexagram": "Thủy Hỏa Ký Tế", "line_label": "Động Hào Tam", "p": "Lục ngưu canh địa,\nKhai khẩn vô cương.\nThu thành kết thực,\nDoanh lẫm doanh thương.\nSao trâu cày cấy ruộng vườn,\nKhai hoang công tác phi thường công lao.\nTrúng mùa kết quả biết bao,\nĐầy kho lúa gạo việc nào phải lo.", "b": "Quẻ này dạy ta: Nếu đem hết tử công phu làm việc thì thế nào cũng thu hoạch được kết quả mỹ mãn. Xưa\nnay máu và mồ hôi, thảy đều biến thành vàng bạc và tiền tài. Tiền nhân hậu quả, đó là lẽ đương nhiên.\nNgười xin được quẻ này, cứ cố gắng làm việc thì thế nào cũng có được kết quả mỹ mãn.\nQuẻ ý mách rằng phàm bạn mưu cầu việc gì phải nên hợp sức với người, thì mới mong được kết quả mỹ\nmãn, vì một mình thì sức quá yếu, khó nên việc to.\nSong người cầu được quẻ này rất là may mắn ngoài sự mưu cầu cần sức hơi người, mà vận trình của bạn\ncũng đến lúc hanh thông đấy, chẳng có gì đáng ngại nữa, hãy mau hăng hái lên, ắt được nhiều may mắn.\nCày sâu, cuốc bẩm, bỏ công, khó vì công việc, thì lo gì chẳng giàu sang. Biểu tượng: Trâu. Đánh số được.", "g": "Muốn thành đại sự, chí ở bốn phương, đừng quanh quẩn một xó, nắm lấy thời cơ hãy sớm hành\nđộng.\nQuẻ nầy có liên quan đến thời vận ở “bảy tám ngày” hoặc “bảy tám giờ”.", "s": "2, 8, 5, 85, 58, 82, 25."}, "286": {"c": "TRUNG TRUNG", "hexagram": "Thủy Hỏa Ký Tế", "line_label": "Động Hào Tứ", "p": "Đại phấn xung thiên chí,\nVật khổ luyến gia hương.\nThấy bát quân hành tảo,\nDương võ tại sa trường.\nChí khí xung chiên mau phát huy,\nChớ nên lưu luyến quê làm gì.\nKhuyên người hãy sớm lên đường tiến,\nDương võ sa trường còn đợi chi.", "b": "Quẻ này chủ người con trai ở chí bốn phương, mạo hiểm mà tiến lên, tự nhiên có chỗ hữu ích, cứ quyến\nluyến quê hương gia đình thì còn làm được việc gì. Bảy, Tám tức là tháng Bảy và tháng Tám. Nếu ra đi\nkiến công lập nghiệp vào những tháng Bảy và tháng Tám thì rất lợi. Và nhất là tìm một nơi địa danh có\nchữ \"Sa\" thì tốt nhất (đó là ý nghĩa của câu thơ chót).\nÝ quẻ muốn nói, muốn lập nghiệp thành đại sự, thì phải xa quê, mất thế xung pha mới nên công nghiệp.\nPhàm mưu cầu việc gì thì phải nắm lấy cái lớn, chớ nên cố chấp tiểu tiết. Vậy tức là vận thời đã đến, bạn\nnên nắm lấy dịp may trong lúc này, ắt thu lượm được nhiều thành công.\nNên hành động kịp thời. Hãy lên đường lập nghiệp, chớ chần chờ. Thời vận đến có thể làm nên. Đánh số\nhạp.", "g": "Người được quẻ nầy, được thuộc hạ yêu mến phò giúp, nên có thể thành tựu nhiều việc, khiến cho\nsự nghiệp lừng lẫy ngày càng phát triển.", "s": "6, 8, 2, 68, 82, 28, 26."}, "287": {"c": "TRUNG TRUNG", "hexagram": "Thủy Hỏa Ký Tế", "line_label": "Động Hào Ngũ", "p": "Quì hoa hướng nhật,\nTrung xích khuyên tâm.\nĐại khai quảng hạ,\nLạc hưởng thái bình.\nHoa quỳ nở hướng phía đông,\nTrung thành nhứt chi son lòng biết bao.\nCửa nhà mở rộng đón chào,\nVui thay hưởng lạc thanh cao thái bình.", "b": "Quẻ này chủ đem hết lòng trung thành để phụng sự chủ nhân. Mình trung thành với chủ tất nhiên chủ quý\nmến mình. Đó bất quá là cái đạo thí ân báo ân đó thôi. Mở rộng cửa nhà lớn để an nghỉ, để đặt tiệc vui\nvầy, an hưởng cảnh thái bình phú quý.\nSự cầu xin của bạn thành đạt hanh thông không có khó khăn trở ngại và sự cầu xin chẳng những được\nthuận lợi mà còn đặng nhiều hạnh phúc nữa bởi ý quẻ cho hay bông quỳ đang hướng về mặt trời nở, người\nlại trung thành hết lòng và mở rộng cánh cửa đón chào ta, nhứt là câu chót nói rõ hưởng lạc thái bình.\nVận thái vô cùng thành đạt, cầu mưu cầu duyên, cầu tài đắc lợi. Đánh số hạp.", "g": "Khi muốn làm việc gì, ắt phải trước tiên nghiên cứu phân tích đánh giá kỹ lưỡng tận nguồn cội\nvấn đề, nắm lấy cốt lõi của nó rồi mới làm, chắc chắn sẽ được thành công.", "s": "27, 72, 2, 7, 20, 70."}, "288": {"c": "TRUNG TRUNG", "hexagram": "Thủy Hỏa Ký Tế", "line_label": "Động Hào Lục", "p": "Nhân bất thức tiên,\nNinh hữu chân quyết.\nNhất nhập hiền môn,\nTân tân hữu ích.\nNgười không hiểu biết thần tiên,\nLàm sao lại được chân truyền bí ngôn.\nMột khi vào đặng huyền môn,\nVô cùng hữu ích, lanh khôn việc đời.", "b": "Quẻ này chủ về trước không biết, cho nên hồ đồ lầm lẩn. Nhưng nay đã rõ hết chuyện, tất nhiên không cho\nqua một cách dễ dàng. Quẻ này ngụ cái ý là như thế. Người xin được quẻ này nên mau mau tỉnh ngộ.\nCông việc làm ăn hay chuyện gì bị trắc trở không vừa ý, là vì người hiểu lý do tại sao nên mới chịu như\nvậy, đó là hai câu đầu của ý thơ, và hai câu sau nói rằng muốn công việc cầu mưu được trôi chảy thì phải\nrút kinh nghiệm, nghiên cứu cho kỹ ắt sẽ thành công.\nPhải có kinh nghiệm mới mong thành công. Cầu sự còn chậm, chờ. Đánh số được.", "g": "Việc muốn hỏi, ý ở chỗ, không thể lấy bên ngoài mà biết rõ việc, phải dùng tâm nghiên cứu kỹ\nlưỡng bên trong vấn đề, mới là thực hiểu.", "s": "2, 8, 7, 28, 87,\n82, 78."}, "289": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Cấn", "line_label": "Động Hào Nhất", "p": "Vật vị thuyết thoại thái trầm.\nNê đinh thiện bất thành chân.\nNgộ xuất thiên ban ảo diệu,\nPhương thức thiên đạo tối thần.\nCông danh lẩm bẩm đáng ghi,\nNhưng trong thực tế có gì hân hoan.\nTu hành chính quả mới màng,\nTrường xuân muôn thuở rõ ràng biết bao.", "b": "Quẻ này chủ biết là đúng khi bắt tay vào việc. Lúc giao thiệp trong tiếp xúc trong công việc hành động, ta\nmới xét lý để biết. Chính là lúc mà thần tiên chỉ điểm cho ta, như những trường hợp ta có ý ngờ tới. Người\nxin được quẻ này phải để hết tâm cơ mà thăm dò, tìm hiểu để tỉnh ngộ, có thế mới đạt tới thành công.\nQuẻ nói: Công danh dù có mà thực tế có gì đâu? Bởi trong đời bạn “sanh không đem lại, chết chẳng đem\nđi\". Nên công danh tiền tài đều như mây khói, chẳng có gì đáng màng lắm. Nếu bạn muốn muôn thuở bất\nhủ thì hãy tu hành. Ý quẻ muốn rằng: Việc cầu xin của bạn tuy được thông hạnh, nhưng phải làm việc\nphúc đức thì mới được hưởng bền.\nTu là cội phúc. Còn tất cả là hư không. Sống gửi thác về, rồi cuộc đời cũng ra ma mà thôi. Cầu xin còn\nchậm. Đánh số ít hạp.", "g": "Đây là nói cho người đang gấp gáp tìm cầu công danh ở đời, chẳng bằng “tu thân dưỡng tính” (tu\nTiên)", "s": "9, 8, 2, 98, 82, 92."}, "290": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Cấn", "line_label": "Động Hào Nhị", "p": "Công danh tuy đa thực tể,\nHà như tu luyện thành chân.\nChân thân bất hủ,\nVạn tai trường xuân.\nCông danh lẩm bẩm đáng ghi,\nNhưng trong thực tế có gì hân hoan.\nTu hành chính quả mới màng,\nTrường xuân muôn thuở rõ ràng biết bao.", "b": "Chức tước, quyền vị tuy quý nhưng giống thực mà lại hư đó. Đấy chỉ là những nhân tước phù ảo, chóng\ntàn, không vững chắc lâu dài. Chi bằng ta đi tìm thiên tước. Thiên tước mới lâu dài vĩnh cửu được. Thiên\ntước tức là cái phú quý tự nhiên của trời đất ban cho.\nMạnh Tử nói: \"Nhân nghĩa trung tín, vui làm điều thiện không chán, đó là thiên tước. Công khanh đại phu,\nđó là nhân tước\". Người xin được quẻ này phải nắm vững chủ kiến, lựa chọn cẩn thận, chứ có bốc đồng\ngặp đâu hay đó.\nQuẻ nói: Công danh dù có mà thực tế có gì đâu? Bởi trong đời bạn “sanh không đem lại, chết chẳng đem\nđi\". Nên công danh tiền tài đều như mây khói, chẳng có gì đáng màng lắm. Nếu bạn muốn muôn thuở bất\nhủ thì hãy tu hành. Ý quẻ muốn rằng: Việc cầu xin của bạn tuy được thông hạnh, nhưng phải làm việc\nphúc đức thì mới được hưởng bền.\nTu là cội phúc. Còn tất cả là hư không. Sống gửi thác về, rồi cuộc đời cũng ra ma mà thôi. Cầu xin còn\nchậm. Đánh số ít hạp.", "g": "Khi làm việc không nên bỏ qua những chi tiết nhỏ nhặt, mà phải chú ý đặc biệt đến những tình\nhuống đột biến, tìm ra nguyên nhân của nó, thì mới không ảnh hưởng đến công việc.", "s": "9, 8, 2, 98, 82, 92."}, "291": {"c": "TRUNG HẠ", "hexagram": "Bát Thuần Cấn", "line_label": "Động Hào Tam", "p": "Tẩu tẩu tẩu,\nNgộ nhất cẩu.\nCấp tư tầm,\nKhả trường cửu.\nĐi đi đang chạy trên đường đi,\nGặp chó ta nên lấy làm kỳ.\nTheo dõi suy tư cho thật xác,\nMới mong yên phận hết lo gì.", "b": "Quẻ này có cái tượng thấy thỏ mà lại nhìn chó, lúc thấy chó hiểm rằng quá muộn. Nếu đem suy nghĩ tính\ntoán cẩn thận lại, thì may ra có thể đổi mối lo ra thành điềm lành, sinh kế do đó mà khả đã lâu bền được.\nNgười xin được quẻ này khi gặp việc, chớ nên do dự bất quyết.\nNhững việc cầu xin của bạn trước tiên phải thấu rõ việc làm và phải trải qua một thời gian dò xét, thì mới\nmong được kết quả như ý. Bởi quẻ tả cảnh của bạn như đang đi trên đường gặp một con chó. Vậy bạn nên\nnghĩ kỹ bài thơ trên, ắt giúp được sự nan giải đấy.\nĐang đông xông, tây đột, mà chưa nên gì. Phải suy cho kỹ, nghĩ cho cùng, thì công việc mới thành. Và\nphải gặp chó mới hay. Biểu tượng: chó. Đánh số dở.", "g": "Nhận được những tin tức vội gấp, đừng nên xem thường, có những sự biến hóa hoặc phản phúc\nkhông chừng đổi. Quan tâm là tốt.", "s": "29, 9, 2, 90, 20, 92."}, "292": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Cấn", "line_label": "Động Hào Tứ", "p": "Bất tri chân tiêu tức,\nTiêu tức mạch địa (hốt nhiên) lai.\nNguyệt viên nguyệt khuyết dạ,\nBất hứa khả môn kha.\nSao mà tin thiệt không hay,\nBỗng nhiên tin tức báo ngay trước thềm.\nTrăng tròn nay khuyết nửa đêm,\nChớ nên mở cửa mới êm việc nhà.", "b": "Quẻ này cho biết: Tin tức tuy có, nhưng cần phải dự phòng. Lúc đắc ý cần phải đề phòng lúc thất ý lại cần\nphải đề phòng tai vạ đến bất ngờ. Người ta sinh ra ở trên đời, suốt đời mình, không có ngày nào là không\nlo sợ đề phòng.\nTheo ý quẻ nói công việc cầu xin của bạn cần phải cẩn thận mới được yên vui. Bởi hai câu sau của quẻ thơ\nnói: trăng tròn nay khuyết, nửa đêm chớ nên mở cửa. Đó là dạy cho ta phải cẩn thận trong công việc.\nVậy những việc cầu xin của bạn ngoài sự cẩn thận, phải suy nghĩ cho kỹ lưỡng, nhứt là không nên đặt cao\nvọng quá và phải yên phận hơn. Thận trọng lúc hành động, chớ để kẻ dòm, bị phá hoại. Cầu sự chưa\nthông, chờ. Đánh số dở.", "g": "Tiến hành công việc điều quan trọng nhất là đầu tiên phải biết cẩn thận tính toán phương thức làm\ncho lớp lang thứ tự, mới tránh khỏi tai hại về sau.", "s": "2, 9, 1, 91, 19, 29, 92."}, "293": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Cấn", "line_label": "Động Hào Ngũ", "p": "Hỏa vương xứ, yếu bất bì,\nThủy thâm xứ, yếu bất ngốc.\nĐáo dầu dương chước lượng,\nVô đắc nhạ tha tai.\nLửa nóng nơi hồng chớ mối mê,\nVực sâu chỗ nước chẳng bề nề.\nDáo đầu mọi việc đều thương lượng,\nTai họa gây thêm ắt thảm thê.", "b": "Quẻ này chủ lặng lẽ tính suy mà quan sát sự biến động, để rồi do đó mà đặt kế chế nguy hoặc tìm ra\nphương pháp thích nghi. Đấy là diệu pháp để thao túng. Muốn thế chớ có câu chấp bảo thủ khiến trở thành\nnếp thành quy củ. Nếu được vậy ắt có thể tránh được thị phi, trái phải.\nVậy Người xin được quẻ này cần phải: bác học, thân tư, thân biện, minh biện, đốc hành. (học rộng, suy\nnghĩ cẩn thận, nhận xét rõ ràng tích cực hành động)\nTheo ý quẻ cho biết hiện nay vận trình của bạn còn trong vòng bế tắc chưa được hanh thông, cho nên tất\ncả những việc cầu mưu cần phải bền chí chịu đựng, thì mới có thể tạm yên, vì hai câu thơ đầu của quẻ đã\nmách dạy bạn vậy. Hơn nữa quẻ còn khuyên bảo rằng mọi công việc làm ăn cũng phải tính toán cho kỹ và\nđừng sơ ý rồi gây thêm rắc rối nữa thì phiền lắm.\nNhững việc cầu xin của bạn tốt hơn là tạm ngưng lại để chờ dịp. Nếu đã làm rồi, phải cẩn thận cho lắm.\nBất thông, bất minh, thận trọng cho lắm mới được, e có nguy hiểm. Sự cầu chưa thông. Đánh số tốt. Số\nhên: 29, 92, 2, 9, 22.", "g": "Được việc rồi cần thu gọn lại. Công thành thân thoái.", "s": ""}, "294": {"c": "TRUNG THƯỢNG", "hexagram": "Bát Thuần Cấn", "line_label": "Động Hào Lục", "p": "Bảo nhạn nhiều hồ, địa thành lục,\nHành kiến công huân tảo hồi trình.\nTham luyến chung phi thế nhân phúc,\nMạc giao kê vụ hội tương tranh.\nChim nhạn bay lượn mặt hồ,\nNhảy lên trên đất dậm dò mà đi.\nCông huân chẳng ngại điều chi,\nLập nên sự nghiệp chớ thì say mê.", "b": "Quẻ này chủ công thành thì thân thoái, chớ dấn thân mình mãi vào dòng danh lợi để đến nổi cầu vinh mà\nlại thành tìm nhục, mua vui mà lại thành chuốc khổ. Người xin được quẻ này nên biết rõ cái đạo xuất xứ.\nÝ quẻ tả rằng hiện nay thời vận của bạn như chim bay lượn rất là đắc ý, và khi con chim nhạn dậm chân\nxuống đất đi cũng biết dậm dò mà tiến bước, nghĩa là tránh được những cạm bẫy.\nVậy những việc cầu mưu của bạn ắt được toại nguyện như ý, như câu thứ ba trong quẻ nói công danh\nchẳng ngại điều chi. Nhưng câu chót của quẻ khuyên khi thành đạt thì nên chớ quá ham mê mà cứ tiến\nhoài sẽ vấp điều không hay.\nThời vận hanh thông. Công thành thân thối, thì sự ắt hay. Biểu tượng: Chim. Đánh số, tốt nhất nữa. Số\nhên: 3, 2, 9, 39, 93, 23, 32, 29.", "g": "Những lúc thời cơ thuận tiện nhất, hãy rán sức tìm cầu chức tước, tìm cầu người phối ngẫu, tìm\ncầu tiền bạc …thảy đều có lợi cả.", "s": ""}, "295": {"c": "THƯỢNG THƯỢNG", "hexagram": "Sơn Thủy Mông", "line_label": "Động Hào Nhất", "p": "Thiên thượng phong,\nThiên biên nguyệt.\nNguyệt bạch phong thanh,\nLưỡng lưỡng tương đắc.\nGió trời nay thổi hiu hiu,\nMặt trời sáng chói, mây điều phủ quanh.\nĐó là cảnh sáng gió thanh,\nĐiềm nhiên tương xứng, may lành hanh thông.", "b": "Quẻ này chủ trong sáng rõ ràng không có gì là xấu hổ giấu diếm, có cái vui tương đối với mọi người. Trái\nlại nếu có chút hôn trọc, mờ ám, bẩn nhơ, thì mọi người điều bỏ mình mà đi hết. Người xin được quẻ này\nnên lấy điều chính đại quang minh làm căn bản cho dự lập thân.\nÝ quẻ nói rằng: cảnh tình của bạn hiện nay như gió hiu hiu, mặt trời sáng chói nơi góc trời. Đó là một\ncảnh trời sáng gió thanh, nghĩa là cảnh tình hiện nay của người tốt, thời vận đã đến. Nên việc xin hỏi của\nbạn được thong dong hoàn hảo, chẳng có gì đáng lo.\nVận thời hanh thông, mã đáo công thành. Tốt đẹp, cầu được, ước thấy. Đánh số, hạp.", "g": "Sự sanh trưởng của vạn vật đi theo một qui luật tự nhiên mà phát triển. Con người cũng vậy, hiểu\nđược cái lý tự nhiên nầy thì được sống lâu và an nhàn.", "s": "4, 9, 2, 49,\n94, 92, 29, 42."}, "296": {"c": "HẠ HẠ", "hexagram": "Sơn Thủy Mông", "line_label": "Động Hào Nhị", "p": "Được qui căn tràn ngập thiên địa,\nThủy thanh nguyên, trùng lưu hà hải.\nNhân đắc kim đan,\nẮt sống mãi muôn thu \"Tràng sinh uyên hối\".\nDiệp lạc quy căn sanh cửu trường,\nNguồn trong chảy mãi đến sông Hương.\nThuốc tiên hái được người trường thọ,\nCuộc sống dài bền chẳng thể lường.", "b": "Quẻ khuyên ta uống nước phải nhớ nguồn, ăn quả phải nhớ kẻ trồng cây, nghĩa là phải nhớ tới nguồn gốc,\nchớ có quên cái đạo \"Tu sinh\" (nhận lấy sự sống). Muốn được vậy ta phải tìm cho kỳ được kim đan mới\ncó thể sống lâu. Kim đan ở đâu? Ở hai chữ \"nhiếp dưỡng\" (nuôi dưỡng) bản thân. Người nhiếp dưỡng ít\nphải chịu \"thanh tâm quở nhục\" mới được.\nÝ quẻ nói lá rụng xuống cội cùng với đất cửu trường, nguồn nước trong và chảy mãi ắt thông đến sông\nbiển, người hái được thuốc tiên, ắt trường sanh bất lão. Vậy những việc cầu xin của bạn hãy ráng lo như\nnước nguồn chảy mãi tới sông lớn. Nên tu tâm, dưỡng tánh, làm lành, tránh dữ thành thiện, thì tức khắc\nlàm ăn lành.\nNên lo việc tu hành. Tạo phúc cùng làm lành, ắt thân ta khỏi khổ, giàu sang, lại vinh danh. Đánh số tốt. Số\nhên: 5, 9, 2, 59, 92, 29, 95.", "g": "Hoa chẳng thê tươi đẹp trăm ngày—Cũng không có suốt ngàn ngày may mắn—Lúc đắc ý phải\nnghĩ đến lúc thất ý.\nKhi mọi việc đến một cách thuận lợi, phải lo đề phòng những việc đột biến hoặc tai ương có thể xãy đến.", "s": ""}, "297": {"c": "THƯỢNG THƯỢNG", "hexagram": "Sơn Thủy Mông", "line_label": "Động Hào Tam", "p": "Thừa nã khứ tràng an,\nKhán hoa hoa chính phát.\nNhất nhật vũ lai lâm,\nHương sắc tận điêu linh.\nLên đường cưỡi ngựa đến Trường An,\nHoa nở đầy đường chẳng ai màng.\nBỗng bị gió mưa mà thổi rụng,\nLàm cho hương sắc đều tiêu tan.", "b": "Quẻ này chủ sự bất đắc ý, chỉ tại thất bại, trụy lạc quá lẹ, trụy lạc, thất bại đều do ở sự kiêu căng mà ra.\nNếu biết giữ gìn cẩn thận thì đâu đến nổi hậu quả tai hại như vậy. Cho nên Người xin quẻ này phải coi\nnhư một roi quất vào mặt.\nHai câu đầu thực là tốt thay, thành ra cái việc cầu xin hãy nên suy tính. Tính thật kỹ là để tránh những điều\nkhông xảy ra cho bạn đó là ý quẻ mách ta thận trọng.\nTiền cát hậu hung, nguy hiểm đến điệp trùng, thận trọng đề phòng gặp cảnh không may xảy ra. Cần bố\nđức. Đánh số xấu.", "g": "Trước hết phải chịu đựng sự trui rèn mài sát, thì sau mới có được sức bền bĩ , vững vàng đối phó\nvới mọi trở lực trên đời.", "s": "2, 9, 6, 29, 96, 26, 92, 62."}, "298": {"c": "TRUNG TRUNG", "hexagram": "Sơn Thủy Mông", "line_label": "Động Hào Tứ", "p": "Mộc trưởng xuân thiên căn cán lão,\nTử thực tam thụ chi diệp diêu.\nMất điêu bất tạ,\nMất kiến căn lao.\nCây mọc trời xuân gốc rễ già,\nTrái mùa quả chín lá đâu ra.\nCành khô lá rụng chẳng chi hại,\nĐổi cũ rồi sau đó có mới mà.", "b": "Quẻ này chủ việc đời từng trải qua nhiều, có từng trải như vậy, mới thấy là già dặn, chẳng khác gì cây kia\ntuy mùa xuân lớn, mùa thu lá hoa tàn, nhưng lúc đó trái đã thành, gốc rễ đã to, đã ăn sâu xuống đất khiến\ngió mưa không thể làm cho tàn héo được. Gốc già lá tàn, đó là những chữ dùng để nói xét việc đời thâm\ntrầm. Người xin được quẻ này đích thị là một người sống trong hoạn nạn.\nHiện nay thời vận của bạn chẳng có gì xấu tuy công việc cầu mưu có vấp phải điều khó khăn và trở ngại,\ncũng không đáng lo buồn vì căn cứ bài thơ trên nói cây mọc trời xuân nghĩa là đúng thời. Câu chót nói đổi\ncũ rồi thì thành mới có như vậy đã mách rõ sự tốt đẹp cho biết.\nVậy sự cầu mưu của bạn ắt thành công mỹ mãn, dù gặp gì trở ngại đừng nên nản chí mà cứ tiến tới sẽ tốt\nlành theo sở nguyện. Sự sự sắp thông hạnh, cứ lo mà tiến hành, mọi việc đều suông sẽ, cần giữ một lòng\nlành. Tốt đẹp khỏi lo. Đánh số tốt.", "g": "Buổi sáng nổi lên “tam quang” (ba luồng sáng), buổi chiều ngơi nghỉ nổi lên “tam hoang” (ba\nđiều bỏ trôi). Nên kịp thời gắng sức, gặp việc chẳng thể chần chờ không phấn đấu tiến lên được.", "s": "7, 9, 2, 79, 92, 27, 29, 97."}, "299": {"c": "TRUNG THƯỢNG", "hexagram": "Sơn Thủy Mông", "line_label": "Động Hào Ngũ", "p": "Khiếu đạo, khiếu đạo,\nThiên tướng minh liễu.\nHà tất thân thủ thư mi ?\nPhản tổ cao bồng dáo lão?.\nTiếng người la lối om sòm,\nKêu la trời sáng đỏ lòm khắp nơi.\nSao còn chẳng chịu thức chơi,\nNgủ nghê mơ mộng cuộc đời trôi qua.", "b": "Quẻ này ý bảo: Thời cơ đã đến, cần nên tuốt kiếm đứng dậy múa đi, xông ra ngoài mà kiến công lập\nnghiệp chứ đừng so vai rụt cổ mãi trong xó nhà mà lỡ hết cơ hội. Người xin được quẻ này rất nên thừa\nthời mà hành động.\nÝ quẻ mách rằng hiện nay vận thời của bạn đã đến lúc hanh thông, bạn hãy nắm lấy dịp may nầy để tiến\nbước chớ lưng chừng rồi mất cơ hội, thì uổng lắm.\nVậy những việc cầu xin của bạn thành công hay thất bại đều do sự có biết nắm lấy thời cơ của mình hay\nkhông. Do đó bạn hãy gan dạ tiến lên, nhứt là trong dịp này ắt thành công.\nKhuyên ta chộp lấy thời cơ, kẻo muộn màng mất đó, vận thời đến rồi lo gì nữa. Đánh số thông.", "g": "Bất cứ sự vật hay hành động nào, thực là thực mà giả là giả. Một phen trải qua khảo nghiệm\nnhiều cách thì “bộ mặt thật ” sẽ hiện ra thôi.", "s": "8,\n9, 2, 89, 92 29, 28."}, "300": {"c": "THƯỢNG THƯỢNG", "hexagram": "Sơn Thủy Mông", "line_label": "Động Hào Lục", "p": "Dược nhĩ chân, phúc liễu ninh,\nTâm tề hậu, túc phân minh.\nThần trung thần, thanh đắc thanh,\nCố đắc khan, khả trường sinh.\nThuốc thiệt uống rồi ắt lành,\nBa thang sẽ thấy thần hồi thân.\nDồi dào sức khỏe mạnh hơn trước,\nGốc rễ vững vàng đỡ một phần.", "b": "Quẻ này cho biết: Nghề nghiệp không cần nhiều mà chỉ cần tinh. Tục ngữ có câu: Nhất nghệ tinh nhất\nthân vinh. Bởi thế chuyên hẳn một nghề đến chỗ tinh vi, thì việc mưu sinh thì còn có gì đáng lo ngại nữa.\nLúc đó thần thì thanh, khí thì sảng, tâm vừa nhàn mà thân lại an nữa. Đây là một tấm gương sáng soi\nchung cho tất cả ai ưa bao biện, nghề thì có nhiều nhưng chả tinh được nghề nào.\nTheo ý quẻ cho hay, cũng như theo kinh nghiệm của chúng tôi, những người cầu được quẻ này, và cầu về\ncông việc làm ăn, thì luôn luôn ứng vào là công việc ấy phải trải qua ba lần cố gắng mới đạt được ý muốn,\nvà sự thành đạt thực là tốt đẹp.\nVậy bạn hãy cố gắng nhẫn nại vượt qua những khó khăn nếu gặp rồi sẽ như ý. Thất bại, rồi mới thành\ncông. Cố gắng ắt nên việc. Đánh số hên.", "g": "đại cát đại lợi , mọi việc tả hữu đều có hậu thuẫn, yên tâm mà tiến tới thành công.", "s": "29, 92, 9, 99."}, "301": {"c": "THƯỢNG THƯỢNG", "hexagram": "Sơn Phong Cổ", "line_label": "Động Hào Nhất", "p": "*Thi：\nTam thiên tằng kết xã,\ntứ hải tận tri danh .\nTrường kỵ tuấn mã,\ntrực nhập thiên đình.\nDịch:\nBa ngày giao du kết bạn,\nbốn biển ai mà chẳng biết tên.\nCưỡi ngựa hay rong ruổi,\nchạy thẳng đến thiên đình.", "b": "(Cáng đáng việc của cha, có con giỏi, già nhưng không tai vạ, có nguy hiểm nhưng rốt cuộc có tốt lành.\nQuẻ này chủ về rong ruổi xa gần, tài lợi đến là đương nhiên. Người được quẻ này ắt hẳn là một người tài\nđức giàu sang. Mọi việc đều hanh thông.", "g": "", "s": ""}, "302": {"c": "TRUNG TRUNG", "hexagram": "Sơn Phong Cổ", "line_label": "Động Hào Nhị", "p": "Thi:\nNhàn lai phu tử xứ,\nngẫu nhiên ngộ nhất nhân,\nĐồng nhan hạc phát,\ntiểu lý sinh xuân\nDịch:\nKhi nhàn rỗi đến nhà thầy,\nbỗng nhiên lại gặp mặt một người tươi trẻ,\ntóc bạc trắng, nụ cười mang sắc xuân.", "b": "(Cáng đáng việc của mẹ. Hỏi bói thì không được)\nQuẻ này có tượng gặp gỡ quý nhân. Người được quẻ này thế nào cũng gặp được bạn tốt một cách bất ngờ.\nThời vận đã tốt lên, mưu cầu của bạn chẳng bao lâu nữa sẽ thành đạt. Hào này lợi cho đàn ông, không lợi\ncho đàn bà.", "g": "Người nầy được cát nhân tương trợ.", "s": ""}, "303": {"c": "HẠ HẠ", "hexagram": "Sơn Phong Cổ", "line_label": "Động Hào Tam", "p": "*Thi ：\nNhàn vân dã hạc vọng đông hành ,\nduy hữu hương nhân tiện thị tri âm ,\nKinh doanh bố trí lưỡng tam xuân ,\nliên nhai đăng hoả hậu ,\ncẩm phàm tiền trình .\n-Dịch:-\nMây trôi hạc nội hướng Đông bay\nChỉ có người làng mới là kẻ tri âm.\nKinh doanh tổ chức hai ba năm,\nnắm bắt hết đường đi nước bước,\nđủ sức giương buồm gấm thẳng xông phía trước.", "b": "(Cáng đáng việc của cha,có khó khăn nhỏ không bị tai họa lớn.)\nQuẻ này chủ về phiêu bạt về hướng Đông, bỗng gặp được đồng hương bèn kết làm tri âm, cùng nhau mưu\ntính việc làm ăn. Sau khi trải qua hai ba năm làm ăn vất vả đã tạo lập được sự nghiệp. Người được quẻ\nnày, nếu muốn hoạt động kinh doanh, nên thực hiện ở miền Đông, và phải hợp tác với người đồng hương\nthì mới thành công. Hiện thời vận của bạn đã bắt đầu hanh thông. Nhưng chưa thể thành đạt được ngay.\nCông việc còn phải trải qua vài ba lần gian nan vất vả rồi mới ổn định.", "g": "Nên có thái độ làm việc trong sự thung dung nhàn hạ, không nóng vội đòi hỏi kết quả đến sớm.\nVừa làm vừa rút tỉa kinh nghiệm trong vài năm, sau đó thì ung dung làm việc được tốt thôi.", "s": ""}, "304": {"c": "TRUNG TRUNG", "hexagram": "Sơn Phong Cổ", "line_label": "Động Hào Tứ", "p": "*Thi ：\nHán thuỷ vô tình ,\nThục thuỷ trừng thanh ,\nhuỳnh hà cổn cổn ,\ntứ xứ yên trần .\n-Dịch:-\nNước sông Hán vô tình,\nnước của đất Thục rất trong,\nHuỳnh Hà chảy xiết,\nbốn xứ đầy khói bụi.", "b": "(Đối với công việc của cha, nói gì cũng nghe theo, ra đi có lo lắng)\nQuẻ này chủ về sự bất an, không có cách gì làm cho dừng lại được, chỉ có đi nơi khác thì mới yên. Người\nđược quẻ này sẽ gặp nhiều khó khăn trên con đường lữ hành. Vì vậy những mưu cầu của bạn trong thời\ngian này khó mà toại nguyện. Mọi việc đều bất lợi, bất thông, phải chờ đợi.", "g": "Đục thì vốn nó đục, còn trong thì nó vốn trong, chúng ta hãy tự làm trong sạch cho bản thân, lấy\nđó mà đi trên đường đời hiểm ác hỗn loạn, mới được an toàn.", "s": ""}, "305": {"c": "TRUNG HẠ", "hexagram": "Sơn Phong Cổ", "line_label": "Động Hào Ngũ", "p": "*Thi ：\ntiềm long dĩ thụ khốn ,\nthượng bất kiến vân hưng ,\ntrữ khan vân tứ hợp ,\nphi khứ đáo thiên đình .\n-Dịch:-\nrồng nằm đã thọ khốn,\nnên chẳng thấy mây nổi,\nlâu sau mây bốn phương hợp lại,\nbay thẳng đến thiên đình.", "b": "(Cáng đáng việc của cha được khen ngợi)\nQuẻ này chủ về người sau tiếp nối người đi trước, công danh chậm chạp, thời vận hiện còn chưa đến.\nNgười được quẻ này chớ nên vội vã và hiện tại công việc của bạn chưa hanh thông. Cần phải chờ đợi một\nthời gian nữa thì mới có lợi. Cần ẩn nhẫn chờ thời.", "g": "Người được quẻ nấy tạm thời gặp chuyện gãy đổ, trước mắt nên ngưng lại công việc để chờ thời\ncơ thuận tiện rồi làm mới tốt.", "s": ""}, "306": {"c": "HẠ HẠ", "hexagram": "Sơn Phong Cổ", "line_label": "Động Hào Lục", "p": "*Thi：\nthử xứ tư vị nùng ,\nnùng diễm bất nại cửu ,\nhà như đàm tiếu sinh phong ,\nđảo hảo đông bôn tây tẩu.\n-Dịch:-\nXứ nầy có mùi vị nồng,\ncái đẹp sắc sảo thì không bền,\nsao bằng cười nói sanh gió (có ảnh hưởng mạnh),\nkhỏi cần phải chạy Đông chạy Tây.", "b": "(không làm quan, không theo Vương hầu, chỉ theo sự nghiệp của mình, đó mới cao thượng)\nQuẻ này chủ về việc xử thế tiếp vật, chớ nên sai lầm. Khi người nhường mình thì mình nhường lại. Lúc\nnào cũng cứ tươi cười vui vẻ, nhưng lòng thì luôn giữ lập trường của mình, đó là bí quyết. Thời vận của\nbạn hiện nay, việc mưu cầu dù có đạt thành đi nữa cũng không bền, chung quy chỉ được vui vẻ trong một\nchốc lát mà thôi. Cần ẩn nhẫn đợi thời cơ hanh thông hơn.", "g": "Hoa tốt chẳng thường nở, một ngày nào có gặp nơi tuyệt đẹp (như ý) đi nữa, cũng bình thản mà\nsống, để ẩn náu mà mưu việc lớn sau nầy.", "s": ""}, "307": {"c": "HẠ HẠ", "hexagram": "Sơn Thiên Đại Súc", "line_label": "Động Hào Nhất", "p": "*Thi ：\ngiá lí hữu tiểu nhân ,\nthiết mạc sáo lưu đình ,\nmang đả điểm , hảo khởi hành ,\nnhật nguyệt như thệ vật cửu tồn .\n-Dịch:-\nNơi nầy có tiểu nhân,\nđừng gắn bó lưu lại, giờ tốt đến,\nmau lên đường,\ncó nhật nguyệt chứng minh vật còn tồn tại lâu dài.", "b": "(Hào này có tượng khó khăn, lợi về việc cử hành lễ tế tự)\nQuẻ này chủ về nên tránh bọn tiểu nhân. Mưu cầu của bạn đang bị bọn tiểu nhân phá hoại, bạn đừng nên\nlưu luyến công việc này, hãy từ bỏ nó ngay. Dây dưa chần chờ cũng chẳng được tích sự gì. Phàm ở đời,\nnhân tình ấm lạnh, gió mưa bất thường, hãy đề phòng tiểu nhân. Việc mưu cầu hiện còn khó định, cần\nphải đi xa, và thay đổi công việc mới mong thành đạt.", "g": "Việc muốn hỏi có thể bi kẻ tiểu nhân quấy rối ngăn trở, tranh đua với chúng vô ích, tìm cách lánh\nxa là tốt.", "s": ""}, "308": {"c": "TRUNG TRUNG", "hexagram": "Sơn Thiên Đại Súc", "line_label": "Động Hào Nhị", "p": "*thi ：\nlong sanh đầu giác,\ntương phái cam lâm ,\nlục thất bát tảo ,\nhảo tế thương sinh .\n-Dịch:-\nRồng sanh sừng trên đầu,\nsẽ có mưa dầm lớn,\nsớm là sáu bảy tám ngày nữa,\ncứu giúp cho người đời", "b": "(Xe bị rơi cái trục)\nQuẻ này có tượng tạm thời hãy giữ gìn cẩn thận, sắp đến vận hanh thông, nhất là vào khoảng tháng 6,7,8,\nchắc chắn có chuyện vui. Người được quẻ này thời vận đã tới lúc tốt đẹp. Nhưng muốn thành đạt sở\nnguyện thì hãy sớm tính toán và cố gắng bước nhanh tới mới được kết quả mỹ mãn.", "g": "Đây là quẻ có cảm ứng, nếu cầu chức tước sự nghiệp , gặp người tuổi Thìn sẽ được trợ giúp. Nếu\ndời chỗ ở chỗ làm, chọn ngày có số sáu, bảy, tám thì được thuận lợi.", "s": ""}, "309": {"c": "TRUNG THƯỢNG", "hexagram": "Sơn Thiên Đại Súc", "line_label": "Động Hào Tam", "p": "*Thi ：\nThái Bạch hiện Tây Nam ,\nlong xà tương cạnh trục ,\nlong tự phi thượng thiên ,\nxà khước bị hình lục .\n-Dịch:-\nSao Thái bạch hiện ở Tây nam,\nrồng rắn đánh đuổi nhau,\nrồng tự bay lên trời,\ncòn rắn bị phân thây.", "b": "(Ngựa giỏi bị mất. Hào này có lợi cho người hỏi về việc gian nan. Lời hào bảo hãy giữ gìn xe cho tốt, đi\nxa có lợi)\nQuẻ này chủ về tranh cạnh, chiến đấu gian nan, vất vả. Nhưng hiện thời đã đến lúc hanh thông. Song\nnhững toan tính sẽ phải cạnh tranh với bọn tiểu nhân. Rốt cuộc chính cũng thắng tà. Cầu tài, cầu danh đều\nđạt thành.", "g": "Quẻ nầy để chỉ cho người hãy nhớ câu:- “Thiện ác đáo đầu chung hữu báo” (thiện ác cuối cùng\nđều có báo ứng)", "s": ""}, "310": {"c": "TRUNG TRUNG", "hexagram": "Sơn Thiên Đại Súc", "line_label": "Động Hào Tứ", "p": "*Thi:\ntằng bả thụ tài ,\ndã yếu đãi xuân lai ,\nđông phong niệu niệu ,\nkhai biến hoa nhai .\n-Dịch:-\nđã từng trồng cây,\nbiết chờ mùa Xuân đến,\ngió đông hây hẩy,\nnở rộ đường hoa.\n-Giải：-Có hai ý:- 1.- đã có cày cấy, ắt có thu hoạch. 2.-Vì việc nào đó mà lao tâm tận lực, nhưng phải\nchờ thời cơ tốt và người trợ giúp mới thành .", "b": "(Nhốt con trâu nhỏ để nuôi dưỡng nó. Hào này không có tai họa)\nQuẻ này có tượng trở ngại, phải chờ đến mùa xuân hoa nở mới có thể thuận buồm xuôi gió. Trong lúc này\nnên tu dưỡng chí khí và tài nghệ của mình cho thành thục, đợi đến lúc thời mà hành động. Việc mưu cầu\ncủa bạn đã cố công vun trồng thì sẽ đến ngày hái quả. Bạn chỉ cần ráng chờ đợi một thời gian nữa, ắt ý\nnguyện sẽ đạt thành.", "g": "", "s": ""}, "311": {"c": "TRUNG TRUNG", "hexagram": "Sơn Thiên Đại Súc", "line_label": "Động Hào Ngũ", "p": "*Thi：\nTứ thập dư niên khổ dĩ thâm ,\nnhi kim nhữ lạc độ quang âm ,\nmạc trù luận.\nÂn ái thượng đa hoan hỉ sự ,\ntích thậm thanh xuân ,\nbất giảm thanh xuân .\n-Dịch:-\nHơn bốn mươi năm khổ đã nhiều,\nmà nay mới được hưởng ngày vui,\nđừng lo tính.\nNhiều năm ân ái vui chung hưởng, tiếc nuối thuở thanh xuân, đâu thể nào níu kéo lại được.", "b": "(Nhốt con heo thiến trong chuồng. Hào này cát tường)\nQuẻ này có tượng “Khổ tận cam lai”. Phúc đến tuy muộn nhưng chớ nên buồn phiền. Người được quẻ này\nphải biết thương tiếc tuổi xuân của mình. Mưu cầu của bạn sẽ thành đạt nhưng hơi chậm, cần ẩn nhẫn một\nthời gian.", "g": "Quẻ nầy khuyên người nên biết “tri túc”, để có thể hưởng thụ cuộc sống trải qua ngày tháng,\nđừng bỏ phí mà hối tiếc sau nầy.", "s": ""}, "312": {"c": "HẠ HẠ", "hexagram": "Sơn Thiên Đại Súc", "line_label": "Động Hào Lục", "p": "*Thi：\ntam đông túc ,\nvăn nghệ tinh , đáo đầu xứ ,\ndiệc thành băng , cấp cấp hồi thủ ,\nvật ngộ tiền trình .\n-Dịch:-\nba mùa Đông vừa đủ,\nnghề văn đã tinh thông, việc đến lúc sau cùng,\nbổng trở thành băng giá, mau hồi đầu tỉnh ngộ,\nđừng lầm lẫn đi tiếp.", "b": "(Dựa vào sự che chở của trời. Hào này thuận lợi) Quẻ này nói về vi ệc công danh không thành, chi bằng\nhãy mau mau đổi sang nghề khác, nếu chậm sẽ không kịp. Người được quẻ này nên gấp rút thay đổi nghề\nnghiệp. Những mưu cầu của bạn cugnx nên xem xét lại mà thay đổi thì mới có tương lai vui vẻ. Thời vận\ncòn lận đận, chưa mấy hanh thông. Cần phải cố gắng nhiều, và biết nắm bắt thời cơ mới.", "g": "Việc muốn hỏi có liên quan đến vấn đề luật pháp, mau sửa đổi chỗ sai sót để công việc được an\nổn.", "s": ""}, "313": {"c": "TRUNG THƯỢNG", "hexagram": "Sơn Địa Bác", "line_label": "Động Hào Nhất", "p": "*Thi ：\nkỳ quái kỳ quái ,\ntiền Phiên lai liễu ,\nkim Phiên hựu lai ,\ncẩn thận đề phòng ,\nvật bị lộng hoại .\n-Dịch:-\nkỳ quái kỳ quái,\ngiặc Phiên trước đến rồi,\nnay lại giặc Phiên đến, cẩn thận đề phòng,\nđừng xem thường nó mà nguy hiểm.", "b": "(Cái giường bị gãy chân, hư hỏng, hào này hung hiểm)\nQuẻ này có tượng tai vạ thường đến liên tiếp. Nếu không đề phòng cẩn thận thì làm sao tránh được nguy\nhại. Người được quẻ này phải cố gắng phòng bị cho nghiêm mật. Muốn công việc được đến nơi đến chốn\nhãy bền lòng. Rút kinh nghiệm cũ và có kế hoạch tỷ mỉ rồi mới tiến hành.", "g": "Việc muốn hỏi lâm vào tình cảnh quái dị, nên đề phòng sanh biến, mới khỏi hư hại việc lớn.", "s": ""}, "314": {"c": "THƯỢNG TRUNG", "hexagram": "Sơn Địa Bác", "line_label": "Động Hào Nhị", "p": "*Thi ：canh ngưu phục , tích thổ khai cương , toạ khan thu hoạch , thử tắc đạo lương .\n-Dịch:- trâu cày nằm, đất vua mở ranh giới, ngồi chờ thu hoạch, lúa nếp lương thực.", "b": "(Sửa sang cái giường hư hỏng, vẫn không dùng được. Hào này hung hiểm.)\nQuẻ này chủ về làm biếng thì nghèo, siêng năng thì giàu có. Xưa nay chưa có kẻ nào làm biếng mà có thể\ntrở nên giàu sang. Người được quẻ này muốn giàu có, trước hết phải siêng năng cần kiệm. Hiện vận thời\ncủa bạn đã đến lúc hanh thông, mọi mưu cầu đều sẽ toại nguyện, nhưng phải nỗ lực nhiều.", "g": "Được quẻ nầy, coi như là “lấy khỏe chờ mệt” , là vận hưởng thụ thành quả làm ra.", "s": ""}, "315": {"c": "TRUNG HẠ", "hexagram": "Sơn Địa Bác", "line_label": "Động Hào Tam", "p": "*Thi ：yêu hạ bội thanh bình , bộ nhập kim loan điện , phúc hộ tam sơn , thiên truỳ bách liên .\n-Dịch:- lưng đeo đai “bèo xanh”, bước vào điện Kim Loan, che chở cho ba núi, ngàn cây chùy, trăm dây\nxích.", "b": "(Bị hỏng nhưng không có tai họa)\nQuẻ này chủ về phàm làm việc gì cũng vậy, chẳng phải hễ bắt tay vào là xong ngay, trái lại cần phải bỏ\ncông sức ra lâu ngày chày tháng mới thành. Hiện thời vận số của bạn rất tốt, có quyền thế, nhưng muốn\nđạt thành sở nguyện thì phải trải qua rèn luyện thử thách nhiều phen nữa mới được.", "g": "Người được quẻ nầy là người lập công trạng nổi tiếng, là nhân vật số một đứng đầu trong việc\nhành nghiệp. Việc muốn hỏi rất là vững vàng và thành công chắc chắn.", "s": ""}, "316": {"c": "TRUNG TRUNG", "hexagram": "Sơn Địa Bác", "line_label": "Động Hào Tứ", "p": "*Thi ：sồ điểu phi cao , xuất cốc thiên kiều , long thần nha trảo , biến hoá hải đảo .\n-Dịch:- chim non bay cao, ra khỏi hang ổ, răng móng long thần, biến hóa hải đảo.", "b": "(Lửa ở đầu giường. Hào này hung hiểm)\nQuẻ này có tượng từ thấp mà lên cao, từ nhỏ mà thành lớn, biến hóa vô cùng bất trắc. Những mưu cầu của\nbạn khó mà đạt thành trong lúc này, phàm việc gì cũng phải cẩn thận lo liệu. Vì sự cố nguy hiểm luôn đến\nthình lình.", "g": "Chim non dụ cho những kẻ mới học nghề, chưa tinh thông , chưa biết trời cao đất dày thế nào,\nmà đã muốn ra ngoài xã hội, đương nhiên là phải hứng chịu biết bao sóng gió dập vùi khổ sở.", "s": ""}, "317": {"c": "TRUNG TRUNG", "hexagram": "Sơn Địa Bác", "line_label": "Động Hào Ngũ", "p": "*Thi ：-cát cát cát , tầm thường nhất dạng song tiền nguyệt ,\n-hung hung hung , hữu liễu mai hoa tiện bất đồng ,\nhàm tiếu hướng đông phong , nhân tình bất tỉ cựu thời nồng .\n-Dịch:- -tốt tốt tốt, một dạng tầm thường, trăng trước cửa sổ.\n-xấu xấu xấu, có những hoa mai không giống nhau\nHướng về gió đông mà nở ra (như nụ cười), nhân tình ngày nay không còn nồng hậu như xưa nữa.", "b": "(Cung nữ phi tần được được sủng ái, giống như xâu cá. Hào này không có gì không cát lợi)\nQuẻ này chủ về khi khi tốt lành thì rất bình thường. Nhưng khi vận rủi đến thì thì tình đời liền đổi thay.\nNhững mưu cầu của bạn chẳng xấu, mà cũng chẳng tốt lắm. Thời vận bình thường, nên ẩn nhẫn chờ thời\ncơ tốt hơn.", "g": "Người được quẻ nầy sợ rằng đang lâm vào việc không tốt, việc nầy có liên quan đến sự bạc bẻo\nthường tình của con người .", "s": ""}, "318": {"c": "HẠ TRUNG", "hexagram": "Sơn Địa Bác", "line_label": "Động Hào Lục", "p": "*Thi ：đại hoả viêm viêm , nghi thuỷ tương tế , bảo đỉnh đan thành , hân thiên yết địa .\n-Dịch:- lửa lớn hừng hực, được nước cứu chữa, giữ vẹn được cái đỉnh , báo cho trời đất biết.", "b": "(Trái lớn không ăn, quân tử được xe, tiểu nhân bị hư nhà tranh)\nQuẻ này chủ về mưu cầu của bạn rất là khó khăn, giống như lửa cháy lớn vậy. Nhưng nếu bạn biết cách\nđối phó, vượt qua khó khăn trở ngại thì sự việc chẳng có gì tai hại, mà còn thành công một cách huy\nhoàng.", "g": "bất cẩn sanh ra tai nạn nhưng tìm ra được biện pháp khắc chế. Nhưng nhớ sau nầy đừng để cho\ntái phát, không ai cứu nổi.", "s": ""}, "319": {"c": "TRUNG TRUNG", "hexagram": "Sơn Lôi Di", "line_label": "Động Hào Nhất", "p": "*Thi ：thiết tác nhất điều , vị bả cô châu hệ , kim đao nhất hạ , tảo bả đầu lạc địa .\n-Dịch:- một sợi tơ sắt, có thể buộc được chiếc thuyền côi, một phen hạ lưỡi đao vàng, có thể làm rơi cái\nđầu xuống đất.", "b": "(Bỏ con rùa thiêng của ngươi đi, hãy nhìn diện mạo của ta. Hào này hung hiểm)\nQuẻ này có tượng trôi nổi, nguy hiểm. Phàm mưu cầu việc gì, bạn hãy suy nghĩ kỹ lưỡng trước, nắm lấy\ncơ hội và biết lợi dụng những phương tiện chung quanh thì mới mong có được kết quả như ý muốn. nếu\nkhông, có thể sẽ gây nên hậu quả không hay.", "g": "Việc muốn hỏi cần phải dùng đao bén chém bừa vào các đám gai gốc để xử lý, mới tránh được tai\nnạn về sau.", "s": ""}, "320": {"c": "TRUNG THƯỢNG", "hexagram": "Sơn Lôi Di", "line_label": "Động Hào Nhị", "p": "*Thi ：thập nhị thời trung , khẩn cấp luyện trước , nhất khắc thiểu diên , vô xứ hạ cước .\n-Dịch:- trong mười hai thời, siêng năng khổ luyện, một khắc cũng không chậm trễ, còn chỗ nào để mà đá\ntrúng mình.", "b": "(Ăn cho xong, bị đánh đập ở gò núi, đi chinh chiến có hung hiểm.)\nQuẻ này cho biết lợi lộc vẫn còn đôi chút, chớ có chán nản mà lười biếng sẽ không còn chỗ đứng trên đời.\nNhững mưu cầu của bạn phải cố gắng lắm mới đạt thành.", "g": "Khi nhận nhiệm vụ nào, cần phải có thái độ tích cực là đem hết sức lực để đối phó mới tiến hành\nsuôn sẻ. Nếu mà để cho bị ngưng trệ thì rất khó khăn cho sự thành công.", "s": ""}, "321": {"c": "HẠ HẠ", "hexagram": "Sơn Lôi Di", "line_label": "Động Hào Tam", "p": "*Thi ：phong khởi Tây nam , hồng nhật đương thiên , kỳ môn diệu quyết , nhất chưởng năng trước .\n-Dịch:- gió khởi hướng Tây nam, mặt trời hồng ở trên trời, có được “diệu quyết” của pháp “Kỳ Môn”\nrồi, chỉ cần một chưởng là có thể nắm lấy.", "b": "(Bị người tát vào má. Hào này hung hiểm. Trong vòng 10 năm không làm được gì, chẳng có lợi ích gì cả.)\nQuẻ này có tượng phong ba nguy hiểm nổi lên. Người gặp quẻ này đang gặp nhiều khó khăn, chỉ còn cách\nẩn nhẫn đợi thời. Mọi mưu cầu còn phải chờ đợi lâu. Cầu danh cầu lợi đều khó.", "g": "Đang ở vào lúc thời cơ chín mùi, nhưng vẫn còn sự bán tính bán nghi. Những điều còn nghi ngờ,\nnay chắc chắn đã có đáp án rồi.", "s": ""}, "322": {"c": "HẠ TRUNG", "hexagram": "Sơn Lôi Di", "line_label": "Động Hào Tứ", "p": "*Thi ：vạn lại vô thanh tế , nhất nguyệt chính đương không , hốt bị vân già yểm , hạo phách phản mông\nlung .\nCó miệng mà chẳng mở lời được. Mặt trăng đang ở trên không, bổng bị mây che ám, khiến cho ánh sáng\ntrở thành mờ ảo không rõ.", "b": "(Được nuôi dưỡng. Hào này cát tường. Không có tai họa. Giống như con hổ nhìn mồi chăm chăm, mau lẹ\nthì thỏa mãn được mong muốn.)\nQuẻ này có tượng hung hiểm, nhưng rốt cuộc thì tốt lành. Người có quẻ này chẳng có gì phải lo sợ, lòng\ncứ giứ bình thản an nhiên, chẳng bao lâu mọi việc sẽ đâu vào đấy. Những mưu cầu của bạn ắt khó tránh\ngặp nhiều cay đắng, nên cố gắng vượt qua.", "g": "cẩn thận trong việc giao tiếp ứng xử cho chân chính, kẻo bị tai tiếng khó thanh minh. Người\nđược quẻ nầy, bị những người thù oán đang ngầm mưu hại rất nguy hiểm.", "s": ""}, "323": {"c": "TRUNG HẠ", "hexagram": "Sơn Lôi Di", "line_label": "Động Hào Ngũ", "p": "*Thi：nhất cá tri âm , khước tại thiên biên đẳng , thiết vật nhân tuần , tĩnh dạ đương tư tỉnh .\n-Dịch:- một kẻ tri âm, đã ở tận chân trời, chớ để tái phạm, đêm vắng đang mong nhớ ai.", "b": "(Cổ bị đau lở ra. Hào này ở nhà thì cát lợi, vượt qua sông lớn thì không có lợi)\nQuẻ này chủ về đừng có trông cậy người ở xa, mà phải trông cậy vào chính mình. Hiện việc mưu tính của\nbạn nên tự mình giải quyết, chớ có trông cậy mãi vào bạn bè, cần phải thực tế hơn. Nếu bạn tính toán kỹ\nlưỡng hơn thì việc ắt sẽ thành đạt.", "g": "Người được quẻ nầy đang ở vào tình trạng :-“quanh quá gấp và cô độc”, cần phải gấp điều chỉnh\nlại mới được.", "s": ""}, "324": {"c": "THƯỢNG THƯỢNG", "hexagram": "Sơn Lôi Di", "line_label": "Động Hào Lục", "p": "*Thi ：chúng khuyển tướng tụ , lệ xỉ giảo nha , dao đầu bãi vĩ , chỉ cố khan gia .\n-Dịch:- bầy chó tụ lại, nhe răng gầm gừ, đầu múa đuôi vẫy, chỉ để giữ nhà.", "b": "(Được nuôi dưỡng trong lúc đi săn bắn. Hào này vừa hung hiểm, vừa cát tường, việc vượt qua sông lớn có\nlợi)\nQuẻ này chủ về được người ta đem hết tâm lực ra mà sống chết với mình. Người được quẻ này, công việc\nlàm ăn tuy chưa được thuận lợi lắm nhưng sẽ có kết quả, mưu cầu của bạn chưa thông, chớ có cao vọng\nquá mà sẽ thất vọng. Cầu tài tạm được, cầu danh còn lâu. Nên đi làm ăn xa.", "g": "Người được quẻ nầy đang lâm vào tình trạng bị nhiều kẻ tiểu nhân bao vây làm hại.", "s": ""}, "325": {"c": "HẠ HẠ", "hexagram": "Sơn Hỏa Bí", "line_label": "Động Hào Nhất", "p": "*Thi ：thê tiền phu hậu nhất đồng hành , hảo tỉ tiên cơ triệu dĩ minh , quân nhược hữu tình tu thiết ký ,\nthập niên ân nghĩa mạc vong tâm .\n-Dịch:- vợ trước chồng sau cùng lên đường, chiếm được tiên cơ điềm đã sáng, nếu anh có tình nên gắng\nnhớ, mười năm ân nghĩa chớ tâm quên.", "b": "(Chăm chút ngón chân, bỏ xe đi bộ)\nQuẻ này chủ về việc giao du với người, cần phải có nghĩa có tình. Hãy nhớ công ơn kẻ đã giúp mình,\nkhông được vong ân bội nghĩa, vợ chồng hòa hợp thì mới tốt lành. Cầu tài cầu danh đều được, nhưng hơi\nchậm.", "g": "Đây là nói một cặp vợ chồng mà vợ mạnh chồng yếu. Người được quẻ nầy có thể sẽ gặp cảnh như\ntrên . Nếu đã như vậy, nên nhớ đến câu tình sâu nghĩa nặng mà sống với nhau.", "s": ""}, "326": {"c": "TRUNG TRUNG", "hexagram": "Sơn Hỏa Bí", "line_label": "Động Hào Nhị", "p": "*Thi ：thử phục huyệt , bản tự ninh , nhất lộ thủ , miêu tức cân , dương uy thân trảo , thử táng tàn sinh .\n-Dịch:- chuột nằm dưới hang, vốn tự an ổn, nếu ra khỏi hang, sẽ bị mèo bắt, ra oai giơ móng, chuột chết\nhết đời.", "b": "(Nên chăm chút cho đẹp râu)\nQuẻ này khen ta nên ẩn không nên hiện, nên ngụy trang chứ không chường mặt ra. Nên nhường nhịn mà\nkhông nên tranh dành. Hiện thời vận của bạn vẫn còn chưa thông, mọi mưu cầu của bạn đều khó được như\ný. Bạn nên yên phận, giữ gìn cách sống cũ, hãy ráng đợi chờ một thời gian nữa thì hay hơn.", "g": "phàm công việc thì nhất động không bằng nhất tịnh, giữ chặt cái gốc thì yên ổn vô sự. Hoặc có ý\nnói rán giữ kín những điều bí mật trong công việc đừng để sơ hở ra ngoài không hay.", "s": ""}, "327": {"c": "THƯỢNG THƯỢNG", "hexagram": "Sơn Hỏa Bí", "line_label": "Động Hào Tam", "p": "*Thi：thư trung hữu nữ nhan như ngọc , thư trung tự hữu huỳnh kim ốc , độc tận ngũ xa thư , chí nguyện\ntự năng túc , hà tất tiêu lao tâm trung mang lục .\n-Dịch:- trong sách có gái đẹp như ngọc, trong sách vốn có nhà cửa vàng. Học hết năm xe sách, điều mong\nmỏi sẽ đạt được. Chẳng cần phải lo lo lắng lắng quanh năm mà không chịu học.", "b": "(Trau chuốt, chăm chút đi, Hào này tốt lành về lâu dài)\nQuẻ này ngụ ý ngọc mà chẳng mài giũa thì chẳng thành ngọc quý, người chẳng học thì không nên người\ntốt được. Những mưu cầu của bạn rốt cuộc sẽ đạt thành một cách vô cùng tốt đẹp. Song bạn phải không\nngừng cố gắng thì mới được. Thời vận hanh thông, mọi việc thuận lợi.", "g": "", "s": ""}, "328": {"c": "HẠ HẠ", "hexagram": "Sơn Hỏa Bí", "line_label": "Động Hào Tứ", "p": "*Thi：báo biến thành văn thái , thừa long phúc tự trăn , xích thân thành phú quí , sự sự đắc chấn tân.\n-Dịch:-con beo trở thành vằn vện, cỡi rồng thì phúc tự đến, thân đỏ thành phú quí, mọi việc được thỏa\nlòng.", "b": "(Chăm chút cho sạch sẽ thơm tho, ngồi trên lưng ngựa trắng với dáng vẻ đường hoàng. Họ không phải là\ntrộm cướp mà đến để cầu hôn)\nQuẻ này chủ về tay trắng làm nên. Nếu bạn cố gắng và siêng năng ắt cuộc đời bạn sẽ hanh thông. Việc\nmưu cầu của bạn đều được như ý, không có gì đáng lo, nhất là về tình duyên. Cầu danh và lợi đều được.", "g": "Người được quẻ nầy sắp được rễ quí, từ đó cuộc đời thay đổi hẳn, hưởng vinh hoa phú quí không\nngớt.", "s": ""}, "329": {"c": "TRUNG THƯỢNG", "hexagram": "Sơn Hỏa Bí", "line_label": "Động Hào Ngũ", "p": "*Thi：cô dương vi hề , quần âm dật hề , lực kí đàn hề , tương bất khả mạo hề , chân cẩn thận hề , nghi\nkhả bảo hề .\n-Dịch:- chỉ có một dương thì ít ỏi, mà bị nhiều âm thì bao vây , sức đã hết rồi, phải cẩn thận cho lắm, mới\ncó thể giữ được cơ nghiệp.", "b": "(Vườn gò dược chăm chút như mới. Nhà trai dâng từng tấm lụa lễ vật biếu cho nhà gái. Hào này mới đầu\ngian nan, nhưng cuối cùng thì cát lợi)\nQuẻ này chủ về cô dương không địch nổi quần âm, cho nên phải cẩn thận lời ăn tiếng nói, cho đến việc\nlàm, giữ mình phải cẩn thận. Phàm mưu cầu việc gì cũng phải suy tính cho cho chu đáo. Nếu sơ ý là sẽ\nhỏng việc. Công việc lúc đầu gặp nhiều trở ngại, gian nan, nhưng rốt cuộc thì đạt thành. Đề phòng bị phá\nhoại.", "g": "", "s": ""}, "330": {"c": "HẠ TRUNG", "hexagram": "Sơn Hỏa Bí", "line_label": "Động Hào Lục", "p": "*Thi：hiểu vũ sơ tình ánh bích khê , trùng trùng xuân sắc thượng sài phi , huỳnh kim bất tận gia ân phú ,\nhà tất khu khu tiện cẩm y ？\n-Dịch:- mưa sớm vừa tạnh chiếu khe biếc, sắc Xuân tràn ngập vẻ xinh tươi, được hưởng vàng ròng luôn\nbất tận, sao còn tham vọng đòi áo gấm ? (quan chức)\n*giải：Quẻ nầy ngụ ý rằng:- một người đang hưởng cảnh giàu có, cứ bằng lòng với hiện trạng, sao lại\nkhởi tâm cầu quan chức hay kinh doanh làm chi nữa ?", "b": "(Chăm chút sạch sẽ. Hào này không có tai họa)\nQuẻ này chủ về tài vận hanh thông, nhất định sẽ thành cự phú, tiền vào như nước. Giàu thì có, nhưng danh\nthì không, vì vậy người được quẻ này đừng hy vọng có chức tước. Vận thời của bạn đã đến lúc hanh\nthông, từ đây về sau chẳng có lo âu gì nữa., cứ theo dự định mà tiến tới.", "g": "", "s": ""}, "331": {"c": "HẠ HẠ", "hexagram": "Sơn Trạch Tổn", "line_label": "Động Hào Nhất", "p": "*Thi：thế đạo đa kinh cức , nhân tình mỗi dụng ta , lợi danh như hữu lộ , cần khổ trục sinh nhai .\n-Dịch;- đường đời nhiều chông gai, tình người hay thay đổi, đang có hoàn cảnh hưởng lợi danh, cứ siêng\nnăng làm việc.", "b": "(Hãy mau đến tham gia lễ tế tự, sẽ không có tai họa. Tế phẩm có thể châm chước giảm bớt)\nQuẻ này chủ về suôt đời cần khổ mới dành dụm được đôi chút. Thế mới biết việc không trải qua thì không\nbiết khó. Việc mưu cầu của bạn sẽ gặp nhiều trở ngại, khó được như ý. Vì vậy, đừng than trời trách người\nlàm gì. Trong công việc làm ăn, bạn đừng kể gian nan, cứ tiến tới ắt được toại chí phần nào trong cuộc\nsống, nhưng đừng quá tham vọng, đừng làm việc gì quá sức mình.", "g": "Ta đang có duyên với danh lợi, chẳng cần phải bôn ba tranh đua với đời làm chi, cứ an thân giữ\nphận mà sống, siêng năng làm việc hàng ngày là tốt rồi.", "s": ""}, "332": {"c": "HẠ HẠ", "hexagram": "Sơn Trạch Tổn", "line_label": "Động Hào Nhị", "p": "*Thi ：sơn cùng lộ chuyển mê , thuỷ cấp châu nan độ , vạn sự mạc cưỡng vi , xuất xử tao nghiên đố.\n-Dịch:- Nơi cùng tận rừng núi, đường sá mờ mịt—Nước chảy xiết thuyền khó đi—Muôn việc đừng gượng\nlàm—Việc nào lại chẳng có người ganh ghét .", "b": "(Hào này có lợi cho người bói hỏi. Đi xa có hung hiểm. Vì vậy không nên giảm bớt binh lực, mà nên tăng\nthêm binh lực)\nQuẻ này chủ về có kẻ gian ghen ghét, đang tìm cách hại bạn, bạn nên giữ gìn cẩn thận và cố gắng hơn để\ntránh tai họa. hời vận của bạn đang rất xấu, hãy tạm ngừng mọi mưu tính lại, chờ vận bĩ qua rồi hãy tính.\nĐi xa không có lợi.", "g": "Lội suối trèo non để đi xa đều bất lợi. Nếu mang lấy ảo tưởng, khởi tham vọng mà một mình\nlàm việc, không thể nào tránh khỏi những hậu quả vô cùng ân hận.", "s": ""}, "333": {"c": "THƯỢNG THƯỢNG", "hexagram": "Sơn Trạch Tổn", "line_label": "Động Hào Tam", "p": "*Thi ：thời biên đa gian , chiến chiến căng căng , giới cẩn khủng cụ , như lí bạc băng , tu thức tiền trình\nnguy dữ hiểm , nhất lung phong lí nhất chi đăng .\n-Dịch:- nhiều lúc gian nan, chiến đấu không ngừng, phải hết sức cẩn thận, như giẫm trên băng mỏng, Cần\nbiết con đường trước mặt nhiều nguy hiểm, một lần gió thổi qua đèn bị tắt phải đốt lại.", "b": "(Ba Người cùng đi, sẽ có một người chạy mất, một người đi, thì gặp lại bạn trên đường)\nQuẻ này chủ về thời vận chuyển biến thành xấu. Người được quẻ này phải rất thận trọng mới mong tránh\nđược tai hại, lỗi lầm xảy ra ngoài dự liệu. Việc mưu cầu của bạn khó mà toại ý, nên ẩn nhẫn đợi thời.", "g": "-：Thời vận không tốt, những ngày sắp tới gặp nhiều sóng gió nguy hiểm, người được quẻ nầy phải\nhết sức đề phòng mới được.", "s": ""}, "334": {"c": "TRUNG THƯỢNG", "hexagram": "Sơn Trạch Tổn", "line_label": "Động Hào Tứ", "p": "*Thi ：nhất đoá hoa chi diễm cánh phương , thanh hương phức uất thấu lan phòng , thời phong xuy tống\nchung thành tiếu , hảo cú diên tiền tiến kỷ thương .\n-Dịch:- Một đóa hoa xinh, đẹp lại thơm—Mùi hương lan tỏa khắp phòng loan—Gió may thổi đến , mang\ncười đến—Trong tiệc dâng lên chén rượu ngon.", "b": "(Bệnh hoạn tiêu trừ, thân thể hồi phục mau chóng. Hào này không có tai họa)\nQuể này chủ về thời vận tốt đã tới. Người được quẻ này cứ việc làm theo dự định, nhất định sẽ đạt thành.\nCảnh tình của bạn đã tới thời kỳ lên hương rồi, hãy cố gắng tiến tới, mọi việc sẽ thuận buồm xuôi gió. Cầu\ntài cầu danh đều được.", "g": "Người được quẻ nầy, nếu là nữ thì vừa đẹp vừa thông minh, xa gần đều khen ngợi; nếu là nam\nthì có phẩm đức cao quí, được mọi người ca tụng tán dương.", "s": ""}, "335": {"c": "TRUNG THƯỢNG", "hexagram": "Sơn Trạch Tổn", "line_label": "Động Hào Ngũ", "p": "*Thi ：tự tùng trì thủ định , công tại chúng nhân tiên , biệt hữu phi thường hỉ , tuỳ long đáo cửu thiên.\n-Dịch:- từ lúc nắm giữ chặc, công đứng ở hàng đầu, có được vui hết mực, cỡi rồng lên cửu thiên.", "b": "(Có người đem đến cho con rùa đắt tiền. Đây là điều đang cần. Hào này rất cát tường)\nQuẻ này có những chuyện vui mừng ngoài dự liệu liên tục đến. Việc mưu cầu của bạn đã có những bước\nvững chắc, vì trước đây đã cố gắng bỏ công nhiều. Nhưng cũng đừng có quá tự đắc mà hỏng việc. Công\ndanh phú quý đã rõ ràng. Cầu danh cầu tài đều đạt thành.", "g": "Người làm việc gì, nếu có đủ tâm huyết và nghị lực, thì khả năng thành công rất lớn.", "s": ""}, "336": {"c": "TRUNG TRUNG", "hexagram": "Sơn Trạch Tổn", "line_label": "Động Hào Lục", "p": "*Thi：viễn thiệp ba đào nhất diệp châu , nhi kim thuỷ đắc quá than đầu , niên lai tâm sự tài thành tựu ,\nkhuất chỉ tùng tiền đa khả ưu .\n-Dịch:- Thuyền con đã từng đối phó với biết bao sóng gió mà nay được cặp bến an toàn. Sang năm ước\nnguyện được thành tựu, bỏ hết những ngày trước khổ lo.", "b": "(Không nên giảm bớt mà nên tăng thêm. Hào này không có tai họa. Với người bói hỏi là cát tường. Lợi về\nđi xa, có thể được kẻ nô bộc không có chủ)\nQuẻ này chủ về nên mạo hiểm tiến tới, đi xa có lợi. Lúc đầu tuy có gặp nhiều hiểm nguy trắc trở, nhưng\nvề sau lại được an nhiên ngồi hưởng thụ. Không còn phải lo ngại gì nữa. Bạn hãy nắm lấy thời cơ. Thời\nvận đã hanh thông.", "g": "Quẻ nấy rất tốt. mọi việc hanh thông, như:- tìm vật được, mưu sự nên, tìm phối ngẫu như ý, kinh\ndoanh có lời, xây dựng nhà cửa tốt.", "s": ""}, "337": {"c": "HẠ TRUNG", "hexagram": "Bát Thuần Khôn", "line_label": "Động Hào Nhất", "p": "*Thi：thụ quân chi lộc , cửu giáng trinh tường , doanh nhi bất phúc , thủ chi nãi xương , vô đãi vô kiêu ,\nvĩnh bảo an khang .\n-Dịch:- được hưởng lộc của vua, ban cho mình lâu ngày,đủ đầy không che lấp, chớ lười đừng kiêu ngạo,\ngiữ mãi mãi an khang.", "b": "(Đạp lên sương thu thì mới biết băng cứng mùa đông sắp tới)\nQuẻ này chủ về sáng lập nên sự nghiệp đã khó, giữ gìn nó còn khó hơn. Nếu không giỏi giữ gìn thì chỉ\nmột thời gian ngắn là sụp đổ. Người được quẻ này phải biết tiên liệu siêng năng, và đừng có kiêu căng thì\ngiữ được cơ nghiệp lâu dài. Cầu tài cầu danh đều đạt thành.", "g": "Người được quẻ nầy lâu ngày hưởng ân sủng lợi lộc, sinh hoạt sung túc, nay muốn khởi tâm khác\nhoặc kiêu mạn, có thể bị mất hết mọi thứ.", "s": ""}, "338": {"c": "HẠ HẠ", "hexagram": "Bát Thuần Khôn", "line_label": "Động Hào Nhị", "p": "*Thi ：-Vạn sự bất do nhân kế hiệu , nhất sinh tận thị mệnh an bài , mạc nghi sai ,\n-Mệnh lí hữu thời tổng hữu phận , hà tu lục lục hỗn trần ai , hưu tai ！\n-Dịch:- Muôn việc do người ham tính toán—Một đời số mệnh đã an bài, quả chẳng sai !\n-Tất cả vận thời của mệnh người, sao còn bươn chải chạy lăng xăng, dừng ngay !", "b": "(Phẩm chất thẳng thắn, khoáng đạt, dù kết quả quẻ bói không lý tưởng cũng chẳng có gì bất lợi)\nQuẻ này chủ về sức người khó thắng nổi mạng trời. Tuy vậy, chỉ ngồi trông mong vào mạng số thì cũng là\nhạ sách. Cảnh tình và thời vận của bạn trong giai đoạn này đã được an bài sẵn, chớ cưỡng cầu, đừng lo\nlắng làm gì cho mệt tâm, khổ chí. Mọi việc cứ làm hết mình, thuận theo tự nhiên thì không có gì hại.", "g": "“ mưu sự tại nhân , thành sự tại thiên” (người mưu tính việc, trời định kết quả) . Đối với tất cả\ncông việc, đừng tham lam mong cầu xa xỉ thái quá .", "s": ""}, "339": {"c": "TRUNG HẠ", "hexagram": "Bát Thuần Khôn", "line_label": "Động Hào Tam", "p": "*Thi ：nhất phiến ưu tâm vị khẳng hưu , hoa phùng xuân vũ diễm nan lưu , đắc ý qui hưu , thất ý qui\nhưu , tiên gia chỉ thử nhất trù mưu .\n-Dịch:- Một mảnh tâm lo thôi bỏ đi—Hoa gặp mưa Xuân hết đẹp gì—Đắc ý cũng lui mà thất ý cũng lui—\nTiên gia chỉ như vậy mà trù tính công việc.", "b": "(Đánh hạ nhà Thương, hào này có thể làm được việc đó. Như theo sự nghiệp của Vương, lúc đầu chẳng\nthành đạt gì nhưng về sau có kết cuộc)\nQuẻ này chủ về phú quý, nghèo hèn thảy cũng chỉ là một giấc mộng, chẳng có nghĩa lý gì, cho nên mọi lo\nlắng âu sầu, rốt cuộc cũng chỉ là tự chuốc khổ chứ có ích gì. Người được quẻ này dù thắng, dù bại cũng\nchẳng nên lo lắng bồn chồn, mà cũng chớ nên vui mừng hí hửng.", "g": "Việc muốn hỏi không được thuận lợi vừa lòng, bởi vì bị nhiều khó khăn, lo âu phiền não bao\nvây.\nNgười nữ được quẻ nầy đề phòng có những biến đổi về tình cảm hay sinh hoạt.", "s": ""}, "340": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Khôn", "line_label": "Động Hào Tứ", "p": "*Thi ：lưỡng nữ nhất phu , thượng hạ tương khư , âm khí thừa dương , dụng thị hao hư .\n-Dịch:- Hai gái lấy một chồng, dưới trên đều đuổi đi, khí âm lấn khí dương, dùng nó bị hư hao.", "b": "(Im lặng giống như thắt mirngj túi lại. Hào này không tai vạ nhưng cũng không được khen.)\nQuẻ này chủ về đàn bà lắm lời, Việc mưu cầu của bạn, đúng ra là hay lắm, giống như một người có hai\nvợ, lúc ban đầu thì thấy vui sướng tốt đẹp lắm. hưng lâu ngày rồi, sẽ thấy mệt nhọc mỏi mòn. Gia đình\ncàng về sau càng lộn xộn và khó phân xử. Nên thận trọng trong việc giao du, công việc nên quy về một\nmối.", "g": "Phải hết sức cảnh giác về những tai hại của việc đam mê nữ sắc, mà bớt đi sự ham luyến nó, như\nvậy mới tránh khỏi những đáng tiếc về sau.", "s": ""}, "341": {"c": "TRUNG TRUNG", "hexagram": "Bát Thuần Khôn", "line_label": "Động Hào Ngũ", "p": "*Thi ：song yến qui nam quốc , lai tầm Vương Tạ gia , hoa đường xuân tận tĩnh , tiến thử thác sinh nhai\n.\n-Hai con chim én bay về nước Nam, đến tìm nhà họ Vương họ Tạ, nhà đẹp Xuân yên tĩnh, cuộc sống gởi\nlại đây.", "b": "(Mặc áo lễ phục vàng đên tế lễ. Hào này rất tốt đẹp)\nQuẻ này chủ về gặp chủ tốt, cơm áo nhờ đó mà có chỗ nương nhờ. Người được quẻ này chớ nên đứng ra\ntự đứng ra một mình làm việc gì. Hiện thời vận của bạn đang gặp khó khăn, cần tìm người có khả năng\ngiúp mình. Việc mưu cầu của bạn cần có sự giúp sức của người khác mới đạt thành", "g": "Mệt mõi quay trở về, mọi cảnh vật đều đổi thay.", "s": ""}, "342": {"c": "TRUNG HẠ", "hexagram": "Bát Thuần Khôn", "line_label": "Động Hào Lục", "p": "*Thi ：mệnh vận kiển hề thời vi , tai ương cập hề thân bì , vọng Hoàng Thiên hề bất ngã cố , ta ngã thân\nhề bệnh tư nguy .\n-Dịch:- Vận xấu đến rồi chịu trái nghịch—Tai ương đến phải mệt cho thân—Cầu khấn Hoàng Thiên,\nkhông hộ trợ--Cha Mẹ thôi đành nguy hiểm thân.", "b": "(Rồng đánh nhau nơi hoang dã, máu chảy lênh láng)\nQuẻ này có tượng mọi việc đều tuyệt vọng, tai họa tới tấp xảy ra. Người được quẻ này cần phải tích đức tu\nthân, may ra có thể chuyển nguy thành an. Trong giai đoạn này, mọi mưu cầu đều khó toại nguyện, vì hiện\nthời vận của bạn đang bế tắc. Những mưu cầu nên dừng lại, chờ qua thời vận bĩ này rồi hãy tính thì tốt\nhơn.", "g": "Không tốt, mọi việc chẳng nên làm.", "s": ""}, "343": {"c": "HẠ HẠ", "hexagram": "Địa Sơn Khiêm", "line_label": "Động Hào Nhất", "p": "*Thi ：thái dược thiên đài lộ chuyển mê , đào hoa lưu thuỷ phú giai kỳ , xuân phong đề điểu đa tình tứ ,\nký ngữ lưu lang thả mạc qui .\n-Dịch:- Hái thuốc trời xa đường chớ lạc—Hoa đào nước chảy hưởng sang giàu—Gió Xuân chim hót\nnhiều tình tứ--Gởi tiếng nhà Lưu chớ trở về.", "b": "(Quân tử khiêm tốn, nên vượt qua sông lớn. Hào này tốt đẹp)\nQuẻ này chủ về đi xa có lợi, ở cố hương chẳng bằng ở tha hương, cho nên chớ vội tìm đường về. Vì vận\ntốt đến là có kỳ hạn, không nắm bắt kịp thời thì nó sẽ qua đi. Cầu tài, cầu danh chỉ được trong thời gian\nngắn.", "g": "Quê người lập nghiệp thỏa lòng—Tri âm đã gặp , thành công mọi bề--Khuyên người chớ khởi ý\nmê—Tạm thời đừng nghĩ việc về cố hương.", "s": ""}, "344": {"c": "TRUNG TRUNG", "hexagram": "Địa Sơn Khiêm", "line_label": "Động Hào Nhị", "p": "*Thi ：xuất ôn nhập hàn , bị bạc y đơn , khứ ngã từ hàng , nan giải hoạnh khiên .\n-Dịch:- ra ấm vào lạnh, chăn đơn áo chiếc, hãy cứu giúp tôi, thoát khỏi nạn tai.", "b": "(Đã có danh vọng mà lại khiêm tốn, Hào này tốt đẹp)\nQuẻ này chủ về thời vận thay đổi, từ an thành nguy. Hiện cảnh tình của bạn đã chuyển may thành rủi, vận\ntrình không còn được gió thuận buồm xuôi gió, Bạn hãy nên khiêm tốn để giữ mình. Phàm những việc\nmưu cầu, hãy nên lấy hai chữ từ bi làm đầu thì mới hóa giải được những điều trở ngại và được bình yên.", "g": "Vì thời vận quá xấu và tự mình sai lầm nặng, nên không ai cứu giúp lúc nầy. Chỉ còn cách nhờ\nvào niềm tin của tín ngưỡng mình mà cầu cứu thôi.", "s": ""}, "345": {"c": "HẠ HẠ", "hexagram": "Địa Sơn Khiêm", "line_label": "Động Hào Tam", "p": "*Thi ：tam thăng tam thạch phóng tại nhất đấu , mãn nhi dật , tử tự đắc .\n-Dịch:- Ba thùng ba giạ chỉ đổ vào cái lít nên dư tràn ra ngoài, con sanh ra tự đắc.", "b": "(Siêng năng mà khiêm tốn. Quân tử sẽ có kết quả tốt)\nQuẻ này chủ về phải hợp sức mới tốt. Phàm việc mưu cầu của bạn cần phải nhờ người góp sức mà làm thì\nmới thành công. Quẻ này cầu lợi cầu danh đều được, nhưng hơi chậm.", "g": "Ý nói người ta không thể gọt bàn chân cho vừa với chiếc giày, cũng nói đến việc “hưởng thụ\nnhiều, tổn phúc đức” , nên cẩn thận chế giảm bớt.", "s": ""}, "346": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Sơn Khiêm", "line_label": "Động Hào Tứ", "p": "*Thi ：thuỳ thuyết cố hương vô tư vị , phiêu linh hồ hải tại thiên nhai , nhậm tư ta , trung thu nguyệt ẩn\n,xuân vũ lâm hoa , đa thiểu chinh nhân trường ức gia .\n-Dịch:- Ai bảo rằng quê xưa không có mùi vị, tại sao khi phiêu linh hồ biển đến góc trời lại nhớ cố hương\nquay quắt ? Nhất là những ngày Trung Thu không có trăng, mưa phùn lất phất khóm hoa, biết bao nhiêu\nchinh nhân tha thiết nhớ nhà !", "b": "(Không có gì bất lợi nếu hành động mà khiêm tốn)\nQuẻ này chủ về ở đất khách quê người không bằng trở về quê nhà. Người được quẻ này nên khiêm tốn mà\ncảnh tỉnh. Mọi mưu cầu của bạn tuy có trắc trở nhưng không có gì đáng lo. Nếu bạn xử trí cho đúng phép\nthì sẽ toại nguyện.", "g": "Người được quẻ nầy, quanh năm bôn ba lập nghiệp nơi xứ người, vào những đêm Thu quạnh\nquẽ, hết sức nhớ quê hương xứ sở.", "s": ""}, "347": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Sơn Khiêm", "line_label": "Động Hào Ngũ", "p": "*Thi ：vân tán nguyệt đương không , ngưu tiền mã hậu phùng , trương cung phương để ngự , nhất tiễn\nđịnh toàn công .\n-Dịch:- mây tan trăng trên trời—trước trâu sau ngựa, gặp—giương cung lên phòng ngự--Một mũi tên\nthành công.", "b": "(Bị nước láng giềng làm cho không giàu có thì nên đánh họ. Không có gì bất lợi)\nQuẻ này chủ về thời vận đã hanh thông. Nhưng bất cứ điều lợi gì ở đời cũng đều phải lao khổ mới có\nđược. Không có dâng không cho mình. Người được quẻ này nên tiến hành những việc mà mình mưu cầu\nthì nhất định sẽ thành công.", "g": "Được quẻ nầy, đến năm Tí và Mùi sẽ có cơ hội nhất cử thành công.", "s": ""}, "348": {"c": "HẠ HẠ", "hexagram": "Địa Sơn Khiêm", "line_label": "Động Hào Lục", "p": "*Thi ：mã tiến từ hàng tự hữu trình , nguyệt trầm tây hải nhật đông thăng , vận lai hà tất lao tâm lực ,\nphong tống giang hồ vạn lí thanh .\n-Dịch:-ngựa theo thứ tự bước lên đường—Trăng chìm xuống biển Tây , mặt trời lên hướng Đông—Khi\nvận tốt đến khỏi phải hao phí tâm lực—Gió đưa sông hồ ngàn dậm trong.", "b": "(Đã có danh vọng mà lại khiêm tốn. Hào này có lợi đối với việc dấy binh đi chinh phạt)\nQuẻ này có tượng hanh thông, việc chẳng cần phải mệt nhọc mà vẫn được. Việc mưu cầu cảu bạn ắt sẽ\nđược toại nguyện. Nhưng chậm, mà sự chậm chạp này mới vững bền.", "g": "Trước mắt vận hạn không tốt, công việc cứ chậm chạp rề rề, đêm ngày mệt nhọc. Rán đợi ít ngày\nnữa, sẽ có chuyển biến tốt, tình hình khả quan hơn.", "s": ""}, "349": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Thủy sư", "line_label": "Động Hào Nhất", "p": "*Thi ：vân hoành sơn tế thuỷ mang mang , thiên lí trường đồ vọng cố hương , kiển ách sự lai quân mạc\nhận , ỷ môn trù trướng lập tà dương .\n-Dịch:- Mây ngang đỉnh núi, nước mênh mông—Ngàn dậm đường xa nhớ cố hương—Khổ khó phủ vây,\nxin chớ hận—Buồn rầu tựa cửa ngóng tà dương.", "b": "(Quân đội xuất chinh cần phải có kỷ luật, không tuân thủ ắt có tai họa)\nQuẻ này chủ về người lữ khách cô đơn nơi xứ người, đang ở trong cảnh truân chuyên mà không người an\nủi thân thích hay giúp đỡ. Thời vận của bạn không có gì may mắn, những mưu cầu cảu bạn khó mà đạt\nthành theo ý muốn. Nhưng dù sự tình có ngặt ngèo đến đâu cũng đừng có oán thán, mà phải cố gắng vượt\nqua. Chờ đợi thời cơ mới đến.", "g": "Việc khốn khó đến với mình, một lúc không thể giải trừ liền được. Hãy giảm bớt rầu buồn , đừng\nkhởi tâm oán hận.", "s": ""}, "350": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Thủy sư", "line_label": "Động Hào Nhị", "p": "*Thi ：phong ba kim dĩ tức , châu tiếp ngộ an lưu , tự thử công danh toại , hà tu thán bạch đầu .\n-Dịch:- sóng gió nay đã yên—Thuyền tiếp tục lên đường—Từ giờ công danh toại—Sao còn than bạc đầu ?", "b": "(Ở trong quân, tốt lành, không tai vạ, còn được vua ba lần ban thưởng)\nQuẻ này chủ về họa đã qua, phúc đang đến. Mọi việc đều đang thuận buồm xuôi gió đến tuổi già. Người\nđược quẻ này sự nghiệp sẽ thành tựu, tình duyên sẽ như ý, công danh sẽ hiển đạt. Cầu tài lộc đều thuận\nlợi. Mọi mưu cầu đều như ý.", "g": "tất cả phân tranh đã dừng, từ đây về sau hành trình êm ái không còn hiểm nguy. Kinh doanh\nnhiều thuận lợi, thành công rồi nhớ đừng bắt chước số người hay sanh tâm tự mãn đó nhé !", "s": ""}, "351": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Thủy sư", "line_label": "Động Hào Tam", "p": "*Thi ：ba đáo bình an địa , giang sơn vạn lí trình , lục dương phương thảo xứ , phong khoái mã đề\nkhinh .\n-Dịch:- Đến nước ba an bình—Núi sông ngàn dậm qua—Nơi cỏ thơm dương xanh—Gió đưa ngựa phi\nnhanh.", "b": "(Trong quân có xe chở xác chết là có hung hiểm)\nQuẻ này chủ về tiến đến nơi nào là thắng lợi ở nơi đó. Vận trình đã đến lúc hanh thông, mọi mưu cầu sẽ\nnhư ý. Quẻ này không lợi về chinh chiến, tranh dành. Cầu danh cầu tài đều đạt.", "g": "Đã qua hết những ngày gian khổ, từ đây mọi việc sẽ an ổn tốt đẹp.", "s": ""}, "352": {"c": "HẠ TRUNG", "hexagram": "Địa Thủy sư", "line_label": "Động Hào Tứ", "p": "*Thi ：điêu ngạc đương thu thế chuyển hùng , thừa phong phân dực đáo thiềm cung , vinh hoa nhược\nvấn tương lai sự , tiên hậu danh thanh đạt cửu trùng .\n-Dịch:- Con chim điêu và con cá sấu vào mùa Thu, thế chuyển sang mạnh bạo—Nương gió sãi cánh đến\ncung Thiềm—Nếu hỏi việc vinh hoa ở tương lai—Trước sau danh thơm tiếng tốt cũng đến tai vua.", "b": "(Quân dừng lại trú binh nghỉ ngơi ở phía bên trái thì không tai vạ)\nQuẻ này chủ về nhân thời cơ thuận lợi mà hưng khởi, vừa dễ lại vừa nhanh lẹ. Ngày sau ắt sẽ thành tựu\nkhông thể lường được. Cảnh tình hiện nay của bạn giống như con chim ưng đang tung hoành trên bầu trời.\nNhững mưu cầu của bạn ắt sẽ toại nguyện trong những ngày gần đây.", "g": "", "s": ""}, "353": {"c": "HẠ TRUNG", "hexagram": "Địa Thủy sư", "line_label": "Động Hào Ngũ", "p": "*Thi ：thử vi hoạn chung tiêu bất đắc nịnh , miêu nhi nhất khiếu kỷ dạ thái bình , nhân khởi thức như\nthú , kỳ lý thậm phân minh .\n-Dịch:- Ban đêm chuột khó tránh khỏi tai họa, mèo kêu một tiến đêm sẽ bình yên. Nên biết việc người\ncũng tương tự việc của loài thú, lẽ ấy quá rõ ràng !", "b": "(Đi săn có thú, nên bắt tội nhân, không tai vạ. Con trai lớn ra quân, con trai thứ chở thây. Bói quẻ này có\nhung hiểm.)\nQuẻ này chủ về tà không thể thắng chính, điều cần nhất là phải đồng tâm hiệp lực để chống lại đối\nphương. Được vậy thì kẻ gian tuy đông cũng không có gì đáng lo ngại. Những mưu cầu của bạn cần phải\nnhở nhiều người giúp đỡ thì mới nên, nếu chỉ ỷ vào sức của một mình mình thì khó mà toại nguyện.", "g": "Kẻ tiểu nhân lúc đắc chí sẽ hiu hiu tự đắc ngông cuồng, nhưng thời gian ấy không kéo dài đâu!", "s": ""}, "354": {"c": "HẠ HẠ", "hexagram": "Địa Thủy sư", "line_label": "Động Hào Lục", "p": "*Thi ：lưỡng nhân tại bàng , thái dương tại thượng , chiếu nhữ nhất thốn tâm , tiên cơ tằng phủ minh.\n-Dịch- hai người hai bên, mặt trời ở trên cao, chiếu tấc lòng của anh, máy Tiên cơ từng không sáng.", "b": "(Vua ban thưởng, phong đất đai cho người có công, tiểu nhân chớ hành động)\nQuẻ này chủ về phò chúa có công sẽ được thưởng hậu. Người không có tài năng thì không được như vậy.\nVì vậy những mưu cầu của bạn thành công hay thất bại, đều là do tự mình làm lấy. Phàm mưu cầu việc gì\nbạn nên tính toán kỹ lưỡng, và làm việc đúng đắn, thì mới thành tựu.", "g": "Ngẫng đầu ba thước có thần minh luôn theo dõi con người nên chớ coi thường, công tội (phải\nquấy) đến lúc chết mới rõ ràng.", "s": ""}, "355": {"c": "TRUNG TRUNG", "hexagram": "Địa Phong Thăng", "line_label": "Động Hào Nhất", "p": "*Thi ：quân tử đạo tiêu , tiểu nhân đạo trưởng , âm khí uất uất , dương khí bất dương , như hà như hà ,\nlương cổ thâm tàng .\n-Dịch:- Đạo của quân tử thì nhỏ, đạo của tiểu nhân lại lớn, khí âm u ẩn, khí dương chẳng lên, biết làm\nsao đây ?—Cách hay nhất là “chôn sâu che giấu” nó đi.", "b": "(Tiến lên, rất tốt lành)\nQuẻ này chủ về dương bị âm áp chế, chỉ còn cách ẩn kỹ để đợi thời tiến lên. Người được quẻ này nên mau\nlo liệu, chớ nên tranh giành với bọn tiểu nhân trong lúc này. Hiện vận trình của bạn còn bế tắc, vì kẻ tiểu\nnhân đang bủa đầy. Những mưu cầu của bạn hãy nên tạm ngừng một thời gian.", "g": "Sống vào lúc mà đại trượng phu (quân tử) không thể phát triển được tài năng của mình, thì chọn\ncách “chôn sâu không để lộ ra” là thượng sách.", "s": ""}, "356": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Phong Thăng", "line_label": "Động Hào Nhị", "p": "*Thi ：khứ đáo Trường An , đông bắc chuyển giác , phùng trước thiên môn , tiện hữu hạ lạc .\n-Dịch:- đi tới Trường An (kinh đô), đổi hướng về phía Đông Bắc, gặp được cửa trời, liền có sự rơi xuống.", "b": "(Có điềm ứng rằng, cử hành lế tế xuân là có lợi. Hào này không có tai họa)\nQuẻ này chủ về đường công danh thuận lợi. Người được quẻ này chớ có chậm trễ do dự. Những việc mưu\ncầu của bạn sẽ được toại nguyện. Bạn muốn đạt thành sở nguyện thì phải đi theo hướng Đông Bắc.", "g": "chưa sáng sủa. tùy theo việc mà định liệu.", "s": ""}, "357": {"c": "TRUNG HẠ", "hexagram": "Địa Phong Thăng", "line_label": "Động Hào Tam", "p": "*Thi ：từ bộ nhập thiên đài , vi thính hảo tiêu tức , thái dược hữu tiên đồng , động phủ liệt xuân sắc.\n-Dịch:- thong thả vào thiên đài, nghe được tin tức tốt, hái thuốc có Tiên Đồng, trong động phủ hết sắc\nXuân.", "b": "(Lên theo hướng thành ấp ở trên đỉnh cao)\nQuẻ này cho biết thời cơ tốt đã hiện ra trước mắt, chỉ cần tiến lên mà lấy. Người được quẻ này rất nên cố\ngắng, những mưu cầu của bạn ắt sẽ thành công mỹ mãn, lại còn được quý nhân giúp đỡ. Vận thời hanh\nthông, cầu danh, cầu lợi đều được.", "g": "Tình trạng nầy không thể ngồi yên một chỗ được, phải tìm cầu người thân vấn kế, may ra có lối\nthoát cho mình.", "s": ""}, "358": {"c": "TRUNG TRUNG", "hexagram": "Địa Phong Thăng", "line_label": "Động Hào Tứ", "p": "*Thi ：tư lương nhất dạ , bất như đả cán nhất phiên , nhược hoàn thác , phiền não cập phế can.\n-Dịch:- suy nghĩ một đêm, không bằng bắt tay vào làm một lần, nếu còn sai sót, phiền não với gan phổi\n(đem hết sức ra suy nghĩ tính toán)", "b": "(Vua cử hành lễ tế ở Kỳ Sơn. Hào này tốt đẹp, không có tai họa)\nQuẻ này chủ về dù việc lớn nhỏ cũng phải quyết đoán, chứ không nên do dự, chần chừ. Suy nghĩ mãi sao\nbằng bắt tay vào làm. Lúc này là lúc bạn đang lên hương, hãy mau tiến hành công việc. Việc mưu cầu nếu\nchần chờ thì khó mà toại ý, lỡ dịp may hiếm có.", "g": "Lời quẻ nói đã quá rõ.", "s": ""}, "359": {"c": "TRUNG TRUNG", "hexagram": "Địa Phong Thăng", "line_label": "Động Hào Ngũ", "p": "*Thi ：tâm tế đảm thô , khả thắng thượng tướng chi nhiệm , dũng vãng tiền hành thành bại hà tất tại\ntâm , hung trung bả trì đắc định , địch nhân tự năng thụ khốn .\n-Dịch:- tâm nhỏ mật to có thể thắng công việc của thượng tướng, mạnh dạn tiến lên, việc thành bại nào\nchỉ do tâm, trong bụng đã nắm giữ sự định đoạt, kẻ địch sẽ tự thua mà thôi.", "b": "(Hào này tốt đẹp, lên cao từng bậc)\nQuẻ này chủ về phàm muốn làm việc gì thì phải lấy hết ruột gan ra để thực hiện, phải có dũng khí xông\ntới, lúc đó thành hay bại cũng chẳng sao. Nếu chỉ có vì chút ít trở ngại mà nhút nhát, sợ khó thì chẳng\nnhững công lao bao năm nay mất hết mà kẻ địch còn thừa dịp đến hại bạn. Người được quẻ này nên gan\ndạ tính toán cẩn thận, ắt được toại nguyện. Phàm việc thành hay bại là do ở trời mà cũng do sức mình.", "g": "Lời quẻ đã nói rõ ràng.", "s": ""}, "360": {"c": "HẠ HẠ", "hexagram": "Địa Phong Thăng", "line_label": "Động Hào Lục", "p": "*Thi ：thiên niệm khổ tu nhân , chung bất lạc hồng trần , thanh tâm năng kiến đạo , nhiễu nhiễu táng\nchân linh .\n-Dịch:- trời biết người khổ tu, rốt ráo không rơi xuống hồng trần, lòng trong trắng có thể thấy đạo, sự\nphiền nhiễu làm mất chân linh.", "b": "(Giữa đêm vẫn tiến lên. Hào này có lợi cho người không ngừng tiến lên phái trước)\nQuẻ này chủ về trời giúp cho kẻ có lòng thành. Việc mưu cầu của bạn sẽ được như ý, nếu bạn không\nngừng tu sửa bản thân, kiên trì tiến tới. Cầu tài, cầu danh còn chậm, nhưng sẽ đạt thành.", "g": "Đối với bất cứ chuyện gì cũng phải chuyên tâm trì chí mà làm, thì kết quả cũng không nhỏ bao\ngiờ.", "s": ""}, "361": {"c": "HẠ HẠ", "hexagram": "Địa Lôi Phục", "line_label": "Động Hào Nhất", "p": "*Thi ：bộ huỷ ư uyên , cầu ngư ư sơn , tùng triêu chí mộ , công phụ lực quyên , cải huyền dị triệt , thứ\nkhả đồ toàn .\n-Dịch:- Bắt tê giác (cái) dưới hang sâu, bắt cá trên núi, từ sáng đến chiều, sức lực mòn mỏi, sửa đổi cách\nlàm, may ra còn hy vọng.", "b": "(Đi chưa xa mà đã quay về, Hào này không có khó khăn, rất tốt đẹp)\nQuẻ này chủ về biết sai lầm thì phải sửa đổi. Nếu cố chấp mà không biết thay đổi bản thân thì hết sức ngu\nngốc. Người được quẻ này phải cẩn thận, chớ bước vào vết xe đổ, cần phải mau mau thay đổi sách lược\nthì mới thành công.", "g": "đã đi sai phương hướng mà còn sai cả phương pháp nữa, nên khó mà thành công được. Nên sửa\nđổi lại phương pháp và hướng làm , mới mong có thể thành tựu vào một ngày khác.", "s": ""}, "362": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Lôi Phục", "line_label": "Động Hào Nhị", "p": "*Thi ：thủ trì nhất mộc ngư , diên nhai khứ hoá duyên , bất kiến từ công lai , khước ngộ nhất điểu khứ .\n-Dịch:- tay cầm con cá gỗ (cái mõ) , trên đường đi hóa duyên (khất thực), chẳng thấy Ông Từ đến, chỉ gặp\ncon chim bay.", "b": "(Chớ quay về thì cát lợi)\nQuẻ này chủ về mưu vọng không được toại ý, làm mà không có công. Vận hạn lại điêu linh, tiến trình còn\nvận bĩ. Nhưng nếu không nản chí, cứ tiến tới ắt sẽ thành đạt. Người được quẻ này phải cố gắng nhiều. Cầu\ndanh cầu lợi sẽ đạt thành nhưng chậm.", "g": "Việc muốn hỏi e rằng chỉ bỏ công lao ra một cách vô ích.", "s": ""}, "363": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Lôi Phục", "line_label": "Động Hào Tam", "p": "*Thi ：thuỷ hoả kí tế , âm dương tương khế , dục vật tân dân , tham thiên tán địa .\n-Dịch:- được quẻ “Thủy hỏa kí tế”, âm dương khế hợp nhau, muốn đổi mới sự vật , nghiên cứu rõ lẽ trời\nđất (tự nhiên) mà làm.", "b": "(Nhăn nhó quay về, Hào này có nguy hiểm, nhưng không có tai họa)\nQuẻ này có tượng chí đồng mà đạo hợp, có thể cùng nhau làm việc lớn. Việc tuy có hung hiểm, nhưng biết\nthoái lui thì không sao. Đây chính là tượng hoạn nạn mà lại yên vui. Người được quẻ này quả là vận thời\nđến lúc lên hương. Mọi việc sẽ như ý. Có cầu là có ứng, cầu tài, cầu danh đều đạt thành.", "g": "Những xung đột cũ đã được hóa giải, chướng ngại đã tiêu trừ rồi, hoàn cảnh bây giờ rất tốt, thích\nnghi hoàn toàn với công việc.", "s": ""}, "364": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Lôi Phục", "line_label": "Động Hào Tứ", "p": "*Thi ：kỵ Ngọc Thố , đáo Quảng Hàn , ngộ Thường Nga , tương quế phàn , mãn thân phức uất , lưỡng\ntụ hinh hương .\n-Dịch:- Cỡi thỏ ngọc, đến cung Quảng Hàn, gặp Hằng Nga, bẻ cành quế. Toàn thân sực nức hương\nthơm. Hai tay áo cũng đầy mùi thơm.", "b": "(Đi giữa đường một mình quay lại)\nQuẻ này có tượng một thân một mình dám đi con đường riêng để lập nên sự nghiệp. Người được quẻ này,\nthời vận hiện đã sáng sủa lắm rồi, chẳng còn gì phải lo âu. Mọi mưu cầu sẽ được toại ý. Cầu tài, cầu danh\nđều đạt thành.", "g": "Người được quẻ nầy, cơ duyên tốt đặc biệt, gặp được quí nhân, như cỡi rồng vàng mọi việc đều\ntoại lòng xứng ý . Nếu hỏi về nhân duyên, gặp được kẻ “tâm đầu ý hợp”.", "s": ""}, "365": {"c": "TRUNG TRUNG", "hexagram": "Địa Lôi Phục", "line_label": "Động Hào Ngũ", "p": "*Thi ：nhất cá thần đạo , tuỳ nhĩ khứ hành , phùng nhân thuyết pháp , đáo xứ hiển linh .\n-Dịch:- một pháp thần đạo, tùy anh vận dụng, gặp người thuyết pháp, đền chỗ hiển linh.", "b": "(Mau mau quay trở về thì không có khó khăn)\nQuẻ này chủ vè thời vận hanh thông là cũng do con người biết sai mà sửa, tùy thời mà ứng đối. Mọi mưu\ncầu của bạn đều sẽ được như ý. Nhưng hãy nhớ một điều là chớ làm điều gì thất đức. Quẻ này cầu tài cầu\ndanh đều thành đạt", "g": "Người được quẻ nầy có được thủ pháp cao minh, giải quyết công việc của người rất linh hoạt\nhiệu quả, như có được “thần thông” tùy nghi sử dụng vậy.", "s": ""}, "366": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Lôi Phục", "line_label": "Động Hào Lục", "p": "*Thi ：lô trung hoả , sa lí kim , công lực đáo , đan đỉnh thành .\n-Dịch:- lửa trong lò, vàng trong cát, công lực đến, lò thuốc linh đan luyện thành.", "b": "(Lạc mất đường, cố quay trở về, Hào này hung hiểm, có tai họa. Lúc hành quân lạc đường ắt bị thua lớn.\nVua cũng sẽ bị nguy hiểm. Đến mười năm sau vẫn chưa thể chinh chiến.)\nQuẻ này chủ về công phu chưa đạt thì nguyện vọng chưa thể thành. Khai lò nổi lửa, đãi cát tìm vàng, quả\nlà chuyện khó khăn, vất vả. Người được quẻ này nhất thiết chớ nên vội vàng hấp tấp cầu tiến, mà phạm sai\nlầm. Mà cũng không thể ngồi nhìn mà nên việc. Những mưu cầu của bạn phải cần ráng sức, cố gắng có kế\nhoạch tỷ mỉ để tiến hành từng bước một, ắt có ngày thành đạt.", "g": "Công phu đúng mức, việc gì cũng làm xong.", "s": ""}, "367": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Hỏa Minh Di", "line_label": "Động Hào Nhất", "p": "*Thi ：thử khứ vạn lí trình , khước ngộ kiến tri âm , đồng tâm cộng tế , đại lập huân danh .\n-Dịch:- chuyến đi nầy dài mưo6n dậm, may gặp được tri âm, cùng nhau hợp tác, làm nên việc lớn.", "b": "(Con chim Trĩ bay lượn trên trời, vừa kêu vừa rủ cánh xuống. Người quân tử bôn ba trên đường, đã ba\nngày khoogn ăn. Có việc đi xa, chủ nhân có lời khen ngợi.)\nQuẻ này chủ về rất nên đi xa, đi xa có lợi ích mà còn được người phù trợ. Người được quẻ này chớ nên\nquyến luyến quê nhà mà phải tung hoành giang hồ thì mới có sự nghiệp lẫy lừng. Việc mưu cầu của bạn\ncứ thực hiện, ắt sẽ gập may mắn. Cầu tài, cầu danh đều được. Lợi ở phương xa.", "g": "Người được quẻ nầy, sắp có chuyến đi xa, đến nơi đó gặp được tri âm, nên gia thất với nhau, xây\ndựng sự nghiệp thành tựu mỹ mãn.", "s": ""}, "368": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Hỏa Minh Di", "line_label": "Động Hào Nhị", "p": "*Thi ：tầm phương xuân nhật , thích kiến hoa khai , đoá đoá kham trích , chi chi khả tài .\n-Dịch:- tìm mùi thơm ngày Xuân, vừa gặp hoa nở, mỗi đóa có thể hái, mỗi cành có thể trồng.", "b": "(Con chim trĩ kêu, bị thương ở đùi trái. Đó là bị người ngồi trên con ngựa khỏe đuổi bắn. Hào này cát\ntường)\nQuẻ này chủ về mọi việc đều như ý. Người được quẻ này mưu cầu bất cứ việc gì đều được tốt lành. Nhất\nlà về tình duyên, trai thì được vợ hiền, gái thì có chồng sang, hạnh phúc một đời.", "g": "Muốn làm công việc gì thì đây là thời gian thích hợp nhất, lại biết rõ ngọn ngành của nó, nên\nmọi việc đều đạt kết quả tốt.", "s": ""}, "369": {"c": "HẠ TRUNG", "hexagram": "Địa Hỏa Minh Di", "line_label": "Động Hào Tam", "p": "*Thi ：long nhất ngâm , vân tiện hứng , xung tiêu trực thướng , khoái đổ thái bình , vi văn vi vũ , quân\nquân thần thần .\n-Dịch:- rồng kêu lên, mây liền nổi, bay thẳng lên trời, nhanh thấy thái bình, làm văn làm vũ, vua vua tôi\ntôi.", "b": "(Con chim trĩ kêu, đi săn bắn ở phía nam, bắn được con lớn nhất, làm nó bị thương. Hào này bất lợi cho\nngười bói về bệnh tật)\nQuẻ này chủ về công danh toại nguyện, thẳng bước thang mây. Làm quan thì tạo được công lớn, được bạn\nđồng liêu đồng lòng. ĐI buôn thì chủ khách giao dịch mua bán thuận hòa. Hiện cảnh tình của bạn đã đến\nhồi lên hương. Nhất là đường công danh. Cầu tài, cầu việc đều hợp. Bất lợi hỏi về sức khỏe bệnh tật.", "g": "Việc muốn hỏi xuất hiện điềm lành, cục diện hài hòa sẽ xuất hiện nay mai.", "s": ""}, "370": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Hỏa Minh Di", "line_label": "Động Hào Tứ", "p": "*Thi ：hổ xuất kim bảng , hữu dũng diệc hà tế , chẩm tự sơn ông , phi phú do hữu thú .\n-Dịch:- cọp ra khỏi bảng vàng, có sức mạnh cứu giúp mọi việc, nhưng giống như “sơn ông” (ông già ở\nnúi) , không làm giàu là do sở thích của ông.", "b": "(Con chim trĩ kêu, bị bắn trúng mũi tên bắn vào bụng trái, lấy trái tim của nó rồi ra khỏi nhà)\nQuẻ này chủ về bị công danh trói buộc bằng thú vui ẩn dật ở chốn sơn lâm Chim trĩ bị giết cũng bởi vì bộ\nlông sặc sỡ của nó, người ta bị hại cũng vì tài ba của họ. Cái đạo lập thân là ở đức chứ chứ không phải ở\ndũng. Cái đạo giữ thân là nhờ ở lòng nhân chứ không phải nhờ sự giàu có. Người được quẻ này nên tự suy\nnghĩ mà phân biệt cho rõ ràng để chọn một lối sống thích hợp. Những mưu cầu của bạn phải chờ đợi một\nthời gian .", "g": "Tình huống hiện tại vượt ra ngoài sự việc bình thường, không thể dùng những hiểu biết thông\nthường để giải quyết, cần phải cầu những người có khả năng chuyên môn góp ý giải quyết mới được.", "s": ""}, "371": {"c": "HẠ HẠ", "hexagram": "Địa Hỏa Minh Di", "line_label": "Động Hào Ngũ", "p": "*Thi ：quá dương trường , nhập khang trang , ngũ lăng cừu mã , đương tư cố hương .\n-Dịch:- qua đoạn đường quanh co như ruột dê, đến được trang trại lớn, hưởng mọi thứ tiện nghi, phải\nnhớ đến quê xưa.", "b": "(Cơ tử bắn được con chim trĩ kêu. Hào này có lợi.)\nQuẻ này chủ về trước lo âu, sau vui vẻ. Thời vận của bạn đã hanh thông, chẳng còn gì phải lo ngại, nên cố\ngắng cầu tiến. Khi mưu cầu đã thành, hãy nghĩ đến những kẻ đã từng giúp sức cho thì mới được yên lành\nlâu bền", "g": "Trải qua hết mọi khó khăn gian khổ, đến được chỗ xứng ý toại lòng. Nên nhớ câu “uống nước\nnhớ nguồn” mà đừng lãng quên gốc tích.", "s": ""}, "372": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Hỏa Minh Di", "line_label": "Động Hào Lục", "p": "*Thi ：hoả tao thuỷ khắc , hoả diệt kỳ quang , thuỷ thế thao thao , nguyên viễn lưu trường .\n-Dịch:- lửa gặp nước khắc, lửa mất ánh sáng, thế nước ào ào, gốc xa chảy dài.", "b": "(Chim trĩ không kêu nưa, trời tối. Con chim trĩ lúc đầu bay lượn trên trời, về sau ẩn nấp dưới đất)\nQuẻ này chủ về tiền tài vào như nước. Vì lửa ở đây là chỉ tâm tư lo lắng nóng nảy, còn nước ở đây là chỉ\ntài lộc. Người được quẻ này sẽ giàu to. Nhưng hiện thời vận của bạn không được sáng sủa, còn gặp nhiều\ntrở lực, cho nên những điều mưu cầu khó mà được như ý. Hãy cẩn thận trong việc làm và chớ có cao vọng\nquá, nên ẩn nhẫn chờ qua một thời gian nữa.", "g": "Giải quyết những việc khẩn cấp, phải nhanh nhưng không thể làm đại làm càn, cũng còn phải\nnghĩ đến hậu hoạn về sau.", "s": ""}, "373": {"c": "HẠ TRUNG", "hexagram": "Địa Trạch Lâm", "line_label": "Động Hào Nhất", "p": "*Thi ：đông các diên khai , giai khách tự lai , cao ca xướng hoà , triển ấp thư hoài .\n-Dịch:- gác Đông mở tiệc, khách quí tự đến, ca hát vui vầy, chơi đùa thoải mái.", "b": "(Dũng cảm hóa để xử lý sự việc. Hào này cát lợi)\nQuẻ này chủ về hòa hợp với mọi người. Người được quẻ này có nhiều bạn cùng nhau mưu đồ việc lớn.\nViệc mưu cầu của bạn sẽ được giải quyết thỏa đáng trong tương lai gần. Thời vận đã đến kỳ hanh thông.\nCầu danh, cầu tài đều được.", "g": "Người được quẻ nầy là người có danh vọng địa vị cao, vui vẻ trong giao tiếp chiêu đãi , khách\nđến dự toàn là những nhân vật có tiếng tăm.", "s": ""}, "374": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Trạch Lâm", "line_label": "Động Hào Nhị", "p": "*Thi ：thế giới tự thanh ninh , bất tri từ dĩ hưu , đả điệp yếu tiểu tâm , tu phòng tao hoả .\n-Dịch:- thế giới tự an ổn, chẳng biết làm hay nghỉ, bày ra việc cần cẩn thận, coi chừng bị lửa táp.", "b": "(Lấy oai nghiêm mà xử lý, Hào này tốt lành, không có gì bất lợi)\nQuẻ này chủ về thời vận ngày càng rối loạn, phải hết sức đề phòng cẩn thận. Nếu không sẽ xảy ra tai họa\nbất ngờ. Hiện nay công ăn việc làm của bạn tuy được bình thường, nhưng nếu bạn sơ ý, không tính toán\nvà đề phòng chu đáo ắt sẽ xảy ra những điều không hay. Đối với cấp dưới phải xử lý cho nghiêm minh.\nThì mới không hỏng việc. Cầu tài cầu danh đều được nhưng phải thận trọng.", "g": "Trong thiên hạ vốn vô sự, do bởi con người tự làm loạn lên, cho nên nói là :- “Khổ não giai nhân\ncưỡng xuất đầu” (Có khổ là do con người bày bố áp đặt ra)", "s": ""}, "375": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Trạch Lâm", "line_label": "Động Hào Tam", "p": "*Thi ：khiêu long môn , tu kích lãng , lôi điện oanh oanh , dũng dược vạn trượng .\n-Dịch:- nhảy cửa rồng, chống ngăn sóng, sấm điện ầm ầm, vọt cao muôn trượng.", "b": "(Dùng nghiêm khắc để xử lý sự việc, chẳng lợi gì. Đã biết lo lắng về điều này thì không tai vạ)\nQuẻ này chủ về lý ngư vượt long môn, người tài vượt qua sóng gió để tung hoành bốn bể. Người được quẻ\nnày chẳng bao lâu nữa vận số sẽ được hanh thông. Nhưng muốn đạt được mục tiêu thì phải cố công vượt\nqua những khó khăn trở ngại. Trong quan hệ giao tế không nên quá nghiêm khắc mà hỏng việc. Cầu danh,\ncầu tài đều đắc lợi.", "g": "Muốn đạt mục tiêu thật cao, ắt phải có bản lãnh siêu quần mới có đủ thế và lực thành tựu công\nviệc.", "s": ""}, "376": {"c": "TRUNG TRUNG", "hexagram": "Địa Trạch Lâm", "line_label": "Động Hào Tứ", "p": "*Thi ：sơn thượng hữu cổ tùng , đình đình xung hán đấu , cán lão chi cánh trường , thiên địa sanh vinh\ncửu .\n-Dịch:- trên núi có cây tùng cổ, vút vút chỏi trời cao, thân già nhánh thật dài, trời đất nuôi dưỡng xanh tốt\nlâu dài.", "b": "(Lấy chí hướng để xử lý sự việc. Hào này khoogn có tai họa)\nQuẻ này có tượng bền bỉ lâu dài. Trong cuộc sống phải có chí hướng lâu dài, không nên thay đổi công việc\nlàm ăn liền liền. Vì như vậy sẽ khó tạo được căn cơ. Cây tùng già sống trên núi cao, phải chịu đựng sương\ngió, nhưng cây tùng ấy thân chắc, cành dài thì sợ gì gió sương. Những mưu cầu của bạn dầu có gặp phải\nkhó khăn gì, vẫn cứ cố gắng làm, tương lai ắt sẽ sán lạn. Mọi việc sẽ như ý muốn.", "g": "Nếu biết vận dụng đúng theo quy luật tự nhiên mà phát triển công việc thì có thể thu đạt kết quả\nnhư ý.", "s": ""}, "377": {"c": "HẠ THƯỢNG", "hexagram": "Địa Trạch Lâm", "line_label": "Động Hào Ngũ", "p": "*Thi ：phỉ báng ngôn , vật kế luận , đáo đầu lai , số dĩ định , lục lục phù sinh , bất như an phận .\n-Dịch:- Lời phỉ báng xin đừng để ý –Việc đáo đầu thiên lý an bài—Bôn ba lận đận xưa nay—Sao bằng\nan phận qua ngày tháng trôi ?", "b": "(Dùng cái trí hiểu biết để xử lý sự việc, chỉ có bực đại quân tử mới làm được. Hào này cát lợi)\nQuẻ này chủ về cầu toàn thì hỏng. Đời người trên cõi thế, kiếp sống có là bao. Vì vậy người được quẻ này\nbiết tiến thì cũng phải biết thoái, lui một bước mà suy nghĩ căn kẽ rồi hãy tính chuyện chấn hưng cơ đò.\nCầu danh, cầu tài đều được, nhưng phải uyển chuyển.", "g": "Đối với những lời lẽ tạp nhạp thêu dệt lăng nhăng thì để ý đến làm gì ? Tất cả đều do định số\ncùng với nhân quả thiện ác báo ứng nào có sai ngoa bao giờ.", "s": ""}, "378": {"c": "TRUNG TRUNG", "hexagram": "Địa Trạch Lâm", "line_label": "Động Hào Lục", "p": "*Thi ：nhất đầu trư , khả tế thiên địa , tuy táng thân , diệc toán hảo xứ .\n-Dịch:- một cái đầu heo cũng có thể cúng tế trời đất, tuy heo mất thân mạng mà giúp người được điều tốt.", "b": "(Dùng hậu đãi để xử lý sự việc. Hào này tốt đẹp. Không có tai họa)\nQuẻ này chủ về xử sự phải hậu hĩ với người. Vật gì dù có nhỏ nhoi kém cỏi đến đâu cũng có chỗ hữu ích\ncủa nó. Người nào được quẻ này đôi lúc nên hy sinh cái nhỏ để được cái lớn.", "g": "Trời sanh muôn vật ắt có chỗ dùng, nhưng nói về cái “dụng” thì người và chó heo phải có chỗ\nchẳng giống nhau.", "s": ""}, "379": {"c": "THƯỢNG THƯỢNG", "hexagram": "Địa Thiên Thái", "line_label": "Động Hào Nhất", "p": "*Thi ：dữ kỳ nhật doanh doanh , hà như dạ thổn thổn , nhật lí đa lao hình , dạ gian khước an ổn .\n-Dịch:- cứ theo ban ngày mà lượn qua lượn lại sao bằng đêm chỉ nằm một chỗ, trong ngày nhiều nhọc\nmệt cực khổ, lúc ban đêm an ổn chẳng lo sợ.", "b": "(Nhổ rễ ổ tranh phải nắm cả bụi, đi chinh phạt thì tốt lành)\nQuẻ này chủ về ở đời tốt hay xấu là do cách nghĩ và cách làm của mình. Người được quẻ này nên suy nghĩ\ncẩn thận mà chọn lấy điều hay, bỏ đi điều dở. Những mưu cầu của bạn cứ làm, chớ nên suy nghĩ và đắn đo\nquá. Phàm làm việc gì cũng phải nắm vững toàn bộ vấn đề, có vậy mới lường được bất trắc xảy ra. Cầu tài\ncầu danh đều được.", "g": "Lời quẻ nói đã quá rõ.", "s": ""}, "380": {"c": "TRUNG TRUNG", "hexagram": "Địa Thiên Thái", "line_label": "Động Hào Nhị", "p": "*Thi ：đông phong lai , hoa tự khai , đại gia hát thái , sướng ẩm tam bôi .\n-Dịch:- gió Đông đến , hoa tự nở, mọi người ngắm vẻ đẹp của nó, thích thú uống ba chén rượu.", "b": "(Bơi qua sông bằng trái bầu rỗng, không bị chìm, nhưng vẫn bị mất tiền của, về sau được người khác giúp\nđỡ ở giữa đường)\nQuẻ này chủ về thời bĩ đã qua vận tốt đã về, có phúc thì cùng hưởng. Việc mưu cầu của bạn ắt sẽ được\ntoại nguyện trong nay mai. Cầu tài, cầu danh đều được nhưng phải cố công nhiều.", "g": "muôn sự điều đủ, chỉ thiếu gió Đông. Nay gió Đông đã có, chính là lúc bắt đầu công việc hằng\nmong đợi của mình.", "s": ""}, "381": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Thiên Thái", "line_label": "Động Hào Tam", "p": "*Thi ：sơ tự ẩm thuỷ , lạc tại kỳ trung , cao lương mỹ vị , phản sử tâm mông .\n-Dịch:- ăn cơm hẩm uống nước lạnh, có niềm vui rồi, cao lương mỹ vị, làm tâm hoang mang chờ đợi.", "b": "(Không có gì bằng phẳng mà không nghiêng lệch, không có gì đi mãi mà không trở lại, bói hỏi về sự gian\nnan thì không tai vạ, chớ lo nghĩ về việc bị phạt, chỉ là ăn mà có rượu tế)\nQuẻ này chủ về cuộc đời lúc này lúc khác, không thể suôn sẻ mãi được. Người được quẻ này nên an bần\nlạc đạo là hơn. Phàm mưu tính làm việc gì, điều cần nhất là đừng có cao vọng quá, hãy nên tính kỹ lưỡng.", "g": "Biết tri túc thì luôn hưởng được niềm vui.", "s": ""}, "382": {"c": "TRUNG THƯỢNG", "hexagram": "Địa Thiên Thái", "line_label": "Động Hào Tứ", "p": "*Thi ：huỳnh ngưu bích thổ , đại lực khai cương , tây thành thời hậu , cốc mễ doanh thương .\n-Dịch:- trâu vàng đất vua, sức lớn mở bờ cõi, lúc ở thành Tây, gão thóc đầy kho.", "b": "(Bôn ba qua lại không ngừng, không thể giàu có vì bị láng giềng trộm cặp. Do không biết cảnh giác ngăn\nngừa.)\nQuẻ này chủ về lao khổ lúc đầu thì về sau được yên vui. Người được quẻ này khi gặp việc cần nên hăng\nhái hoạt động, nhìn xa trông rộng, cẩn thận đề phòng, có như thế mới bảo toàn được thành quả do mình\ntạo ra.", "g": "một phen cày cấy, một phen thu hoạch (có làm có ăn)", "s": ""}, "383": {"c": "TRUNG TRUNG", "hexagram": "Địa Thiên Thái", "line_label": "Động Hào Ngũ", "p": "*Thi ：xà khả hoá long , đầu giác tương xuất , bình địa nhất thanh lôi , phương hiển long xà lực .\n-Dịch:- rắn có thể hóa rồng, đầu sừng sẽ hiện, đất bằng một tiếng sấm, mới biết sức rắn rồng.", "b": "(Đế Ất gả em gái, có phúc trạch. Hào này rất tốt đẹp)\nQuể này chủ về tài năng thực mới là quan trọng sự nghiệp là do mình hoàn toàn là do mình tạo ra. Những\nmưu cầu của bạn sắp được toại ý và sự thành tựu sẽ rất tốt đẹp. Bạn hãy cố sức, chỉ cần có người đề bạt là\ncông danh sẽ rỡ ràng. Cầu tài, cầu danh đều được.", "g": "Người được quẻ nầy là đang trong tình trạng bình thường, muốn cầu một lực phi thường, có cơ\nhội thành tựu ý muốn.", "s": ""}, "384": {"c": "HẠ TRUNG", "hexagram": "Địa Thiên Thái", "line_label": "Động Hào Lục", "p": "*Thi ：Cửu Hoa Sơn đỉnh , tử khí đằng đằng , dị tận nhất châu , thủ khứ tiền hành .\n-Dịch:- cái đỉnh ở núi Cửu Hoa, sắc tía bốc lên cao, trùm phủ một chiếc thuyền, nhờ đó đi tới trước.", "b": "(Tường thành đổ xuống hào nước, chớ xuất binh, từ ấp báo lên như vậy. Hào này có khó khăn)\nQuể này chủ về chí ccao nghiệp cả, việc lớn có thể thành. Người được quẻ này nhất định sẽ có tiến trình\ntốt đẹp, nhưng phải trải qua nhiều gian nan, thử thách. Bạn muốn thành đạt sở cầu, thì phải cố sức và gan\ndạ tiến tới, mới có thể toại nguyện.", "g": "Người được quẻ nầy là đạt cơ duyên may mắn, từ đây sẽ “thuận buồm xuôi gió”.", "s": ""}};